<script>
    // --------------------------------------------------------------
    // 100 TÉCNICAS DE FONOLOGÍAS ESTRUCTURALISTAS + MORFOLOGÍA
    // Fonología diacrónica (evolución histórica), sincrónica (sistema actual),
    // árboles genealógicos del español, reglas fonológicas,
    // más morfología flexiva/derivativa, clases de palabras, formación léxica,
    // accidentes gramaticales y morfemática.
    // --------------------------------------------------------------
    const techniques = [];

    function add(id, name, category, teoria, ejemplo, ejercicio, suggestedAnswer) {
        techniques.push({ id, name, category, teoria, ejemplo, ejercicio, suggestedAnswer });
    }

    // ========= 1. FONOLOGÍA ESTRUCTURAL (sincrónica, diacrónica, sistema de oposiciones) =========
    add(1, "Fonología sincrónica", "Fonología estructural", "Estudio del sistema fonológico en un momento dado del tiempo.", "Fonemas del español actual: /p, t, k, b, d, g, f, θ, s, x, tʃ, m, n, ɲ, l, ʎ, r, ɾ, i, e, a, o, u/.", "¿Cuántos fonemas vocálicos tiene el español estándar?", "5");
    add(2, "Fonología diacrónica", "Fonología estructural", "Estudio de la evolución de los sistemas fonológicos a través del tiempo.", "Del latín al castellano: pérdida de cantidad vocálica, creación de nuevas consonantes.", "¿Qué fenómeno eliminó las vocales largas del latín?", "pérdida de cantidad vocálica");
    add(3, "Fonema (unidad distintiva)", "Fonología estructural", "Unidad fonológica mínima que puede diferenciar significados.", "/p/ y /b/ diferencian 'piso' y 'biso'.", "¿Qué fonema diferencia 'casa' de 'caza' en zonas con distinción?", "/s/ vs /θ/");
    add(4, "Arquifonema", "Fonología estructural", "Unidad que representa la neutralización de dos o más fonemas.", "En español, /N/ representa la neutralización de /m, n, ɲ/ antes de consonante.", "Arquifonema de /b, d, g/ en posición implosiva", "/B, D, G/");
    add(5, "Rasgos distintivos (Escuela de Praga)", "Fonología estructural", "Propiedades acústicas o articulatorias que definen a los fonemas.", "[±sonoro], [±nasal], [±continuo].", "Rasgo que distingue /p/ de /b/", "[±sonoro]");
    add(6, "Neutralización fonológica", "Fonología estructural", "Cuando la oposición entre dos fonemas desaparece en un contexto.", "/l/ y /r/ se neutralizan en final de sílaba en algunos dialectos: 'arma/ alma'.", "Fonema resultante de neutralización de /s/ y /θ/ en seseo", "/s/");
    add(7, "Oposición fonológica", "Fonología estructural", "Contraste entre fonemas que produce cambio de significado.", "Pino / pito (oposición /n/ vs /t/)", "Ejemplo de oposición entre /l/ y /r/", "pala / para");
    add(8, "Archifonema nasal", "Fonología estructural", "El archifonema /N/ se realiza como [m], [n], [ɲ] según contexto.", "iN+posible → imposible; iN+necesario → innecesario", "Realización de /N/ ante /f/", "[ɱ] labiodental");
    add(9, "Sistema vocálico del castellano", "Fonología estructural", "5 vocales /i, e, a, o, u/ con oposiciones de abertura y localización.", "/i/ y /u/ son vocales altas, /e/ y /o/ medias, /a/ baja.", "¿Cuántas vocales tiene el sistema?", "5");
    add(10, "Sistema consonántico del español", "Fonología estructural", "18-24 fonemas según variante dialectal.", "Oclusivas: /p, t, k, b, d, g/; fricativas: /f, θ, s, x/; africada: /tʃ/; nasales: /m, n, ɲ/; laterales: /l, ʎ/; vibrantes: /r, ɾ/.", "¿Qué fonemas han desaparecido en el yeísmo?", "/ʎ/ se fusiona con /ʝ/");

    // ========= 2. ESTRUCTURA ARBÓREA HISTÓRICA (evolución del latín al castellano) =========
    add(11, "Árbol genealógico romance", "Estructura arbórea histórica", "Evolución desde el latín vulgar hacia las lenguas romances.", "Latín → Romance occidental → Ibero romance → Castellano.", "Rama del árbol del español", "Iberorromance");
    add(12, "Sonorización de oclusivas sordas intervocálicas", "Estructura arbórea histórica", "En latín vulgar, /p, t, k/ se sonorizan a /b, d, g/ entre vocales.", "VITA → vida, APE(S) → abeja, LACU → lago", "Evolución de 'CAPRA'", "cabra");
    add(13, "Pérdida de /f/ inicial (f- → h- → ∅)", "Estructura arbórea histórica", "F inicial latina se convierte en h aspirada y luego muda.", "FABULARE → fablar → hablar", "Palabra que conserva h muda: 'hijo'", "FILIU → fijo → hijo");
    add(14, "Diptongación de E, O abiertas", "Estructura arbórea histórica", "Las vocales latinas /ɛ/ y /ɔ/ diptongan en 'ie' y 'ue'.", "PĒTRA → piedra, FŌCU → fuego", "Diptongo en 'BONU'", "bueno");
    add(15, "Palatalización de /l/ y /n/ ante yod", "Estructura arbórea histórica", "/l/ + /j/ → /ʎ/; /n/ + /j/ → /ɲ/.", "MULJERE → mujer, HISPANIOLA → española", "Resultado de /l/ + /j/", "/ʎ/ (elle)");
    add(16, "Betacismo (confusión B/V)", "Estructura arbórea histórica", "Desde el siglo XVI, /b/ y /v/ se fusionan en español.", "Latín BELLU y VACCA → bello y vaca (sin contraste)", "¿Se distinguen 'bacía' y 'vacía'?", "no, homófonas");
    add(17, "Evolución de los grupos iniciales PL-, CL-, FL-", "Estructura arbórea histórica", "PL-, CL-, FL- se palatalizan a /ʎ/ en la mayor parte del dominio.", "PLANU → llano, CLAVE → llave, FLAMMA → llama", "Evolución de 'PLORARE'", "llorar");
    add(18, "Pérdida de consonantes finales", "Estructura arbórea histórica", "El latín pierde /m/ final y otras consonantes en romance.", "PANEM → pan, CANTARE → cantar", "¿Qué perdió 'AMORE'?", "la e final no, pero ej: AMOR → amor");
    add(19, "Síncopa (pérdida de vocal átona interior)", "Estructura arbórea histórica", "Desaparición de vocales breves en posición interior.", "CALIDU → caldo, DOMINU → dueño", "Evolución de 'LEGITIMA'", "legítima (no síncopa) pero 'légitima'? mejor 'cálido'");
    add(20, "Aféresis (pérdida inicial)", "Estructura arbórea histórica", "Supresión de sonido al principio de palabra.", "APOTHECA → bodega (con evolución), también 'estudiar' sin aféresis.", "Ejemplo de aféresis en 'arena'", "latín ARENA → arena");

    // ========= 3. PROCESOS FONOLÓGICOS SINC RÓNICOS =========
    add(21, "Asimilación de nasal", "Fonología estructural", "La nasal adquiere el punto de articulación de la consonante siguiente.", "iN+posible → imposible, iN+relativo → irrelativo", "Resultado de /n/ antes de /p/", "[m]");
    add(22, "Espirantización de /b, d, g/", "Fonología estructural", "Las oclusivas sonoras se realizan como aproximantes en contexto intervocálico.", "/b/ → [β], /d/ → [ð], /g/ → [ɣ]", "Realización de /d/ en 'nada'", "[ð]");
    add(23, "Yeísmo", "Fonología estructural", "Fusión del fonema palatal lateral /ʎ/ con el fricativo palatal /ʝ/ (representado como y).", "calló / cayó → homófonos", "¿En qué regiones se conserva /ʎ/?", "zonas bilingües (catalán, vasco, gallego) y norte de España");
    add(24, "Seseo", "Fonología estructural", "Fusión de /θ/ con /s/; ambos se realizan como [s].", "casa y caza se pronuncian igual [ˈkasa]", "¿Dónde se da seseo?", "América, Canarias, sur de España");
    add(25, "Ceceo", "Fonología estructural", "Fusión de /s/ con /θ/; ambos se realizan como [θ].", "casa y caza → [ˈkaθa]", "Zona geográfica del ceceo", "sur de Andalucía (Cádiz, Sevilla, Granada)");
    add(26, "Aspiración de /s/ implosiva", "Fonología estructural", "La /s/ al final de sílaba se aspira como [h] en muchos dialectos.", "mosca → [ˈmohka]", "Realización de 'este' en andaluz", "[ˈehte]");
    add(27, "Pérdida de /d/ intervocálica", "Fonología estructural", "La /d/ tiende a desaparecer en participios y palabras cotidianas.", "cansado → cansa'o, partido → partío", "Ejemplo en 'helado'", "helao");
    add(28, "Sonorización de /s/ ante consonante sonora", "Fonología estructural", "En algunos dialectos, /s/ se sonoriza a [z] ante /b, d, g, m, n, l, r/.", "mismo → [ˈmizmo], desde → [ˈdezðe]", "¿En qué variante es común?", "caribeña y andaluza oriental");

    // ========= 4. MORFOLOGÍA FLEXIVA =========
    add(29, "Flexión de género (sustantivos)", "Flexión", "Los sustantivos varían de género con -o/-a u otras marcas.", "niño/niña, poeta/poetisa", "Femenino de 'actor'", "actriz");
    add(30, "Flexión de número (plural)", "Flexión", "Se forma con -s, -es o invariables.", "árbol/árboles, crisis/crisis", "Plural de 'jabalí'", "jabalíes/jabalís");
    add(31, "Pretérito perfecto simple", "Flexión", "Desinencias -é, -aste, -ó, -amos, -asteis, -aron.", "canté, comiste, vivió", "Conjuga 'escribir' en 1ª singular", "escribí");
    add(32, "Modo subjuntivo presente", "Flexión", "Expresa deseo, duda, posibilidad.", "Espero que venga", "Conjuga 'temer' 3ª singular subjuntivo", "tema");
    add(33, "Aspecto perfectivo/imperfectivo", "Flexión", "Perfectivo: acción terminada; imperfectivo: en desarrollo.", "Canté / Cantaba", "Aspecto de 'había comido'", "perfectivo");
    add(34, "Persona verbal", "Flexión", "Desinencias 1ª, 2ª, 3ª persona.", "hablo, hablas, habla", "Persona de 'decían'", "3ª plural");
    add(35, "Futuro de indicativo", "Flexión", "-é, -ás, -á, -emos, -éis, -án.", "hablaré, comerás", "Futuro de 'poner' 2ª singular", "pondrás");
    add(36, "Condicional simple", "Flexión", "-ía, -ías, -ía, -íamos, -íais, -ían.", "cantaría, comerías", "Condicional de 'vivir' 3ª singular", "viviría");
    add(37, "Imperativo afirmativo", "Flexión", "Mandatos.", "¡Canta! ¡Comed!", "Imperativo de 'venir' para vosotros", "venid");

    // ========= 5. DERIVACIÓN =========
    add(38, "Prefijación (negación)", "Derivación", "Prefijos con significado negativo o reversivo.", "inútil, deshacer", "Aplica prefijo 're-' a 'hacer'", "rehacer");
    add(39, "Sufijación -ción", "Derivación", "Sustantivos abstractos deverbales.", "actuación, decisión", "Sustantivo de 'decidir'", "decisión");
    add(40, "Interfijación", "Derivación", "Inserción de segmento no morfemático.", "cafecito (café+c+ito)", "Interfijo en 'polvareda'", "-ar-");
    add(41, "Parasíntesis", "Derivación", "Prefijo + sufijo simultáneos.", "entristecer (en-+triste+-ecer)", "Parasíntesis en 'apiedrar'", "a-+piedra+-ar");
    add(42, "Sufijos aumentativos", "Derivación", "-ón, -azo.", "cabezón, librazo", "Aumentativo de 'coche'", "cochezote");
    add(43, "Sufijo diminutivo (-ito)", "Sufijos apreciativos", "Expresa tamaño pequeño o afecto.", "perrito, mesilla", "Diminutivo de 'flor'", "florecita");
    add(44, "Sufijo despectivo -ucho", "Derivación", "Indica desprecio.", "pueblucho, medicucho", "Despectivo de 'casa'", "casucha");
    add(45, "Sufijo -ble", "Derivación", "Posibilidad.", "amable, temible", "Adjetivo de 'comprender'", "comprensible");

    // ========= 6. CLASES DE PALABRAS Y FORMACIÓN LÉXICA =========
    add(46, "Sustantivos concretos/abstractos", "Clases de palabras", "Concretos vs abstractos.", "mesa, libertad", "Clasifica 'esperanza'", "abstracto");
    add(47, "Adjetivos calificativos", "Clases de palabras", "Expresan cualidades.", "grande, azul", "Adjetivo en 'mujer hermosa'", "hermosa");
    add(48, "Verbos copulativos", "Clases de palabras", "Ser, estar, parecer.", "Ella es doctora", "Copulativo en 'Luisa parece cansada'", "parece");
    add(49, "Adverbios de modo", "Clases de palabras", "-mente o invariables.", "rápidamente, bien", "Adverbio de 'feliz'", "felizmente");
    add(50, "Preposiciones", "Clases de palabras", "a, ante, bajo, con, contra, de, desde, en, entre, hacia, hasta, para, por, según, sin, so, sobre, tras.", "Voy a Madrid", "Preposición de destino", "a");
    add(51, "Conjunciones", "Clases de palabras", "y, pero, porque.", "Juan y Pedro", "Adversativa en 'Quiero ir ___ no puedo'", "pero");
    add(52, "Determinantes demostrativos", "Clases de palabras", "este, ese, aquel.", "Ese libro", "Determinante en 'Aquellos días'", "aquellos");
    add(53, "Pronombres átonos", "Clases de palabras", "me, te, se, lo, la, le, nos, os, los, las, les.", "Se lo di", "Acusativo para 'el libro'", "lo");
    add(54, "Composición propia", "Formación de palabras", "Unión de dos lexemas.", "pelirrojo (pelo+rojo)", "Analiza 'cortafuegos'", "verbo + sustantivo");
    add(55, "Acronimia y siglación", "Formación de palabras", "OTAN, RENFE, DGT, IVA.", "Significado de 'RENFE'", "Red Nacional de Ferrocarriles Españoles");

    // ========= 7. ACCIDENTES GRAMATICALES Y MORFEMÁTICA =========
    add(56, "Accidente de género", "Accidentes gramaticales", "Masculino/femenino.", "el mar / la mar", "Femenino de 'el poeta'", "la poetisa");
    add(57, "Número gramatical", "Accidentes gramaticales", "Singular/plural.", "detalle → detalles", "Plural de 'jabalí'", "jabalíes");
    add(58, "Persona verbal", "Accidentes gramaticales", "1ª, 2ª, 3ª.", "soy, eres, es", "Persona de 'corrieron'", "3ª plural");
    add(59, "Tiempo absoluto", "Accidentes gramaticales", "Presente, pasado, futuro.", "como, comí, comeré", "Tiempo de 'había soñado'", "pretérito pluscuamperfecto");
    add(60, "Modo verbal", "Accidentes gramaticales", "Indicativo, subjuntivo, imperativo.", "Ojalá venga", "Modo en '¡Ven aquí!'", "imperativo");
    add(61, "Grado del adjetivo", "Accidentes gramaticales", "Positivo, comparativo, superlativo.", "alto, más alto que, altísimo", "Superlativo de 'fuerte'", "fortísimo");
    add(62, "Lexema o raíz", "Morfemática", "Núcleo semántico.", "cant- en 'cantamos'", "Lexema de 'floristería'", "flor-");
    add(63, "Morfema flexivo de tiempo", "Morfemática", "Desinencia de tiempo.", "cantaba: -ba", "Morfema de futuro en 'comerás'", "-ás");
    add(64, "Alomorfo de plural", "Morfemática", "Variantes: -s, -es, cero.", "soles, crisis", "Alomorfo plural de 'lunes'", "cero");
    add(65, "Alomorfo de género femenino", "Morfemática", "-a, -isa, -ina, -triz.", "actriz, princesa", "Alomorfo en 'emperatriz'", "-triz");
    add(66, "Tema verbal", "Morfemática", "Raíz + vocal temática.", "cant-a-", "Tema de 'partir'", "part-");
    add(67, "Base morfológica", "Morfemática", "Base sobre reglas derivacionales.", "claro → claridad", "Base de 'fortalecer'", "fort-");
    add(68, "Interfijo", "Morfemática", "Elemento sin significado.", "humareda (-ar-)", "Interfijo en 'huesecillo'", "-ec-");
    add(69, "Morfema cero", "Morfemática", "Categoría sin marca.", "singular en 'mesa'", "Marca de singular en 'cactus'", "cero");

    // ========= 8. MÁS PROCESOS FONOLÓGICOS Y ESTRUCTURAS (hasta 100) =========
    add(70, "Metátesis histórica", "Estructura arbórea histórica", "Cambio de orden de sonidos.", "CROCODILE → cocodrilo", "Ejemplo de metátesis en 'palabra'", "parabla");
    add(71, "Prótesis de e-", "Estructura arbórea histórica", "Adición de e- ante grupos con s + consonante.", "Latín SPATHA → espada, STATUS → estado", "Palabra con prótesis: 'esfera'", "del latín SPHAERA");
    add(72, "Epéntesis de /d/ en grupos cultos", "Fonología estructural", "Inserción de /d/ en combinaciones como 'n+d' o 'l+d'.", "cuidado, peligro (del latín cogitatu, periculu) → no es epéntesis", "Ejemplo: 'faldas' no. Mejor 'caldo' (CALIDU)");
    add(73, "Evolución de los grupos -MB-, -ND-", "Estructura arbórea histórica", "Se simplifican perdiendo la nasal en castellano antiguo.", "LUMBU → lomo", "Evolución de 'CUMBA'", "coma (ant.)");
    add(74, "Árbol de las sibilantes medievales", "Estructura arbórea histórica", "El español medieval tenía un sistema de seis sibilantes: /s/, /z/, /ʃ/, /ʒ/, /ts/, /dz/.", "Pasó al sistema actual con /s/, /θ/, /x/.", "¿Qué sonido se perdió completamente?", "la fricativa alveolar sonora /z/");
    add(75, "Reajuste de las sibilantes (siglos XVI-XVII)", "Estructura arbórea histórica", "Las sibilantes medievales se reestructuraron en el sistema actual.", "La antigua /ʃ/ se convirtió en /x/ (j).", "¿Qué fonema moderno proviene de /ʒ/?", "/x/ (en posición final de palabra, luego /x/ general)");
    add(76, "Ensordecimiento de sibilantes sonoras", "Fonología estructural", "Las sibilantes sonoras medievales (/z/, /ʒ/, /dz/) se ensordecieron.", "/z/ → /s/, /ʒ/ → /ʃ/, /dz/ → /ts/ → /θ/", "Resultado de /dz/ en el español moderno", "/θ/");
    add(77, "Fonotáctica del español actual", "Fonología estructural", "Restricciones en combinaciones de sonidos.", "No puede haber /tl/ al inicio de palabra (excepto préstamos).", "¿Es válida 'tl' en 'tlatoani'?", "sí, préstamo del náhuatl");
    add(78, "Estructura silábica preferida (CV)", "Fonología estructural", "La sílaba universal tiende a ser consonante+ vocal.", "Casa: CV.CV", "¿Cuántas sílabas tiene 'transporte'?", "tres: trans.por.te");
    add(79, "Acento prosódico (función distintiva)", "Fonología estructural", "El acento puede diferenciar palabras.", "término, termino, terminó", "Clase de palabra según acento de 'café'", "aguda");
    add(80, "Monoptongación", "Estructura arbórea histórica", "Reducción de diptongo a vocal simple.", "AU → o (cauda → cola, faux → foz)", "Evolución de 'AURU'", "oro");
    add(81, "Palatalización de velares ante e,i", "Estructura arbórea histórica", "C + e,i → (t)θ o x.", "CĪNU → ceniza, GENTE → gente", "Resultado de 'CERVU'", "ciervo");
    add(82, "Abertura vocálica en hiato", "Fonología estructural", "Vocales en hiato se mantienen en sílabas separadas.", "poeta [po.ˈe.ta]", "¿Diptongo o hiato en 'caer'?", "hiato (ca.er)");
    add(83, "Derivación con sufijo -ero", "Derivación", "pan → panadero", "Oficio de 'caja'", "cajero");
    add(84, "Prefijo mono-", "Formación de palabras", "monolito, monótono", "Mono- + 'cromático'", "monocromático");
    add(85, "Sufijo -ancia", "Derivación", "importancia, dependencia", "Sustantivo de 'confiar'", "confianza");
    add(86, "Interfijo -it-", "Morfemática", "abuelito (abuel+it+o)", "Interfijo en 'jovencito'", "-enc-");
    add(87, "Prefijo ex-", "Derivación", "exmarido, expresidente", "Palabra con ex- + 'alumno'", "exalumno");
    add(88, "Futuro de subjuntivo", "Flexión", "Si así fuere...", "Futuro subjuntivo de 'ser'", "fuere");
    add(89, "Gerundio compuesto", "Flexión", "Habiendo comido", "Gerundio compuesto de 'hablar'", "habiendo hablado");
    add(90, "Oración con 'sino'", "Gramática", "No es alto, sino bajo.", "Completa: 'No estudió, ___ durmió'", "sino");
    add(91, "Complemento de régimen", "Gramática", "Carecer de, arrepentirse de", "CRV en 'Se acordó de nosotros'", "de nosotros");
    add(92, "Verbo pronominal", "Accidentes gramaticales", "Se arrepintió.", "Analiza 'Se durmió'", "pronominal reflexivo");
    add(93, "Alternancia vocálica", "Morfemática", "contar → cuento", "Alternancia en 'dormir'", "duermo (o→ue)");
    add(94, "Sustantivo epiceno", "Clases de palabras", "la jirafa (macho/hembra)", "Epiceno: 'el lince' hembra", "la lince");
    add(95, "Interjección impropia", "Clases de palabras", "¡Cielos! ¡Vaya!", "Interjección de admiración", "¡Oh!");
    add(96, "Oración exclamativa indirecta", "Gramática", "Dime qué bonito es.", "Exclamativa indirecta en 'Me asombra lo rápido que corre'", "lo rápido que corre");
    add(97, "Concesiva con 'por más que'", "Gramática", "Por más que estudies, no aprobarás.", "Concesiva con 'por mucho que'", "Por mucho que corras, llegarás tarde");
    add(98, "Oración enfática (ser + que)", "Gramática", "Fue Juan quien lo dijo.", "Enfatiza el objeto: 'Compré el coche'", "Fue el coche lo que compré");
    add(99, "Apócope", "Flexión", "buen (bueno), gran (grande)", "Apócope de 'malo' ante 'momento'", "mal");
    add(100, "Préstamo fonológico", "Fonología estructural", "Adopción de sonidos extranjeros.", "En español, palabras como 'show' introducen /ʃ/ en préstamos.", "¿El fonema /ʃ/ es nativo del español?", "no, solo en préstamos");

    // ---------------------- PROGRESO LOCALSTORAGE ----------------------
    let userProgress = JSON.parse(localStorage.getItem('fonoEstructuralProgress')) || {};

    function updateGlobalProgress() {
        const total = techniques.length;
        let completed = 0;
        for (let i = 0; i < total; i++) {
            if (userProgress[i+1] === true) completed++;
        }
        const percent = Math.round((completed / total) * 100);
        const fillBar = document.getElementById('globalProgressFill');
        const percentSpan = document.getElementById('progressPercent');
        if (fillBar) fillBar.style.width = percent + '%';
        if (percentSpan) percentSpan.innerText = percent + '%';
    }

    function setCardStatus(cardId, isCorrect) {
        const statusSpan = document.getElementById(`status-${cardId}`);
        if (statusSpan) {
            if (isCorrect) {
                statusSpan.innerHTML = ' ✅';
                statusSpan.style.color = '#2b6e2b';
            } else {
                statusSpan.innerHTML = '';
            }
        }
        userProgress[cardId] = isCorrect;
        localStorage.setItem('fonoEstructuralProgress', JSON.stringify(userProgress));
        updateGlobalProgress();
    }

    function checkAnswer(cardId, userAnswer, correctAnswer, inputElement, feedbackElement) {
        const normalizedUser = userAnswer.trim().toLowerCase().replace(/[¿¡]/g, '');
        const normalizedCorrect = correctAnswer.trim().toLowerCase().replace(/[¿¡]/g, '');
        const isOk = normalizedUser === normalizedCorrect;
        if (isOk) {
            feedbackElement.innerHTML = '✓ ¡Correcto!';
            feedbackElement.className = 'feedback correct';
            setCardStatus(cardId, true);
        } else {
            feedbackElement.innerHTML = `✗ Incorrecto. Respuesta sugerida: "${correctAnswer}"`;
            feedbackElement.className = 'feedback incorrect';
            setCardStatus(cardId, false);
        }
        inputElement.disabled = true;
        inputElement.style.backgroundColor = '#f0f0f0';
    }

    function resetCard(cardId, inputElement, feedbackElement) {
        inputElement.disabled = false;
        inputElement.value = '';
        inputElement.style.backgroundColor = 'white';
        feedbackElement.innerHTML = '';
        feedbackElement.className = 'feedback';
        userProgress[cardId] = false;
        localStorage.setItem('fonoEstructuralProgress', JSON.stringify(userProgress));
        updateGlobalProgress();
        const statusSpan = document.getElementById(`status-${cardId}`);
        if (statusSpan) statusSpan.innerHTML = '';
    }

    function speakText(text) {
        if ('speechSynthesis' in window) {
            speechSynthesis.cancel();
            const utterance = new SpeechSynthesisUtterance(text);
            utterance.lang = 'es-ES';
            utterance.rate = 0.9;
            speechSynthesis.speak(utterance);
        } else {
            alert("Tu navegador no soporta síntesis de voz.");
        }
    }

    // Renderizado
    document.getElementById('totalCount').innerText = techniques.length;
    const container = document.getElementById('cardsContainer');
    const searchInput = document.getElementById('searchInput');
    const categorySelect = document.getElementById('categorySelect');

    function renderCards() {
        const searchTerm = searchInput.value.toLowerCase();
        const selectedCat = categorySelect.value;
        const filtered = techniques.filter(t => {
            const matchSearch = t.name.toLowerCase().includes(searchTerm) ||
                                t.category.toLowerCase().includes(searchTerm) ||
                                t.teoria.toLowerCase().includes(searchTerm);
            const matchCat = selectedCat === 'all' || t.category === selectedCat;
            return matchSearch && matchCat;
        });

        if (filtered.length === 0) {
            container.innerHTML = `<div style="grid-column:1/-1; text-align:center;padding:3rem;">🔍 No hay técnicas con esos filtros.</div>`;
            return;
        }

        container.innerHTML = filtered.map(item => {
            const isCompleted = userProgress[item.id] === true;
            return `
            <div class="card">
                <div class="card-header">
                    <h3>#${item.id} · ${item.name} <span id="status-${item.id}" class="status-icon">${isCompleted ? '✅' : ''}</span></h3>
                    <span class="category-tag">${item.category}</span>
                </div>
                <div class="card-body">
                    <div class="teoria">
                        <span>📘 ${item.teoria}</span>
                        <button class="btn-speak" data-teoria="${item.teoria.replace(/"/g, '&quot;')}">🔊 Leer teoría</button>
                    </div>
                    <div class="ejemplo">
                        <span>💡 ${item.ejemplo}</span>
                        <button class="btn-speak-ejemplo" data-ejemplo="${item.ejemplo.replace(/"/g, '&quot;')}">🔊 Leer ejemplo</button>
                    </div>
                    <div class="ejercicio-area">
                        <div class="ejercicio-text">✏️ Ejercicio: ${item.ejercicio}</div>
                        <div class="input-group">
                            <input type="text" id="input-${item.id}" placeholder="Escribe tu respuesta..." ${isCompleted ? 'disabled' : ''}>
                            <button class="check-btn" data-id="${item.id}" ${isCompleted ? 'disabled' : ''}>Comprobar</button>
                        </div>
                        <div id="feedback-${item.id}" class="feedback"></div>
                        <button class="reset-card-btn" data-reset="${item.id}">⟳ Reiniciar ejercicio</button>
                    </div>
                </div>
            </div>
            `;
        }).join('');

        document.querySelectorAll('.btn-speak').forEach(btn => {
            btn.addEventListener('click', (e) => {
                const text = btn.getAttribute('data-teoria');
                if (text) speakText(text);
            });
        });
        document.querySelectorAll('.btn-speak-ejemplo').forEach(btn => {
            btn.addEventListener('click', (e) => {
                const text = btn.getAttribute('data-ejemplo');
                if (text) speakText(text);
            });
        });

        techniques.forEach(t => {
            const btn = document.querySelector(`.check-btn[data-id="${t.id}"]`);
            const resetBtn = document.querySelector(`.reset-card-btn[data-reset="${t.id}"]`);
            const inputEl = document.getElementById(`input-${t.id}`);
            const feedbackEl = document.getElementById(`feedback-${t.id}`);
            if (btn && inputEl && feedbackEl) {
                btn.addEventListener('click', () => {
                    if (!inputEl.disabled) {
                        checkAnswer(t.id, inputEl.value, t.suggestedAnswer, inputEl, feedbackEl);
                        btn.disabled = true;
                    }
                });
            }
            if (resetBtn && inputEl && feedbackEl) {
                resetBtn.addEventListener('click', () => {
                    resetCard(t.id, inputEl, feedbackEl);
                    const checkBtn = document.querySelector(`.check-btn[data-id="${t.id}"]`);
                    if (checkBtn) checkBtn.disabled = false;
                });
            }
        });
    }

    searchInput.addEventListener('input', renderCards);
    categorySelect.addEventListener('change', renderCards);
    renderCards();
    updateGlobalProgress();
</script>
</body>
</html>

