<body>
<div class="container">
    <div class="hero">
        <h1>🗣️ Fonologías Estructuralistas · 100 técnicas del castellano</h1>
        <p>Fonología diacrónica y sincrónica · Árboles históricos · Morfología · Clases de palabras · Formación léxica</p>
    </div>
    <div class="stats-progress">
        <span>📚 Inventario: <strong id="totalCount">100</strong> entradas</span>
        <div class="progress-area">
            <span>🏆 Progreso global:</span>
            <div class="progress-bar-container">
                <div class="progress-fill" id="globalProgressFill"></div>
            </div>
            <span id="progressPercent">0%</span>
        </div>
        <span class="badge">🔊 Lector de voz · ✍️ Ejercicios fonológicos</span>
    </div>
    <div class="filter-bar">
        <input type="text" id="searchInput" placeholder="🔍 Buscar por nombre, categoría o concepto...">
        <select id="categorySelect">
            <option value="all">📌 Todas las categorías</option>
            <option value="Fonología estructural">🗣️ Fonología estructural (sincronía/diacronía, sistema)</option>
            <option value="Estructura arbórea histórica">🌳 Estructura arbórea histórica (evolución fonética)</option>
            <option value="Flexión">🎭 Morfología flexiva</option>
            <option value="Derivación">⚙️ Derivación</option>
            <option value="Formación de palabras">🧩 Formación de palabras</option>
            <option value="Clases de palabras">📂 Clases de palabras</option>
            <option value="Accidentes gramaticales">⚡ Accidentes gramaticales</option>
            <option value="Morfemática">🧬 Morfemática</option>
            <option value="Sufijos apreciativos">✨ Sufijos apreciativos</option>
        </select>
    </div>
    <div id="cardsContainer" class="cards-grid"></div>
    <div class="footer-note">
        ✅ Enfoque estructuralista (Escuela de Praga, Saussure, Trubetzkoy, Martinet): fonología como sistema de oposiciones, árboles genealógicos, cambios fonéticos regulares.<br>
        🧠 Incluye fonética articulatoria, evolución histórica del español, morfología flexiva/derivativa, clases de palabras, formación léxica y morfemática.
    </div>
</div>

<script>
    // --------------------------------------------------------------
    // 100 TÉCNICAS DE FONOLOGÍAS ESTRUCTURALISTAS + MORFOLOGÍA
    // Fonología diacrónica (evolución histórica), sincrónica (sistema actual),
    // árboles genealógicos del español, reglas fonológicas,
    // más morfología flexiva/derivativa, clases de palabras, formación léxica,
    // accidentes gramaticales y morfemática.
    // --------------------------------------------------------------
    const techniques = [];

    function add(id, name, category, teoria, ejemplo, ejercicio, suggestedAnswer) {
        techniques.push({ id, name, category, teoria, ejemplo, ejercicio, suggestedAnswer });
    }

    // ========= 1. FONOLOGÍA ESTRUCTURAL (sincrónica, diacrónica, sistema de oposiciones) =========
    add(1, "Fonología sincrónica", "Fonología estructural", "Estudio del sistema fonológico en un momento dado del tiempo.", "Fonemas del español actual: /p, t, k, b, d, g, f, θ, s, x, tʃ, m, n, ɲ, l, ʎ, r, ɾ, i, e, a, o, u/.", "¿Cuántos fonemas vocálicos tiene el español estándar?", "5");
    add(2, "Fonología diacrónica", "Fonología estructural", "Estudio de la evolución de los sistemas fonológicos a través del tiempo.", "Del latín al castellano: pérdida de cantidad vocálica, creación de nuevas consonantes.", "¿Qué fenómeno eliminó las vocales largas del latín?", "pérdida de cantidad vocálica");
    add(3, "Fonema (unidad distintiva)", "Fonología estructural", "Unidad fonológica mínima que puede diferenciar significados.", "/p/ y /b/ diferencian 'piso' y 'biso'.", "¿Qué fonema diferencia 'casa' de 'caza' en zonas con distinción?", "/s/ vs /θ/");
    add(4, "Arquifonema", "Fonología estructural", "Unidad que representa la neutralización de dos o más fonemas.", "En español, /N/ representa la neutralización de /m, n, ɲ/ antes de consonante.", "Arquifonema de /b, d, g/ en posición implosiva", "/B, D, G/");
    add(5, "Rasgos distintivos (Escuela de Praga)", "Fonología estructural", "Propiedades acústicas o articulatorias que definen a los fonemas.", "[±sonoro], [±nasal], [±continuo].", "Rasgo que distingue /p/ de /b/", "[±sonoro]");
    add(6, "Neutralización fonológica", "Fonología estructural", "Cuando la oposición entre dos fonemas desaparece en un contexto.", "/l/ y /r/ se neutralizan en final de sílaba en algunos dialectos: 'arma/ alma'.", "Fonema resultante de neutralización de /s/ y /θ/ en seseo", "/s/");
    add(7, "Oposición fonológica", "Fonología estructural", "Contraste entre fonemas que produce cambio de significado.", "Pino / pito (oposición /n/ vs /t/)", "Ejemplo de oposición entre /l/ y /r/", "pala / para");
    add(8, "Archifonema nasal", "Fonología estructural", "El archifonema /N/ se realiza como [m], [n], [ɲ] según contexto.", "iN+posible → imposible; iN+necesario → innecesario", "Realización de /N/ ante /f/", "[ɱ] labiodental");
    add(9, "Sistema vocálico del castellano", "Fonología estructural", "5 vocales /i, e, a, o, u/ con oposiciones de abertura y localización.", "/i/ y /u/ son vocales altas, /e/ y /o/ medias, /a/ baja.", "¿Cuántas vocales tiene el sistema?", "5");
    add(10, "Sistema consonántico del español", "Fonología estructural", "18-24 fonemas según variante dialectal.", "Oclusivas: /p, t, k, b, d, g/; fricativas: /f, θ, s, x/; africada: /tʃ/; nasales: /m, n, ɲ/; laterales: /l, ʎ/; vibrantes: /r, ɾ/.", "¿Qué fonemas han desaparecido en el yeísmo?", "/ʎ/ se fusiona con /ʝ/");

    // ========= 2. ESTRUCTURA ARBÓREA HISTÓRICA (evolución del latín al castellano) =========
    add(11, "Árbol genealógico romance", "Estructura arbórea histórica", "Evolución desde el latín vulgar hacia las lenguas romances.", "Latín → Romance occidental → Ibero romance → Castellano.", "Rama del árbol del español", "Iberorromance");
    add(12, "Sonorización de oclusivas sordas intervocálicas", "Estructura arbórea histórica", "En latín vulgar, /p, t, k/ se sonorizan a /b, d, g/ entre vocales.", "VITA → vida, APE(S) → abeja, LACU → lago", "Evolución de 'CAPRA'", "cabra");
    add(13, "Pérdida de /f/ inicial (f- → h- → ∅)", "Estructura arbórea histórica", "F inicial latina se convierte en h aspirada y luego muda.", "FABULARE → fablar → hablar", "Palabra que conserva h muda: 'hijo'", "FILIU → fijo → hijo");
    add(14, "Diptongación de E, O abiertas", "Estructura arbórea histórica", "Las vocales latinas /ɛ/ y /ɔ/ diptongan en 'ie' y 'ue'.", "PĒTRA → piedra, FŌCU → fuego", "Diptongo en 'BONU'", "bueno");
    add(15, "Palatalización de /l/ y /n/ ante yod", "Estructura arbórea histórica", "/l/ + /j/ → /ʎ/; /n/ + /j/ → /ɲ/.", "MULJERE → mujer, HISPANIOLA → española", "Resultado de /l/ + /j/", "/ʎ/ (elle)");
    add(16, "Betacismo (confusión B/V)", "Estructura arbórea histórica", "Desde el siglo XVI, /b/ y /v/ se fusionan en español.", "Latín BELLU y VACCA → bello y vaca (sin contraste)", "¿Se distinguen 'bacía' y 'vacía'?", "no, homófonas");
    add(17, "Evolución de los grupos iniciales PL-, CL-, FL-", "Estructura arbórea histórica", "PL-, CL-, FL- se palatalizan a /ʎ/ en la mayor parte del dominio.", "PLANU → llano, CLAVE → llave, FLAMMA → llama", "Evolución de 'PLORARE'", "llorar");
    add(18, "Pérdida de consonantes finales", "Estructura arbórea histórica", "El latín pierde /m/ final y otras consonantes en romance.", "PANEM → pan, CANTARE → cantar", "¿Qué perdió 'AMORE'?", "la e final no, pero ej: AMOR → amor");
    add(19, "Síncopa (pérdida de vocal átona interior)", "Estructura arbórea histórica", "Desaparición de vocales breves en posición interior.", "CALIDU → caldo, DOMINU → dueño", "Evolución de 'LEGITIMA'", "legítima (no síncopa) pero 'légitima'? mejor 'cálido'");
    add(20, "Aféresis (pérdida inicial)", "Estructura arbórea histórica", "Supresión de sonido al principio de palabra.", "APOTHECA → bodega (con evolución), también 'estudiar' sin aféresis.", "Ejemplo de aféresis en 'arena'", "latín ARENA → arena");

    // ========= 3. PROCESOS FONOLÓGICOS SINC RÓNICOS =========
    add(21, "Asimilación de nasal", "Fonología estructural", "La nasal adquiere el punto de articulación de la consonante siguiente.", "iN+posible → imposible, iN+relativo → irrelativo", "Resultado de /n/ antes de /p/", "[m]");
    add(22, "Espirantización de /b, d, g/", "Fonología estructural", "Las oclusivas sonoras se realizan como aproximantes en contexto intervocálico.", "/b/ → [β], /d/ → [ð], /g/ → [ɣ]", "Realización de /d/ en 'nada'", "[ð]");
    add(23, "Yeísmo", "Fonología estructural", "Fusión del fonema palatal lateral /ʎ/ con el fricativo palatal /ʝ/ (representado como y).", "calló / cayó → homófonos", "¿En qué regiones se conserva /ʎ/?", "zonas bilingües (catalán, vasco, gallego) y norte de España");
    add(24, "Seseo", "Fonología estructural", "Fusión de /θ/ con /s/; ambos se realizan como [s].", "casa y caza se pronuncian igual [ˈkasa]", "¿Dónde se da seseo?", "América, Canarias, sur de España");
    add(25, "Ceceo", "Fonología estructural", "Fusión de /s/ con /θ/; ambos se realizan como [θ].", "casa y caza → [ˈkaθa]", "Zona geográfica del ceceo", "sur de Andalucía (Cádiz, Sevilla, Granada)");
    add(26, "Aspiración de /s/ implosiva", "Fonología estructural", "La /s/ al final de sílaba se aspira como [h] en muchos dialectos.", "mosca → [ˈmohka]", "Realización de 'este' en andaluz", "[ˈehte]");
    add(27, "Pérdida de /d/ intervocálica", "Fonología estructural", "La /d/ tiende a desaparecer en participios y palabras cotidianas.", "cansado → cansa'o, partido → partío", "Ejemplo en 'helado'", "helao");
    add(28, "Sonorización de /s/ ante consonante sonora", "Fonología estructural", "En algunos dialectos, /s/ se sonoriza a [z] ante /b, d, g, m, n, l, r/.", "mismo → [ˈmizmo], desde → [ˈdezðe]", "¿En qué variante es común?", "caribeña y andaluza oriental");

    // ========= 4. MORFOLOGÍA FLEXIVA =========
    add(29, "Flexión de género (sustantivos)", "Flexión", "Los sustantivos varían de género con -o/-a u otras marcas.", "niño/niña, poeta/poetisa", "Femenino de 'actor'", "actriz");
    add(30, "Flexión de número (plural)", "Flexión", "Se forma con -s, -es o invariables.", "árbol/árboles, crisis/crisis", "Plural de 'jabalí'", "jabalíes/jabalís");
    add(31, "Pretérito perfecto simple", "Flexión", "Desinencias -é, -aste, -ó, -amos, -asteis, -aron.", "canté, comiste, vivió", "Conjuga 'escribir' en 1ª singular", "escribí");
    add(32, "Modo subjuntivo presente", "Flexión", "Expresa deseo, duda, posibilidad.", "Espero que venga", "Conjuga 'temer' 3ª singular subjuntivo", "tema");
    add(33, "Aspecto perfectivo/imperfectivo", "Flexión", "Perfectivo: acción terminada; imperfectivo: en desarrollo.", "Canté / Cantaba", "Aspecto de 'había comido'", "perfectivo");
    add(34, "Persona verbal", "Flexión", "Desinencias 1ª, 2ª, 3ª persona.", "hablo, hablas, habla", "Persona de 'decían'", "3ª plural");
    add(35, "Futuro de indicativo", "Flexión", "-é, -ás, -á, -emos, -éis, -án.", "hablaré, comerás", "Futuro de 'poner' 2ª singular", "pondrás");
    add(36, "Condicional simple", "Flexión", "-ía, -ías, -ía, -íamos, -íais, -ían.", "cantaría, comerías", "Condicional de 'vivir' 3ª singular", "viviría");
    add(37, "Imperativo afirmativo", "Flexión", "Mandatos.", "¡Canta! ¡Comed!", "Imperativo de 'venir' para vosotros", "venid");

    // ========= 5. DERIVACIÓN =========
    add(38, "Prefijación (negación)", "Derivación", "Prefijos con significado negativo o reversivo.", "inútil, deshacer", "Aplica prefijo 're-' a 'hacer'", "rehacer");
    add(39, "Sufijación -ción", "Derivación", "Sustantivos abstractos deverbales.", "actuación, decisión", "Sustantivo de 'decidir'", "decisión");
    add(40, "Interfijación", "Derivación", "Inserción de segmento no morfemático.", "cafecito (café+c+ito)", "Interfijo en 'polvareda'", "-ar-");
    add(41, "Parasíntesis", "Derivación", "Prefijo + sufijo simultáneos.", "entristecer (en-+triste+-ecer)", "Parasíntesis en 'apiedrar'", "a-+piedra+-ar");
    add(42, "Sufijos aumentativos", "Derivación", "-ón, -azo.", "cabezón, librazo", "Aumentativo de 'coche'", "cochezote");
    add(43, "Sufijo diminutivo (-ito)", "Sufijos apreciativos", "Expresa tamaño pequeño o afecto.", "perrito, mesilla", "Diminutivo de 'flor'", "florecita");
