<script>
    // --------------------------------------------------------------
    // 100 TÉCNICAS DE FONOLOGÍAS ESTRUCTURALISTAS + MORFOLOGÍA
    // Fonología diacrónica (evolución histórica), sincrónica (sistema actual),
    // árboles genealógicos del español, reglas fonológicas,
    // más morfología flexiva/derivativa, clases de palabras, formación léxica,
    // accidentes gramaticales y morfemática.
    // --------------------------------------------------------------
    const techniques = [];

    function add(id, name, category, teoria, ejemplo, ejercicio, suggestedAnswer) {
        techniques.push({ id, name, category, teoria, ejemplo, ejercicio, suggestedAnswer });
    }

    // ========= 1. FONOLOGÍA ESTRUCTURAL (sincrónica, diacrónica, sistema de oposiciones) =========
    add(1, "Fonología sincrónica", "Fonología estructural", "Estudio del sistema fonológico en un momento dado del tiempo.", "Fonemas del español actual: /p, t, k, b, d, g, f, θ, s, x, tʃ, m, n, ɲ, l, ʎ, r, ɾ, i, e, a, o, u/.", "¿Cuántos fonemas vocálicos tiene el español estándar?", "5");
    add(2, "Fonología diacrónica", "Fonología estructural", "Estudio de la evolución de los sistemas fonológicos a través del tiempo.", "Del latín al castellano: pérdida de cantidad vocálica, creación de nuevas consonantes.", "¿Qué fenómeno eliminó las vocales largas del latín?", "pérdida de cantidad vocálica");
