    // ---------------------- PROGRESO LOCALSTORAGE ----------------------
    let userProgress = JSON.parse(localStorage.getItem('fonoEstructuralProgress')) || {};

    function updateGlobalProgress() {
        const total = techniques.length;
        let completed = 0;
        for (let i = 0; i < total; i++) {
            if (userProgress[i+1] === true) completed++;
        }
        const percent = Math.round((completed / total) * 100);
        const fillBar = document.getElementById('globalProgressFill');
        const percentSpan = document.getElementById('progressPercent');
        if (fillBar) fillBar.style.width = percent + '%';
        if (percentSpan) percentSpan.innerText = percent + '%';
    }

    function setCardStatus(cardId, isCorrect) {
        const statusSpan = document.getElementById(`status-${cardId}`);
        if (statusSpan) {
            if (isCorrect) {
                statusSpan.innerHTML = ' ✅';
                statusSpan.style.color = '#2b6e2b';
            } else {
                statusSpan.innerHTML = '';
            }
        }
        userProgress[cardId] = isCorrect;
        localStorage.setItem('fonoEstructuralProgress', JSON.stringify(userProgress));
        updateGlobalProgress();
    }

    function checkAnswer(cardId, userAnswer, correctAnswer, inputElement, feedbackElement) {
        const normalizedUser = userAnswer.trim().toLowerCase().replace(/[¿¡]/g, '');
        const normalizedCorrect = correctAnswer.trim().toLowerCase().replace(/[¿¡]/g, '');
        const isOk = normalizedUser === normalizedCorrect;
        if (isOk) {
            feedbackElement.innerHTML = '✓ ¡Correcto!';
            feedbackElement.className = 'feedback correct';
            setCardStatus(cardId, true);
        } else {
            feedbackElement.innerHTML = `✗ Incorrecto. Respuesta sugerida: "${correctAnswer}"`;
            feedbackElement.className = 'feedback incorrect';
            setCardStatus(cardId, false);
        }
        inputElement.disabled = true;
        inputElement.style.backgroundColor = '#f0f0f0';
    }

    function resetCard(cardId, inputElement, feedbackElement) {
        inputElement.disabled = false;
        inputElement.value = '';
        inputElement.style.backgroundColor = 'white';
        feedbackElement.innerHTML = '';
        feedbackElement.className = 'feedback';
        userProgress[cardId] = false;
        localStorage.setItem('fonoEstructuralProgress', JSON.stringify(userProgress));
        updateGlobalProgress();
        const statusSpan = document.getElementById(`status-${cardId}`);
        if (statusSpan) statusSpan.innerHTML = '';
    }

    function speakText(text) {
        if ('speechSynthesis' in window) {
            speechSynthesis.cancel();
            const utterance = new SpeechSynthesisUtterance(text);
            utterance.lang = 'es-ES';
            utterance.rate = 0.9;
            speechSynthesis.speak(utterance);
        } else {
            alert("Tu navegador no soporta síntesis de voz.");
        }
    }

