    add(35, "Futuro de indicativo", "Flexión", "-é, -ás, -á, -emos, -éis, -án.", "hablaré, comerás", "Futuro de 'poner' 2ª singular", "pondrás");
    add(36, "Condicional simple", "Flexión", "-ía, -ías, -ía, -íamos, -íais, -ían.", "cantaría, comerías", "Condicional de 'vivir' 3ª singular", "viviría");
    add(37, "Imperativo afirmativo", "Flexión", "Mandatos.", "¡Canta! ¡Comed!", "Imperativo de 'venir' para vosotros", "venid");

    // ========= 5. DERIVACIÓN =========
    add(38, "Prefijación (negación)", "Derivación", "Prefijos con significado negativo o reversivo.", "inútil, deshacer", "Aplica prefijo 're-' a 'hacer'", "rehacer");
    add(39, "Sufijación -ción", "Derivación", "Sustantivos abstractos deverbales.", "actuación, decisión", "Sustantivo de 'decidir'", "decisión");
    add(40, "Interfijación", "Derivación", "Inserción de segmento no morfemático.", "cafecito (café+c+ito)", "Interfijo en 'polvareda'", "-ar-");
    add(41, "Parasíntesis", "Derivación", "Prefijo + sufijo simultáneos.", "entristecer (en-+triste+-ecer)", "Parasíntesis en 'apiedrar'", "a-+piedra+-ar");
    add(42, "Sufijos aumentativos", "Derivación", "-ón, -azo.", "cabezón, librazo", "Aumentativo de 'coche'", "cochezote");
    add(43, "Sufijo diminutivo (-ito)", "Sufijos apreciativos", "Expresa tamaño pequeño o afecto.", "perrito, mesilla", "Diminutivo de 'flor'", "florecita");
    add(44, "Sufijo despectivo -ucho", "Derivación", "Indica desprecio.", "pueblucho, medicucho", "Despectivo de 'casa'", "casucha");
    add(45, "Sufijo -ble", "Derivación", "Posibilidad.", "amable, temible", "Adjetivo de 'comprender'", "comprensible");

    // ========= 6. CLASES DE PALABRAS Y FORMACIÓN LÉXICA =========
    add(46, "Sustantivos concretos/abstractos", "Clases de palabras", "Concretos vs abstractos.", "mesa, libertad", "Clasifica 'esperanza'", "abstracto");
    add(47, "Adjetivos calificativos", "Clases de palabras", "Expresan cualidades.", "grande, azul", "Adjetivo en 'mujer hermosa'", "hermosa");
    add(48, "Verbos copulativos", "Clases de palabras", "Ser, estar, parecer.", "Ella es doctora", "Copulativo en 'Luisa parece cansada'", "parece");
    add(49, "Adverbios de modo", "Clases de palabras", "-mente o invariables.", "rápidamente, bien", "Adverbio de 'feliz'", "felizmente");
    add(50, "Preposiciones", "Clases de palabras", "a, ante, bajo, con, contra, de, desde, en, entre, hacia, hasta, para, por, según, sin, so, sobre, tras.", "Voy a Madrid", "Preposición de destino", "a");
    add(51, "Conjunciones", "Clases de palabras", "y, pero, porque.", "Juan y Pedro", "Adversativa en 'Quiero ir ___ no puedo'", "pero");
    add(52, "Determinantes demostrativos", "Clases de palabras", "este, ese, aquel.", "Ese libro", "Determinante en 'Aquellos días'", "aquellos");
    add(53, "Pronombres átonos", "Clases de palabras", "me, te, se, lo, la, le, nos, os, los, las, les.", "Se lo di", "Acusativo para 'el libro'", "lo");
    add(54, "Composición propia", "Formación de palabras", "Unión de dos lexemas.", "pelirrojo (pelo+rojo)", "Analiza 'cortafuegos'", "verbo + sustantivo");
    add(55, "Acronimia y siglación", "Formación de palabras", "OTAN, RENFE, DGT, IVA.", "Significado de 'RENFE'", "Red Nacional de Ferrocarriles Españoles");

    // ========= 7. ACCIDENTES GRAMATICALES Y MORFEMÁTICA =========
    add(56, "Accidente de género", "Accidentes gramaticales", "Masculino/femenino.", "el mar / la mar", "Femenino de 'el poeta'", "la poetisa");
    add(57, "Número gramatical", "Accidentes gramaticales", "Singular/plural.", "detalle → detalles", "Plural de 'jabalí'", "jabalíes");
    add(58, "Persona verbal", "Accidentes gramaticales", "1ª, 2ª, 3ª.", "soy, eres, es", "Persona de 'corrieron'", "3ª plural");
    add(59, "Tiempo absoluto", "Accidentes gramaticales", "Presente, pasado, futuro.", "como, comí, comeré", "Tiempo de 'había soñado'", "pretérito pluscuamperfecto");
