    add(61, "Grado del adjetivo", "Accidentes gramaticales", "Positivo, comparativo, superlativo.", "alto, más alto que, altísimo", "Superlativo de 'fuerte'", "fortísimo");
    add(62, "Lexema o raíz", "Morfemática", "Núcleo semántico.", "cant- en 'cantamos'", "Lexema de 'floristería'", "flor-");
    add(63, "Morfema flexivo de tiempo", "Morfemática", "Desinencia de tiempo.", "cantaba: -ba", "Morfema de futuro en 'comerás'", "-ás");
    add(64, "Alomorfo de plural", "Morfemática", "Variantes: -s, -es, cero.", "soles, crisis", "Alomorfo plural de 'lunes'", "cero");
    add(65, "Alomorfo de género femenino", "Morfemática", "-a, -isa, -ina, -triz.", "actriz, princesa", "Alomorfo en 'emperatriz'", "-triz");
    add(66, "Tema verbal", "Morfemática", "Raíz + vocal temática.", "cant-a-", "Tema de 'partir'", "part-");
    add(67, "Base morfológica", "Morfemática", "Base sobre reglas derivacionales.", "claro → claridad", "Base de 'fortalecer'", "fort-");
    add(68, "Interfijo", "Morfemática", "Elemento sin significado.", "humareda (-ar-)", "Interfijo en 'huesecillo'", "-ec-");
    add(69, "Morfema cero", "Morfemática", "Categoría sin marca.", "singular en 'mesa'", "Marca de singular en 'cactus'", "cero");

    // ========= 8. MÁS PROCESOS FONOLÓGICOS Y ESTRUCTURAS (hasta 100) =========
    add(70, "Metátesis histórica", "Estructura arbórea histórica", "Cambio de orden de sonidos.", "CROCODILE → cocodrilo", "Ejemplo de metátesis en 'palabra'", "parabla");
    add(71, "Prótesis de e-", "Estructura arbórea histórica", "Adición de e- ante grupos con s + consonante.", "Latín SPATHA → espada, STATUS → estado", "Palabra con prótesis: 'esfera'", "del latín SPHAERA");
    add(72, "Epéntesis de /d/ en grupos cultos", "Fonología estructural", "Inserción de /d/ en combinaciones como 'n+d' o 'l+d'.", "cuidado, peligro (del latín cogitatu, periculu) → no es epéntesis", "Ejemplo: 'faldas' no. Mejor 'caldo' (CALIDU)");
    add(73, "Evolución de los grupos -MB-, -ND-", "Estructura arbórea histórica", "Se simplifican perdiendo la nasal en castellano antiguo.", "LUMBU → lomo", "Evolución de 'CUMBA'", "coma (ant.)");
    add(74, "Árbol de las sibilantes medievales", "Estructura arbórea histórica", "El español medieval tenía un sistema de seis sibilantes: /s/, /z/, /ʃ/, /ʒ/, /ts/, /dz/.", "Pasó al sistema actual con /s/, /θ/, /x/.", "¿Qué sonido se perdió completamente?", "la fricativa alveolar sonora /z/");
    add(75, "Reajuste de las sibilantes (siglos XVI-XVII)", "Estructura arbórea histórica", "Las sibilantes medievales se reestructuraron en el sistema actual.", "La antigua /ʃ/ se convirtió en /x/ (j).", "¿Qué fonema moderno proviene de /ʒ/?", "/x/ (en posición final de palabra, luego /x/ general)");
    add(76, "Ensordecimiento de sibilantes sonoras", "Fonología estructural", "Las sibilantes sonoras medievales (/z/, /ʒ/, /dz/) se ensordecieron.", "/z/ → /s/, /ʒ/ → /ʃ/, /dz/ → /ts/ → /θ/", "Resultado de /dz/ en el español moderno", "/θ/");
    add(77, "Fonotáctica del español actual", "Fonología estructural", "Restricciones en combinaciones de sonidos.", "No puede haber /tl/ al inicio de palabra (excepto préstamos).", "¿Es válida 'tl' en 'tlatoani'?", "sí, préstamo del náhuatl");
    add(78, "Estructura silábica preferida (CV)", "Fonología estructural", "La sílaba universal tiende a ser consonante+ vocal.", "Casa: CV.CV", "¿Cuántas sílabas tiene 'transporte'?", "tres: trans.por.te");
    add(79, "Acento prosódico (función distintiva)", "Fonología estructural", "El acento puede diferenciar palabras.", "término, termino, terminó", "Clase de palabra según acento de 'café'", "aguda");
    add(80, "Monoptongación", "Estructura arbórea histórica", "Reducción de diptongo a vocal simple.", "AU → o (cauda → cola, faux → foz)", "Evolución de 'AURU'", "oro");
    add(81, "Palatalización de velares ante e,i", "Estructura arbórea histórica", "C + e,i → (t)θ o x.", "CĪNU → ceniza, GENTE → gente", "Resultado de 'CERVU'", "ciervo");
    add(82, "Abertura vocálica en hiato", "Fonología estructural", "Vocales en hiato se mantienen en sílabas separadas.", "poeta [po.ˈe.ta]", "¿Diptongo o hiato en 'caer'?", "hiato (ca.er)");
    add(83, "Derivación con sufijo -ero", "Derivación", "pan → panadero", "Oficio de 'caja'", "cajero");
    add(84, "Prefijo mono-", "Formación de palabras", "monolito, monótono", "Mono- + 'cromático'", "monocromático");
    add(85, "Sufijo -ancia", "Derivación", "importancia, dependencia", "Sustantivo de 'confiar'", "confianza");
    add(86, "Interfijo -it-", "Morfemática", "abuelito (abuel+it+o)", "Interfijo en 'jovencito'", "-enc-");
    add(87, "Prefijo ex-", "Derivación", "exmarido, expresidente", "Palabra con ex- + 'alumno'", "exalumno");
    add(88, "Futuro de subjuntivo", "Flexión", "Si así fuere...", "Futuro subjuntivo de 'ser'", "fuere");
    add(89, "Gerundio compuesto", "Flexión", "Habiendo comido", "Gerundio compuesto de 'hablar'", "habiendo hablado");
    add(90, "Oración con 'sino'", "Gramática", "No es alto, sino bajo.", "Completa: 'No estudió, ___ durmió'", "sino");
    add(91, "Complemento de régimen", "Gramática", "Carecer de, arrepentirse de", "CRV en 'Se acordó de nosotros'", "de nosotros");
    add(92, "Verbo pronominal", "Accidentes gramaticales", "Se arrepintió.", "Analiza 'Se durmió'", "pronominal reflexivo");
    add(93, "Alternancia vocálica", "Morfemática", "contar → cuento", "Alternancia en 'dormir'", "duermo (o→ue)");
    add(94, "Sustantivo epiceno", "Clases de palabras", "la jirafa (macho/hembra)", "Epiceno: 'el lince' hembra", "la lince");
    add(95, "Interjección impropia", "Clases de palabras", "¡Cielos! ¡Vaya!", "Interjección de admiración", "¡Oh!");
    add(96, "Oración exclamativa indirecta", "Gramática", "Dime qué bonito es.", "Exclamativa indirecta en 'Me asombra lo rápido que corre'", "lo rápido que corre");
    add(97, "Concesiva con 'por más que'", "Gramática", "Por más que estudies, no aprobarás.", "Concesiva con 'por mucho que'", "Por mucho que corras, llegarás tarde");
    add(98, "Oración enfática (ser + que)", "Gramática", "Fue Juan quien lo dijo.", "Enfatiza el objeto: 'Compré el coche'", "Fue el coche lo que compré");
    add(99, "Apócope", "Flexión", "buen (bueno), gran (grande)", "Apócope de 'malo' ante 'momento'", "mal");
    add(100, "Préstamo fonológico", "Fonología estructural", "Adopción de sonidos extranjeros.", "En español, palabras como 'show' introducen /ʃ/ en préstamos.", "¿El fonema /ʃ/ es nativo del español?", "no, solo en préstamos");

    // ---------------------- PROGRESO LOCALSTORAGE ----------------------
    let userProgress = JSON.parse(localStorage.getItem('fonoEstructuralProgress')) || {};

    function updateGlobalProgress() {
        const total = techniques.length;
        let completed = 0;
        for (let i = 0; i < total; i++) {
            if (userProgress[i+1] === true) completed++;
        }
        const percent = Math.round((completed / total) * 100);
        const fillBar = document.getElementById('globalProgressFill');
        const percentSpan = document.getElementById('progressPercent');
        if (fillBar) fillBar.style.width = percent + '%';
        if (percentSpan) percentSpan.innerText = percent + '%';
    }

    function setCardStatus(cardId, isCorrect) {
        const statusSpan = document.getElementById(`status-${cardId}`);
        if (statusSpan) {
            if (isCorrect) {
                statusSpan.innerHTML = ' ✅';
                statusSpan.style.color = '#2b6e2b';
            } else {
                statusSpan.innerHTML = '';
            }
        }
        userProgress[cardId] = isCorrect;
        localStorage.setItem('fonoEstructuralProgress', JSON.stringify(userProgress));
        updateGlobalProgress();
    }

    function checkAnswer(cardId, userAnswer, correctAnswer, inputElement, feedbackElement) {
        const normalizedUser = userAnswer.trim().toLowerCase().replace(/[¿¡]/g, '');
        const normalizedCorrect = correctAnswer.trim().toLowerCase().replace(/[¿¡]/g, '');
        const isOk = normalizedUser === normalizedCorrect;
        if (isOk) {
            feedbackElement.innerHTML = '✓ ¡Correcto!';
            feedbackElement.className = 'feedback correct';
            setCardStatus(cardId, true);
        } else {
            feedbackElement.innerHTML = `✗ Incorrecto. Respuesta sugerida: "${correctAnswer}"`;
            feedbackElement.className = 'feedback incorrect';
            setCardStatus(cardId, false);
        }
        inputElement.disabled = true;
        inputElement.style.backgroundColor = '#f0f0f0';
    }

    function resetCard(cardId, inputElement, feedbackElement) {
        inputElement.disabled = false;
        inputElement.value = '';
        inputElement.style.backgroundColor = 'white';
        feedbackElement.innerHTML = '';
        feedbackElement.className = 'feedback';
        userProgress[cardId] = false;
        localStorage.setItem('fonoEstructuralProgress', JSON.stringify(userProgress));
        updateGlobalProgress();
        const statusSpan = document.getElementById(`status-${cardId}`);
        if (statusSpan) statusSpan.innerHTML = '';
    }

    function speakText(text) {
        if ('speechSynthesis' in window) {
            speechSynthesis.cancel();
            const utterance = new SpeechSynthesisUtterance(text);
            utterance.lang = 'es-ES';
            utterance.rate = 0.9;
            speechSynthesis.speak(utterance);
        } else {
            alert("Tu navegador no soporta síntesis de voz.");
        }
    }

    // Renderizado
    document.getElementById('totalCount').innerText = techniques.length;
    const container = document.getElementById('cardsContainer');
    const searchInput = document.getElementById('searchInput');
    const categorySelect = document.getElementById('categorySelect');

    function renderCards() {
        const searchTerm = searchInput.value.toLowerCase();
        const selectedCat = categorySelect.value;
        const filtered = techniques.filter(t => {
            const matchSearch = t.name.toLowerCase().includes(searchTerm) ||
                                t.category.toLowerCase().includes(searchTerm) ||
                                t.teoria.toLowerCase().includes(searchTerm);
            const matchCat = selectedCat === 'all' || t.category === selectedCat;
            return matchSearch && matchCat;
        });

        if (filtered.length === 0) {
            container.innerHTML = `<div style="grid-column:1/-1; text-align:center;padding:3rem;">🔍 No hay técnicas con esos filtros.</div>`;
            return;
        }

        container.innerHTML = filtered.map(item => {
            const isCompleted = userProgress[item.id] === true;
            return `
            <div class="card">
                <div class="card-header">
                    <h3>#${item.id} · ${item.name} <span id="status-${item.id}" class="status-icon">${isCompleted ? '✅' : ''}</span></h3>
                    <span class="category-tag">${item.category}</span>
                </div>
                <div class="card-body">
                    <div class="teoria">
                        <span>📘 ${item.teoria}</span>
                        <button class="btn-speak" data-teoria="${item.teoria.replace(/"/g, '&quot;')}">🔊 Leer teoría</button>
                    </div>
                    <div class="ejemplo">
                        <span>💡 ${item.ejemplo}</span>
                        <button class="btn-speak-ejemplo" data-ejemplo="${item.ejemplo.replace(/"/g, '&quot;')}">🔊 Leer ejemplo</button>
                    </div>
                    <div class="ejercicio-area">
                        <div class="ejercicio-text">✏️ Ejercicio: ${item.ejercicio}</div>
                        <div class="input-group">
                            <input type="text" id="input-${item.id}" placeholder="Escribe tu respuesta..." ${isCompleted ? 'disabled' : ''}>
                            <button class="check-btn" data-id="${item.id}" ${isCompleted ? 'disabled' : ''}>Comprobar</button>
                        </div>
                        <div id="feedback-${item.id}" class="feedback"></div>
                        <button class="reset-card-btn" data-reset="${item.id}">⟳ Reiniciar ejercicio</button>
                    </div>
                </div>
            </div>
            `;
        }).join('');

        document.querySelectorAll('.btn-speak').forEach(btn => {
            btn.addEventListener('click', (e) => {
                const text = btn.getAttribute('data-teoria');
                if (text) speakText(text);
            });
        });
        document.querySelectorAll('.btn-speak-ejemplo').forEach(btn => {
            btn.addEventListener('click', (e) => {
                const text = btn.getAttribute('data-ejemplo');
                if (text) speakText(text);
            });
        });

        techniques.forEach(t => {
            const btn = document.querySelector(`.check-btn[data-id="${t.id}"]`);
            const resetBtn = document.querySelector(`.reset-card-btn[data-reset="${t.id}"]`);
            const inputEl = document.getElementById(`input-${t.id}`);
            const feedbackEl = document.getElementById(`feedback-${t.id}`);
            if (btn && inputEl && feedbackEl) {
                btn.addEventListener('click', () => {
                    if (!inputEl.disabled) {
                        checkAnswer(t.id, inputEl.value, t.suggestedAnswer, inputEl, feedbackEl);
                        btn.disabled = true;
                    }
                });
            }
            if (resetBtn && inputEl && feedbackEl) {
                resetBtn.addEventListener('click', () => {
                    resetCard(t.id, inputEl, feedbackEl);
                    const checkBtn = document.querySelector(`.check-btn[data-id="${t.id}"]`);
                    if (checkBtn) checkBtn.disabled = false;
                });
            }
        });
    }

    searchInput.addEventListener('input', renderCards);
    categorySelect.addEventListener('change', renderCards);
    renderCards();
    updateGlobalProgress();
</script>
</body>
</html>

