<body>
<div class="container">
    <div class="hero">
        <h1>🗣️ Fonologías Estructuralistas · 100 técnicas del castellano</h1>
        <p>Fonología diacrónica y sincrónica · Árboles históricos · Morfología · Clases de palabras · Formación léxica</p>
    </div>
    <div class="stats-progress">
        <span>📚 Inventario: <strong id="totalCount">100</strong> entradas</span>
        <div class="progress-area">
            <span>🏆 Progreso global:</span>
            <div class="progress-bar-container">
                <div class="progress-fill" id="globalProgressFill"></div>
            </div>
            <span id="progressPercent">0%</span>
        </div>
        <span class="badge">🔊 Lector de voz · ✍️ Ejercicios fonológicos</span>
    </div>
    <div class="filter-bar">
