                    {nombre:"Texto expositivo: La cultura y la literatura", desc:"La literatura nos conecta con la cultura de los pueblos.", ej:"'Los cuentos y poemas nos enseñan sobre nuestra cultura.'", pregunta:"¿Qué nos enseña la literatura?", respuesta:"Sobre nuestra cultura."}
                ]
            }
        ];

        // ----------------------------- RENDERIZADO DE FAMILIAS Y TÉCNICAS -----------------------------
        const acordeon = document.getElementById('acordeonFamilias');
        const buscador = document.getElementById('buscarTecnica');
        const sinResultados = document.getElementById('sinResultados');
        let allTecnicas = [];

        function renderizarFamilias(familias) {
            acordeon.innerHTML = '';
            let totalTecnicas = 0;
            familias.forEach((familia, idx) => {
                totalTecnicas += familia.tecnicas.length;
                const col = document.createElement('div');
                col.className = 'col-lg-6 mb-3';
                const card = document.createElement('div');
                card.className = 'card card-familia';
                const header = document.createElement('div');
                header.className = 'card-header d-flex justify-content-between align-items-center';
                header.innerHTML = `<span>${familia.nombre}</span><span class="badge badge-tecnicas">${familia.tecnicas.length} técnicas</span>`;
                header.setAttribute('data-bs-toggle', 'collapse');
                header.setAttribute('data-bs-target', '#collapse' + idx);
                header.setAttribute('aria-expanded', 'false');
                const body = document.createElement('div');
                body.className = 'collapse';
                body.id = 'collapse' + idx;
                const inner = document.createElement('div');
                inner.className = 'card-body p-0';
                familia.tecnicas.forEach((tec, i) => {
                    const item = document.createElement('div');
                    item.className = 'tecnica-item';
                    const anotacion = document.createElement('span');
                    anotacion.className = 'tecnica-anotacion';
                    anotacion.textContent = '✎ ' + (i+1);
                    const nombre = document.createElement('div');
                    nombre.className = 'tecnica-nombre';
                    nombre.textContent = tec.nombre;
                    const desc = document.createElement('div');
                    desc.className = 'tecnica-desc';
                    desc.textContent = tec.desc;
                    const ejemplo = document.createElement('div');
                    ejemplo.className = 'tecnica-ejemplo';
                    ejemplo.textContent = '📝 ' + tec.ej;
                    const preguntaDiv = document.createElement('div');
                    preguntaDiv.style.cssText = 'font-weight:500; color:#B3242A; margin-top:0.5rem; font-size:0.85rem;';
                    preguntaDiv.textContent = '❓ ' + tec.pregunta;
                    const respuestaDiv = document.createElement('div');
                    respuestaDiv.style.cssText = 'font-weight:400; color:#1A1A1A; margin-top:0.2rem; font-size:0.85rem; border-top:1px dashed #d9d5ce; padding-top:0.3rem;';
                    respuestaDiv.textContent = '💡 ' + tec.respuesta;

                    // Botón de audio
                    const audioDiv = document.createElement('div');
                    audioDiv.style.cssText = 'margin-top:0.3rem;';
                    const btnSpeak = document.createElement('button');
                    btnSpeak.className = 'btn-speak';
                    btnSpeak.innerHTML = '🔊 Escuchar';
                    const textoCompleto = `${tec.nombre}. ${tec.desc}. Ejemplo: ${tec.ej}. Pregunta: ${tec.pregunta}. Respuesta: ${tec.respuesta}`;
                    btnSpeak.addEventListener('click', function(e) {
                        e.stopPropagation();
                        speakText(textoCompleto, this);
                    });
                    audioDiv.appendChild(btnSpeak);

                    item.appendChild(anotacion);
                    item.appendChild(nombre);
                    item.appendChild(desc);
                    item.appendChild(ejemplo);
                    item.appendChild(preguntaDiv);
                    item.appendChild(respuestaDiv);
                    item.appendChild(audioDiv);
                    inner.appendChild(item);
                    // Guardar para búsqueda y quiz
                    allTecnicas.push({familia: familia.nombre, ...tec});
                });
                body.appendChild(inner);
                card.appendChild(header);
                card.appendChild(body);
                col.appendChild(card);
                acordeon.appendChild(col);
            });
        }

        renderizarFamilias(familiasData);

        // Búsqueda
        buscador.addEventListener('input', function() {
            const q = this.value.trim().toLowerCase();
            let hay = false;
            const cards = acordeon.querySelectorAll('.card-familia');
            cards.forEach(card => {
                const items = card.querySelectorAll('.tecnica-item');
                let visible = false;
                items.forEach(item => {
                    const texto = item.textContent.toLowerCase();
                    if (q === '' || texto.includes(q)) {
                        item.style.display = 'block';
                        visible = true;
                    } else {
                        item.style.display = 'none';
                    }
                });
                if (visible) {
                    card.style.display = 'block';
                    hay = true;
                } else {
                    card.style.display = 'none';
                }
            });
            sinResultados.style.display = hay ? 'none' : 'block';
        });

        // ----------------------------- QUIZ -----------------------------
        let preguntas = [];
        let indicePregunta = 0;
        let aciertos = 0;
        let racha = 0;
        let totalIntentos = 0;
        let respondido = false;

        function generarPreguntas() {
            const seleccionadas = [];
            const copia = [...allTecnicas];
            for (let i = copia.length - 1; i > 0; i--) {
                const j = Math.floor(Math.random() * (i + 1));
                [copia[i], copia[j]] = [copia[j], copia[i]];
            }
            for (let i = 0; i < Math.min(10, copia.length); i++) {
                seleccionadas.push(copia[i]);
            }
            preguntas = seleccionadas.map(tec => {
                const correcta = tec.respuesta;
                const otros = allTecnicas.filter(t => t.respuesta !== correcta);
                const opciones = [correcta];
                const shuffled = otros.sort(() => Math.random() - 0.5);
                for (let i = 0; i < 3 && i < shuffled.length; i++) {
                    opciones.push(shuffled[i].respuesta);
                }
                const opcionesMezcladas = opciones.sort(() => Math.random() - 0.5);
                return {
                    tecnica: tec,
                    opciones: opcionesMezcladas,
                    correcta: correcta,
                    preguntaTexto: tec.pregunta
                };
            });
            indicePregunta = 0;
            aciertos = 0;
            racha = 0;
            totalIntentos = 0;
            actualizarMarcadores();
        }

        function mostrarPregunta() {
            if (indicePregunta >= preguntas.length) {
                document.getElementById('preguntaTexto').textContent = '🎉 ¡Has completado todas las preguntas!';
                document.getElementById('opcionesFragmentos').innerHTML = '';
                document.getElementById('feedbackQuiz').innerHTML = `<div class="alert alert-success">Total aciertos: ${aciertos} de ${preguntas.length}. ¡Sigue practicando!</div>`;
                document.getElementById('btnSiguiente').style.display = 'none';
                return;
            }
            const p = preguntas[indicePregunta];
            document.getElementById('preguntaTexto').textContent = `❓ ${p.preguntaTexto}`;
            const contenedor = document.getElementById('opcionesFragmentos');
            contenedor.innerHTML = '';
            p.opciones.forEach(op => {
                const col = document.createElement('div');
                col.className = 'col-12 col-md-6';
                const div = document.createElement('div');
                div.className = 'quiz-option';
                div.textContent = op;
                div.dataset.opcion = op;
                div.addEventListener('click', function() {
                    if (respondido) return;
                    respondido = true;
                    totalIntentos++;
                    const esCorrecta = op === p.correcta;
                    if (esCorrecta) {
                        aciertos++;
                        racha++;
                        this.classList.add('correcta');
                    } else {
                        racha = 0;
                        this.classList.add('incorrecta');
                        document.querySelectorAll('.quiz-option').forEach(el => {
                            if (el.dataset.opcion === p.correcta) {
                                el.classList.add('correcta');
                            }
                        });
                    }
                    actualizarMarcadores();
                    document.getElementById('feedbackQuiz').innerHTML = esCorrecta
                        ? `<div class="alert alert-success">✅ ¡Correcto! ${p.correcta}</div>`
                        : `<div class="alert alert-danger">❌ Incorrecto. La respuesta correcta era: ${p.correcta}</div>`;
                    document.getElementById('btnSiguiente').style.display = 'block';
                });
                col.appendChild(div);
                contenedor.appendChild(col);
            });
            document.getElementById('feedbackQuiz').innerHTML = '';
            document.getElementById('btnSiguiente').style.display = 'none';
            respondido = false;
        }

        function actualizarMarcadores() {
            document.getElementById('contadorAciertos').textContent = aciertos;
            document.getElementById('contadorRacha').textContent = racha;
            document.getElementById('contadorTotal').textContent = totalIntentos;
        }

        document.getElementById('btnSiguiente').addEventListener('click', function() {
            indicePregunta++;
            mostrarPregunta();
        });

        // Iniciar quiz
        generarPreguntas();
        mostrarPregunta();

        // Regenerar preguntas al cambiar a la pestaña Practicar
        document.querySelector('button[data-bs-target="#practicarTab"]').addEventListener('shown.bs.tab', function() {
            generarPreguntas();
            mostrarPregunta();
        });

        // Fecha
        document.getElementById('fechaHoy').textContent = new Date().toLocaleDateString('es-CO', { year: 'numeric', month: 'long', day: 'numeric' });

        console.log('📚 Redacción Castellana · 5° grado · MEN · 100 técnicas cargadas');
    })();
</script>

</body>
</html>

