<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script>
<script>
    (function() {
        // ----------------------------- LECTOR DE VOZ -----------------------------
        let currentSpeaker = null;
        let currentUtterance = null;

        function speakText(text, button) {
            if (!window.speechSynthesis) {
                alert('Tu navegador no soporta la síntesis de voz.');
                return;
            }

            if (currentSpeaker === button && speechSynthesis.speaking) {
                speechSynthesis.cancel();
                button.classList.remove('speaking');
                button.innerHTML = '🔊 Escuchar';
                currentSpeaker = null;
                return;
            }

            if (speechSynthesis.speaking) {
                speechSynthesis.cancel();
                if (currentSpeaker) {
                    currentSpeaker.classList.remove('speaking');
                    currentSpeaker.innerHTML = '🔊 Escuchar';
                }
            }

            const utterance = new SpeechSynthesisUtterance(text);
            utterance.lang = 'es-ES';
            utterance.rate = 0.85;
            utterance.pitch = 1.1;

            utterance.onend = function() {
                if (button) {
                    button.classList.remove('speaking');
                    button.innerHTML = '🔊 Escuchar';
                }
                currentSpeaker = null;
            };

            utterance.onerror = function() {
                if (button) {
                    button.classList.remove('speaking');
                    button.innerHTML = '🔊 Escuchar';
                }
                currentSpeaker = null;
            };

            speechSynthesis.speak(utterance);
            button.classList.add('speaking');
            button.innerHTML = '⏹️ Detener';
            currentSpeaker = button;
            currentUtterance = utterance;
        }

        // ----------------------------- DATOS DE 100 TÉCNICAS (10 por familia) -----------------------------
        const familiasData = [
            {
                nombre: "A. La narración y sus elementos",
                tecnicas: [
                    {nombre:"Estructura de la narración: inicio, nudo y desenlace", desc:"Toda narración tiene tres partes: inicio (presentación), nudo (conflicto) y desenlace (resolución).", ej:"'Inicio: Había una vez un niño llamado Tomás. Nudo: Tomás perdió su perro. Desenlace: Lo encontró felizmente.'", pregunta:"¿Cuáles son las tres partes de una narración?", respuesta:"Inicio, nudo y desenlace."},
                    {nombre:"El narrador en primera persona", desc:"El narrador en primera persona cuenta la historia usando 'yo'.", ej:"'Yo vi cómo el perro saltaba la cerca.'", pregunta:"¿Qué persona usa el narrador en primera persona?", respuesta:"Usa 'yo'."},
                    {nombre:"El narrador en tercera persona", desc:"El narrador en tercera persona cuenta la historia usando 'él' o 'ella'.", ej:"'Tomás vio cómo su perro saltaba la cerca.'", pregunta:"¿Qué persona usa el narrador en tercera persona?", respuesta:"Usa 'él' o 'ella'."},
                    {nombre:"Los personajes en la narración", desc:"Los personajes son los seres que realizan acciones en la historia.", ej:"'Tomás y su perro son los personajes principales.'", pregunta:"¿Qué son los personajes?", respuesta:"Los seres que realizan acciones en la historia."},
                    {nombre:"El diálogo en la narración", desc:"El diálogo es la conversación entre personajes.", ej:"'—¿Dónde está mi perro? —preguntó Tomás.'", pregunta:"¿Qué es el diálogo?", respuesta:"La conversación entre personajes."},
                    {nombre:"El tiempo y el espacio en la narración", desc:"El espacio es el lugar y el tiempo indica cuándo ocurre la historia.", ej:"'La historia ocurre en un pueblo, una tarde de verano.'", pregunta:"¿Qué son el espacio y el tiempo?", respuesta:"El lugar y el momento donde ocurre la historia."},
                    {nombre:"El cuento: características", desc:"El cuento es una narración breve con pocos personajes.", ej:"'El cuento de Tomás y su perro es corto y sencillo.'", pregunta:"¿Qué es un cuento?", respuesta:"Una narración breve con pocos personajes."},
                    {nombre:"La fábula y su enseñanza", desc:"La fábula es un cuento breve que deja una enseñanza o moraleja.", ej:"'La fábula de la liebre y la tortuga enseña que la constancia es importante.'", pregunta:"¿Qué enseñanza deja una fábula?", respuesta:"Una moraleja o enseñanza."},
                    {nombre:"El orden cronológico en la narración", desc:"Los hechos se cuentan en el orden en que ocurrieron.", ej:"'Primero, Tomás perdió a su perro. Luego, lo buscó. Finalmente, lo encontró.'", pregunta:"¿Qué es el orden cronológico?", respuesta:"Contar los hechos en el orden en que ocurrieron."},
                    {nombre:"Texto expositivo: Contar historias", desc:"Contar historias nos permite compartir experiencias y emociones.", ej:"'Contar historias es una forma de comunicarnos y divertirnos.'", pregunta:"¿Por qué contamos historias?", respuesta:"Para compartir experiencias y emociones."}
                ]
            },
            {
                nombre: "B. La descripción de personas, animales y lugares",
                tecnicas: [
                    {nombre:"Describir personas (físico y personalidad)", desc:"Describe cómo es una persona físicamente y cómo es su carácter.", ej:"'Tomás es alto y delgado. Es alegre y curioso.'", pregunta:"¿Qué se describe de una persona?", respuesta:"Su físico y su personalidad."},
                    {nombre:"Describir animales", desc:"Describe cómo es un animal: tamaño, color, qué come, dónde vive.", ej:"'El perro de Tomás es grande, peludo y de color café. Come croquetas y vive en el patio.'", pregunta:"¿Qué se describe de un animal?", respuesta:"Su tamaño, color, alimentación y hábitat."},
                    {nombre:"Describir lugares", desc:"Describe cómo es un lugar: qué hay, cómo es el ambiente.", ej:"'El parque es grande, tiene árboles, flores y un lago.'", pregunta:"¿Qué se describe de un lugar?", respuesta:"Qué hay y cómo es el ambiente."},
                    {nombre:"Usar adjetivos en la descripción", desc:"Los adjetivos describen cualidades de las personas, animales o cosas.", ej:"'El perro grande, peludo y juguetón.'", pregunta:"¿Qué son los adjetivos?", respuesta:"Palabras que describen cualidades."},
                    {nombre:"Usar comparaciones (como)", desc:"Las comparaciones usan la palabra 'como' para describir.", ej:"'Sus ojos brillaban como estrellas.'", pregunta:"¿Qué palabra se usa para comparar?", respuesta:"La palabra 'como'."},
                    {nombre:"Describir objetos", desc:"Describe cómo es un objeto: tamaño, color, forma, material.", ej:"'La mochila es roja, grande y tiene tres bolsillos.'", pregunta:"¿Qué se describe de un objeto?", respuesta:"Su tamaño, color, forma y material."},
                    {nombre:"Describir olores y sonidos", desc:"Los olores y sonidos hacen la descripción más viva.", ej:"'El parque huele a pasto fresco y se escucha el canto de los pájaros.'", pregunta:"¿Qué sentidos se usan en la descripción?", respuesta:"El olfato y el oído."},
                    {nombre:"Organizar la descripción", desc:"Primero describe lo general, luego los detalles.", ej:"'El jardín es grande y verde. Tiene flores de muchos colores.'", pregunta:"¿Cómo se organiza una descripción?", respuesta:"De lo general a lo particular."},
                    {nombre:"El retrato", desc:"El retrato es la descripción completa de una persona.", ej:"'Tomás es un niño de ojos brillantes, cabello castaño, alegre y muy inteligente.'", pregunta:"¿Qué es un retrato?", respuesta:"La descripción completa de una persona."},
                    {nombre:"Texto expositivo: Describir es pintar con palabras", desc:"Describir es pintar imágenes con palabras para que otros imaginen.", ej:"'Describir es como pintar un cuadro con palabras.'", pregunta:"¿Qué es describir?", respuesta:"Pintar imágenes con palabras."}
                ]
            },
            {
                nombre: "C. La argumentación y la opinión",
                tecnicas: [
                    {nombre:"Dar una opinión", desc:"Una opinión es lo que piensas sobre algo.", ej:"'Yo creo que reciclar es importante.'", pregunta:"¿Qué es una opinión?", respuesta:"Lo que piensas sobre algo."},
                    {nombre:"Apoyar la opinión con razones", desc:"Las razones explican por qué piensas así.", ej:"'Creo que reciclar es importante porque cuidamos el medio ambiente.'", pregunta:"¿Qué necesitas para apoyar una opinión?", respuesta:"Razones."},
                    {nombre:"Estructura del texto argumentativo", desc:"Un texto argumentativo tiene: opinión, razones y conclusión.", ej:"'Opinión: Reciclar es importante. Razones: Cuidamos el planeta. Conclusión: Todos debemos reciclar.'", pregunta:"¿Cuáles son las partes de un texto argumentativo?", respuesta:"Opinión, razones y conclusión."},
                    {nombre:"Usar conectores de causa", desc:"Conectores como 'porque' y 'ya que' explican las razones.", ej:"'Reciclamos porque queremos cuidar el planeta.'", pregunta:"¿Qué conectores explican las razones?", respuesta:"Porque, ya que."},
                    {nombre:"Usar ejemplos como razones", desc:"Los ejemplos ayudan a entender mejor las razones.", ej:"'En mi escuela recogemos papel y lo llevamos a reciclar.'", pregunta:"¿Qué recurso ayuda a entender las razones?", respuesta:"Los ejemplos."},
                    {nombre:"El debate", desc:"El debate es una discusión donde se presentan opiniones diferentes.", ej:"'En el debate sobre el reciclaje, unos estaban a favor y otros en contra.'", pregunta:"¿Qué es un debate?", respuesta:"Una discusión con diferentes opiniones."},
                    {nombre:"Escuchar otras opiniones", desc:"Es importante escuchar lo que otros piensan.", ej:"'Escuché a mi compañero y entendí su punto de vista.'", pregunta:"¿Qué es importante hacer en una discusión?", respuesta:"Escuchar a los demás."},
                    {nombre:"La conclusión en la argumentación", desc:"La conclusión es el cierre donde reafirmas tu opinión.", ej:"'Por todo lo anterior, todos debemos reciclar.'", pregunta:"¿Qué hace la conclusión?", respuesta:"Reafirmar tu opinión."},
                    {nombre:"Argumentar con respeto", desc:"Se debe argumentar sin ofender a los demás.", ej:"'Respeto tu opinión, pero yo pienso diferente.'", pregunta:"¿Cómo se debe argumentar?", respuesta:"Con respeto."},
                    {nombre:"Texto expositivo: Argumentar es defender ideas", desc:"Argumentar es defender nuestras ideas con razones.", ej:"'Argumentar es dar razones para convencer a otros.'", pregunta:"¿Qué es argumentar?", respuesta:"Defender ideas con razones."}
                ]
            },
            {
                nombre: "D. La exposición y la explicación",
                tecnicas: [
                    {nombre:"Estructura del texto expositivo", desc:"Un texto expositivo tiene: introducción, desarrollo y conclusión.", ej:"'Introducción: ¿Qué es el reciclaje? Desarrollo: cómo se recicla. Conclusión: importancia del reciclaje.'", pregunta:"¿Cuáles son las partes de un texto expositivo?", respuesta:"Introducción, desarrollo y conclusión."},
                    {nombre:"Definir conceptos", desc:"Explica claramente qué significa un concepto.", ej:"'El reciclaje es convertir desechos en nuevos productos.'", pregunta:"¿Qué es una definición?", respuesta:"La explicación clara de un concepto."},
                    {nombre:"Usar ejemplos en la exposición", desc:"Los ejemplos ayudan a entender mejor.", ej:"'Por ejemplo, el papel reciclado se convierte en nuevo papel.'", pregunta:"¿Qué ayuda a entender mejor?", respuesta:"Los ejemplos."},
                    {nombre:"Organizar la información", desc:"Divide la información en partes.", ej:"'1. ¿Qué es? 2. Tipos. 3. Beneficios.'", pregunta:"¿Cómo se organiza la información?", respuesta:"En partes o subtemas."},
                    {nombre:"Usar conectores de orden", desc:"Conectores como 'primero', 'luego', 'finalmente' organizan.", ej:"'Primero, explicaré qué es. Luego, sus beneficios. Finalmente, cómo hacerlo.'", pregunta:"¿Qué conectores organizan la información?", respuesta:"Primero, luego, finalmente."},
                    {nombre:"Explicar procesos paso a paso", desc:"Explica un proceso en orden.", ej:"'Primero, se recolecta el papel. Segundo, se limpia. Tercero, se convierte en pulpa.'", pregunta:"¿Cómo se explica un proceso?", respuesta:"Paso a paso."},
                    {nombre:"La introducción en la exposición", desc:"La introducción presenta el tema.", ej:"'¿Sabías que podemos reciclar el papel? En este texto aprenderemos cómo.'", pregunta:"¿Qué hace la introducción?", respuesta:"Presenta el tema."},
                    {nombre:"La conclusión en la exposición", desc:"La conclusión resume lo más importante.", ej:"'En conclusión, reciclar es una práctica muy importante.'", pregunta:"¿Qué hace la conclusión?", respuesta:"Resume lo más importante."},
                    {nombre:"Explicar con palabras sencillas", desc:"Usa palabras fáciles de entender.", ej:"'Reciclar es darle una nueva vida a las cosas que ya no usamos.'", pregunta:"¿Cómo se debe explicar?", respuesta:"Con palabras sencillas."},
                    {nombre:"Texto expositivo: Explicar es enseñar", desc:"Explicar es una forma de enseñar a otros.", ej:"'Cuando explicamos, compartimos lo que sabemos.'", pregunta:"¿Qué es explicar?", respuesta:"Enseñar a otros."}
                ]
            },
            {
                nombre: "E. La poesía y la expresión literaria",
                tecnicas: [
                    {nombre:"La poesía y sus características", desc:"La poesía expresa sentimientos y emociones con versos.", ej:"'La poesía usa palabras bonitas para expresar lo que sentimos.'", pregunta:"¿Qué es la poesía?", respuesta:"Una forma de expresar sentimientos con versos."},
                    {nombre:"El verso y la estrofa", desc:"El verso es cada línea; la estrofa es un grupo de versos.", ej:"'Estrofa: 'El sol brilla en el cielo / y las flores se abren / los pájaros vuelan / y el viento las mece.''", pregunta:"¿Qué es un verso y una estrofa?", respuesta:"El verso es una línea; la estrofa es un grupo de versos."},
                    {nombre:"La rima", desc:"La rima es la repetición de sonidos al final de los versos.", ej:"'Rima: 'casa' y 'pasa'.'", pregunta:"¿Qué es la rima?", respuesta:"La repetición de sonidos al final de los versos."},
                    {nombre:"La metáfora", desc:"La metáfora compara dos cosas sin usar 'como'.", ej:"'Tus ojos son estrellas.'", pregunta:"¿Qué es la metáfora?", respuesta:"Una comparación sin usar 'como'."},
                    {nombre:"La personificación", desc:"La personificación da cualidades humanas a animales o cosas.", ej:"'El sol sonríe en el horizonte.'", pregunta:"¿Qué es la personificación?", respuesta:"Dar cualidades humanas a animales o cosas."},
