                document.getElementById('feedbackQuiz').innerHTML = `<div class="alert alert-success">Total aciertos: ${aciertos} de ${preguntas.length}. ¡Sigue practicando!</div>`;
                document.getElementById('btnSiguiente').style.display = 'none';
                return;
            }
            const p = preguntas[indicePregunta];
            document.getElementById('preguntaTexto').textContent = `❓ ${p.preguntaTexto}`;
            const contenedor = document.getElementById('opcionesFragmentos');
            contenedor.innerHTML = '';
            p.opciones.forEach(op => {
                const col = document.createElement('div');
                col.className = 'col-12 col-md-6';
                const div = document.createElement('div');
                div.className = 'quiz-option';
                div.textContent = op;
                div.dataset.opcion = op;
                div.addEventListener('click', function() {
                    if (respondido) return;
                    respondido = true;
                    totalIntentos++;
                    const esCorrecta = op === p.correcta;
                    if (esCorrecta) {
                        aciertos++;
                        racha++;
                        this.classList.add('correcta');
                    } else {
                        racha = 0;
                        this.classList.add('incorrecta');
                        document.querySelectorAll('.quiz-option').forEach(el => {
                            if (el.dataset.opcion === p.correcta) {
                                el.classList.add('correcta');
                            }
                        });
                    }
                    actualizarMarcadores();
                    document.getElementById('feedbackQuiz').innerHTML = esCorrecta
                        ? `<div class="alert alert-success">✅ ¡Correcto! ${p.correcta}</div>`
                        : `<div class="alert alert-danger">❌ Incorrecto. La respuesta correcta era: ${p.correcta}</div>`;
                    document.getElementById('btnSiguiente').style.display = 'block';
                });
                col.appendChild(div);
                contenedor.appendChild(col);
            });
            document.getElementById('feedbackQuiz').innerHTML = '';
            document.getElementById('btnSiguiente').style.display = 'none';
            respondido = false;
        }

        function actualizarMarcadores() {
            document.getElementById('contadorAciertos').textContent = aciertos;
            document.getElementById('contadorRacha').textContent = racha;
            document.getElementById('contadorTotal').textContent = totalIntentos;
        }

        document.getElementById('btnSiguiente').addEventListener('click', function() {
            indicePregunta++;
            mostrarPregunta();
        });

        // Iniciar quiz
        generarPreguntas();
        mostrarPregunta();

        // Regenerar preguntas al cambiar a la pestaña Practicar
        document.querySelector('button[data-bs-target="#practicarTab"]').addEventListener('shown.bs.tab', function() {
            generarPreguntas();
            mostrarPregunta();
        });

        // Fecha
        document.getElementById('fechaHoy').textContent = new Date().toLocaleDateString('es-CO', { year: 'numeric', month: 'long', day: 'numeric' });

        console.log('📚 Redacción Castellana · 5° grado · MEN · 100 técnicas cargadas');
    })();
</script>

</body>
</html>

