                    {nombre:"Texto expositivo: La poesía es sentimiento", desc:"La poesía es una forma de expresar lo que el corazón siente.", ej:"'La poesía es el lenguaje del corazón.'", pregunta:"¿Qué expresa la poesía?", respuesta:"Los sentimientos del corazón."}
                ]
            },
            {
                nombre: "F. Ortografía y gramática",
                tecnicas: [
                    {nombre:"Uso de la 'b'", desc:"La 'b' se usa en palabras como 'bueno', 'hablar'.", ej:"'Bueno, vamos a hablar de las letras.'", pregunta:"¿Cuándo se usa la 'b'?", respuesta:"En palabras como bueno, hablar."},
                    {nombre:"Uso de la 'v'", desc:"La 'v' se usa en palabras como 'verde', 'vosotros'.", ej:"'El verde es mi color favorito.'", pregunta:"¿Cuándo se usa la 'v'?", respuesta:"En palabras como verde, vosotros."},
                    {nombre:"Uso de la 'g'", desc:"La 'g' se usa en palabras como 'gato', 'gente'.", ej:"'El gato juega en el jardín.'", pregunta:"¿Cuándo se usa la 'g'?", respuesta:"En palabras como gato, gente."},
                    {nombre:"Uso de la 'j'", desc:"La 'j' se usa en palabras como 'jugar', 'jarro'.", ej:"'Juego con mi perro en el parque.'", pregunta:"¿Cuándo se usa la 'j'?", respuesta:"En palabras como jugar, jarro."},
                    {nombre:"El punto y la coma", desc:"El punto termina una oración; la coma separa elementos.", ej:"'Compré pan, leche y huevos. Fui a casa.'", pregunta:"¿Qué hace el punto y la coma?", respuesta:"El punto termina; la coma separa."},
                    {nombre:"Los signos de interrogación", desc:"Los signos de interrogación (¿?) se usan en preguntas.", ej:"'¿Cómo estás?'", pregunta:"¿Cuándo se usan los signos de interrogación?", respuesta:"En preguntas."},
                    {nombre:"Los signos de exclamación", desc:"Los signos de exclamación (¡!) expresan sorpresa o emoción.", ej:"'¡Qué bonito es el paisaje!'", pregunta:"¿Cuándo se usan los signos de exclamación?", respuesta:"Para expresar sorpresa o emoción."},
                    {nombre:"Las mayúsculas", desc:"Las mayúsculas se usan al inicio de una oración y en nombres propios.", ej:"'María y Tomás fueron al parque.'", pregunta:"¿Cuándo se usan mayúsculas?", respuesta:"Al inicio de oración y en nombres propios."},
                    {nombre:"La tilde en palabras agudas", desc:"Las palabras agudas llevan tilde si terminan en n, s o vocal.", ej:"'Camión', 'café', 'reloj' (sin tilde).'", pregunta:"¿Cuándo llevan tilde las palabras agudas?", respuesta:"Si terminan en n, s o vocal."},
                    {nombre:"Texto expositivo: Escribir bien es importante", desc:"Escribir bien nos ayuda a comunicarnos mejor.", ej:"'La ortografía es importante para que nos entiendan.'", pregunta:"¿Por qué es importante la ortografía?", respuesta:"Para comunicarnos mejor."}
                ]
            },
            {
                nombre: "G. Comprensión lectora",
                tecnicas: [
                    {nombre:"Identificar la idea principal", desc:"La idea principal es lo más importante del texto.", ej:"'La idea principal del texto es que reciclar es importante.'", pregunta:"¿Qué es la idea principal?", respuesta:"Lo más importante del texto."},
                    {nombre:"Identificar ideas secundarias", desc:"Las ideas secundarias apoyan a la idea principal.", ej:"'Ideas secundarias: reciclar ahorra energía y reduce la basura.'", pregunta:"¿Qué son las ideas secundarias?", respuesta:"Ideas que apoyan la principal."},
                    {nombre:"Hacer inferencias", desc:"Las inferencias son conclusiones que sacamos del texto.", ej:"'El texto dice que llueve mucho. Inferencia: la ciudad tiene inundaciones.'", pregunta:"¿Qué son las inferencias?", respuesta:"Conclusiones que sacamos del texto."},
                    {nombre:"Identificar el tipo de texto", desc:"Identifica si es narrativo, descriptivo, expositivo o argumentativo.", ej:"'El texto es narrativo porque cuenta una historia.'", pregunta:"¿Qué tipos de texto hay?", respuesta:"Narrativo, descriptivo, expositivo y argumentativo."},
                    {nombre:"Identificar el propósito del autor", desc:"El propósito puede ser informar, convencer o entretener.", ej:"'El autor quiere convencer de que reciclemos.'", pregunta:"¿Cuál puede ser el propósito del autor?", respuesta:"Informar, convencer o entretener."},
                    {nombre:"Responder preguntas del texto", desc:"Las preguntas ayudan a verificar la comprensión.", ej:"'¿Qué es el reciclaje?', '¿Por qué es importante reciclar?'", pregunta:"¿Cómo verificamos la comprensión?", respuesta:"Respondiendo preguntas."},
                    {nombre:"Hacer un resumen", desc:"El resumen es la versión corta del texto.", ej:"'El texto habla sobre el reciclaje y su importancia.'", pregunta:"¿Qué es un resumen?", respuesta:"La versión corta de un texto."},
                    {nombre:"Identificar el orden de los hechos", desc:"Identifica qué pasó primero, después y al final.", ej:"'Primero, Tomás perdió a su perro. Después, lo buscó. Finalmente, lo encontró.'", pregunta:"¿Qué orden tienen los hechos?", respuesta:"Cronológico."},
                    {nombre:"El título y su relación con el texto", desc:"El título resume el tema del texto.", ej:"'El título 'El reciclaje' habla sobre el reciclaje.'", pregunta:"¿Qué relación tiene el título con el texto?", respuesta:"Resume el tema."},
                    {nombre:"Texto expositivo: Leer es aprender", desc:"Leer es una herramienta para aprender.", ej:"'A través de la lectura aprendemos muchas cosas.'", pregunta:"¿Qué permite la lectura?", respuesta:"Aprender."}
                ]
            },
            {
                nombre: "H. Producción textual: escribir textos",
                tecnicas: [
                    {nombre:"Planificar antes de escribir", desc:"Antes de escribir, piensa en qué vas a escribir.", ej:"'Planificación: voy a escribir sobre mi perro.'", pregunta:"¿Qué se debe hacer antes de escribir?", respuesta:"Planificar."},
                    {nombre:"Escribir un borrador", desc:"El borrador es la primera versión del texto.", ej:"'Escribí un borrador de mi cuento.'", pregunta:"¿Qué es un borrador?", respuesta:"La primera versión de un texto."},
                    {nombre:"Revisar y corregir", desc:"Después de escribir, revisa la ortografía y la gramática.", ej:"'Revisé mi texto y corregí los errores.'", pregunta:"¿Qué se debe hacer después de escribir?", respuesta:"Revisar y corregir."},
                    {nombre:"Escribir con claridad", desc:"Las ideas deben ser fáciles de entender.", ej:"'Escribí el cuento de manera clara y ordenada.'", pregunta:"¿Cómo deben estar las ideas?", respuesta:"Claras y ordenadas."},
                    {nombre:"Usar conectores", desc:"Los conectores unen las ideas: primero, luego, después.", ej:"'Primero, fui al parque. Luego, jugué con mi perro.'", pregunta:"¿Qué unen los conectores?", respuesta:"Las ideas."},
                    {nombre:"Escribir diferentes tipos de textos", desc:"Se pueden escribir cuentos, poemas, cartas, etc.", ej:"'Escribí un cuento y una carta.'", pregunta:"¿Qué tipos de textos se pueden escribir?", respuesta:"Cuentos, poemas, cartas."},
                    {nombre:"Escribir para otros", desc:"El texto debe ser claro para quien lo lee.", ej:"'Si escribo para niños, uso palabras sencillas.'", pregunta:"¿Cómo se adapta el texto?", respuesta:"Según el lector."},
                    {nombre:"Usar la imaginación", desc:"La imaginación hace los textos más interesantes.", ej:"'Inventé un mundo mágico para mi cuento.'", pregunta:"¿Qué hace los textos más interesantes?", respuesta:"La imaginación."},
                    {nombre:"Escribir un cuento", desc:"Elige un tema, crea personajes y escribe la historia.", ej:"'Escribí un cuento sobre un niño que viaja al espacio.'", pregunta:"¿Cómo se escribe un cuento?", respuesta:"Con personajes y una historia."},
                    {nombre:"Texto expositivo: Escribir es comunicar", desc:"Escribir es una forma de comunicarnos.", ej:"'A través de la escritura compartimos lo que pensamos.'", pregunta:"¿Qué es escribir?", respuesta:"Comunicar."}
                ]
            },
            {
                nombre: "I. Comunicación oral",
                tecnicas: [
                    {nombre:"Hablar en público", desc:"Practica antes de hablar y habla con confianza.", ej:"'Practiqué mi exposición frente al espejo.'", pregunta:"¿Cómo se habla en público?", respuesta:"Con práctica y confianza."},
                    {nombre:"Escuchar atentamente", desc:"Escuchar es tan importante como hablar.", ej:"'Cuando mi compañero habla, lo escucho sin interrumpir.'", pregunta:"¿Qué es escuchar atentamente?", respuesta:"Prestar atención sin interrumpir."},
                    {nombre:"Participar en diálogos", desc:"Participa respetuosamente en las conversaciones.", ej:"'En clase, participé dando mi opinión.'", pregunta:"¿Cómo se participa en un diálogo?", respuesta:"Con respeto."},
                    {nombre:"Expresar ideas con claridad", desc:"Organiza tus ideas antes de hablar.", ej:"'Pensé en lo que iba a decir y luego hablé.'", pregunta:"¿Cómo se expresan ideas con claridad?", respuesta:"Organizándolas antes de hablar."},
                    {nombre:"Usar gestos", desc:"Los gestos ayudan a comunicar.", ej:"'Usé gestos para explicar mejor.'", pregunta:"¿Qué ayudan a comunicar?", respuesta:"Los gestos."},
                    {nombre:"El volumen de voz", desc:"Habla con un volumen adecuado.", ej:"'Hablé fuerte para que todos me escucharan.'", pregunta:"¿Cómo debe ser el volumen de voz?", respuesta:"Adecuado."},
                    {nombre:"Contar anécdotas", desc:"Las anécdotas hacen la comunicación más interesante.", ej:"'Conté una anécdota sobre mi perro.'", pregunta:"¿Qué hace la comunicación más interesante?", respuesta:"Las anécdotas."},
                    {nombre:"Hacer preguntas", desc:"Las preguntas son parte de la comunicación.", ej:"'Hice preguntas para entender mejor.'", pregunta:"¿Qué son las preguntas?", respuesta:"Parte de la comunicación."},
                    {nombre:"Respetar los turnos de habla", desc:"Espera a que el otro termine para hablar.", ej:"'Esperé a que mi compañero terminara para hablar.'", pregunta:"¿Cómo se respetan los turnos de habla?", respuesta:"Esperando a que el otro termine."},
                    {nombre:"Texto expositivo: Comunicarse es importante", desc:"Comunicarse bien es clave para la vida.", ej:"'Comunicarse bien nos ayuda a relacionarnos con los demás.'", pregunta:"¿Por qué es importante comunicarse?", respuesta:"Para relacionarnos con los demás."}
                ]
            },
            {
                nombre: "J. Literatura infantil y cultura",
                tecnicas: [
                    {nombre:"Los cuentos infantiles", desc:"Los cuentos infantiles son historias para niños.", ej:"'Los cuentos de los hermanos Grimm son para niños.'", pregunta:"¿Qué son los cuentos infantiles?", respuesta:"Historias para niños."},
                    {nombre:"Las fábulas", desc:"Las fábulas son cuentos breves con enseñanza.", ej:"'La fábula de la liebre y la tortuga.'", pregunta:"¿Qué son las fábulas?", respuesta:"Cuentos breves con enseñanza."},
                    {nombre:"Las leyendas", desc:"Las leyendas son historias que mezclan realidad y fantasía.", ej:"'La leyenda de El Dorado.'", pregunta:"¿Qué son las leyendas?", respuesta:"Historias que mezclan realidad y fantasía."},
                    {nombre:"Los mitos", desc:"Los mitos explican el origen del mundo y la naturaleza.", ej:"'El mito de la creación del mundo.'", pregunta:"¿Qué son los mitos?", respuesta:"Historias que explican el origen del mundo."},
                    {nombre:"Los poemas infantiles", desc:"Los poemas infantiles son versos para niños.", ej:"'Los poemas de Rafael Pombo.'", pregunta:"¿Qué son los poemas infantiles?", respuesta:"Versos para niños."},
                    {nombre:"La literatura colombiana para niños", desc:"Colombia tiene grandes escritores de literatura infantil.", ej:"'Rafael Pombo es un escritor colombiano de literatura infantil.'", pregunta:"¿Qué escritor colombiano escribió para niños?", respuesta:"Rafael Pombo."},
                    {nombre:"La tradición oral", desc:"La tradición oral son historias que se cuentan de generación en generación.", ej:"'Los abuelos cuentan historias de la tradición oral.'", pregunta:"¿Qué es la tradición oral?", respuesta:"Historias que se cuentan de generación en generación."},
                    {nombre:"Los refranes", desc:"Los refranes son dichos populares con enseñanza.", ej:"'Más vale tarde que nunca.'", pregunta:"¿Qué son los refranes?", respuesta:"Dichos populares con enseñanza."},
                    {nombre:"Las adivinanzas", desc:"Las adivinanzas son juegos de palabras que invitan a pensar.", ej:"'Oro parece, plata no es. ¿Qué es?' (El plátano).'", pregunta:"¿Qué son las adivinanzas?", respuesta:"Juegos de palabras."},
                    {nombre:"Texto expositivo: La cultura y la literatura", desc:"La literatura nos conecta con la cultura de los pueblos.", ej:"'Los cuentos y poemas nos enseñan sobre nuestra cultura.'", pregunta:"¿Qué nos enseña la literatura?", respuesta:"Sobre nuestra cultura."}
                ]
            }
        ];

        // ----------------------------- RENDERIZADO DE FAMILIAS Y TÉCNICAS -----------------------------
        const acordeon = document.getElementById('acordeonFamilias');
        const buscador = document.getElementById('buscarTecnica');
        const sinResultados = document.getElementById('sinResultados');
        let allTecnicas = [];

        function renderizarFamilias(familias) {
            acordeon.innerHTML = '';
            let totalTecnicas = 0;
            familias.forEach((familia, idx) => {
                totalTecnicas += familia.tecnicas.length;
                const col = document.createElement('div');
                col.className = 'col-lg-6 mb-3';
                const card = document.createElement('div');
                card.className = 'card card-familia';
                const header = document.createElement('div');
                header.className = 'card-header d-flex justify-content-between align-items-center';
                header.innerHTML = `<span>${familia.nombre}</span><span class="badge badge-tecnicas">${familia.tecnicas.length} técnicas</span>`;
                header.setAttribute('data-bs-toggle', 'collapse');
                header.setAttribute('data-bs-target', '#collapse' + idx);
                header.setAttribute('aria-expanded', 'false');
                const body = document.createElement('div');
                body.className = 'collapse';
                body.id = 'collapse' + idx;
                const inner = document.createElement('div');
                inner.className = 'card-body p-0';
                familia.tecnicas.forEach((tec, i) => {
                    const item = document.createElement('div');
                    item.className = 'tecnica-item';
                    const anotacion = document.createElement('span');
                    anotacion.className = 'tecnica-anotacion';
                    anotacion.textContent = '✎ ' + (i+1);
                    const nombre = document.createElement('div');
                    nombre.className = 'tecnica-nombre';
                    nombre.textContent = tec.nombre;
                    const desc = document.createElement('div');
                    desc.className = 'tecnica-desc';
                    desc.textContent = tec.desc;
                    const ejemplo = document.createElement('div');
                    ejemplo.className = 'tecnica-ejemplo';
                    ejemplo.textContent = '📝 ' + tec.ej;
                    const preguntaDiv = document.createElement('div');
                    preguntaDiv.style.cssText = 'font-weight:500; color:#B3242A; margin-top:0.5rem; font-size:0.85rem;';
                    preguntaDiv.textContent = '❓ ' + tec.pregunta;
                    const respuestaDiv = document.createElement('div');
                    respuestaDiv.style.cssText = 'font-weight:400; color:#1A1A1A; margin-top:0.2rem; font-size:0.85rem; border-top:1px dashed #d9d5ce; padding-top:0.3rem;';
                    respuestaDiv.textContent = '💡 ' + tec.respuesta;

                    // Botón de audio
                    const audioDiv = document.createElement('div');
                    audioDiv.style.cssText = 'margin-top:0.3rem;';
                    const btnSpeak = document.createElement('button');
                    btnSpeak.className = 'btn-speak';
                    btnSpeak.innerHTML = '🔊 Escuchar';
                    const textoCompleto = `${tec.nombre}. ${tec.desc}. Ejemplo: ${tec.ej}. Pregunta: ${tec.pregunta}. Respuesta: ${tec.respuesta}`;
                    btnSpeak.addEventListener('click', function(e) {
                        e.stopPropagation();
                        speakText(textoCompleto, this);
                    });
                    audioDiv.appendChild(btnSpeak);

                    item.appendChild(anotacion);
                    item.appendChild(nombre);
                    item.appendChild(desc);
                    item.appendChild(ejemplo);
                    item.appendChild(preguntaDiv);
                    item.appendChild(respuestaDiv);
                    item.appendChild(audioDiv);
                    inner.appendChild(item);
                    // Guardar para búsqueda y quiz
                    allTecnicas.push({familia: familia.nombre, ...tec});
                });
                body.appendChild(inner);
                card.appendChild(header);
                card.appendChild(body);
                col.appendChild(card);
                acordeon.appendChild(col);
            });
        }

        renderizarFamilias(familiasData);

        // Búsqueda
        buscador.addEventListener('input', function() {
            const q = this.value.trim().toLowerCase();
            let hay = false;
            const cards = acordeon.querySelectorAll('.card-familia');
            cards.forEach(card => {
                const items = card.querySelectorAll('.tecnica-item');
                let visible = false;
                items.forEach(item => {
                    const texto = item.textContent.toLowerCase();
                    if (q === '' || texto.includes(q)) {
                        item.style.display = 'block';
                        visible = true;
                    } else {
                        item.style.display = 'none';
                    }
                });
                if (visible) {
                    card.style.display = 'block';
                    hay = true;
                } else {
                    card.style.display = 'none';
                }
            });
            sinResultados.style.display = hay ? 'none' : 'block';
        });

        // ----------------------------- QUIZ -----------------------------
        let preguntas = [];
        let indicePregunta = 0;
        let aciertos = 0;
        let racha = 0;
        let totalIntentos = 0;
        let respondido = false;

        function generarPreguntas() {
            const seleccionadas = [];
            const copia = [...allTecnicas];
            for (let i = copia.length - 1; i > 0; i--) {
                const j = Math.floor(Math.random() * (i + 1));
                [copia[i], copia[j]] = [copia[j], copia[i]];
            }
            for (let i = 0; i < Math.min(10, copia.length); i++) {
                seleccionadas.push(copia[i]);
            }
            preguntas = seleccionadas.map(tec => {
                const correcta = tec.respuesta;
                const otros = allTecnicas.filter(t => t.respuesta !== correcta);
                const opciones = [correcta];
                const shuffled = otros.sort(() => Math.random() - 0.5);
                for (let i = 0; i < 3 && i < shuffled.length; i++) {
                    opciones.push(shuffled[i].respuesta);
                }
                const opcionesMezcladas = opciones.sort(() => Math.random() - 0.5);
                return {
                    tecnica: tec,
                    opciones: opcionesMezcladas,
                    correcta: correcta,
                    preguntaTexto: tec.pregunta
                };
            });
            indicePregunta = 0;
            aciertos = 0;
            racha = 0;
            totalIntentos = 0;
            actualizarMarcadores();
        }

        function mostrarPregunta() {
            if (indicePregunta >= preguntas.length) {
                document.getElementById('preguntaTexto').textContent = '🎉 ¡Has completado todas las preguntas!';
                document.getElementById('opcionesFragmentos').innerHTML = '';
                document.getElementById('feedbackQuiz').innerHTML = `<div class="alert alert-success">Total aciertos: ${aciertos} de ${preguntas.length}. ¡Sigue practicando!</div>`;
                document.getElementById('btnSiguiente').style.display = 'none';
                return;
            }
            const p = preguntas[indicePregunta];
            document.getElementById('preguntaTexto').textContent = `❓ ${p.preguntaTexto}`;
            const contenedor = document.getElementById('opcionesFragmentos');
            contenedor.innerHTML = '';
            p.opciones.forEach(op => {
                const col = document.createElement('div');
                col.className = 'col-12 col-md-6';
                const div = document.createElement('div');
                div.className = 'quiz-option';
                div.textContent = op;
                div.dataset.opcion = op;
                div.addEventListener('click', function() {
                    if (respondido) return;
                    respondido = true;
                    totalIntentos++;
                    const esCorrecta = op === p.correcta;
                    if (esCorrecta) {
                        aciertos++;
                        racha++;
                        this.classList.add('correcta');
                    } else {
                        racha = 0;
                        this.classList.add('incorrecta');
                        document.querySelectorAll('.quiz-option').forEach(el => {
                            if (el.dataset.opcion === p.correcta) {
                                el.classList.add('correcta');
                            }
                        });
                    }
                    actualizarMarcadores();
                    document.getElementById('feedbackQuiz').innerHTML = esCorrecta
                        ? `<div class="alert alert-success">✅ ¡Correcto! ${p.correcta}</div>`
                        : `<div class="alert alert-danger">❌ Incorrecto. La respuesta correcta era: ${p.correcta}</div>`;
                    document.getElementById('btnSiguiente').style.display = 'block';
                });
                col.appendChild(div);
                contenedor.appendChild(col);
            });
            document.getElementById('feedbackQuiz').innerHTML = '';
            document.getElementById('btnSiguiente').style.display = 'none';
            respondido = false;
        }

        function actualizarMarcadores() {
            document.getElementById('contadorAciertos').textContent = aciertos;
            document.getElementById('contadorRacha').textContent = racha;
            document.getElementById('contadorTotal').textContent = totalIntentos;
        }

        document.getElementById('btnSiguiente').addEventListener('click', function() {
            indicePregunta++;
            mostrarPregunta();
        });

        // Iniciar quiz
        generarPreguntas();
        mostrarPregunta();

        // Regenerar preguntas al cambiar a la pestaña Practicar
        document.querySelector('button[data-bs-target="#practicarTab"]').addEventListener('shown.bs.tab', function() {
            generarPreguntas();
            mostrarPregunta();
        });

        // Fecha
        document.getElementById('fechaHoy').textContent = new Date().toLocaleDateString('es-CO', { year: 'numeric', month: 'long', day: 'numeric' });

        console.log('📚 Redacción Castellana · 5° grado · MEN · 100 técnicas cargadas');
    })();
</script>

</body>
</html>

