<div class="container-fluid px-4 py-4">
    <div class="tab-content">

        <div class="tab-pane fade show active" id="explorarTab">
            <div class="row mb-4">
                <div class="col-md-8 mx-auto">
                    <input type="text" class="form-control search-box" id="buscarTecnica" placeholder="🔍 Buscar técnica (ej. 'narración', 'descripción', 'poesía', 'ortografía')...">
