            </div>
            <div class="row" id="acordeonFamilias"></div>
            <div class="text-center py-5 text-muted fst-italic" id="sinResultados" style="display:none;">Ninguna técnica coincide con tu búsqueda.</div>
        </div>

        <div class="tab-pane fade" id="practicarTab">
            <div class="d-flex justify-content-between align-items-center mb-4 flex-wrap gap-3">
                <h2 class="h4 mb-0" style="font-family:'Source Serif 4',serif;">✍️ Pon a prueba tus conocimientos</h2>
                <div class="d-flex gap-3 flex-wrap">
                    <span class="marcador-badge">✔️ <strong class="text-primary" id="contadorAciertos">0</strong></span>
                    <span class="marcador-badge">📈 Racha <strong class="text-danger" id="contadorRacha">0</strong></span>
                    <span class="marcador-badge">📋 <span id="contadorTotal">0</span> intentos</span>
                </div>
            </div>
