            { titulo: "Número gramatical", teoria: "El número indica si el sustantivo o adjetivo está en singular (uno) o plural (varios). El plural se forma con -s o -es.", ejemplo: "'casa' (singular) → 'casas' (plural); 'pez' → 'peces' (plural con -es).", ejercicio: "Forma el plural de 10 palabras.", reto: "Escribe 3 oraciones con sustantivos en singular y plural." },
            { titulo: "Persona gramatical", teoria: "La persona indica quién realiza la acción: primera (yo, nosotros), segunda (tú, vosotros) o tercera (él, ellos).", ejemplo: "'yo canto' (1ª), 'tú cantas' (2ª), 'él canta' (3ª).", ejercicio: "Conjuga un verbo en las tres personas del singular.", reto: "Escribe 3 oraciones con cada persona." },
            { titulo: "Tiempo verbal", teoria: "El tiempo verbal sitúa la acción en el pasado, presente o futuro. Hay tiempos simples y compuestos.", ejemplo: "'canto' (presente), 'canté' (pasado perfecto), 'cantaré' (futuro).", ejercicio: "Conjuga el verbo 'comer' en presente, pasado y futuro.", reto: "Escribe 3 oraciones en diferentes tiempos verbales." },
            { titulo: "Modo verbal", teoria: "El modo indica la actitud del hablante: indicativo (realidad), subjuntivo (deseo, duda) e imperativo (orden).", ejemplo: "'canto' (indicativo), 'cante' (subjuntivo), 'canta' (imperativo).", ejercicio: "Conjuga un verbo en los tres modos.", reto: "Escribe 3 oraciones con cada modo." },
            { titulo: "Aspecto verbal", teoria: "El aspecto indica si la acción está terminada (perfecto) o no (imperfecto).", ejemplo: "'he cantado' (perfecto), 'cantaba' (imperfecto).", ejercicio: "Escribe 3 oraciones con aspecto perfecto e imperfecto.", reto: "Conjuga el verbo 'vivir' en todos los tiempos." },
            { titulo: "Flexión nominal", teoria: "Los sustantivos y adjetivos varían en género y número. La flexión nominal es el conjunto de estas variaciones.", ejemplo: "'el gato' → 'los gatos' (número); 'el gato' → 'la gata' (género).", ejercicio: "Flexiona 5 sustantivos en género y número.", reto: "Escribe 5 pares con todas las combinaciones de género y número." },
            { titulo: "Flexión verbal: presente", teoria: "El presente de indicativo expresa acciones actuales o habituales. Las terminaciones varían según la conjugación.", ejemplo: "'amar' → 'amo, amas, ama, amamos, amáis, aman'.", ejercicio: "Conjuga el verbo 'beber' en presente.", reto: "Escribe 3 oraciones con verbos en presente." },
            { titulo: "Flexión verbal: pretérito perfecto", teoria: "El pretérito perfecto simple indica acciones pasadas y terminadas. Las terminaciones son -é, -aste, -ó, etc.", ejemplo: "'cantar' → 'canté, cantaste, cantó, cantamos, cantasteis, cantaron'.", ejercicio: "Conjuga el verbo 'escribir' en pretérito perfecto.", reto: "Escribe 3 oraciones con verbos en pretérito perfecto." },
            { titulo: "Flexión verbal: futuro", teoria: "El futuro de indicativo expresa acciones futuras. Se forma con el infinitivo + terminaciones.", ejemplo: "'amar' → 'amaré, amarás, amará, amaremos, amaréis, amarán'.", ejercicio: "Conjuga el verbo 'vivir' en futuro.", reto: "Escribe 3 oraciones con verbos en futuro." },
            { titulo: "Flexión adjetival", teoria: "Los adjetivos concuerdan en género y número con el sustantivo al que modifican.", ejemplo: "'niño alto' (masculino singular) → 'niña alta' (femenino singular).", ejercicio: "Flexiona 5 adjetivos en género y número.", reto: "Escribe 3 oraciones con adjetivos flexionados." },
            { titulo: "Flexión pronominal", teoria: "Los pronombres personales varían según persona, número, género y caso.", ejemplo: "'yo' (1ª singular), 'nosotros' (1ª plural), 'tú' (2ª singular).", ejercicio: "Escribe los pronombres personales en todas las personas y números.", reto: "Escribe 3 oraciones con diferentes pronombres." },
            { titulo: "Flexión en el subjuntivo", teoria: "El subjuntivo se usa para expresar duda, deseo, posibilidad. Sus terminaciones son distintas al indicativo.", ejemplo: "'amar' → 'ame, ames, ame, amemos, améis, amen'.", ejercicio: "Conjuga el verbo 'comer' en presente de subjuntivo.", reto: "Escribe 3 oraciones con subjuntivo." },
            { titulo: "Flexión en el imperativo", teoria: "El imperativo se usa para dar órdenes. Solo tiene formas para segunda persona.", ejemplo: "'amar' → 'ama' (tú), 'amad' (vosotros), 'ame' (usted).", ejercicio: "Conjuga el verbo 'escribir' en imperativo.", reto: "Escribe 3 oraciones imperativas." },
            { titulo: "Verbos irregulares en flexión", teoria: "Algunos verbos tienen irregularidades en su flexión: diptongos, cambios vocálicos, etc.", ejemplo: "'poder' → 'puedo' (diptongo), 'decir' → 'digo' (cambio).", ejercicio: "Conjuga 3 verbos irregulares en presente.", reto: "Escribe 3 oraciones con verbos irregulares." },
            { titulo: "Flexión de participios", teoria: "Los participios tienen flexión de género y número en función adjetiva (cuando no son verbos auxiliares).", ejemplo: "'escrito' → 'escrita' (femenino), 'escritos' (plural).", ejercicio: "Flexiona 5 participios en género y número.", reto: "Escribe 3 oraciones con participios como adjetivos." },
            { titulo: "Flexión de gerundios", teoria: "El gerundio no tiene flexión de género o número; es invariable.", ejemplo: "'cantando', 'bebiendo', 'viviendo'.", ejercicio: "Escribe 3 gerundios de diferentes verbos.", reto: "Escribe 3 oraciones con gerundios." },
            { titulo: "Flexión de infinitivos", teoria: "Los infinitivos no tienen flexión de persona, número o tiempo; son la forma base del verbo.", ejemplo: "'amar', 'temer', 'partir'.", ejercicio: "Escribe 5 infinitivos.", reto: "Escribe 3 oraciones con infinitivos." },
            { titulo: "Flexión en la concordancia", teoria: "La concordancia exige que el verbo concuerde con el sujeto en persona y número, y el adjetivo con el sustantivo en género y número.", ejemplo: "'Los niños juegan en el parque' (plural).", ejercicio: "Corrige 3 oraciones con errores de concordancia.", reto: "Escribe 3 oraciones con concordancia correcta." },
            { titulo: "Flexión en la formación de tiempos compuestos", teoria: "Los tiempos compuestos se forman con el verbo 'haber' + participio. El auxiliar 'haber' se flexiona.", ejemplo: "'he cantado', 'había comido', 'habré vivido'.", ejercicio: "Conjuga el verbo 'correr' en todos los tiempos compuestos.", reto: "Escribe 3 oraciones con tiempos compuestos." }
        ]
    },
    deriva: {
