        especialidad: "Derivación: prefijos, sufijos, interfijos, parasíntesis",
        tecnicas: [
            { titulo: "Prefijación", teoria: "Los prefijos se añaden al principio de una palabra para modificar su significado (negación, intensidad, localización, etc.).", ejemplo: "'hacer' → 'rehacer' (repetición), 'legal' → 'ilegal' (negación).", ejercicio: "Escribe 5 palabras con prefijo.", reto: "Crea 5 palabras derivadas con prefijos y escribe oraciones." },
            { titulo: "Sufijación", teoria: "Los sufijos se añaden al final de una palabra para crear nuevas palabras o cambiar su categoría gramatical.", ejemplo: "'pan' → 'panadería' (lugar), 'lento' → 'lentamente' (adverbio).", ejercicio: "Escribe 5 palabras con sufijo.", reto: "Crea 5 palabras derivadas con sufijos y escribe oraciones." },
            { titulo: "Interfijación", teoria: "Los interfijos son elementos que se insertan entre la raíz y el sufijo, sin significado propio, para facilitar la pronunciación.", ejemplo: "'café' → 'cafetera' (interfijo -et-), 'sangre' → 'sangriento' (interfijo -ient-).", ejercicio: "Escribe 3 palabras con interfijo.", reto: "Encuentra 5 palabras con interfijo en un texto." },
            { titulo: "Parasíntesis", teoria: "La parasíntesis es la formación de palabras con prefijo y sufijo a la vez, donde la palabra simple resultante no existe o se forma simultáneamente.", ejemplo: "'enriquecer' (en- + rico + -ecer), 'enternecer' (en- + tierno + -ecer).", ejercicio: "Escribe 3 palabras parasintéticas.", reto: "Explica por qué son parasintéticas." },
            { titulo: "Prefijos de negación", teoria: "Los prefijos de negación (a-, des-, in-, i-, im-) indican oposición o carencia.", ejemplo: "'moral' → 'amoral' (a-), 'hacer' → 'deshacer' (des-), 'útil' → 'inútil' (in-).", ejercicio: "Escribe 5 palabras con prefijos de negación.", reto: "Crea 5 oraciones con prefijos de negación." },
            { titulo: "Prefijos de intensidad", teoria: "Los prefijos de intensidad (re-, super-, extra-, hiper-, ultra-) indican aumento o énfasis.", ejemplo: "'hacer' → 'rehacer' (re-), 'mercado' → 'supermercado' (super-).", ejercicio: "Escribe 5 palabras con prefijos de intensidad.", reto: "Crea 5 oraciones con prefijos de intensidad." },
            { titulo: "Prefijos de localización", teoria: "Los prefijos de localización (ante-, pre-, post-, sub-, inter-, entre-) indican posición espacial o temporal.", ejemplo: "'poner' → 'anteponer' (ante-), 'guerra' → 'posguerra' (post-).", ejercicio: "Escribe 5 palabras con prefijos de localización.", reto: "Crea 5 oraciones con prefijos de localización." },
            { titulo: "Sufijos diminutivos", teoria: "Los sufijos diminutivos (-ito, -ita, -illo, -illa, -ín, -ina) indican tamaño pequeño o afecto.", ejemplo: "'casa' → 'casita', 'perro' → 'perrito'.", ejercicio: "Escribe 5 palabras con sufijos diminutivos.", reto: "Crea 5 oraciones con diminutivos." },
            { titulo: "Sufijos aumentativos", teoria: "Los sufijos aumentativos (-ón, -ona, -azo, -aza) indican gran tamaño o intensidad.", ejemplo: "'casa' → 'casona' (-ona), 'golpe' → 'golpazo' (-azo).", ejercicio: "Escribe 5 palabras con sufijos aumentativos.", reto: "Crea 5 oraciones con aumentativos." },
            { titulo: "Sufijos despectivos", teoria: "Los sufijos despectivos (-aco, -ajo, -ucho, -uelo) indican desprecio o menosprecio.", ejemplo: "'casa' → 'casucha' (-ucha), 'gente' → 'gentuza' (-uza).", ejercicio: "Escribe 5 palabras con sufijos despectivos.", reto: "Crea 5 oraciones con despectivos." },
            { titulo: "Sufijos de profesión", teoria: "Los sufijos de profesión (-ero, -ista, -dor, -ente) indican oficio o actividad.", ejemplo: "'pan' → 'panadero' (-ero), 'arte' → 'artista' (-ista).", ejercicio: "Escribe 5 palabras con sufijos de profesión.", reto: "Crea 5 oraciones con profesiones." },
            { titulo: "Sufijos de cualidad", teoria: "Los sufijos de cualidad (-ez, -eza, -ura, -ía) forman sustantivos abstractos a partir de adjetivos.", ejemplo: "'bello' → 'belleza' (-eza), 'alto' → 'altura' (-ura).", ejercicio: "Escribe 5 palabras con sufijos de cualidad.", reto: "Crea 5 oraciones con sustantivos abstractos." },
            { titulo: "Sufijos de lugar", teoria: "Los sufijos de lugar (-ería, -ero, -dor) indican el lugar donde se realiza una actividad.", ejemplo: "'pan' → 'panadería' (ería), 'zapato' → 'zapatería' (ería).", ejercicio: "Escribe 5 palabras con sufijos de lugar.", reto: "Crea 5 oraciones con lugares." },
            { titulo: "Sufijos de acción", teoria: "Los sufijos de acción (-ción, -sión, -aje, -miento) forman sustantivos de acción a partir de verbos.", ejemplo: "'construir' → 'construcción' (-ción), 'viajar' → 'viaje' (-je).", ejercicio: "Escribe 5 palabras con sufijos de acción.", reto: "Crea 5 oraciones con sustantivos de acción." },
            { titulo: "Sufijos de instrumento", teoria: "Los sufijos de instrumento (-dor, -ero, -nte) indican el objeto o herramienta que realiza la acción.", ejemplo: "'cortar' → 'cortador' (-dor), 'hervir' → 'hervidor' (-dor).", ejercicio: "Escribe 5 palabras con sufijos de instrumento.", reto: "Crea 5 oraciones con instrumentos." },
