<script>
// ============================================================
// DATOS: 5 AMAZONAS × 20 TÉCNICAS = 100
// ============================================================
const AMAZONAS_DATA = {
    flexia: {
        nombre: "Flexia", color: "azul", icono: "bi-robot",
        especialidad: "Flexión: género, número, persona, tiempo, modo, aspecto",
        tecnicas: [
            { titulo: "Género gramatical", teoria: "El género es un rasgo gramatical que distingue masculino y femenino en sustantivos y adjetivos. Puede ser natural (sexo) o gramatical (arbitrario).", ejemplo: "'niño' (masculino) vs 'niña' (femenino); 'el problema' (masculino) vs 'la mano' (femenino).", ejercicio: "Clasifica 10 sustantivos por su género.", reto: "Escribe 5 pares de palabras que cambien de género." },
            { titulo: "Número gramatical", teoria: "El número indica si el sustantivo o adjetivo está en singular (uno) o plural (varios). El plural se forma con -s o -es.", ejemplo: "'casa' (singular) → 'casas' (plural); 'pez' → 'peces' (plural con -es).", ejercicio: "Forma el plural de 10 palabras.", reto: "Escribe 3 oraciones con sustantivos en singular y plural." },
            { titulo: "Persona gramatical", teoria: "La persona indica quién realiza la acción: primera (yo, nosotros), segunda (tú, vosotros) o tercera (él, ellos).", ejemplo: "'yo canto' (1ª), 'tú cantas' (2ª), 'él canta' (3ª).", ejercicio: "Conjuga un verbo en las tres personas del singular.", reto: "Escribe 3 oraciones con cada persona." },
            { titulo: "Tiempo verbal", teoria: "El tiempo verbal sitúa la acción en el pasado, presente o futuro. Hay tiempos simples y compuestos.", ejemplo: "'canto' (presente), 'canté' (pasado perfecto), 'cantaré' (futuro).", ejercicio: "Conjuga el verbo 'comer' en presente, pasado y futuro.", reto: "Escribe 3 oraciones en diferentes tiempos verbales." },
            { titulo: "Modo verbal", teoria: "El modo indica la actitud del hablante: indicativo (realidad), subjuntivo (deseo, duda) e imperativo (orden).", ejemplo: "'canto' (indicativo), 'cante' (subjuntivo), 'canta' (imperativo).", ejercicio: "Conjuga un verbo en los tres modos.", reto: "Escribe 3 oraciones con cada modo." },
            { titulo: "Aspecto verbal", teoria: "El aspecto indica si la acción está terminada (perfecto) o no (imperfecto).", ejemplo: "'he cantado' (perfecto), 'cantaba' (imperfecto).", ejercicio: "Escribe 3 oraciones con aspecto perfecto e imperfecto.", reto: "Conjuga el verbo 'vivir' en todos los tiempos." },
            { titulo: "Flexión nominal", teoria: "Los sustantivos y adjetivos varían en género y número. La flexión nominal es el conjunto de estas variaciones.", ejemplo: "'el gato' → 'los gatos' (número); 'el gato' → 'la gata' (género).", ejercicio: "Flexiona 5 sustantivos en género y número.", reto: "Escribe 5 pares con todas las combinaciones de género y número." },
            { titulo: "Flexión verbal: presente", teoria: "El presente de indicativo expresa acciones actuales o habituales. Las terminaciones varían según la conjugación.", ejemplo: "'amar' → 'amo, amas, ama, amamos, amáis, aman'.", ejercicio: "Conjuga el verbo 'beber' en presente.", reto: "Escribe 3 oraciones con verbos en presente." },
