        .exercise-section,
        .quiz-section {
            background: rgba(255, 255, 255, 0.05);
            border: 1px solid rgba(201, 168, 76, 0.04);
            border-radius: 14px;
            padding: 1.2rem 1.5rem;
            margin-top: 1rem;
            backdrop-filter: blur(4px);
        }

        .exercise-section h3,
        .quiz-section h3 {
            font-family: var(--font-uncial);
            font-size: 1rem;
            color: var(--telon);
            margin-bottom: 0.6rem;
            display: flex;
            align-items: center;
            gap: 0.5rem;
        }

        .exercise-section .exercise-prompt,
        .quiz-section .quiz-question {
            font-size: 0.9rem;
            color: var(--tinta-clara);
            line-height: 1.7;
            margin-bottom: 0.5rem;
        }

        .exercise-section .exercise-input {
            width: 100%;
            background: rgba(255, 255, 255, 0.06);
            border: 1px solid rgba(201, 168, 76, 0.04);
            border-radius: 10px;
            padding: 0.5rem 0.8rem;
            font-family: var(--font-serif);
            font-size: 0.85rem;
            color: var(--tinta);
            resize: vertical;
            min-height: 70px;
            transition: border-color 0.3s;
        }

        .exercise-section .exercise-input:focus {
            border-color: var(--oro);
            outline: none;
            box-shadow: 0 0 0 3px rgba(201, 168, 76, 0.02);
        }

        .exercise-section .exercise-actions,
        .quiz-section .quiz-actions {
            display: flex;
            gap: 0.5rem;
            margin-top: 0.5rem;
            flex-wrap: wrap;
        }

        .btn-exercise,
        .btn-quiz {
            font-family: var(--font-uncial);
            font-size: 0.6rem;
            padding: 0.2rem 1.2rem;
            border-radius: 40px;
            border: 1px solid var(--oro-light);
            background: rgba(255, 255, 255, 0.04);
            color: var(--tinta-clara);
            cursor: pointer;
            transition: all 0.3s;
        }

        .btn-exercise:hover,
        .btn-quiz:hover {
            background: rgba(139, 26, 43, 0.02);
            border-color: var(--telon);
            color: var(--telon);
        }

        .btn-exercise.primary,
        .btn-quiz.primary {
            background: rgba(139, 26, 43, 0.03);
            border-color: var(--telon-claro);
            color: var(--telon);
        }

        .btn-exercise.primary:hover,
        .btn-quiz.primary:hover {
            background: rgba(139, 26, 43, 0.05);
        }

        .exercise-feedback,
        .quiz-result {
            margin-top: 0.5rem;
            font-size: 0.8rem;
            color: var(--tinta-clara);
            padding: 0.3rem 0.8rem;
            border-radius: 8px;
            background: rgba(201, 168, 76, 0.02);
            border-left: 3px solid var(--oro-light);
            min-height: 1.6rem;
            line-height: 1.6;
        }

        .exercise-feedback .highlight,
        .quiz-result .correct {
            color: #2d7a3a;
            font-weight: 600;
        }
        .quiz-result .incorrect {
            color: var(--telon);
            font-weight: 600;
        }

        .quiz-section .quiz-options {
            display: flex;
            flex-direction: column;
            gap: 0.25rem;
            margin-bottom: 0.5rem;
        }

        .quiz-section .quiz-options label {
            display: flex;
            align-items: center;
            gap: 0.5rem;
            font-size: 0.8rem;
            color: var(--tinta-clara);
            cursor: pointer;
            padding: 0.15rem 0.5rem;
            border-radius: 8px;
            transition: background 0.2s;
        }

        .quiz-section .quiz-options label:hover {
            background: rgba(139, 26, 43, 0.02);
        }

        .quiz-section .quiz-options input[type="radio"] {
            appearance: none;
            width: 0.9rem;
            height: 0.9rem;
            border: 2px solid var(--oro-dark);
            border-radius: 50%;
            cursor: pointer;
            background: var(--escenario);
            transition: all 0.15s;
            flex-shrink: 0;
        }

        .quiz-section .quiz-options input[type="radio"]:checked {
            background: var(--oro);
            border-color: var(--oro);
            box-shadow: 0 0 0 2px var(--escenario), 0 0 0 4px var(--oro-light);
        }

        /* ============================================================
           MODAL DE TÉCNICA
           ============================================================ */

        .modal-overlay {
            display: none;
            position: fixed;
            inset: 0;
            background: rgba(26, 26, 46, 0.4);
            backdrop-filter: blur(6px);
            z-index: 1000;
            justify-content: center;
            align-items: center;
            padding: 2rem;
        }

        .modal-overlay.open {
            display: flex;
        }

        .modal-content {
            background: var(--escenario);
            background-image:
                repeating-linear-gradient(0deg, transparent, transparent 27px, rgba(200, 190, 175, 0.10) 27px, rgba(200, 190, 175, 0.10) 28px);
            border-radius: 16px;
            max-width: 700px;
            width: 100%;
            max-height: 90vh;
            overflow-y: auto;
            padding: 2rem;
            border: 2px solid var(--telon);
            box-shadow: 0 8px 60px rgba(26, 26, 46, 0.2);
            position: relative;
        }

        .modal-content::-webkit-scrollbar {
            width: 5px;
        }
        .modal-content::-webkit-scrollbar-track {
            background: var(--escenario);
            border-radius: 30px;
        }
        .modal-content::-webkit-scrollbar-thumb {
            background: var(--oro);
            border-radius: 30px;
        }

        .modal-close {
            position: absolute;
            top: 1rem;
            right: 1.2rem;
            font-size: 1.6rem;
            background: none;
            border: none;
            color: var(--tinta-gris);
            cursor: pointer;
            transition: all 0.3s;
            font-family: var(--font-serif);
            line-height: 1;
        }

        .modal-close:hover {
            color: var(--telon);
            transform: rotate(90deg);
        }

        .modal-content .modal-head {
            display: flex;
            align-items: baseline;
            gap: 0.6rem;
            flex-wrap: wrap;
            margin-bottom: 0.8rem;
            padding-bottom: 0.5rem;
            border-bottom: 2px dotted var(--oro-light);
        }

        .modal-content .modal-head .modal-num {
            font-family: var(--font-uncial);
            font-size: 0.8rem;
            color: var(--oro-dark);
            opacity: 0.5;
        }

        .modal-content .modal-head .modal-title {
            font-family: var(--font-uncial);
            font-size: 1.6rem;
            color: var(--telon);
        }

        .modal-content .modal-head .modal-rhetoric {
            font-size: 0.7rem;
            background: rgba(139, 26, 43, 0.03);
            padding: 0.05rem 0.8rem;
            border-radius: 30px;
            color: var(--telon);
            font-style: italic;
            border: 1px solid rgba(139, 26, 43, 0.04);
        }

        .modal-content .modal-def {
            font-size: 0.95rem;
            color: var(--tinta-clara);
            line-height: 1.7;
            margin-bottom: 0.8rem;
        }

        .modal-content .modal-example {
            font-size: 0.85rem;
            color: var(--tinta-clara);
            font-style: italic;
            background: rgba(201, 168, 76, 0.02);
            padding: 0.5rem 0.8rem;
            border-radius: 8px;
            border-left: 3px solid var(--oro-light);
            margin-bottom: 1rem;
            line-height: 1.7;
        }

        .modal-content .modal-example strong {
            font-style: normal;
            color: var(--telon);
        }

        .modal-content .modal-practice-area {
            margin-top: 0.5rem;
