            // ============================================================

            const CATEGORIES = [{
                id: 't1',
                icon: '🎭',
                name: 'Clásicos griegos y romanos',
                techniques: [
                    { id: 1, author: 'Esquilo', name: 'La trilogía trágica', rhetoric: 'Estructura',
                        def: 'Estructura dramática en tres obras que componen una historia completa, como la Orestíada.',
                        example: 'La Orestíada de Esquilo es una trilogía que narra el ciclo de violencia y justicia en la casa de Atreo.' },
                    { id: 2, author: 'Sófocles', name: 'Ironía trágica', rhetoric: 'Recurso',
                        def: 'El personaje cree saber algo que el público sabe que es falso, creando tensión dramática.',
                        example: 'En Edipo Rey, Sófocles usa la ironía trágica cuando Edipo jura encontrar al asesino de Layo, sin saber que él mismo es el culpable.' },
                    { id: 3, author: 'Eurípides', name: 'El deus ex machina', rhetoric: 'Recurso',
                        def: 'Intervención de una divinidad al final de la obra para resolver el conflicto de manera sobrenatural.',
                        example: 'En Medea, Eurípides utiliza el carro del sol para que Medea escape, un clásico deus ex machina.' },
                    { id: 4, author: 'Aristófanes', name: 'Sátira política', rhetoric: 'Género',
                        def: 'Comedia que critica la política y la sociedad de su tiempo con humor y exageración.',
                        example: 'Las nubes de Aristófanes satiriza a Sócrates y la educación ateniense.' },
                    { id: 5, author: 'Séneca', name: 'El drama de sangre', rhetoric: 'Género',
                        def: 'Tragedia romana con elementos de violencia explícita y horror, precursora del teatro isabelino.',
                        example: 'Las tragedias de Séneca, como Fedra, son conocidas por su violencia y su influencia en Shakespeare.' },
                    { id: 6, author: 'Plauto', name: 'La comedia de enredos', rhetoric: 'Género',
                        def: 'Comedia con situaciones confusas, equívocos y personajes arquetípicos como el esclavo astuto.',
                        example: 'El soldado fanfarrón de Plauto es un ejemplo de comedia de enredos con personajes cómicos.' },
                    { id: 7, author: 'Terencio', name: 'El diálogo naturalista', rhetoric: 'Estilo',
                        def: 'Diálogo que busca la naturalidad y la verosimilitud, alejándose de la exageración cómica.',
                        example: 'En La suegra de Terencio, el diálogo refleja la complejidad de las relaciones humanas.' },
                    { id: 8, author: 'Eurípides', name: 'El monólogo interior', rhetoric: 'Recurso',
                        def: 'Monólogo que revela los pensamientos y emociones más profundos del personaje.',
                        example: 'El monólogo de Medea antes de matar a sus hijos es un ejemplo de monólogo interior.' },
                    { id: 9, author: 'Sófocles', name: 'El coro como narrador', rhetoric: 'Estructura',
                        def: 'El coro comenta la acción, guía la interpretación del público y crea atmósfera.',
                        example: 'En Antígona, el coro comenta los eventos y la moralidad de las acciones de los personajes.' },
                    { id: 10, author: 'Esquilo', name: 'El conflicto entre divinidades', rhetoric: 'Temática',
                        def: 'Conflicto entre dioses y mortales, o entre dioses, que refleja las tensiones humanas.',
                        example: 'En Prometeo encadenado, el conflicto entre Prometeo y Zeus representa la lucha por la libertad.' }
                ]
            }, {
                id: 't2',
                icon: '🎭',
                name: 'Renacimiento y Barroco',
                techniques: [
                    { id: 11, author: 'William Shakespeare', name: 'El soliloquio', rhetoric: 'Recurso',
                        def: 'Monólogo en el que el personaje expresa sus pensamientos en voz alta, a solas en el escenario.',
                        example: 'El soliloquio de Hamlet "Ser o no ser" es uno de los más famosos de la literatura universal.' },
                    { id: 12, author: 'William Shakespeare', name: 'El personaje trágico', rhetoric: 'Personaje',
                        def: 'Personaje noble con un defecto fatal (hamartia) que lleva a su caída.',
                        example: 'El rey Lear es un personaje trágico cuyo orgullo y falta de juicio lo llevan a la ruina.' },
                    { id: 13, author: 'Lope de Vega', name: 'La comedia nueva', rhetoric: 'Estructura',
                        def: 'Estructura en tres actos con mezcla de elementos cómicos y trágicos, rompiendo las reglas clásicas.',
                        example: 'Fuenteovejuna de Lope de Vega mezcla el drama social con elementos cómicos.' },
                    { id: 14, author: 'Lope de Vega', name: 'El honor como tema', rhetoric: 'Temática',
                        def: 'El honor es un tema central en el teatro del Siglo de Oro, motor de la acción dramática.',
                        example: 'El caballero de Olmedo explora el honor, el amor y la muerte en la España del siglo XVII.' },
                    { id: 15, author: 'Calderón de la Barca', name: 'La vida como sueño', rhetoric: 'Temática',
                        def: 'Reflexión sobre la naturaleza de la realidad y la ilusión, donde la vida se compara con un sueño.',
                        example: 'La vida es sueño de Calderón plantea la duda sobre si lo que vivimos es real o solo un sueño.' },
                    { id: 16, author: 'Calderón de la Barca', name: 'El auto sacramental', rhetoric: 'Género',
                        def: 'Obra alegórica de tema religioso que representa la lucha entre el bien y el mal.',
                        example: 'El gran teatro del mundo es un auto sacramental que representa la vida como una obra de teatro.' },
                    { id: 17, author: 'Tirso de Molina', name: 'El burlador de Sevilla', rhetoric: 'Personaje',
                        def: 'Arquetipo del seductor que desafía las normas sociales y religiosas.',
                        example: 'El burlador de Sevilla de Tirso de Molina crea el arquetipo de Don Juan.' },
                    { id: 18, author: 'William Shakespeare', name: 'El equívoco dramático', rhetoric: 'Recurso',
