            }, {
                id: 't3',
                icon: '🎭',
                name: 'Neoclasicismo y Romanticismo',
                techniques: [
                    { id: 21, author: 'Jean Racine', name: 'La unidad de lugar', rhetoric: 'Estructura',
                        def: 'La acción se desarrolla en un único lugar, siguiendo las reglas del teatro clásico.',
                        example: 'En Fedra de Racine, la acción se desarrolla en el palacio de Trecén, manteniendo la unidad de lugar.' },
                    { id: 22, author: 'Jean Racine', name: 'La pasión trágica', rhetoric: 'Temática',
