                    { id: 28, author: 'Federico García Lorca', name: 'El teatro poético', rhetoric: 'Estilo',
                        def: 'Teatro que utiliza el lenguaje poético para crear atmósfera y explorar temas universales.',
                        example: 'Bodas de sangre de Lorca es un ejemplo de teatro poético, con un lenguaje lírico y simbólico.' },
                    { id: 29, author: 'Federico García Lorca', name: 'El conflicto generacional', rhetoric: 'Temática',
                        def: 'Conflicto entre padres e hijos, entre tradición y modernidad, típico del teatro de Lorca.',
                        example: 'La casa de Bernarda Alba explora el conflicto entre la autoridad materna y el deseo de libertad de las hijas.' },
                    { id: 30, author: 'Alexandre Dumas (hijo)', name: 'El drama social', rhetoric: 'Género',
                        def: 'Obra que aborda temas sociales y políticos, como la prostitución, el adulterio o la injusticia.',
                        example: 'La dama de las camelias de Dumas hijo es un drama social sobre el amor y la enfermedad.' }
