                    {nombre:"Pronombres de cortesía (usted, ustedes) / Formal pronouns (you formal)", desc_es:"'Usted, ustedes'. En inglés no hay distinción.", desc_en:"'Usted, ustedes'. No distinction in English.", ej_es:"¿Cómo está usted?", ej_en:"How are you?"},
                    {nombre:"Pronombres interrogativos (¿quién?, ¿qué?) / Interrogative pronouns (who?, what?)", desc_es:"'¿Quién?, ¿qué?'. En inglés 'who?, what?'.", desc_en:"'¿Quién?, ¿qué?'. In English 'who?, what?'.", ej_es:"¿Quién es?", ej_en:"Who is it?"},
                    {nombre:"Pronombres relativos (que, quien) / Relative pronouns (who, which, that)", desc_es:"'Que, quien'. En inglés 'who, which, that'.", desc_en:"'Que, quien'. In English 'who, which, that'.", ej_es:"El libro que leo.", ej_en:"The book that I read."},
                    {nombre:"Omisión del pronombre sujeto en español / Subject pronoun omission", desc_es:"En español se omite frecuentemente.", desc_en:"Frequently omitted in Spanish.", ej_es:"(Yo) voy al cine.", ej_en:"I go to the cinema (obligatory in English)."}
                ]
            },
            {
                nombre: "E. Verbos en presente / Present Tense Verbs (indicativo / indicative)",
                tecnicas: [
                    {nombre:"Presente de indicativo -AR / Present tense -AR verbs", desc_es:"-AR: -o, -as, -a, -amos, -áis, -an.", desc_en:"-AR verbs conjugation. English: I speak, you speak...", ej_es:"Hablo, hablas, habla...", ej_en:"I speak, you speak, he speaks... (s in 3rd person)."},
                    {nombre:"Presente de indicativo -ER / Present tense -ER verbs", desc_es:"-ER: -o, -es, -e, -emos, -éis, -en.", desc_en:"-ER verbs conjugation. English: I eat, you eat...", ej_es:"Como, comes, come...", ej_en:"I eat, you eat, he eats... (s in 3rd person)."},
                    {nombre:"Presente de indicativo -IR / Present tense -IR verbs", desc_es:"-IR: -o, -es, -e, -imos, -ís, -en.", desc_en:"-IR verbs conjugation. English: I live, you live...", ej_es:"Vivo, vives, vive...", ej_en:"I live, you live, he lives... (s in 3rd person)."},
                    {nombre:"Verbos irregulares en español (ser, estar, ir) / Irregular verbs (to be, to go)", desc_es:"'Ser, estar, ir'. En inglés 'to be, to go'.", desc_en:"'Ser, estar, ir'. In English 'to be, to go'.", ej_es:"Soy, estoy, voy.", ej_en:"I am, I go."},
                    {nombre:"Verbo 'ser' vs 'estar' (diferencia) / 'Ser' vs 'estar' (difference)", desc_es:"'Ser' (permanente), 'estar' (temporal). Inglés: solo 'to be'.", desc_en:"'Ser' (permanent), 'estar' (temporary). English: only 'to be'.", ej_es:"Soy alto (permanente).", ej_en:"I am tall."},
                    {nombre:"Verbo 'haber' impersonal (hay) / There is / there are", desc_es:"'Hay' para singular y plural.", desc_en:"'There is' (singular), 'there are' (plural).", ej_es:"Hay un libro.", ej_en:"There is a book."},
                    {nombre:"Verbos reflexivos (lavarse) / Reflexive verbs (to wash oneself)", desc_es:"En español se usa 'se': lavarse.", desc_en:"In Spanish 'se'. In English 'oneself'.", ej_es:"Me lavo las manos.", ej_en:"I wash my hands."},
                    {nombre:"Verbos modales (poder, querer) / Modal verbs (can, want)", desc_es:"'Poder, querer, deber'. Inglés: 'can, want, must'.", desc_en:"'Poder, querer, deber'. English: 'can, want, must'.", ej_es:"Puedo hablar español.", ej_en:"I can speak Spanish."},
                    {nombre:"Verbos con preposición (soñar con) / Verbs with prepositions (dream of)", desc_es:"En español rigen preposición. En inglés también.", desc_en:"Both languages use prepositions with verbs.", ej_es:"Soñar con.", ej_en:"Dream of."},
                    {nombre:"Verbos de cambio (ponerse, volverse) / Verbs of change (to become)", desc_es:"'Ponerse, volverse, hacerse'. Inglés: 'to become, to get'.", desc_en:"'Ponerse, volverse, hacerse'. English: 'to become, to get'.", ej_es:"Se puso triste.", ej_en:"He became sad."}
                ]
            },
            {
                nombre: "F. Orden de palabras / Word Order (SVO / SVO)",
                tecnicas: [
                    {nombre:"Orden SVO en español / SVO in Spanish", desc_es:"Sujeto + Verbo + Objeto. Similar al inglés.", desc_en:"Subject + Verb + Object. Similar to English.", ej_es:"Juan come manzanas.", ej_en:"John eats apples."},
                    {nombre:"Orden flexible en español / Flexible order in Spanish", desc_es:"El español permite cambiar el orden. El inglés es más rígido.", desc_en:"Spanish allows order changes. English is more rigid.", ej_es:"Manzanas come Juan.", ej_en:"John eats apples (only this order)."},
                    {nombre:"Adverbios de frecuencia (siempre, nunca) / Frequency adverbs (always, never)", desc_es:"Van antes o después del verbo en español.", desc_en:"Usually before the verb in English.", ej_es:"Siempre estudio.", ej_en:"I always study (before)."},
                    {nombre:"Negación en español (no) / Negation in English (not, don't)", desc_es:"'No' antes del verbo. 'Not' después del auxiliar.", desc_en:"'No' before the verb. 'Not' after the auxiliary.", ej_es:"No hablo inglés.", ej_en:"I do not speak English."},
                    {nombre:"Doble negación en español / Double negation", desc_es:"En español es correcta. En inglés no.", desc_en:"Correct in Spanish. Incorrect in English.", ej_es:"No quiero nada.", ej_en:"I do not want anything (no double negation)."},
                    {nombre:"Preguntas sí/no en español / Yes/no questions in English", desc_es:"Entonación o inversión. 'Do/does' en inglés.", desc_en:"Intonation or inversion. 'Do/does' in English.", ej_es:"¿Hablas español?", ej_en:"Do you speak Spanish?"},
                    {nombre:"Preguntas con pronombre interrogativo / Wh- questions", desc_es:"'¿Qué?, ¿quién?, ¿dónde?'. 'What?, who?, where?'.", desc_en:"'¿Qué?, ¿quién?, ¿dónde?'. 'What?, who?, where?'.", ej_es:"¿Dónde vives?", ej_en:"Where do you live?"},
                    {nombre:"Exclamaciones (¡qué...!) / Exclamations (how...! / what...!)", desc_es:"'¡Qué bonito!'. 'How beautiful! / What a...!'.", desc_en:"'¡Qué bonito!'. 'How beautiful! / What a...!'.", ej_es:"¡Qué día tan hermoso!", ej_en:"What a beautiful day!"},
                    {nombre:"Oraciones con 'gustar' / Sentences with 'to like'", desc_es:"'Gustar' funciona al revés que 'like'.", desc_en:"'Gustar' works differently from 'like'.", ej_es:"Me gusta el café.", ej_en:"I like coffee (subject: I, not coffee)."},
                    {nombre:"Oraciones con 'haber' (hay que) / Sentences with 'have to'", desc_es:"'Hay que + infinitivo'. 'One must...'.", desc_en:"'Hay que + infinitive'. 'One must...'.", ej_es:"Hay que estudiar.", ej_en:"One must study."}
                ]
            },
            {
                nombre: "G. Preposiciones básicas / Basic Prepositions (a, en, de, to, in, of)",
                tecnicas: [
                    {nombre:"Preposición 'a' / Preposition 'to'", desc_es:"Movimiento: 'Voy a Madrid'.", desc_en:"Movement: 'I go to Madrid'.", ej_es:"Voy a la escuela.", ej_en:"I go to school."},
                    {nombre:"Preposición 'en' / Preposition 'in, on, at'", desc_es:"Lugar: 'Estoy en casa'.", desc_en:"Place: 'I am at home'.", ej_es:"Estoy en la oficina.", ej_en:"I am at the office."},
                    {nombre:"Preposición 'de' / Preposition 'of, from'", desc_es:"Posesión u origen: 'El libro de Juan'.", desc_en:"Possession or origin: 'John's book'.", ej_es:"Soy de Colombia.", ej_en:"I am from Colombia."},
                    {nombre:"Preposición 'con' / Preposition 'with'", desc_es:"Compañía: 'Voy con mi amigo'.", desc_en:"Company: 'I go with my friend'.", ej_es:"Hablé con ella.", ej_en:"I spoke with her."},
                    {nombre:"Preposición 'por' / Preposition 'for, through'", desc_es:"Causa o medio: 'Gracias por todo'.", desc_en:"Cause or means: 'Thanks for everything'.", ej_es:"Caminé por el parque.", ej_en:"I walked through the park."},
                    {nombre:"Preposición 'para' / Preposition 'for (purpose)'", desc_es:"Finalidad: 'Estudio para aprender'.", desc_en:"Purpose: 'I study to learn'.", ej_es:"Es para ti.", ej_en:"It is for you."},
                    {nombre:"Preposición 'sobre' / Preposition 'on, about'", desc_es:"Tema o lugar: 'Un libro sobre historia'.", desc_en:"Topic or place: 'A book about history'.", ej_es:"Está sobre la mesa.", ej_en:"It is on the table."},
                    {nombre:"Preposición 'entre' / Preposition 'between'", desc_es:"Dos elementos: 'Entre tú y yo'.", desc_en:"Two elements: 'Between you and me'.", ej_es:"Está entre la casa y el jardín.", ej_en:"It is between the house and the garden."},
                    {nombre:"Preposición 'sin' / Preposition 'without'", desc_es:"Carencia: 'Sin azúcar'.", desc_en:"Lack: 'Without sugar'.", ej_es:"Café sin leche.", ej_en:"Coffee without milk."},
                    {nombre:"Contracciones en español (al, del) / Contractions (to the, of the)", desc_es:"'a + el = al', 'de + el = del'. Inglés no tiene.", desc_en:"'a + el = al', 'de + el = del'. English has none.", ej_es:"Voy al cine.", ej_en:"I go to the cinema."}
                ]
            },
            {
                nombre: "H. Conjunciones básicas / Basic Conjunctions (y, o, pero, and, or, but)",
                tecnicas: [
                    {nombre:"Conjunción 'y' / Conjunction 'and'", desc_es:"Une palabras u oraciones. 'E' ante 'i' o 'hi'.", desc_en:"Joins words or sentences. 'And' in English.", ej_es:"Juan y María.", ej_en:"John and Mary."},
                    {nombre:"Conjunción 'o' / Conjunction 'or'", desc_es:"Alternativa. 'U' ante 'o' u 'ho'.", desc_en:"Alternative. 'Or' in English.", ej_es:"¿Café o té?", ej_en:"Coffee or tea?"},
                    {nombre:"Conjunción 'pero' / Conjunction 'but'", desc_es:"Oposición. 'But' en inglés.", desc_en:"Opposition. 'But' in English.", ej_es:"Quiero ir, pero no puedo.", ej_en:"I want to go, but I cannot."},
                    {nombre:"Conjunción 'porque' / Conjunction 'because'", desc_es:"Causa. 'Because' en inglés.", desc_en:"Cause. 'Because' in English.", ej_es:"Estudio porque quiero aprender.", ej_en:"I study because I want to learn."},
                    {nombre:"Conjunción 'aunque' / Conjunction 'although'", desc_es:"Concesión. 'Although' en inglés.", desc_en:"Concession. 'Although' in English.", ej_es:"Aunque llueva, saldré.", ej_en:"Although it rains, I will go out."},
                    {nombre:"Conjunción 'si' / Conjunction 'if'", desc_es:"Condición. 'If' en inglés.", desc_en:"Condition. 'If' in English.", ej_es:"Si llueve, no salgo.", ej_en:"If it rains, I do not go out."},
                    {nombre:"Conjunción 'cuando' / Conjunction 'when'", desc_es:"Tiempo. 'When' en inglés.", desc_en:"Time. 'When' in English.", ej_es:"Cuando llegue, te llamo.", ej_en:"When I arrive, I will call you."},
                    {nombre:"Conjunción 'que' / Conjunction 'that'", desc_es:"Subordinación. 'That' en inglés.", desc_en:"Subordination. 'That' in English.", ej_es:"Creo que es verdad.", ej_en:"I think that it is true."},
                    {nombre:"Conjunción 'ni' / Conjunction 'nor'", desc_es:"Negación. 'Nor' en inglés.", desc_en:"Negation. 'Nor' in English.", ej_es:"Ni come ni deja comer.", ej_en:"Neither eats nor lets eat."},
                    {nombre:"Conjunción 'sino' / Conjunction 'but rather'", desc_es:"Corrige una negación. 'But rather' en inglés.", desc_en:"Corrects a negation. 'But rather' in English.", ej_es:"No es azul, sino verde.", ej_en:"It is not blue, but rather green."}
                ]
            },
            {
                nombre: "I. Comparaciones básicas / Basic Comparisons (tan... como / as... as)",
                tecnicas: [
                    {nombre:"Comparativo de igualdad (tan... como) / As... as", desc_es:"'Tan... como'. 'As... as' en inglés.", desc_en:"'Tan... como'. 'As... as' in English.", ej_es:"Es tan alto como yo.", ej_en:"He is as tall as me."},
                    {nombre:"Comparativo de superioridad (más... que) / More... than or -er than", desc_es:"'Más... que'. 'More... than' o '-er than'.", desc_en:"'Más... que'. 'More... than' or '-er than'.", ej_es:"Más grande que.", ej_en:"Bigger than."},
                    {nombre:"Comparativo de inferioridad (menos... que) / Less... than", desc_es:"'Menos... que'. 'Less... than' en inglés.", desc_en:"'Menos... que'. 'Less... than' in English.", ej_es:"Menos caro que.", ej_en:"Less expensive than."},
                    {nombre:"Superlativo relativo (el más... de) / The most... or the -est", desc_es:"'El más... de'. 'The most...' o '-est'.", desc_en:"'El más... de'. 'The most...' or '-est'.", ej_es:"El más alto de.", ej_en:"The tallest."},
                    {nombre:"Comparativos irregulares (mejor, peor) / Irregular comparatives (better, worse)", desc_es:"'Mejor, peor, mayor, menor'.", desc_en:"'Better, worse, older, younger'.", ej_es:"Mejor que.", ej_en:"Better than."},
                    {nombre:"Comparativos de cantidad (tanto... como) / As much... as", desc_es:"'Tanto... como'. 'As much... as'.", desc_en:"'Tanto... como'. 'As much... as'.", ej_es:"Tanto dinero como tú.", ej_en:"As much money as you."},
                    {nombre:"Comparativos con 'más de' (cantidad) / More than (quantity)", desc_es:"'Más de' para cantidades numéricas.", desc_en:"'More than' for quantities.", ej_es:"Más de diez personas.", ej_en:"More than ten people."},
                    {nombre:"Comparativos con 'menos de' (cantidad) / Less than (quantity)", desc_es:"'Menos de' para cantidades numéricas.", desc_en:"'Less than' for quantities.", ej_es:"Menos de cinco euros.", ej_en:"Less than five euros."},
                    {nombre:"Comparativos progresivos (cada vez más) / More and more", desc_es:"'Cada vez más'. 'More and more'.", desc_en:"'Cada vez más'. 'More and more'.", ej_es:"Cada vez más difícil.", ej_en:"More and more difficult."},
                    {nombre:"Comparativos con 'igual de' / As... as (equal)", desc_es:"'Igual de... que'. 'As... as'.", desc_en:"'Igual de... que'. 'As... as'.", ej_es:"Igual de bonito que.", ej_en:"As beautiful as."}
                ]
            },
            {
                nombre: "J. Errores comunes y cómo evitarlos / Common Mistakes and How to Avoid Them",
                tecnicas: [
                    {nombre:"Confundir 'ser' y 'estar' / Confusing 'ser' and 'estar'", desc_es:"'Ser' permanente, 'estar' temporal.", desc_en:"'Ser' permanent, 'estar' temporary.", ej_es:"Soy feliz (siempre).", ej_en:"I am happy (always)."},
                    {nombre:"Olvidar el artículo en inglés con profesiones / Forgetting the article with professions in English", desc_es:"En español se omite. En inglés 'a/an'.", desc_en:"Omitted in Spanish. 'A/an' in English.", ej_es:"Ella es médica.", ej_en:"She is a doctor."},
                    {nombre:"Usar doble negación en inglés / Using double negation in English", desc_es:"En español es correcta. En inglés no.", desc_en:"Correct in Spanish. Incorrect in English.", ej_es:"No quiero nada.", ej_en:"I do not want anything (not 'nothing')."},
                    {nombre:"Colocar el adjetivo antes del sustantivo en español / Placing the adjective before the noun in Spanish", desc_es:"En español va detrás normalmente.", desc_en:"Normally after the noun in Spanish.", ej_es:"Un libro interesante.", ej_en:"An interesting book (before in English)."},
                    {nombre:"Omitir el pronombre sujeto en inglés / Omitting the subject pronoun in English", desc_es:"En español se omite. En inglés es obligatorio.", desc_en:"Omitted in Spanish. Obligatory in English.", ej_es:"Voy al cine.", ej_en:"I go to the cinema."},
                    {nombre:"Confundir 'por' y 'para' / Confusing 'por' and 'para'", desc_es:"'Por' (causa), 'para' (finalidad).", desc_en:"'Por' (cause), 'para' (purpose).", ej_es:"Gracias por todo.", ej_en:"Thanks for everything."},
                    {nombre:"Usar 'the' con idiomas en inglés / Using 'the' with languages in English", desc_es:"En español 'el español'. En inglés 'Spanish'.", desc_en:"'El español'. In English 'Spanish' (no 'the').", ej_es:"El español es fácil.", ej_en:"Spanish is easy."},
                    {nombre:"Concordancia de género en adjetivos españoles / Gender agreement in Spanish adjectives", desc_es:"El adjetivo concuerda con el sustantivo.", desc_en:"Adjectives agree with nouns in Spanish.", ej_es:"La casa blanca.", ej_en:"The white house."},
                    {nombre:"Verbo 'gustar' (me gusta vs I like) / Verb 'gustar' vs 'like'", desc_es:"'Gustar' funciona al revés que 'like'.", desc_en:"'Gustar' works differently from 'like'.", ej_es:"Me gusta el café.", ej_en:"I like coffee."},
                    {nombre:"Uso correcto de 'hay' vs 'there is/are' / Correct use of 'hay' vs 'there is/are'", desc_es:"'Hay' invariable. 'There is' (singular), 'there are' (plural).", desc_en:"'Hay' invariable. 'There is' (singular), 'there are' (plural).", ej_es:"Hay un libro.", ej_en:"There is a book."}
                ]
            }
        ];

        const todasLasTecnicas = [];
        familiasData.forEach(fam => {
            fam.tecnicas.forEach(t => {
                todasLasTecnicas.push({...t, familia: fam.nombre});
            });
        });

        // Fecha
        document.getElementById('fechaHoy').textContent = new Date().toLocaleDateString('es-ES',{year:'numeric',month:'long',day:'numeric'});

        // Acordeón
        const acordeonDiv = document.getElementById('acordeonFamilias');
        const sinResultados = document.getElementById('sinResultados');
        const buscadorInput = document.getElementById('buscarTecnica');

        function renderizarAcordeon(familiasFiltradas = null) {
            acordeonDiv.innerHTML = '';
            const familiasARenderizar = familiasFiltradas || familiasData;
            let algunaCoincidencia = false;
            familiasARenderizar.forEach((fam, idx) => {
                const colDiv = document.createElement('div');
                colDiv.className = 'col-lg-6 mb-3';
                const card = document.createElement('div');
                card.className = 'card card-familia';
                const header = document.createElement('div');
                header.className = 'card-header d-flex justify-content-between align-items-center';
                header.setAttribute('data-bs-toggle', 'collapse');
                header.setAttribute('data-bs-target', `#familia${idx}`);
                header.setAttribute('aria-expanded', 'false');
                header.style.cursor = 'pointer';
                header.innerHTML = `<span>${fam.nombre}</span><span class="badge badge-tecnicas">${fam.tecnicas.length} técnicas</span>`;
                const collapse = document.createElement('div');
                collapse.className = 'collapse';
                collapse.id = `familia${idx}`;
                const body = document.createElement('div');
                body.className = 'card-body';
                fam.tecnicas.forEach(t => {
                    const item = document.createElement('div');
                    item.className = 'tecnica-item';
                    const anotacion = document.createElement('div');
                    anotacion.className = 'tecnica-anotacion';
                    anotacion.textContent = '✎ ' + t.nombre.substring(0, 18);
                    item.appendChild(anotacion);
                    const nombre = document.createElement('div');
                    nombre.className = 'tecnica-nombre';
                    nombre.innerHTML = `${t.nombre} <span class="en">(${t.en || ''})</span>`;
                    item.appendChild(nombre);
                    const desc = document.createElement('div');
                    desc.className = 'tecnica-desc';
                    desc.innerHTML = `${t.desc_es} <br><span class="en">${t.desc_en}</span>`;
                    item.appendChild(desc);
                    const ejemplo = document.createElement('div');
                    ejemplo.className = 'tecnica-ejemplo';
                    ejemplo.innerHTML = `<span class="es">${t.ej_es}</span><span class="en">${t.ej_en}</span>`;
                    item.appendChild(ejemplo);
                    body.appendChild(item);
                });
                collapse.appendChild(body);
                card.appendChild(header);
                card.appendChild(collapse);
                colDiv.appendChild(card);
                acordeonDiv.appendChild(colDiv);
                algunaCoincidencia = true;
            });
            sinResultados.style.display = algunaCoincidencia ? 'none' : 'block';
        }

        buscadorInput.addEventListener('input', () => {
            const termino = buscadorInput.value.toLowerCase().trim();
            if (!termino) { renderizarAcordeon(); return; }
            const filtradas = familiasData.map(fam => {
                const tecFiltradas = fam.tecnicas.filter(t =>
                    t.nombre.toLowerCase().includes(termino) ||
                    t.desc_es.toLowerCase().includes(termino) ||
                    t.desc_en.toLowerCase().includes(termino) ||
                    t.ej_es.toLowerCase().includes(termino) ||
                    t.ej_en.toLowerCase().includes(termino) ||
                    fam.nombre.toLowerCase().includes(termino)
                );
                return {...fam, tecnicas: tecFiltradas};
            }).filter(fam => fam.tecnicas.length > 0);
            renderizarAcordeon(filtradas);
        });
        renderizarAcordeon();

        // Quiz bilingüe
        let preguntaActual = null, respondido = false;
        let aciertos = 0, totalPreguntas = 0, racha = 0, rachaMax = 0;
        const contadorAciertos = document.getElementById('contadorAciertos');
        const contadorRacha = document.getElementById('contadorRacha');
        const contadorTotal = document.getElementById('contadorTotal');
        const preguntaTexto = document.getElementById('preguntaTexto');
        const opcionesDiv = document.getElementById('opcionesFragmentos');
        const feedbackDiv = document.getElementById('feedbackQuiz');
        const btnSiguiente = document.getElementById('btnSiguiente');

        function cargarProgreso() {
            if (localStorage.getItem('progresoMorfosinBilingueA1')) {
                const p = JSON.parse(localStorage.getItem('progresoMorfosinBilingueA1'));
                aciertos = p.aciertos||0; totalPreguntas = p.total||0; racha = p.racha||0; rachaMax = p.rachaMax||0;
            }
            actualizarMarcadores();
        }
        function guardarProgreso() {
            localStorage.setItem('progresoMorfosinBilingueA1', JSON.stringify({aciertos,total:totalPreguntas,racha,rachaMax}));
        }
        function actualizarMarcadores() {
            contadorAciertos.textContent = aciertos;
            contadorRacha.textContent = racha;
            contadorTotal.textContent = totalPreguntas;
        }
        function generarPregunta() {
            const correcta = todasLasTecnicas[Math.floor(Math.random()*todasLasTecnicas.length)];
            const distractores = todasLasTecnicas.filter(t => t.nombre !== correcta.nombre).sort(()=>Math.random()-0.5).slice(0,3);
            return { correcta, opciones: [correcta,...distractores].sort(()=>Math.random()-0.5) };
        }
        function mostrarPregunta() {
            respondido = false;
            const { correcta, opciones } = generarPregunta();
            preguntaActual = { correcta, opciones };
            preguntaTexto.innerHTML = `¿Cuál es el ejemplo en español de esta técnica? <em class="text-danger">${correcta.nombre}</em>?<br><small style="color:var(--bilingue-azul);">What is the Spanish example for <em>${correcta.en}</em>?</small>`;
            opcionesDiv.innerHTML = '';
            opciones.forEach(op => {
                const div = document.createElement('div');
                div.className = 'col-md-6';
                const opt = document.createElement('div');
                opt.className = 'quiz-option';
                opt.innerHTML = `<span class="es">${op.ej_es}</span><br><span class="en" style="font-size:0.75rem;color:var(--bilingue-azul);">${op.ej_en}</span>`;
                opt.addEventListener('click', () => seleccionarFragmento(op, opt));
                div.appendChild(opt);
                opcionesDiv.appendChild(div);
            });
            feedbackDiv.innerHTML = '';
            btnSiguiente.style.display = 'none';
        }
        function seleccionarFragmento(opcion, elementoDiv) {
            if (respondido) return;
            respondido = true;
            const correcta = preguntaActual.correcta;
            const esCorrecta = opcion.nombre === correcta.nombre;
            totalPreguntas++;
            if (esCorrecta) {
                aciertos++; racha++;
                if (racha > rachaMax) rachaMax = racha;
                elementoDiv.classList.add('correcta');
                feedbackDiv.innerHTML = `<div class="alert alert-success mt-3">✓ Correcto: <strong>${correcta.nombre}</strong><br>${correcta.desc_es}<br><small style="color:var(--bilingue-azul);">${correcta.desc_en}</small></div>`;
            } else {
                racha = 0;
                elementoDiv.classList.add('incorrecta');
                const divs = document.querySelectorAll('.quiz-option');
                divs.forEach(d => { if (d.textContent.includes(correcta.ej_es)) d.classList.add('correcta'); });
                feedbackDiv.innerHTML = `<div class="alert alert-danger mt-3">✗ Incorrecto. La respuesta era <strong>${correcta.nombre}</strong>:<br>${correcta.desc_es}<br><small style="color:var(--bilingue-azul);">${correcta.desc_en}</small></div>`;
            }
            guardarProgreso();
            actualizarMarcadores();
            btnSiguiente.style.display = 'inline-block';
        }
        btnSiguiente.addEventListener('click', mostrarPregunta);
        document.querySelector('[data-bs-target="#practicarTab"]').addEventListener('click', () => {
            if (!preguntaActual) mostrarPregunta();
        });
        cargarProgreso();
        mostrarPregunta();
    })();
</script>
</body>
</html>

