<script>
    // ===================== DATOS COMPLETOS =====================
    // Cada técnica: { id, bloque, categoria, nombre, teoria, ejemplo, ejercicio, respuesta }
    const TECNICAS = [
        // Bloque I: Orden de palabras (10)
        { id: 1, bloque: 1, categoria: "orden", nombre: "Hipérbaton", teoria: "Alteración del orden lógico de las palabras en la oración por razones estilísticas.", ejemplo: "Del cielo cayó una rosa → Una rosa cayó del cielo.", ejercicio: "Reordena: 'De su boca dulce miel mana'", respuesta: "Mana dulce miel de su boca." },
        { id: 2, bloque: 1, categoria: "orden", nombre: "Anástrofe", teoria: "Inversión de dos palabras contiguas (hipérbaton menor).", ejemplo: "Campos de sol → De sol campos.", ejercicio: "Invierte: 'Amor eterno'", respuesta: "Eterno amor." },
        { id: 3, bloque: 1, categoria: "orden", nombre: "Tmesis", teoria: "Separación de los elementos de una palabra compuesta.", ejemplo: "¡Qué bien te a- (mañana) -compañaré!", ejercicio: "Separa: 'bienvenido'", respuesta: "bien-venido (tmesis)" },
        { id: 4, bloque: 1, categoria: "orden", nombre: "Sínquisis", teoria: "Ordenación confusa y entrecruzada de palabras.", ejemplo: "De la tierra el fruto el cielo cría.", ejercicio: "Reordena: 'La espada al hombre el hierro forja'", respuesta: "El hierro forja la espada al hombre." },
        { id: 5, bloque: 1, categoria: "orden", nombre: "Histerología", teoria: "Inversión del orden lógico o temporal de los conceptos.", ejemplo: "Primero muere, luego vive.", ejercicio: "Corrige: 'Al atardecer amanece'", respuesta: "Amanece al atardecer (si es metáfora) o invierte." },
        { id: 6, bloque: 1, categoria: "orden", nombre: "Paréntesis", teoria: "Inserción de una frase dentro de otra sin conexión sintáctica.", ejemplo: "El río (que baja del monte) es cristalino.", ejercicio: "Inserta: 'la casa' en 'El árbol es viejo'", respuesta: "El árbol (la casa) es viejo." },
        { id: 7, bloque: 1, categoria: "orden", nombre: "Anacoluto", teoria: "Ruptura de la construcción sintáctica, cambio de sujeto.", ejemplo: "A ti, nunca te he mentido.", ejercicio: "Identifica anacoluto en: 'A mí, me gusta el café'", respuesta: "Sí (redundancia de complemento)." },
        { id: 8, bloque: 1, categoria: "orden", nombre: "Asíndeton", teoria: "Omisión de conjunciones, da agilidad.", ejemplo: "Vine, vi, vencí.", ejercicio: "Convierte: 'y' en elipsis: 'y'", respuesta: "Vine, vi, vencí." },
        { id: 9, bloque: 1, categoria: "orden", nombre: "Polisíndeton", teoria: "Uso repetido de conjunciones, da lentitud.", ejemplo: "Y corre y salta y ríe.", ejercicio: "Añade conjunciones: 'corre salta ríe'", respuesta: "y corre y salta y ríe." },
        { id: 10, bloque: 1, categoria: "orden", nombre: "Elipsis", teoria: "Omisión de un elemento que se sobrentiende.", ejemplo: "Él, médico; ella, abogada.", ejercicio: "Omitir verbo: 'Juan come pan; María come fruta'", respuesta: "Juan, pan; María, fruta." },
        // Bloque II: Concordancia y morfología flexiva (10)
        { id: 11, bloque: 2, categoria: "concordancia", nombre: "Concordancia nominal", teoria: "Coincidencia en género y número entre sustantivo y adjetivo.", ejemplo: "Casa blanca / Casas blancas.", ejercicio: "Corrige: 'niño hermosa'", respuesta: "niño hermoso." },
        { id: 12, bloque: 2, categoria: "concordancia", nombre: "Concordancia verbal", teoria: "Coincidencia en número y persona entre sujeto y verbo.", ejemplo: "Yo canto / Ellos cantan.", ejercicio: "Corrige: 'Ellos canta'", respuesta: "Ellos cantan." },
        { id: 13, bloque: 2, categoria: "morfología", nombre: "Género gramatical", teoria: "Clasificación de sustantivos en masculino/femenino.", ejemplo: "el día, la mano.", ejercicio: "¿Género de 'mar'? (dos opciones)", respuesta: "masculino/femenino (el mar/la mar)." },
