        { id: 53, bloque: 5, categoria: "figuras", nombre: "Sinécdoque", teoria: "La parte por el todo.", ejemplo: "Cien cabezas de ganado.", ejercicio: "Sinécdoque: 'alma' por persona", respuesta: "no hay un alma." },
        { id: 54, bloque: 5, categoria: "figuras", nombre: "Metonimia", teoria: "Relación de causa-efecto, continente-contenido.", ejemplo: "Bebo una copa.", ejercicio: "Metonimia: 'pluma' por escritor", respuesta: "una pluma famosa." },
        // Bloque VI: Pronombres y deícticos (8)
        { id: 55, bloque: 6, categoria: "pronombre", nombre: "Pronombre personal", teoria: "Sustituye al nombre (yo, tú, él...).", ejemplo: "Yo leo.", ejercicio: "Sustituye: 'María'", respuesta: "ella." },
        { id: 56, bloque: 6, categoria: "pronombre", nombre: "Pronombre posesivo", teoria: "Indica pertenencia (mío, tuyo...).", ejemplo: "El libro es mío.", ejercicio: "Posesivo de 'nosotros'", respuesta: "nuestro." },
        { id: 57, bloque: 6, categoria: "pronombre", nombre: "Pronombre demostrativo", teoria: "Señala distancia (este, ese, aquel).", ejemplo: "Ese es mi coche.", ejercicio: "Demostrativo lejano", respuesta: "aquel." },
        { id: 58, bloque: 6, categoria: "pronombre", nombre: "Pronombre relativo", teoria: "Refiere a un antecedente (que, quien, cual).", ejemplo: "El niño que ríe.", ejercicio: "Relativo: 'la casa, vive'", respuesta: "la casa donde vive." },
        { id: 59, bloque: 6, categoria: "pronombre", nombre: "Pronombre interrogativo", teoria: "Pregunta directa (qué, quién, cuál).", ejemplo: "¿Qué quieres?", ejercicio: "Interrogativo: 'persona'", respuesta: "¿quién?" },
        { id: 60, bloque: 6, categoria: "pronombre", nombre: "Pronombre exclamativo", teoria: "Exclamación (qué, quién, cuál).", ejemplo: "¡Qué día!", ejercicio: "Exclamativo: 'sorpresa'", respuesta: "¡qué sorpresa!" },
        { id: 61, bloque: 6, categoria: "deíctico", nombre: "Deíctico de persona", teoria: "Señala al hablante/oyente (yo, tú).", ejemplo: "Tú y yo.", ejercicio: "Deíctico 2ª persona", respuesta: "tú." },
        { id: 62, bloque: 6, categoria: "deíctico", nombre: "Deíctico de lugar", teoria: "Aquí, allí, cerca, lejos.", ejemplo: "Ven aquí.", ejercicio: "Deíctico de lejanía", respuesta: "allí." },
        // Bloque VII: Estilo y cohesión (13)
        { id: 63, bloque: 7, categoria: "estilo", nombre: "Cohesión referencial", teoria: "Uso de pronombres para evitar repetición.", ejemplo: "Juan estudia. Él es inteligente.", ejercicio: "Sustituye: 'María, María'", respuesta: "María, ella." },
        { id: 64, bloque: 7, categoria: "estilo", nombre: "Cohesión léxica", teoria: "Uso de sinónimos o hiperónimos.", ejemplo: "perro, can, animal.", ejercicio: "Sinónimo de 'casa'", respuesta: "hogar." },
        { id: 65, bloque: 7, categoria: "estilo", nombre: "Conectores", teoria: "Palabras que enlazan ideas (pero, además).", ejemplo: "Estudia, además practica.", ejercicio: "Añade conector: 'cansado, sigue'", respuesta: "cansado, pero sigue." },
        { id: 66, bloque: 7, categoria: "estilo", nombre: "Marcadores de orden", teoria: "Primero, después, finalmente.", ejemplo: "Primero, prepara.", ejercicio: "Marcador de cierre", respuesta: "finalmente." },
        { id: 67, bloque: 7, categoria: "estilo", nombre: "Repetición", teoria: "Uso reiterado de una palabra.", ejemplo: "El viento, el viento.", ejercicio: "Repite: 'silencio'", respuesta: "silencio, silencio." },
        { id: 68, bloque: 7, categoria: "estilo", nombre: "Paralelismo", teoria: "Estructura sintáctica similar.", ejemplo: "Correr, saltar, jugar.", ejercicio: "Paralelismo: 'amar, soñar'", respuesta: "amar, soñar, vivir." },
        { id: 69, bloque: 7, categoria: "estilo", nombre: "Anáfora", teoria: "Repetición al comienzo de versos.", ejemplo: "Tú, tú...", ejercicio: "Anáfora: 'no'", respuesta: "no, no, no." },
        { id: 70, bloque: 7, categoria: "estilo", nombre: "Epífora", teoria: "Repetición al final.", ejemplo: "canta, siempre canta.", ejercicio: "Epífora: 'siempre'", respuesta: "siempre, siempre." },
        { id: 71, bloque: 7, categoria: "estilo", nombre: "Epanadiplosis", teoria: "Repetición al inicio y final.", ejemplo: "Blanca, la nieve blanca.", ejercicio: "Epanadiplosis: 'amor'", respuesta: "Amor, te quiero amor." },
        { id: 72, bloque: 7, categoria: "estilo", nombre: "Registro formal", teoria: "Lenguaje cuidado, sin coloquialismos.", ejemplo: "Estimado señor.", ejercicio: "Formal: 'hola, tío'", respuesta: "Buenos días, señor." },
        { id: 73, bloque: 7, categoria: "estilo", nombre: "Registro informal", teoria: "Lenguaje familiar, coloquial.", ejemplo: "¿Qué pasa?", ejercicio: "Informal: 'gracias'", respuesta: "gracias, tío." },
        { id: 74, bloque: 7, categoria: "estilo", nombre: "Precisión léxica", teoria: "Uso de palabras exactas.", ejemplo: "no decir 'cosa'", ejercicio: "Sustituye: 'cosa' por 'asunto'", respuesta: "asunto." },
        { id: 75, bloque: 7, categoria: "estilo", nombre: "Variedad lingüística", teoria: "Adaptación a región o contexto.", ejemplo: "vos (Río de la Plata).", ejercicio: "Voseo: 'tú'", respuesta: "vos." },
    ];

    // Expandir hasta 100 (relleno con técnicas adicionales para completar el número)
    // Se añaden 25 técnicas más de los bloques existentes con datos coherentes.
    const extras = [
        { id: 76, bloque: 1, categoria: "orden", nombre: "Quiasmo", teoria: "Cruza dos elementos en paralelo (ABBA).", ejemplo: "Por la mañana, trabajo; por la tarde, descanso.", ejercicio: "Quiasmo: 'amor, odio'", respuesta: "amor y odio, odio y amor." },
        { id: 77, bloque: 1, categoria: "orden", nombre: "Retruécano", teoria: "Repetición con inversión de elementos.", ejemplo: "¿Estás loco, o loco estás?", ejercicio: "Retruécano: 'tú, yo'", respuesta: "tú por mí, yo por ti." },
        { id: 78, bloque: 2, categoria: "concordancia", nombre: "Concordancia de participio", teoria: "El participio concuerda en género y número con el objeto.", ejemplo: "Hechas las paces.", ejercicio: "Concuerda: 'las tareas, hacer'", respuesta: "hechas las tareas." },
        { id: 79, bloque: 2, categoria: "morfología", nombre: "Aumentativos", teoria: "Sufijos que aumentan tamaño ( -ón, -azo).", ejemplo: "casa → caserón.", ejercicio: "Aumentativo de 'libro'", respuesta: "librote." },
        { id: 80, bloque: 2, categoria: "morfología", nombre: "Diminutivos", teoria: "Sufijos que disminuyen (-ito, -illo).", ejemplo: "casa → casita.", ejercicio: "Diminutivo de 'joven'", respuesta: "jovencito." },
        { id: 81, bloque: 3, categoria: "tiempos", nombre: "Pretérito anterior", teoria: "Pasado inmediato anterior (hube cantado).", ejemplo: "Cuando hube llegado...", ejercicio: "Pret. anterior de 'salir' 1ª sing.", respuesta: "hube salido." },
        { id: 82, bloque: 3, categoria: "tiempos", nombre: "Futuro imperfecto de subjuntivo", teoria: "Futuro incierto (cantare).", ejemplo: "Si cantare...", ejercicio: "Futuro subj. de 'comer' 2ª sing.", respuesta: "comieres." },
        { id: 83, bloque: 4, categoria: "subordinación", nombre: "Subordinación concesiva", teoria: "A pesar de que, aunque.", ejemplo: "Aunque llueva, salgo.", ejercicio: "Concesiva: 'estudiar, suspendió'", respuesta: "aunque estudió, suspendió." },
        { id: 84, bloque: 4, categoria: "subordinación", nombre: "Subordinación final", teoria: "Indica propósito (para que).", ejemplo: "Estudia para que apruebes.", ejercicio: "Final: 'ahorrar, viajar'", respuesta: "ahorra para viajar." },
        { id: 85, bloque: 5, categoria: "figuras", nombre: "Onomatopeya", teoria: "Imitación de sonidos.", ejemplo: "El tic-tac del reloj.", ejercicio: "Onomatopeya de 'gato'", respuesta: "miau." },
        { id: 86, bloque: 5, categoria: "figuras", nombre: "Aliteración", teoria: "Repetición de sonidos.", ejemplo: "El ruido con recio rumor.", ejercicio: "Aliteración con 's'", respuesta: "susurro de seda." },
        { id: 87, bloque: 6, categoria: "pronombre", nombre: "Pronombre indefinido", teoria: "Indica cantidad imprecisa (alguien, nadie).", ejemplo: "Alguien llamó.", ejercicio: "Indefinido de 'ninguna persona'", respuesta: "nadie." },
        { id: 88, bloque: 6, categoria: "pronombre", nombre: "Pronombre numeral", teoria: "Indica número (uno, dos).", ejemplo: "Llegaron dos.", ejercicio: "Numeral de '7'", respuesta: "siete." },
        { id: 89, bloque: 7, categoria: "estilo", nombre: "Hipálage", teoria: "Atribuir una cualidad a un sustantivo contiguo.", ejemplo: "El triste silencio.", ejercicio: "Hipálage: 'veloz coche'", respuesta: "el veloz coche (veloz=conductor)." },
        { id: 90, bloque: 7, categoria: "estilo", nombre: "Enumeración", teoria: "Lista de elementos.", ejemplo: "Compró pan, leche, huevos.", ejercicio: "Enumera: 'frutas'", respuesta: "manzana, pera, naranja." },
        { id: 91, bloque: 1, categoria: "orden", nombre: "Hipérbaton extremo", teoria: "Inversión drástica del orden.", ejemplo: "De las montañas el viento.", ejercicio: "Reordena: 'El sol brilla en el cielo'", respuesta: "En el cielo brilla el sol." },
        { id: 92, bloque: 2, categoria: "morfología", nombre: "Flexión de caso", teoria: "En español, solo residuos (mío, etc.).", ejemplo: "de mí, para ti.", ejercicio: "Caso: 'a mí'", respuesta: "dativo." },
        { id: 93, bloque: 3, categoria: "tiempos", nombre: "Presente histórico", teoria: "Presente para narrar pasado.", ejemplo: "Colón llega a América.", ejercicio: "Presente histórico: 'descubrir'", respuesta: "descubre." },
        { id: 94, bloque: 4, categoria: "coordinación", nombre: "Coordinación ilativa", teoria: "Conclusión lógica (luego, por tanto).", ejemplo: "Estudió, luego aprobó.", ejercicio: "Ilativa: 'llueve, mojado'", respuesta: "llueve, luego me mojo." },
        { id: 95, bloque: 5, categoria: "figuras", nombre: "Prosopopeya", teoria: "Personificación de objetos abstractos.", ejemplo: "La justicia ciega.", ejercicio: "Prosopopeya: 'la muerte'", respuesta: "la muerte llegó." },
        { id: 96, bloque: 6, categoria: "pronombre", nombre: "Pronombre recíproco", teoria: "Acción mutua (se).", ejemplo: "Se miran el uno al otro.", ejercicio: "Recíproco: 'abrazar'", respuesta: "se abrazan." },
        { id: 97, bloque: 7, categoria: "estilo", nombre: "Asíndeton múltiple", teoria: "Eliminación de varias conjunciones.", ejemplo: "Vino, vio, venció, partió.", ejercicio: "Asíndeton: 'corre, salta, ríe'", respuesta: "corre, salta, ríe." },
        { id: 98, bloque: 7, categoria: "estilo", nombre: "Polisíndeton reiterado", teoria: "Repetición excesiva de y.", ejemplo: "y y y", ejercicio: "Polisíndeton: 'uno dos tres'", respuesta: "uno y dos y tres." },
        { id: 99, bloque: 1, categoria: "orden", nombre: "Pleonasmo", teoria: "Redundancia expresiva.", ejemplo: "Lo vi con mis propios ojos.", ejercicio: "Pleonasmo: 'subir arriba'", respuesta: "subir arriba (redundante)." },
        { id: 100, bloque: 7, categoria: "estilo", nombre: "Cacofonía", teoria: "Sonido desagradable (evitar).", ejemplo: "poco coco.", ejercicio: "Evita cacofonía: 'tres tristes tigres'", respuesta: "tres tristes tigres (cacofonía)." },
    ];
    TECNICAS.push(...extras);

    // ordenar por id
    TECNICAS.sort((a,b) => a.id - b.id);

    // ===================== RENDER =====================
    const blockNav = document.getElementById('blockNav');
    const cardsGrid = document.getElementById('cardsGrid');
    const quizContainer = document.getElementById('quizContainer');

    let currentBlock = 1;
    const BLOCK_NAMES = ['', 'Orden de palabras', 'Concordancia y morfología', 'Tiempos verbales', 'Coordinación/subordinación', 'Figuras retóricas', 'Pronombres y deícticos', 'Estilo y cohesión'];

    // generar navegación
    for (let i = 1; i <= 7; i++) {
        const btn = document.createElement('button');
        btn.textContent = `${i}. ${BLOCK_NAMES[i]}`;
        btn.dataset.block = i;
        btn.addEventListener('click', () => {
            currentBlock = i;
            renderCards(i);
            updateNav(i);
        });
        blockNav.appendChild(btn);
    }

    function updateNav(block) {
        document.querySelectorAll('.block-nav button').forEach(b => b.classList.toggle('active', parseInt(b.dataset.block) === block));
    }
    updateNav(1);

    function renderCards(block) {
        const filtered = TECNICAS.filter(t => t.bloque === block);
        cardsGrid.innerHTML = filtered.map((t, idx) => {
            return `
                <div class="card-flip" data-id="${t.id}" onclick="this.classList.toggle('flipped')">
                    <div class="card-flip-inner">
                        <div class="card-front">
                            <div class="numero">${t.id}</div>
                            <span class="categoria">${t.categoria}</span>
                            <h3>${t.nombre}</h3>
                            <div class="teoria">${t.teoria}</div>
                            <div class="girar-indicador">↻ tocar para ver ejercicio</div>
                        </div>
                        <div class="card-back">
                            <div style="font-weight:600;color:#1F4E5F;margin-bottom:0.2rem;">📘 ${t.nombre}</div>
                            <div class="ejemplo"><strong>Ejemplo:</strong> ${t.ejemplo}</div>
                            <div class="ejercicio">✏️ ${t.ejercicio}</div>
                            <div class="respuesta">✓ ${t.respuesta}</div>
                            <div class="etiqueta">técnica #${t.id} · ${t.categoria}</div>
                        </div>
                    </div>
                </div>
            `;
        }).join('');
    }

    // ===================== QUIZ =====================
    let quizQuestions = [];
    let currentQuizIndex = 0;
    let score = 0;
    let answered = false;

    function generateQuiz() {
        // tomar 10 preguntas aleatorias de las 100
        const shuffled = [...TECNICAS].sort(() => Math.random() - 0.5);
        quizQuestions = shuffled.slice(0, 10).map(t => {
            const opts = [t.respuesta];
            // añadir 3 respuestas falsas de otras técnicas
            const others = TECNICAS.filter(x => x.id !== t.id);
            const shuffledOthers = others.sort(() => Math.random() - 0.5);
            for (let i = 0; i < 3; i++) {
                if (shuffledOthers[i]) opts.push(shuffledOthers[i].respuesta);
            }
            // mezclar
            for (let i = opts.length - 1; i > 0; i--) {
                const j = Math.floor(Math.random() * (i + 1));
                [opts[i], opts[j]] = [opts[j], opts[i]];
            }
            return {
                pregunta: `¿Cuál es la respuesta correcta para: "${t.ejercicio}"? (Técnica: ${t.nombre})`,
                opciones: opts,
                correcta: t.respuesta,
                id: t.id
            };
        });
        currentQuizIndex = 0;
        score = 0;
        answered = false;
        renderQuiz();
    }

    function renderQuiz() {
        if (!quizQuestions.length) return;
        const q = quizQuestions[currentQuizIndex];
        const total = quizQuestions.length;
        const progress = `Pregunta ${currentQuizIndex+1} de ${total}`;
        let html = `
            <div class="quiz-pregunta">
                <p>${q.pregunta}</p>
                <div class="quiz-opciones" id="quizOptions">
        `;
        q.opciones.forEach((op, idx) => {
            html += `<button data-idx="${idx}" onclick="checkAnswer(${idx})">${op}</button>`;
        });
        html += `</div>
                <div id="quizFeedback" style="margin-top:0.8rem;"></div>
                <div class="quiz-result" id="quizScore">Puntuación: ${score}/${total}</div>
            </div>
            <div class="quiz-controles">
                <button id="nextQuizBtn" disabled>→ Siguiente</button>
                <button onclick="generateQuiz()">🔄 Nuevo cuestionario</button>
            </div>
        `;
        quizContainer.innerHTML = html;
        answered = false;
        document.getElementById('nextQuizBtn').disabled = true;
    }

    window.checkAnswer = function(idx) {
        if (answered) return;
        const q = quizQuestions[currentQuizIndex];
        const buttons = document.querySelectorAll('#quizOptions button');
        buttons.forEach((b, i) => {
            b.disabled = true;
            if (i === idx) {
                const esCorrecta = q.opciones[idx] === q.correcta;
                b.classList.add(esCorrecta ? 'correct' : 'incorrect');
                if (esCorrecta) score++;
            }
            if (q.opciones[i] === q.correcta) {
                buttons[i].classList.add('correct');
            }
        });
        answered = true;
        document.getElementById('nextQuizBtn').disabled = false;
        document.getElementById('quizScore').textContent = `Puntuación: ${score}/${quizQuestions.length}`;
        const fb = document.getElementById('quizFeedback');
        fb.innerHTML = `<span style="background:#1F4E5F;color:white;padding:0.2rem 1rem;border-radius:40px;">Respuesta: ${q.correcta}</span>`;
    }

    document.addEventListener('click', function(e) {
        if (e.target.id === 'nextQuizBtn') {
            if (currentQuizIndex < quizQuestions.length - 1) {
                currentQuizIndex++;
                renderQuiz();
            } else {
                alert(`¡Cuestionario finalizado! Puntuación: ${score}/${quizQuestions.length}`);
                document.getElementById('nextQuizBtn').disabled = true;
            }
        }
    });

    // inicializar
    renderCards(1);
    generateQuiz();
</script>
</body>
</html>

