<body>
<div class="container" id="app">
    <div class="header">
        <h1>Fichero <span>100 técnicas</span></h1>
        <div class="sub">lengua española · archivo</div>
    </div>

    <!-- navegación por bloques -->
    <div class="block-nav" id="blockNav"></div>

    <!-- grid de tarjetas -->
    <div id="cardsGrid" class="cards-grid"></div>

    <!-- Quiz -->
    <div class="quiz-section" id="quizSection">
        <h2>📝 Cuestionario <small>elige la respuesta correcta</small></h2>
        <div id="quizContainer"></div>
    </div>
    <div class="footer">Fichas de estudio · 100 técnicas · teoría + ejemplo + ejercicio</div>
</div>

<script>
