            { titulo: "El uso correcto de la 'g' y la 'j'", teoria: "Se escribe 'g' en verbos terminados en -ger, -gir (excepto tejer y crujir). Se escribe 'j' en el resto de casos.", recurso: "G y J", ejemplo: "'coger' (g), 'tejer' (j), 'jirafa' (j).", ejercicio: "Escribe 10 palabras con G y 10 con J.", reto: "Escribe un párrafo usando correctamente G y J." },
            { titulo: "El uso correcto de la 'c', 's' y 'z'", teoria: "La 'c' se usa en verbos terminados en -cer, -cir. La 'z' en terminaciones -anza, -azgo. La 's' en adjetivos con -oso, -osa.", recurso: "C, S y Z", ejemplo: "'conocer' (c), 'esperanza' (z), 'peligroso' (s).", ejercicio: "Escribe 10 palabras con C, S y Z.", reto: "Escribe un párrafo usando correctamente C, S y Z." },
            { titulo: "El uso correcto de la 'h'", teoria: "La 'h' se escribe en palabras que comienzan con 'hie-', 'hue-', 'hu-', y en los verbos 'haber', 'hacer', etc.", recurso: "H", ejemplo: "'hierro', 'hueso', 'hacer', 'haber'.", ejercicio: "Escribe 10 palabras con H.", reto: "Escribe un párrafo usando correctamente la H." },
            { titulo: "El uso correcto de la 'y' y la 'll'", teoria: "La 'y' se escribe al final de palabra (cuando no es vocal) y en la conjunción 'y'. La 'll' en palabras que provienen de 'li-', 'le-', etc.", recurso: "Y y LL", ejemplo: "'hay', 'muy', 'rey', 'llave', 'lluvia'.", ejercicio: "Escribe 10 palabras con Y y 10 con LL.", reto: "Escribe un párrafo usando correctamente Y y LL." },
            { titulo: "El uso correcto de la 'ñ'", teoria: "La 'ñ' se escribe en palabras que provienen de 'ni-', 'ne-', 'na-', etc., y en aquellas con el sonido nasal palatal.", recurso: "Ñ", ejemplo: "'niño', 'leña', 'enseñar'.", ejercicio: "Escribe 10 palabras con Ñ.", reto: "Escribe un párrafo usando correctamente la Ñ." },
            { titulo: "Las reglas de acentuación (agudas, graves, esdrújulas)", teoria: "Agudas (última sílaba) llevan tilde si terminan en N, S o vocal. Graves (penúltima) llevan tilde si NO terminan en N, S o vocal. Esdrújulas (antepenúltima) SIEMPRE llevan tilde.", recurso: "Acentuación", ejemplo: "'canción' (aguda, N → tilde), 'árbol' (grave, L → tilde), 'pájaro' (esdrújula → tilde).", ejercicio: "Acentúa 20 palabras.", reto: "Escribe un texto sin errores de tilde." },
            { titulo: "La tilde diacrítica", teoria: "La tilde diacrítica diferencia palabras que se escriben igual pero tienen distinto significado: él/el, sí/si, té/te, dé/de, mí/mi.", recurso: "Tilde diacrítica", ejemplo: "'Él es valiente' (pronombre) vs 'El guerrero' (artículo).", ejercicio: "Escribe 5 parejas con tilde diacrítica.", reto: "Escribe 5 oraciones con tilde diacrítica." },
            { titulo: "El uso del punto", teoria: "El punto indica el final de una oración, párrafo o texto. Puede ser punto y seguido, punto y aparte, punto final.", recurso: "Punto", ejemplo: "'Llegó. Se sentó. Calló.'", ejercicio: "Escribe un párrafo usando los tres tipos de punto.", reto: "Revisa la puntuación de un texto." },
            { titulo: "El uso de la coma", teoria: "La coma separa elementos de una enumeración, vocativos, aposiciones, etc. También se usa para separar oraciones yuxtapuestas.", recurso: "Coma", ejemplo: "'Compré pan, leche y huevos'.", ejercicio: "Escribe 5 oraciones con coma.", reto: "Revisa el uso de la coma en un texto." },
            { titulo: "El uso del punto y coma", teoria: "El punto y coma separa oraciones relacionadas y se usa en enumeraciones complejas.", recurso: "Punto y coma", ejemplo: "'Llegó tarde; sin embargo, lo esperaron'.", ejercicio: "Escribe 3 oraciones con punto y coma.", reto: "Revisa el uso del punto y coma en un texto." },
            { titulo: "El uso de los dos puntos", teoria: "Los dos puntos introducen una enumeración, una cita, una explicación o un discurso directo.", recurso: "Dos puntos", ejemplo: "'Tres son los colores: rojo, azul y verde'.", ejercicio: "Escribe 3 oraciones con dos puntos.", reto: "Revisa el uso de los dos puntos en un texto." },
            { titulo: "El uso de las comillas", teoria: "Las comillas se usan para citas textuales, títulos de obras y palabras con sentido especial.", recurso: "Comillas", ejemplo: "'El dijo: \"Voy a llegar tarde\"'.", ejercicio: "Escribe 3 oraciones con comillas.", reto: "Revisa el uso de las comillas en un texto." },
            { titulo: "El uso de los paréntesis", teoria: "Los paréntesis se usan para incisos, aclaraciones o información complementaria.", recurso: "Paréntesis", ejemplo: "'La casa (que estaba vacía) se vendió'.", ejercicio: "Escribe 3 oraciones con paréntesis.", reto: "Revisa el uso de los paréntesis en un texto." },
            { titulo: "El uso de los signos de interrogación y exclamación", teoria: "Los signos de interrogación (¿?) y exclamación (¡!) se usan para preguntas y exclamaciones. En español, se colocan al principio y al final.", recurso: "Interrogación y exclamación", ejemplo: "'¿Cómo estás?', '¡Qué bonito!'.", ejercicio: "Escribe 3 preguntas y 3 exclamaciones.", reto: "Revisa el uso de los signos en un texto." },
            { titulo: "El uso de mayúsculas y minúsculas", teoria: "Las mayúsculas se usan al inicio de oración, nombres propios, títulos, etc. Las minúsculas en el resto.", recurso: "Mayúsculas y minúsculas", ejemplo: "'Juan vive en Madrid. La capital es Madrid.'", ejercicio: "Reescribe un texto corrigiendo el uso de mayúsculas.", reto: "Escribe un texto usando correctamente mayúsculas y minúsculas." },
            { titulo: "El uso correcto de 'ahí', 'hay', 'ay'", teoria: "'Ahí' (lugar), 'hay' (existencia), 'ay' (dolor).", recurso: "Ahí, hay, ay", ejemplo: "'La espada está ahí'. 'Hay un guerrero'. '¡Ay, me duele!'", ejercicio: "Escribe 3 oraciones con cada forma.", reto: "Escribe un párrafo usando correctamente 'ahí', 'hay' y 'ay'." },
            { titulo: "El uso correcto de 'porque', 'por qué', 'porqué', 'por que'", teoria: "'Porque' (causa), 'por qué' (pregunta), 'porqué' (sustantivo), 'por que' (preposición + pronombre).", recurso: "Porque", ejemplo: "'Gané porque luché'. '¿Por qué luchaste?'. 'No entiendo el porqué'. 'La razón por que lucho'.", ejercicio: "Escribe 4 oraciones usando cada forma.", reto: "Escribe un párrafo usando las 4 formas." },
            { titulo: "El uso correcto de 'sino' y 'si no'", teoria: "'Sino' es oposición ('No vine a rendirme, sino a vencer'). 'Si no' es condición negativa ('Si no vienes, pierdes').", recurso: "Sino / Si no", ejemplo: "'No es alto, sino bajo' (sino). 'Si no estudias, suspenderás' (si no).", ejercicio: "Escribe 2 oraciones con 'sino' y 2 con 'si no'.", reto: "Escribe un párrafo usando correctamente 'sino' y 'si no'." },
            { titulo: "El uso correcto del gerundio", teoria: "El gerundio (ando/iendo) indica simultaneidad o anterioridad, nunca posterioridad.", recurso: "Gerundio", ejemplo: "'Llegó corriendo' (mientras llegaba, corría). 'Llegó y preguntó' (NO 'llegó preguntando').", ejercicio: "Corrige 3 oraciones con gerundios mal usados.", reto: "Escribe 3 oraciones con gerundios correctos." }
        ]
    }
};

// ============================================================
// GENERAR LISTA COMPLETA DE TÉCNICAS
// ============================================================
let TECNICAS = [];
let idCounter = 0;
for (const [key, amazona] of Object.entries(AMAZONAS_DATA)) {
    const tecnicas = amazona.tecnicas.map((t, idx) => ({
        id: ++idCounter,
        amazonaKey: key,
        amazonaNombre: amazona.nombre,
        color: amazona.color,
        ...t,
        numero: idx + 1
    }));
    TECNICAS.push(...tecnicas);
}

// ============================================================
// LÓGICA DE LA APP
// ============================================================

document.querySelectorAll('.sidebar-stellar .nav-link').forEach(link => {
    link.addEventListener('click', function(e) {
        e.preventDefault();
        const section = this.dataset.section;
        document.querySelectorAll('.sidebar-stellar .nav-link').forEach(l => l.classList.remove('active'));
        this.classList.add('active');
        document.querySelectorAll('.section-content').forEach(el => el.style.display = 'none');
        const target = document.getElementById('section-' + section);
        if (target) target.style.display = 'block';
        if (['morfologia','sintaxis','fonetica','fonologia','norma'].includes(section)) {
            renderAmazona(section);
        }
        if (section === 'dashboard') actualizarDashboard();
        if (section === 'seguimiento') renderSeguimiento();
    });
});

function leerTexto(texto, boton) {
    if (!window.speechSynthesis) { alert('Tu navegador no soporta síntesis de voz.'); return; }
    if (window.speechSynthesis.speaking) {
        window.speechSynthesis.cancel();
        if (boton) { boton.innerHTML = '<i class="bi bi-play-circle"></i> Escuchar'; boton.classList.remove('escuchando'); }
        return;
    }
    const utterance = new SpeechSynthesisUtterance(texto);
    utterance.lang = 'es-ES';
    utterance.rate = 0.9;
    utterance.pitch = 1;
    if (boton) {
        boton.innerHTML = '<i class="bi bi-stop-circle"></i> Detener';
        boton.classList.add('escuchando');
        utterance.onend = function() { boton.innerHTML = '<i class="bi bi-play-circle"></i> Escuchar'; boton.classList.remove('escuchando'); };
        utterance.onerror = function() { boton.innerHTML = '<i class="bi bi-play-circle"></i> Escuchar'; boton.classList.remove('escuchando'); };
    }
    window.speechSynthesis.speak(utterance);
}

function renderAmazona(amazonaKey) {
    const container = document.getElementById('section-' + amazonaKey);
    if (!container) return;
    const data = AMAZONAS_DATA[amazonaKey];
    const colorHex = data.color === 'dorado' ? 'var(--neon-dorado)' :
                     data.color === 'azul' ? 'var(--neon-azul)' :
                     data.color === 'verde' ? 'var(--neon-verde)' :
                     data.color === 'purpura' ? 'var(--neon-purpura)' : 'var(--neon-rojo)';

    let html = `
        <div class="personaje-destacado" style="border-left:4px solid ${colorHex};">
            <div class="avatar">🤖</div>
            <div class="info">
                <h4 style="color:${colorHex};">${data.nombre} · ${data.especialidad}</h4>
                <p style="color:var(--texto-muted);">${data.tecnicas.length} técnicas interactivas. Haz clic para desplegar contenido.</p>
            </div>
        </div>
        <div id="tecnicas-${amazonaKey}">
    `;

    const tecnicas = TECNICAS.filter(t => t.amazonaKey === amazonaKey);
    const seguimiento = getSeguimiento();

    tecnicas.forEach((t) => {
        const completada = seguimiento[t.id] || false;
        const teoriaCompleta = `Técnica ${t.numero}: ${t.titulo}. ${t.teoria}`;
        const flashPregunta = t.titulo;
        const flashRespuesta = t.teoria;
        html += `
            <div class="tecnica-card" style="border-left-color: ${colorHex};">
                <div class="cabecera" onclick="toggleTecnicaCard(${t.id})">
                    <span class="num">#${t.id}</span>
                    <span class="titulo">${t.numero}. ${t.titulo}</span>
                    <span class="badge-personaje" style="background:${completada ? 'rgba(0,255,0,0.15)' : 'rgba(255,255,255,0.05)'}; color:${completada ? 'var(--neon-verde)' : '#fff'};">${completada ? '✅ Completada' : '⬜ Pendiente'}</span>
                </div>
                <div class="contenido" id="contenido-${t.id}">
                    <div class="teoria">
                        <strong>📖 Teoría:</strong> ${t.teoria}
                        <button class="btn-audio ms-2" onclick="event.stopPropagation(); leerTexto('${teoriaCompleta.replace(/'/g, "\\'")}', this);">
                            <i class="bi bi-play-circle"></i> Escuchar
                        </button>
                    </div>
                    <div class="recurso-clave">
                        <span>${t.recurso}</span>
                    </div>
                    <div class="ejemplo">
                        <strong>💡 Ejemplo del autor:</strong> ${t.ejemplo}
                    </div>
                    <div class="ejercicio">
                        <strong>✍️ Ejercicio:</strong> ${t.ejercicio}
                        <textarea placeholder="Escribe tu respuesta aquí..." rows="2"></textarea>
                        <button class="btn-neon-lleno mt-1" onclick="marcarEjercicio(${t.id})"><i class="bi bi-check-circle"></i> Marcar como completado</button>
                    </div>
                    <div class="reto"><i class="bi bi-trophy"></i> <strong>🏆 Reto:</strong> ${t.reto}</div>
                    <div class="flashcard-area" onclick="event.stopPropagation(); toggleFlashcard(${t.id})" id="flash-${t.id}">
                        <div class="flash-front" id="flash-front-${t.id}">${flashPregunta}</div>
                        <div class="flash-back" id="flash-back-${t.id}" style="display:none;">${flashRespuesta}</div>
                        <div class="flash-indicador">👆 Haz clic para ver la respuesta</div>
                    </div>
                </div>
            </div>
        `;
    });

    html += `</div>`;
    container.innerHTML = html;
}

function toggleTecnicaCard(id) {
    const content = document.getElementById('contenido-' + id);
    if (content) {
        content.style.display = content.style.display === 'block' ? 'none' : 'block';
    }
}

function toggleFlashcard(id) {
    const front = document.getElementById('flash-front-' + id);
    const back = document.getElementById('flash-back-' + id);
    const indicador = document.querySelector(`#flash-${id} .flash-indicador`);
    if (!front || !back) return;
    if (front.style.display !== 'none') {
        front.style.display = 'none';
        back.style.display = 'block';
        if (indicador) indicador.textContent = '👆 Haz clic para volver';
    } else {
        front.style.display = 'block';
        back.style.display = 'none';
        if (indicador) indicador.textContent = '👆 Haz clic para ver la respuesta';
    }
}

function marcarEjercicio(id) {
    const seguimiento = getSeguimiento();
    seguimiento[id] = true;
    setSeguimiento(seguimiento);
    const card = document.querySelector(`.tecnica-card .cabecera[onclick*="${id}"]`)?.closest('.tecnica-card');
    if (card) {
        const badge = card.querySelector('.badge-personaje');
        if (badge) {
            badge.textContent = '✅ Completada';
            badge.style.background = 'rgba(0,255,0,0.15)';
            badge.style.color = 'var(--neon-verde)';
        }
        const btn = card.querySelector('.ejercicio button');
        if (btn) {
            btn.textContent = '✅ ¡Completado!';
            btn.disabled = true;
            btn.style.opacity = '0.6';
        }
    }
    actualizarProgreso();
    actualizarDashboard();
}

// ============================================================
// SEGUIMIENTO
// ============================================================
const SEGUIMIENTO_KEY = 'flota_rae_seguimiento_v2';

function getSeguimiento() {
    const raw = localStorage.getItem(SEGUIMIENTO_KEY);
    if (raw) {
        try { return JSON.parse(raw); } catch(e) {}
    }
    return {};
}

function setSeguimiento(data) {
    localStorage.setItem(SEGUIMIENTO_KEY, JSON.stringify(data));
}

function renderSeguimiento() {
    const seguimiento = getSeguimiento();
    const tbody = document.getElementById('tabla-seguimiento-body');
    if (!tbody) return;
    let html = '';
    TECNICAS.forEach(t => {
        const checked = seguimiento[t.id] ? 'checked' : '';
        const colorHex = t.color === 'dorado' ? 'var(--neon-dorado)' :
                         t.color === 'azul' ? 'var(--neon-azul)' :
                         t.color === 'verde' ? 'var(--neon-verde)' :
                         t.color === 'purpura' ? 'var(--neon-purpura)' : 'var(--neon-rojo)';
        html += `
            <tr>
                <td>${t.id}</td>
                <td>${t.titulo}</td>
                <td><span style="background:${colorHex}; color:#0a0e17; padding:0.05rem 0.5rem; border-radius:30px; font-size:0.6rem; font-weight:600;">${t.amazonaNombre}</span></td>
                <td class="text-center"><input class="form-check-input" type="checkbox" ${checked} onchange="toggleTecnicaCheck(${t.id})"></td>
            </tr>
        `;
    });
    tbody.innerHTML = html;
    actualizarProgreso();
}

function toggleTecnicaCheck(id) {
    const seguimiento = getSeguimiento();
    seguimiento[id] = !seguimiento[id];
    setSeguimiento(seguimiento);
    actualizarProgreso();
    actualizarDashboard();
    const card = document.querySelector(`.tecnica-card .cabecera[onclick*="${id}"]`)?.closest('.tecnica-card');
    if (card) {
        const badge = card.querySelector('.badge-personaje');
        if (badge) {
            const completada = seguimiento[id];
            badge.textContent = completada ? '✅ Completada' : '⬜ Pendiente';
            badge.style.background = completada ? 'rgba(0,255,0,0.15)' : 'rgba(255,255,255,0.05)';
            badge.style.color = completada ? 'var(--neon-verde)' : '#fff';
        }
    }
}

function actualizarProgreso() {
    const seguimiento = getSeguimiento();
    const total = TECNICAS.length;
    let completadas = 0;
    TECNICAS.forEach(t => {
        if (seguimiento[t.id]) completadas++;
    });
    const pct = total > 0 ? Math.round((completadas / total) * 100) : 0;
    document.getElementById('sidebar-porcentaje').textContent = pct + '%';
    document.getElementById('sidebar-barra').style.width = pct + '%';
    document.getElementById('sidebar-detalle').textContent = `${completadas} / ${total} técnicas`;
}

function actualizarDashboard() {
    const seguimiento = getSeguimiento();
    const total = TECNICAS.length;
    let completadas = 0;
    TECNICAS.forEach(t => {
        if (seguimiento[t.id]) completadas++;
    });
    const pct = total > 0 ? Math.round((completadas / total) * 100) : 0;
    document.getElementById('dashboard-completadas').textContent = completadas;
    document.getElementById('dashboard-porcentaje').textContent = pct + '%';
}

// ============================================================
// INICIALIZACIÓN
// ============================================================
document.addEventListener('DOMContentLoaded', function() {
    document.querySelectorAll('.section-content').forEach((el, idx) => {
        el.style.display = idx === 0 ? 'block' : 'none';
    });
    renderSeguimiento();
    actualizarDashboard();
});
</script>
</body>
</html>

