        <a class="nav-link" data-section="fonologia" href="#"><i class="bi bi-robot" style="color:var(--neon-purpura);"></i> Fonología <span class="badge-personaje bg-purpura">Sistema</span></a>
        <a class="nav-link" data-section="norma" href="#"><i class="bi bi-robot" style="color:var(--neon-rojo);"></i> Norma RAE <span class="badge-personaje bg-rojo">Ortografía</span></a>
