            { titulo: "La conjugación regular", teoria: "Los verbos regulares siguen un patrón de conjugación fijo en todas sus formas. Hay tres conjugaciones: -ar, -er, -ir.", recurso: "Conjugación regular", ejemplo: "Primera conjugación (-ar): 'amar' → amo, amas, ama... Segunda (-er): 'temer' → temo, temes, teme... Tercera (-ir): 'partir' → parto, partes, parte...", ejercicio: "Conjuga un verbo de cada conjugación en presente.", reto: "Escribe 3 oraciones con verbos de cada conjugación." },
            { titulo: "La conjugación irregular", teoria: "Los verbos irregulares presentan alteraciones en su raíz o desinencias en algunas de sus formas.", recurso: "Conjugación irregular", ejemplo: "'poder' → 'puedo' (diptongo), 'tener' → 'tengo' (cambio), 'decir' → 'digo' (cambio).", ejercicio: "Conjuga 3 verbos irregulares en presente.", reto: "Escribe 5 oraciones con verbos irregulares." },
            { titulo: "Los verbos defectivos", teoria: "Los verbos defectivos son aquellos que no se conjugan en todas las personas o tiempos. Ejemplo: los verbos meteorológicos.", recurso: "Verbos defectivos", ejemplo: "'amanecer', 'llover', 'nevar' (solo se conjugan en tercera persona).", ejercicio: "Escribe 3 oraciones con verbos defectivos.", reto: "Investiga otros verbos defectivos." },
