<script>
// ============================================================
// DATOS: 5 AMAZONAS × 20 TÉCNICAS = 100
// ============================================================
const AMAZONAS_DATA = {
    morfologia: {
        nombre: "Morfología", color: "dorado", icono: "bi-robot",
        especialidad: "La estructura de las palabras: flexión, derivación, composición",
        tecnicas: [
            { titulo: "La raíz o lexema", teoria: "La raíz es el morfema que aporta el significado básico de la palabra. Es el núcleo léxico que comparten las palabras de una misma familia.", recurso: "Raíz", ejemplo: "En 'cantar', 'canto', 'canción' y 'cancionero', la raíz es 'cant-'.", ejercicio: "Identifica la raíz de 5 palabras.", reto: "Escribe 5 palabras con la misma raíz." },
            { titulo: "Los afijos (prefijos, sufijos, interfijos)", teoria: "Los afijos son morfemas que se añaden a la raíz para modificar su significado o categoría gramatical. Los prefijos van delante, los sufijos detrás y los interfijos entre raíz y sufijo.", recurso: "Afijos", ejemplo: "'deshacer' (prefijo des-), 'panadero' (sufijo -ero), 'cafetera' (interfijo -et-).", ejercicio: "Identifica los afijos en 5 palabras.", reto: "Crea 5 palabras con prefijos y sufijos." },
            { titulo: "La flexión nominal (género y número)", teoria: "La flexión nominal es la variación de los sustantivos y adjetivos para expresar género (masculino/femenino) y número (singular/plural).", recurso: "Flexión nominal", ejemplo: "'niño' (masculino singular) → 'niña' (femenino singular) → 'niños' (masculino plural) → 'niñas' (femenino plural).", ejercicio: "Flexiona 5 sustantivos en género y número.", reto: "Escribe 5 oraciones con diferentes flexiones nominales." },
            { titulo: "La flexión verbal (tiempo, modo, aspecto, persona y número)", teoria: "La flexión verbal es la variación del verbo para expresar tiempo, modo, aspecto, persona y número. Es el sistema más complejo de la morfología española.", recurso: "Flexión verbal", ejemplo: "'canto' (1ª persona singular, presente, indicativo) vs 'cantaba' (1ª persona singular, pretérito imperfecto, indicativo) vs 'canté' (1ª persona singular, pretérito perfecto simple, indicativo).", ejercicio: "Conjuga el verbo 'comer' en presente, pasado y futuro.", reto: "Escribe 5 oraciones con diferentes tiempos verbales." },
            { titulo: "La derivación", teoria: "La derivación es el proceso de formar nuevas palabras añadiendo afijos a una raíz. Puede cambiar la categoría gramatical de la palabra.", recurso: "Derivación", ejemplo: "'pan' (sustantivo) → 'panadero' (sustantivo con sufijo -ero) → 'empanar' (verbo con prefijo en- y sufijo -ar).", ejercicio: "Deriva 5 palabras a partir de una raíz.", reto: "Escribe una lista de 10 palabras derivadas." },
            { titulo: "La composición", teoria: "La composición es el proceso de formar nuevas palabras uniendo dos o más raíces o palabras simples.", recurso: "Composición", ejemplo: "'paraguas' (parar + aguas), 'abrelatas' (abrir + latas), 'telaraña' (tela + araña).", ejercicio: "Escribe 5 palabras compuestas.", reto: "Crea 5 oraciones con palabras compuestas." },
            { titulo: "La parasíntesis", teoria: "La parasíntesis es la formación de palabras mediante la combinación simultánea de prefijación y sufijación, donde la palabra simple no existe sin ambos afijos.", recurso: "Parasíntesis", ejemplo: "'enriquecer' (en- + rico + -ecer), 'enternecer' (en- + tierno + -ecer).", ejercicio: "Escribe 5 palabras parasintéticas.", reto: "Explica por qué son parasintéticas." },
            { titulo: "Los morfemas flexivos", teoria: "Los morfemas flexivos son los que indican género, número, persona, tiempo, modo y aspecto. No cambian la categoría gramatical de la palabra.", recurso: "Morfemas flexivos", ejemplo: "En 'cantábamos', '-ábamos' es un morfema flexivo que indica 1ª persona, plural, pretérito imperfecto, indicativo.", ejercicio: "Identifica los morfemas flexivos en 5 verbos.", reto: "Analiza la flexión de 5 palabras." },
            { titulo: "Los morfemas derivativos", teoria: "Los morfemas derivativos son los que se añaden a una raíz para crear una nueva palabra. Pueden cambiar la categoría gramatical.", recurso: "Morfemas derivativos", ejemplo: "En 'cantante', '-ante' es un sufijo derivativo que forma un sustantivo a partir de un verbo.", ejercicio: "Identifica los morfemas derivativos en 5 palabras.", reto: "Crea 5 palabras con morfemas derivativos." },
            { titulo: "El género gramatical", teoria: "El género gramatical es una propiedad de los sustantivos que puede ser masculino, femenino o, en algunos casos, neutro (con el artículo 'lo').", recurso: "Género gramatical", ejemplo: "'niño' (masculino), 'niña' (femenino), 'lo bueno' (neutro).", ejercicio: "Clasifica 10 sustantivos por su género.", reto: "Escribe 5 oraciones con sustantivos de diferentes géneros." },
            { titulo: "El número gramatical", teoria: "El número gramatical indica si el sustantivo o adjetivo está en singular o plural. El plural se forma con -s o -es.", recurso: "Número gramatical", ejemplo: "'casa' → 'casas', 'pez' → 'peces'.", ejercicio: "Forma el plural de 10 sustantivos.", reto: "Escribe 5 oraciones con sustantivos en singular y plural." },
            { titulo: "La persona gramatical", teoria: "La persona gramatical indica quién realiza la acción del verbo: primera (yo), segunda (tú) o tercera (él).", recurso: "Persona gramatical", ejemplo: "'yo canto' (1ª), 'tú cantas' (2ª), 'él canta' (3ª).", ejercicio: "Conjuga un verbo en las tres personas del singular.", reto: "Escribe 3 oraciones con cada persona." },
            { titulo: "El tiempo verbal", teoria: "El tiempo verbal sitúa la acción en el pasado, presente o futuro. Puede ser simple o compuesto.", recurso: "Tiempo verbal", ejemplo: "'canto' (presente), 'canté' (pretérito perfecto simple), 'cantaré' (futuro).", ejercicio: "Conjuga el verbo 'vivir' en presente, pasado y futuro.", reto: "Escribe 5 oraciones en diferentes tiempos." },
            { titulo: "El modo verbal", teoria: "El modo verbal indica la actitud del hablante: indicativo (realidad), subjuntivo (deseo, duda) e imperativo (orden).", recurso: "Modo verbal", ejemplo: "'canta' (indicativo), 'cante' (subjuntivo), 'canta' (imperativo).", ejercicio: "Conjuga un verbo en los tres modos.", reto: "Escribe 3 oraciones con cada modo." },
            { titulo: "El aspecto verbal", teoria: "El aspecto verbal indica si la acción está terminada (perfectivo) o no (imperfectivo).", recurso: "Aspecto verbal", ejemplo: "'he cantado' (perfectivo), 'cantaba' (imperfectivo).", ejercicio: "Escribe 3 oraciones con aspecto perfectivo e imperfectivo.", reto: "Conjuga el verbo 'amar' en todos los aspectos." },
            { titulo: "La conjugación regular", teoria: "Los verbos regulares siguen un patrón de conjugación fijo en todas sus formas. Hay tres conjugaciones: -ar, -er, -ir.", recurso: "Conjugación regular", ejemplo: "Primera conjugación (-ar): 'amar' → amo, amas, ama... Segunda (-er): 'temer' → temo, temes, teme... Tercera (-ir): 'partir' → parto, partes, parte...", ejercicio: "Conjuga un verbo de cada conjugación en presente.", reto: "Escribe 3 oraciones con verbos de cada conjugación." },
            { titulo: "La conjugación irregular", teoria: "Los verbos irregulares presentan alteraciones en su raíz o desinencias en algunas de sus formas.", recurso: "Conjugación irregular", ejemplo: "'poder' → 'puedo' (diptongo), 'tener' → 'tengo' (cambio), 'decir' → 'digo' (cambio).", ejercicio: "Conjuga 3 verbos irregulares en presente.", reto: "Escribe 5 oraciones con verbos irregulares." },
            { titulo: "Los verbos defectivos", teoria: "Los verbos defectivos son aquellos que no se conjugan en todas las personas o tiempos. Ejemplo: los verbos meteorológicos.", recurso: "Verbos defectivos", ejemplo: "'amanecer', 'llover', 'nevar' (solo se conjugan en tercera persona).", ejercicio: "Escribe 3 oraciones con verbos defectivos.", reto: "Investiga otros verbos defectivos." },
            { titulo: "Los verbos copulativos (ser, estar, parecer)", teoria: "Los verbos copulativos enlazan el sujeto con un atributo. No expresan acción, sino estado o cualidad.", recurso: "Verbos copulativos", ejemplo: "'Juan es alto', 'La casa está limpia', 'Ella parece cansada'.", ejercicio: "Escribe 5 oraciones con verbos copulativos.", reto: "Analiza los verbos copulativos en un texto." },
            { titulo: "La voz activa y pasiva", teoria: "En voz activa, el sujeto realiza la acción. En voz pasiva, el sujeto la recibe. La pasiva se forma con 'ser' + participio.", recurso: "Voz activa y pasiva", ejemplo: "'El perro persigue al gato' (activa) → 'El gato es perseguido por el perro' (pasiva).", ejercicio: "Convierte 3 oraciones activas a pasivas.", reto: "Escribe 5 oraciones en voz pasiva." },
            { titulo: "Los verbos pronominales", teoria: "Los verbos pronominales se conjugan con un pronombre reflexivo (me, te, se, nos, os). Indican que la acción recae sobre el sujeto.", recurso: "Verbos pronominales", ejemplo: "'lavarse', 'peinarse', 'levantarse'.", ejercicio: "Conjuga el verbo 'lavarse' en presente.", reto: "Escribe 5 oraciones con verbos pronominales." }
        ]
    },
    sintaxis: {
        nombre: "Sintaxis", color: "azul", icono: "bi-robot",
        especialidad: "La estructura de las oraciones: constituyentes, funciones, relaciones",
        tecnicas: [
            { titulo: "La oración como unidad sintáctica", teoria: "La oración es la unidad máxima de la sintaxis. Tiene sentido completo y está formada por un sujeto y un predicado.", recurso: "Oración", ejemplo: "'El niño juega en el parque' (sujeto: 'El niño', predicado: 'juega en el parque').", ejercicio: "Identifica el sujeto y el predicado en 5 oraciones.", reto: "Escribe 5 oraciones simples." },
            { titulo: "El sujeto de la oración", teoria: "El sujeto es el constituyente que concuerda en persona y número con el verbo. Puede ser léxico (explícito) o elíptico (omitido).", recurso: "Sujeto", ejemplo: "'Juan come' (sujeto léxico: 'Juan'), 'Come' (sujeto elíptico: 'él').", ejercicio: "Identifica el sujeto en 5 oraciones.", reto: "Escribe 5 oraciones con sujeto elíptico." },
            { titulo: "El predicado verbal y nominal", teoria: "El predicado verbal tiene un verbo predicativo (acción). El predicado nominal tiene un verbo copulativo (ser, estar, parecer) y un atributo.", recurso: "Predicado", ejemplo: "'Juan come pan' (predicado verbal). 'Juan es alto' (predicado nominal, atributo: 'alto').", ejercicio: "Clasifica 5 predicados como verbales o nominales.", reto: "Escribe 5 oraciones con predicado nominal." },
            { titulo: "El complemento directo (CD)", teoria: "El CD es la persona o cosa que recibe directamente la acción del verbo. Responde a '¿qué?' o '¿a quién?'.", recurso: "Complemento directo", ejemplo: "'Veo la película' (CD: 'la película').", ejercicio: "Identifica el CD en 5 oraciones.", reto: "Escribe 5 oraciones con CD." },
            { titulo: "El complemento indirecto (CI)", teoria: "El CI indica la persona o cosa que recibe el beneficio o daño de la acción. Responde a '¿a quién?' o '¿para quién?'.", recurso: "Complemento indirecto", ejemplo: "'Doy un libro a Juan' (CI: 'a Juan').", ejercicio: "Identifica el CI en 5 oraciones.", reto: "Escribe 5 oraciones con CI." },
            { titulo: "El complemento circunstancial (CC)", teoria: "El CC expresa las circunstancias de la acción (lugar, tiempo, modo, causa, etc.).", recurso: "Complemento circunstancial", ejemplo: "'Camino por el parque' (CC de lugar).", ejercicio: "Identifica los CC en 5 oraciones.", reto: "Escribe 5 oraciones con diferentes tipos de CC." },
            { titulo: "El atributo", teoria: "El atributo es un complemento que aparece con verbos copulativos (ser, estar, parecer). Indica una cualidad o estado del sujeto.", recurso: "Atributo", ejemplo: "'La casa es grande' (atributo: 'grande').", ejercicio: "Identifica el atributo en 5 oraciones.", reto: "Escribe 5 oraciones con verbos copulativos." },
            { titulo: "El complemento agente", teoria: "El complemento agente aparece en oraciones pasivas e indica quién realiza la acción. Va precedido por la preposición 'por'.", recurso: "Complemento agente", ejemplo: "'La carta fue escrita por Juan' (agente: 'por Juan').", ejercicio: "Identifica el agente en 5 oraciones pasivas.", reto: "Convierte oraciones activas a pasivas con agente." },
            { titulo: "La oración simple", teoria: "La oración simple tiene un solo verbo en forma personal y expresa una única acción o estado.", recurso: "Oración simple", ejemplo: "'El niño juega'.", ejercicio: "Escribe 5 oraciones simples.", reto: "Analiza sintácticamente 5 oraciones simples." },
            { titulo: "La oración compuesta por yuxtaposición", teoria: "Las oraciones yuxtapuestas se unen sin conectores, solo con signos de puntuación (coma, punto y coma, dos puntos).", recurso: "Yuxtaposición", ejemplo: "'Llegué, vi, vencí'.", ejercicio: "Escribe 3 oraciones yuxtapuestas.", reto: "Analiza las yuxtapuestas en un texto." },
            { titulo: "La oración compuesta por coordinación", teoria: "Las oraciones coordinadas se unen mediante conjunciones (y, o, pero, sino, etc.). Tienen la misma jerarquía.", recurso: "Coordinación", ejemplo: "'Estudia y trabaja'.", ejercicio: "Escribe 5 oraciones coordinadas.", reto: "Analiza las coordinadas en un texto." },
            { titulo: "La oración compuesta por subordinación", teoria: "Las oraciones subordinadas dependen de una oración principal. Pueden ser sustantivas, adjetivas o adverbiales.", recurso: "Subordinación", ejemplo: "'Quiero que vengas' (subordinada sustantiva).", ejercicio: "Escribe 5 oraciones subordinadas.", reto: "Analiza las subordinadas en un texto." },
            { titulo: "Las oraciones subordinadas sustantivas", teoria: "Las subordinadas sustantivas funcionan como un sustantivo (sujeto, CD, etc.). Van introducidas por 'que', 'si', 'quien', etc.", recurso: "Subordinadas sustantivas", ejemplo: "'Sé que vendrás'.", ejercicio: "Escribe 3 subordinadas sustantivas.", reto: "Analiza las sustantivas en un texto." },
            { titulo: "Las oraciones subordinadas adjetivas (de relativo)", teoria: "Las subordinadas adjetivas funcionan como un adjetivo, modificando a un sustantivo. Van introducidas por 'que', 'quien', 'cuyo', etc.", recurso: "Subordinadas adjetivas", ejemplo: "'El libro que leí es interesante'.", ejercicio: "Escribe 3 subordinadas adjetivas.", reto: "Analiza las adjetivas en un texto." },
            { titulo: "Las oraciones subordinadas adverbiales", teoria: "Las subordinadas adverbiales funcionan como un adverbio, expresando circunstancias (tiempo, lugar, modo, causa, etc.).", recurso: "Subordinadas adverbiales", ejemplo: "'Cuando llegues, avísame' (tiempo).", ejercicio: "Escribe 3 subordinadas adverbiales.", reto: "Analiza las adverbiales en un texto." },
            { titulo: "La concordancia sujeto-verbo", teoria: "El verbo debe concordar en persona y número con el sujeto. Es una regla fundamental en la gramática.", recurso: "Concordancia", ejemplo: "'Los niños juegan' (plural).", ejercicio: "Corrige 3 oraciones con errores de concordancia.", reto: "Escribe 5 oraciones con concordancia correcta." },
            { titulo: "La concordancia adjetivo-sustantivo", teoria: "El adjetivo concuerda en género y número con el sustantivo al que modifica.", recurso: "Concordancia adjetivo-sustantivo", ejemplo: "'La casa blanca' (femenino singular).", ejercicio: "Corrige 3 oraciones con errores de concordancia.", reto: "Escribe 5 oraciones con concordancia correcta." },
            { titulo: "El análisis sintáctico", teoria: "El análisis sintáctico consiste en identificar las funciones de cada elemento en la oración (sujeto, predicado, complementos).", recurso: "Análisis sintáctico", ejemplo: "Analizar 'El perro come comida en la cocina'.", ejercicio: "Analiza sintácticamente 5 oraciones.", reto: "Realiza el análisis sintáctico de un párrafo." },
            { titulo: "Los conectores textuales", teoria: "Los conectores son palabras o expresiones que relacionan las ideas en un texto (además, por tanto, sin embargo, en conclusión, etc.).", recurso: "Conectores", ejemplo: "'Estudió mucho; por tanto, aprobó'.", ejercicio: "Escribe 5 oraciones con conectores.", reto: "Utiliza conectores en un texto de 10 líneas." },
            { titulo: "La cohesión y coherencia textual", teoria: "La cohesión es la conexión gramatical entre las partes del texto; la coherencia es la relación lógica entre las ideas.", recurso: "Cohesión y coherencia", ejemplo: "Un texto coherente tiene una idea principal bien desarrollada.", ejercicio: "Escribe un texto coherente de 5 líneas.", reto: "Revisa y mejora la cohesión y coherencia de un texto." }
        ]
    },
    fonetica: {
        nombre: "Fonética", color: "verde", icono: "bi-robot",
        especialidad: "Los sonidos del habla: articulación, producción, descripción",
        tecnicas: [
            { titulo: "El aparato fonador", teoria: "El aparato fonador es el conjunto de órganos que intervienen en la producción del habla: pulmones, laringe, cuerdas vocales, faringe, cavidad oral y nasal.", recurso: "Aparato fonador", ejemplo: "Los pulmones son el motor; las cuerdas vocales son la fuente sonora; la boca y la nariz son los filtros.", ejercicio: "Nombra los órganos del aparato fonador.", reto: "Dibuja un esquema del aparato fonador." },
            { titulo: "La producción del sonido", teoria: "El sonido se produce al pasar el aire de los pulmones a través de la laringe, donde las cuerdas vocales pueden vibrar (sonidos sonoros) o no (sordos).", recurso: "Producción del sonido", ejemplo: "Las vocales son sonidos sonoros; las consonantes pueden ser sordas (p, t, k) o sonoras (b, d, g).", ejercicio: "Clasifica 10 consonantes en sordas y sonoras.", reto: "Graba y analiza la producción de un sonido." },
            { titulo: "Los puntos de articulación", teoria: "Los puntos de articulación son los lugares donde se obstruye o modifica el flujo del aire: bilabial, labiodental, interdental, dental, alveolar, palatal, velar, uvular.", recurso: "Puntos de articulación", ejemplo: "'p' y 'b' son bilabiales; 't' y 'd' son dentales; 'k' y 'g' son velares.", ejercicio: "Clasifica 5 consonantes por su punto de articulación.", reto: "Pronuncia cada sonido y siente dónde toca tu lengua." },
            { titulo: "Los modos de articulación", teoria: "Los modos de articulación describen cómo se produce la obstrucción: oclusivo, fricativo, africado, nasal, lateral, vibrante.", recurso: "Modos de articulación", ejemplo: "'p' oclusivo (cierre total), 's' fricativo (cierre parcial), 'm' nasal (aire por nariz).", ejercicio: "Clasifica 5 consonantes por su modo de articulación.", reto: "Graba tu voz diciendo cada modo." },
            { titulo: "Las vocales del español", teoria: "El español tiene 5 vocales: /a/, /e/, /i/, /o/, /u/. Se clasifican por altura (abiertas/cerradas) y localización (anterior/central/posterior).", recurso: "Vocales", ejemplo: "/a/ abierta central; /e/ media anterior; /i/ cerrada anterior; /o/ media posterior; /u/ cerrada posterior.", ejercicio: "Clasifica las 5 vocales.", reto: "Pronuncia las 5 vocales y escucha cómo cambia tu boca." },
            { titulo: "Las consonantes del español", teoria: "El sistema consonántico del español incluye oclusivas, fricativas, nasales, laterales, vibrantes y africadas.", recurso: "Consonantes", ejemplo: "Oclusivas: p,b,t,d,k,g; fricativas: f,θ,s,x; nasales: m,n,ɲ; laterales: l,ʎ.", ejercicio: "Escribe 3 palabras con cada tipo de consonante.", reto: "Graba una lista de palabras y clasifica sus consonantes." },
            { titulo: "La sinalefa", teoria: "La sinalefa es la fusión de la vocal final de una palabra y la vocal inicial de la siguiente en una misma sílaba.", recurso: "Sinalefa", ejemplo: "'Y el mar, y el viento, y el sol' (y+el, viento+y, etc.).", ejercicio: "Identifica la sinalefa en 3 oraciones.", reto: "Escribe un verso con sinalefa." },
            { titulo: "El diptongo", teoria: "El diptongo es la secuencia de dos vocales en la misma sílaba: una abierta + cerrada o viceversa.", recurso: "Diptongo", ejemplo: "'paisaje' (ai), 'cielo' (ie), 'cuatro' (ua).", ejercicio: "Escribe 5 palabras con diptongo.", reto: "Investiga la acentuación de los diptongos." },
            { titulo: "El triptongo", teoria: "El triptongo es la secuencia de tres vocales en la misma sílaba: cerrada + abierta + cerrada.", recurso: "Triptongo", ejemplo: "'limpiáis' (iáis), 'buey' (uey), 'estudiáis' (uáis).", ejercicio: "Escribe 3 palabras con triptongo.", reto: "Investiga la acentuación de los triptongos." },
            { titulo: "El hiato", teoria: "El hiato es la secuencia de dos vocales en sílabas diferentes, generalmente dos vocales abiertas o una cerrada tónica.", recurso: "Hiato", ejemplo: "'poema' (o-e), 'país' (a-í), 'ahí' (a-í).", ejercicio: "Escribe 5 palabras con hiato.", reto: "Investiga la acentuación de los hiatos." },
            { titulo: "El acento prosódico", teoria: "El acento prosódico es la mayor intensidad con la que se pronuncia una sílaba. Toda palabra tiene un acento prosódico.", recurso: "Acento prosódico", ejemplo: "'cá-sa' (acento en 'ca'), 'co-mér' (acento en 'mer').", ejercicio: "Identifica la sílaba tónica en 10 palabras.", reto: "Investiga la diferencia entre acento prosódico y ortográfico." },
            { titulo: "La entonación", teoria: "La entonación es la variación de tono en el habla. Puede ser ascendente (pregunta) o descendente (afirmación).", recurso: "Entonación", ejemplo: "'¿Vienes?' (ascendente), 'Vienes.' (descendente).", ejercicio: "Graba y analiza la entonación de una frase.", reto: "Investiga los patrones entonativos del español." },
            { titulo: "El ritmo del habla", teoria: "El ritmo del habla está determinado por la duración de las sílabas y los acentos. El español tiene un ritmo silábico.", recurso: "Ritmo", ejemplo: "Las sílabas en español tienden a durar lo mismo.", ejercicio: "Graba y analiza el ritmo de una frase.", reto: "Investiga el ritmo del habla en español." },
            { titulo: "La nasalización", teoria: "La nasalización ocurre cuando el aire sale por la nariz. En español, las nasales son /m/, /n/, /ɲ/.", recurso: "Nasalización", ejemplo: "'mano' (/m/), 'nano' (/n/), 'niño' (/ɲ/).", ejercicio: "Escribe 5 palabras con cada nasal.", reto: "Investiga la nasalización en español." },
            { titulo: "La sonoridad", teoria: "Los sonidos pueden ser sonoros (vibran las cuerdas vocales) o sordos (no vibran).", recurso: "Sonoridad", ejemplo: "/b/ sonora, /p/ sorda; /d/ sonora, /t/ sorda.", ejercicio: "Clasifica 10 consonantes en sonoras y sordas.", reto: "Investiga la sonoridad en español." },
            { titulo: "La oclusión", teoria: "Los sonidos oclusivos se producen con un cierre completo del flujo de aire.", recurso: "Oclusión", ejemplo: "/p/, /b/, /t/, /d/, /k/, /g/ son oclusivos.", ejercicio: "Escribe 5 palabras con oclusivas.", reto: "Investiga los puntos de articulación de las oclusivas." },
            { titulo: "La fricación", teoria: "Los sonidos fricativos se producen con una fricción del aire.", recurso: "Fricación", ejemplo: "/f/, /θ/, /s/, /x/ son fricativos.", ejercicio: "Escribe 5 palabras con fricativas.", reto: "Investiga los puntos de articulación de las fricativas." },
            { titulo: "Las africadas", teoria: "Los sonidos africados combinan una oclusión y una fricción en el mismo punto de articulación.", recurso: "Africadas", ejemplo: "/ʧ/ (ch) es la única africada del español.", ejercicio: "Escribe 5 palabras con /ʧ/.", reto: "Investiga la africada en español." },
            { titulo: "Las vibrantes", teoria: "Las vibrantes se producen con la vibración de la lengua: simple (/ɾ/) y múltiple (/r/).", recurso: "Vibrantes", ejemplo: "'pero' (/ɾ/), 'perro' (/r/).", ejercicio: "Escribe 5 pares mínimos con vibrantes.", reto: "Investiga la distribución de las vibrantes en español." },
            { titulo: "Las laterales", teoria: "Las laterales se producen con el aire saliendo por los lados de la lengua: /l/ y /ʎ/.", recurso: "Laterales", ejemplo: "'lado' (/l/), 'llave' (/ʎ/).", ejercicio: "Escribe 5 palabras con laterales.", reto: "Investiga el yeísmo en español." },
            { titulo: "La transcripción fonética", teoria: "La transcripción fonética es la representación escrita de los sonidos del habla utilizando el Alfabeto Fonético Internacional (AFI).", recurso: "Transcripción fonética", ejemplo: "'casa' se transcribe /ˈkasa/ en AFI.", ejercicio: "Transcribe 5 palabras al AFI.", reto: "Investiga el Alfabeto Fonético Internacional." }
        ]
    },
    fonologia: {
        nombre: "Fonología", color: "purpura", icono: "bi-robot",
        especialidad: "El sistema de sonidos: fonemas, alófonos, rasgos distintivos",
        tecnicas: [
            { titulo: "El fonema", teoria: "El fonema es la unidad mínima de sonido que puede distinguir significados en una lengua. Se representa entre barras / /.", recurso: "Fonema", ejemplo: "/p/ y /b/ son fonemas distintos en español porque 'pala' y 'bala' tienen significados diferentes.", ejercicio: "Identifica los fonemas de 5 palabras.", reto: "Investiga los fonemas del español." },
            { titulo: "El alófono", teoria: "El alófono es una variante de un fonema que no cambia el significado. Se representa entre corchetes [ ].", recurso: "Alófono", ejemplo: "La /b/ de 'boca' [b] y la /b/ de 'lobo' [β] son alófonos del fonema /b/.", ejercicio: "Identifica los alófonos de /b/, /d/, /g/.", reto: "Investiga los alófonos del español." },
            { titulo: "El par mínimo", teoria: "Un par mínimo es un par de palabras que se diferencian por un solo fonema en la misma posición.", recurso: "Par mínimo", ejemplo: "'pala' vs 'bala' (/p/ vs /b/), 'casa' vs 'caza' (/s/ vs /θ/).", ejercicio: "Escribe 5 pares mínimos del español.", reto: "Crea 10 pares mínimos con diferentes fonemas." },
            { titulo: "Los rasgos distintivos", teoria: "Los rasgos distintivos son propiedades binarias que definen los fonemas (ej. sonoro/sordo, nasal/oral, anterior/posterior).", recurso: "Rasgos distintivos", ejemplo: "/p/ = [-sonoro, -nasal, +oclusivo, +bilabial]; /b/ = [+sonoro, -nasal, +oclusivo, +bilabial].", ejercicio: "Define los rasgos de 5 fonemas.", reto: "Haz una tabla de rasgos para las consonantes del español." },
            { titulo: "La neutralización", teoria: "La neutralización ocurre cuando dos fonemas distintos se pronuncian igual en ciertos contextos.", recurro: "Neutralización", ejemplo: "En 'espejo', la 'p' se pronuncia como [b] en muchos dialectos (neutralización de /p/ y /b/).", ejercicio: "Investiga la neutralización en español.", reto: "Encuentra ejemplos de neutralización en tu propio habla." },
            { titulo: "El archifonema", teoria: "El archifonema es la unidad que representa la neutralización, escrita con mayúscula (ej. /B/ para la neutralización de /p/ y /b/).", recurso: "Archifonema", ejemplo: "En 'espejo', el archifonema /B/ representa la neutralización.", ejercicio: "Investiga los archifonemas del español.", reto: "Escribe 3 ejemplos de archifonemas en palabras." },
            { titulo: "El inventario fonológico del español", teoria: "El inventario fonológico del español incluye 5 vocales y entre 18 y 24 consonantes según la variedad.", recurso: "Inventario fonológico", ejemplo: "Consonantes: p, b, t, d, k, g, f, θ, s, x, m, n, ɲ, l, ʎ, ɾ, r, ʧ.", ejercicio: "Haz una lista de todos los fonemas del español.", reto: "Compara el inventario de tu variedad con el estándar." },
            { titulo: "Los fonemas oclusivos", teoria: "Los fonemas oclusivos son /p/, /b/, /t/, /d/, /k/, /g/. Se caracterizan por un cierre completo del flujo de aire.", recurso: "Fonemas oclusivos", ejemplo: "'pato', 'bato', 'tato', 'dato', 'gato'.", ejercicio: "Escribe 3 palabras con cada oclusiva.", reto: "Graba y compara las oclusivas sordas y sonoras." },
            { titulo: "Los fonemas fricativos", teoria: "Los fonemas fricativos son /f/, /θ/, /s/, /x/ (y alófonos de oclusivas). Se caracterizan por una fricción del aire.", recurso: "Fonemas fricativos", ejemplo: "'faro', 'zapato' (con distinción), 'sopa', 'jota'.", ejercicio: "Escribe 3 palabras con cada fricativa.", reto: "Graba y analiza las fricativas del español." },
            { titulo: "Los fonemas nasales", teoria: "Los fonemas nasales son /m/, /n/, /ɲ/. Se producen con el aire saliendo por la nariz.", recurso: "Fonemas nasales", ejemplo: "'mano' (/m/), 'nano' (/n/), 'niño' (/ɲ/).", ejercicio: "Escribe 3 palabras con cada nasal.", reto: "Graba y siente la vibración nasal en cada una." },
            { titulo: "Los fonemas laterales y vibrantes", teoria: "Los fonemas laterales son /l/, /ʎ/. Los vibrantes son /ɾ/ (simple) y /r/ (múltiple).", recurso: "Laterales y vibrantes", ejemplo: "'lado' (/l/), 'llave' (/ʎ/), 'pero' (/ɾ/), 'perro' (/r/).", ejercicio: "Escribe 3 palabras con cada uno.", reto: "Graba y compara las vibrantes simple y múltiple." },
            { titulo: "Los fonemas africados", teoria: "Los fonemas africados son /ʧ/ ('ch') y /ʤ/ (en algunas variedades).", recurso: "Fonemas africados", ejemplo: "'chico' (/ʧ/), 'yo' (/ʤ/ en algunas variedades).", ejercicio: "Escribe 3 palabras con /ʧ/.", reto: "Graba y analiza la africada /ʧ/." },
            { titulo: "El sistema vocálico", teoria: "El sistema vocálico del español tiene 5 vocales: /a/, /e/, /i/, /o/, /u/. Se diferencian por altura y localización.", recurso: "Sistema vocálico", ejemplo: "/i/ cerrada anterior, /e/ media anterior, /a/ abierta central, /o/ media posterior, /u/ cerrada posterior.", ejercicio: "Clasifica las 5 vocales por altura y localización.", reto: "Haz un triángulo vocálico del español." },
            { titulo: "La fonotaxis", teoria: "La fonotaxis estudia las combinaciones de sonidos permitidas en una lengua (ej. en español no hay palabras que empiecen con /tl/).", recurso: "Fonotaxis", ejemplo: "En español, las sílabas pueden ser CV, VC, V, CVC (limitado).", ejercicio: "Investiga las restricciones fonotácticas del español.", reto: "Analiza las sílabas de 10 palabras." },
            { titulo: "La sílaba fonológica", teoria: "La sílaba es una unidad fonológica con un núcleo (vocal) y márgenes (consonantes). En español, la estructura más común es CV.", recurso: "Sílaba", ejemplo: "'pa' (CV), 'a' (V), 'pan' (CVC), 'tres' (CCV).", ejercicio: "Divide 10 palabras en sílabas.", reto: "Analiza la estructura silábica de una oración." },
            { titulo: "La estructura silábica (ataque, núcleo, coda)", teoria: "La sílaba tiene tres partes: ataque (consonantes), núcleo (vocal), coda (consonantes). El núcleo es obligatorio.", recurso: "Estructura silábica", ejemplo: "'tren' = ataque 'tr', núcleo 'e', coda 'n'.", ejercicio: "Analiza la estructura silábica de 5 palabras.", reto: "Clasifica palabras por su tipo silábico (CV, CVC, CCV, etc.)." },
            { titulo: "La fonología del acento", teoria: "El acento es un rasgo suprasegmental que destaca una sílaba. El acento léxico es fijo en el español.", recurso: "Acento", ejemplo: "Las palabras agudas, graves y esdrújulas tienen el acento en la última, penúltima o antepenúltima sílaba.", ejercicio: "Clasifica 10 palabras por su tipo de acento.", reto: "Escribe una lista de 10 palabras con acento en diferentes sílabas." },
            { titulo: "Las reglas de acentuación", teoria: "El acento gráfico (tilde) sigue reglas fonológicas: agudas llevan tilde si terminan en N, S o vocal; graves si no terminan en N, S o vocal; esdrújulas siempre.", recurso: "Reglas de acentuación", ejemplo: "'canción' (aguda, N → tilde), 'árbol' (grave, L → tilde), 'pájaro' (esdrújula → tilde).", ejercicio: "Acentúa 10 palabras según las reglas.", reto: "Escribe 10 palabras con y sin tilde correctamente." },
            { titulo: "La alomorfía", teoria: "La alomorfía es la variación de morfemas en diferentes contextos. Ejemplo: el plural puede ser /s/ (casa-s), /es/ (coche-s).", recurso: "Alomorfía", ejemplo: "El plural de 'casa' es /s/, el de 'coche' es /es/, el de 'pez' es /es/ (peces).", ejercicio: "Analiza los alomorfos del plural.", reto: "Encuentra alomorfos en otros morfemas (verbos, adjetivos)." },
            { titulo: "La fonología y la ortografía", teoria: "La ortografía del español se basa en principios fonológicos: un fonema puede tener varias grafías (ej. /b/ → b, v).", recurso: "Fonología y ortografía", ejemplo: "/b/ se escribe b o v; /x/ se escribe j o g (ante e/i).", ejercicio: "Investiga las reglas ortográficas basadas en la fonología.", reto: "Escribe un texto con palabras que tengan grafías de fonemas variables." }
        ]
    },
