            { titulo: "El género gramatical", teoria: "El género gramatical es una propiedad de los sustantivos que puede ser masculino, femenino o, en algunos casos, neutro (con el artículo 'lo').", recurso: "Género gramatical", ejemplo: "'niño' (masculino), 'niña' (femenino), 'lo bueno' (neutro).", ejercicio: "Clasifica 10 sustantivos por su género.", reto: "Escribe 5 oraciones con sustantivos de diferentes géneros." },
            { titulo: "El número gramatical", teoria: "El número gramatical indica si el sustantivo o adjetivo está en singular o plural. El plural se forma con -s o -es.", recurso: "Número gramatical", ejemplo: "'casa' → 'casas', 'pez' → 'peces'.", ejercicio: "Forma el plural de 10 sustantivos.", reto: "Escribe 5 oraciones con sustantivos en singular y plural." },
