        { nombre: "Silogismo de clasificación expositivo", definicion: "Clasifica elementos mediante silogismo.", sintaxis: "Si [A] pertenece a la clase [B] en el [cosmos], y [C] pertenece a la clase [B], entonces [C] es [A] por clasificación.", ejemplo: "Si los planetas rocosos pertenecen a la clase de cuerpos terrestres, y Marte es rocoso, entonces Marte es terrestre.", ejercicio: "¿Qué tipo de silogismo clasifica en el espacio?", respuesta: "silogismo de clasificación expositivo" },
        { nombre: "Silogismo de comparación expositivo", definicion: "Compara elementos mediante silogismo.", sintaxis: "Si [A] es similar a [B] en el [cosmos], y [C] es similar a [B], entonces [C] es similar a [A].", ejemplo: "Si la Tierra es similar a Venus en tamaño, y este planeta es similar a Venus, entonces es similar a la Tierra.", ejercicio: "¿Qué tipo de silogismo compara en el espacio?", respuesta: "silogismo de comparación expositivo" },
