    const TECNICAS = [];

    // =================== BLOQUE 1: SILOGISMOS Y PREGUNTAS NARRATIVAS (25) ===================
    const narrativos = [
        { nombre: "Silogismo hipotético narrativo", definicion: "Si ocurre A en el cosmos, entonces ocurre B.", sintaxis: "Si [premisa mayor] en el [cosmos], entonces [premisa menor]; luego [conclusión].", ejemplo: "Si los viajeros del tiempo existen, entonces el pasado puede ser alterado; luego la historia es mutable.", ejercicio: "¿Qué tipo de silogismo usa una premisa condicional en el espacio?", respuesta: "silogismo hipotético narrativo" },
        { nombre: "Silogismo disyuntivo narrativo", definicion: "Ocurre A o B en el espacio; no A, luego B.", sintaxis: "O [A] o [B] en el [cosmos]; no [A]; luego [B].", ejemplo: "O el universo es infinito o es finito; no es infinito; luego es finito.", ejercicio: "¿Qué tipo de silogismo presenta dos opciones en el cosmos?", respuesta: "silogismo disyuntivo narrativo" },
        { nombre: "Silogismo categórico narrativo", definicion: "Todos los A son B; C es A; luego C es B.", sintaxis: "Todos los [A] son [B] en el [cosmos]; [C] es [A]; luego [C] es [B].", ejemplo: "Todos los agujeros negros son densos; el objeto X es un agujero negro; luego es denso.", ejercicio: "¿Qué tipo de silogismo usa categorías en el espacio?", respuesta: "silogismo categórico narrativo" },
