        { nombre: "Silogismo de autoridad narrativo", definicion: "Apela a una autoridad para validar el razonamiento.", sintaxis: "Según [autoridad], [A] es [B] en el [cosmos]; [C] es [A]; luego [C] es [B].", ejemplo: "Según Einstein, el tiempo es relativo; el viaje interestelar afecta el tiempo; luego el tiempo se dilata.", ejercicio: "¿Qué tipo de silogismo apela a una autoridad en el espacio?", respuesta: "silogismo de autoridad narrativo" },
        { nombre: "Silogismo de analogía narrativo", definicion: "Compara dos situaciones para inferir una conclusión.", sintaxis: "Como [A] es a [B] en el [cosmos], [C] es a [D]; luego [C] es [D].", ejemplo: "Como la Tierra es a la vida, Marte es a la posibilidad; luego Marte puede albergar vida.", ejercicio: "¿Qué tipo de silogismo usa una analogía en el espacio?", respuesta: "silogismo de analogía narrativo" },
        { nombre: "Silogismo de ejemplificación narrativo", definicion: "Usa un ejemplo para construir un razonamiento.", sintaxis: "Si [ejemplo] demuestra [A], entonces [B] es [C] en el [cosmos]; luego [B] es [C].", ejemplo: "Si el rover encontró agua en Marte, entonces el agua es común en el sistema solar; luego la vida puede ser común.", ejercicio: "¿Qué tipo de silogismo usa ejemplos en el espacio?", respuesta: "silogismo de ejemplificación narrativo" },
