<body>
<div class="container" id="app">
    <div class="header">
        <h1>📚 Niveles de comprensión <span>100 técnicas</span></h1>
        <div class="sub">literal · inferencial · crítico-intertextual · concurso docente</div>
    </div>

    <div class="block-nav" id="blockNav"></div>
    <div id="cardsGrid" class="cards-grid"></div>

    <div class="quiz-section" id="quizSection">
        <h2>🧠 Cuestionario <small>niveles de comprensión lectora</small></h2>
        <div id="quizContainer"></div>
    </div>
    <div class="footer">100 técnicas · Escribe tu respuesta en cada tarjeta y verifica · Aprende los niveles de comprensión</div>
</div>

<script>
    // ================================================================
    // 100 TÉCNICAS sobre Niveles de comprensión lectora
    // Literal, Inferencial, Crítico-intertextual
    // Cada tarjeta tiene ejercicio con respuesta verificable por el usuario
    // ================================================================
    const TECNICAS = [];

    // Bloque 1: Nivel literal (25)
    const b1 = [
        { nombre: "Identificación de datos explícitos", teoria: "Reconocer información que aparece directamente en el texto.", ejemplo: "El texto dice 'el perro es negro' → dato literal.", ejercicio: "¿Qué nivel lee lo que está escrito?", respuesta: "literal" },
        { nombre: "Reconocimiento de personajes", teoria: "Identificar quiénes participan en la historia.", ejemplo: "En 'Caperucita', los personajes son Caperucita y el lobo.", ejercicio: "¿Qué nivel identifica personajes?", respuesta: "literal" },
        { nombre: "Secuencia de eventos", teoria: "Ordenar cronológicamente los hechos.", ejemplo: "Primero llegó, luego comió, después se fue.", ejercicio: "¿Qué nivel ordena eventos?", respuesta: "literal" },
        { nombre: "Identificación del lugar", teoria: "Reconocer el espacio donde ocurre la acción.", ejemplo: "La historia ocurre en un bosque.", ejercicio: "¿Qué nivel reconoce el espacio?", respuesta: "literal" },
        { nombre: "Identificación del tiempo", teoria: "Reconocer cuándo ocurre la acción.", ejemplo: "La historia ocurre en la noche.", ejercicio: "¿Qué nivel identifica el tiempo?", respuesta: "literal" },
        { nombre: "Cita textual", teoria: "Extraer fragmentos exactos del texto.", ejemplo: "El autor dice: 'La luna brillaba'.", ejercicio: "¿Qué nivel usa citas textuales?", respuesta: "literal" },
        { nombre: "Paráfrasis literal", teoria: "Repetir con otras palabras lo que dice el texto.", ejemplo: "'El sol calienta' → 'El sol emite calor'.", ejercicio: "¿Qué nivel reformula sin cambiar el sentido?", respuesta: "literal" },
        { nombre: "Identificación del tema explícito", teoria: "Reconocer el tema que el texto menciona directamente.", ejemplo: "El tema es 'la amistad' porque lo dice.", ejercicio: "¿Qué nivel identifica el tema declarado?", respuesta: "literal" },
        { nombre: "Reconocimiento de objetos", teoria: "Identificar objetos mencionados en el texto.", ejemplo: "Se menciona una mesa, una silla.", ejercicio: "¿Qué nivel reconoce objetos?", respuesta: "literal" },
        { nombre: "Identificación de acciones", teoria: "Reconocer las acciones que realizan los personajes.", ejemplo: "El niño corre, salta y ríe.", ejercicio: "¿Qué nivel identifica acciones?", respuesta: "literal" },
        { nombre: "Preguntas de respuesta directa", teoria: "Preguntas cuya respuesta está en el texto.", ejemplo: "¿Qué color es el auto? → El auto es rojo.", ejercicio: "¿Qué nivel responde preguntas directas?", respuesta: "literal" },
        { nombre: "Identificación de características físicas", teoria: "Reconocer cómo es un personaje u objeto.", ejemplo: "El gigante es alto y fuerte.", ejercicio: "¿Qué nivel describe físicamente?", respuesta: "literal" },
        { nombre: "Reconocimiento de números y fechas", teoria: "Identificar datos numéricos y temporales.", ejemplo: "El evento ocurrió en 2020.", ejercicio: "¿Qué nivel reconoce fechas?", respuesta: "literal" },
        { nombre: "Identificación de diálogos", teoria: "Reconocer las conversaciones entre personajes.", ejemplo: "—Hola —dijo Juan.", ejercicio: "¿Qué nivel identifica diálogos?", respuesta: "literal" },
        { nombre: "Reconocimiento de títulos y subtítulos", teoria: "Identificar los encabezados del texto.", ejemplo: "El título es 'El viaje'.", ejercicio: "¿Qué nivel identifica títulos?", respuesta: "literal" },
        { nombre: "Identificación de ejemplos", teoria: "Reconocer ejemplos que da el autor.", ejemplo: "Por ejemplo, 'los perros son mamíferos'.", ejercicio: "¿Qué nivel reconoce ejemplos?", respuesta: "literal" },
        { nombre: "Reconocimiento de definiciones", teoria: "Identificar definiciones explícitas.", ejemplo: "La 'fotosíntesis' es el proceso de las plantas.", ejercicio: "¿Qué nivel reconoce definiciones?", respuesta: "literal" },
        { nombre: "Identificación de conectores", teoria: "Reconocer palabras como 'y', 'pero', 'porque'.", ejemplo: "'y' une ideas.", ejercicio: "¿Qué nivel identifica conectores?", respuesta: "literal" },
        { nombre: "Reconocimiento de estructura", teoria: "Identificar partes del texto (introducción, desarrollo).", ejemplo: "El texto tiene tres párrafos.", ejercicio: "¿Qué nivel reconoce la estructura?", respuesta: "literal" },
        { nombre: "Identificación de género textual", teoria: "Reconocer si es cuento, noticia, carta, etc.", ejemplo: "Es un cuento porque tiene personajes.", ejercicio: "¿Qué nivel identifica el género?", respuesta: "literal" },
        { nombre: "Reconocimiento de marcas gráficas", teoria: "Identificar negritas, cursivas, comillas.", ejemplo: "Las comillas indican diálogo.", ejercicio: "¿Qué nivel reconoce marcas gráficas?", respuesta: "literal" },
        { nombre: "Identificación de listas", teoria: "Reconocer enumeraciones.", ejemplo: "Los colores son: rojo, verde, azul.", ejercicio: "¿Qué nivel reconoce listas?", respuesta: "literal" },
        { nombre: "Reconocimiento de comparaciones explícitas", teoria: "Identificar comparaciones con 'como'.", ejemplo: "Es alto como una torre.", ejercicio: "¿Qué nivel reconoce comparaciones literales?", respuesta: "literal" },
        { nombre: "Identificación de causa explícita", teoria: "Reconocer causas que el texto menciona.", ejemplo: "Se mojó porque llovía.", ejercicio: "¿Qué nivel reconoce causas explícitas?", respuesta: "literal" },
        { nombre: "Reconocimiento de efecto explícito", teoria: "Identificar consecuencias que el texto menciona.", ejemplo: "Llovió, por eso se mojó.", ejercicio: "¿Qué nivel reconoce efectos explícitos?", respuesta: "literal" },
    ];
    b1.forEach((t, i) => TECNICAS.push({ id: i+1, bloque: 1, categoria: "literal", ...t }));

    // Bloque 2: Nivel inferencial (25)
    const b2 = [
        { nombre: "Inferencia de causa-efecto", teoria: "Deducir causas o consecuencias no explícitas.", ejemplo: "Si dice 'llevaba paraguas', inferir que llovía.", ejercicio: "¿Qué nivel deduce causas ocultas?", respuesta: "inferencial" },
        { nombre: "Inferencia de sentimientos", teoria: "Deducir emociones a partir de acciones o descripciones.", ejemplo: "Si tiembla y llora, inferir que tiene miedo.", ejercicio: "¿Qué nivel deduce emociones?", respuesta: "inferencial" },
        { nombre: "Inferencia de intenciones", teoria: "Deducir el propósito de un personaje.", ejemplo: "Si un personaje se esconde, inferir que no quiere ser visto.", ejercicio: "¿Qué nivel deduce intenciones?", respuesta: "inferencial" },
        { nombre: "Inferencia de relaciones", teoria: "Deducir vínculos entre personajes o ideas.", ejemplo: "Si dos personajes discuten, inferir que hay conflicto.", ejercicio: "¿Qué nivel deduce relaciones?", respuesta: "inferencial" },
        { nombre: "Inferencia de contexto", teoria: "Deducir el contexto a partir de pistas.", ejemplo: "Si mencionan 'toga' y 'juez', inferir que es un tribunal.", ejercicio: "¿Qué nivel deduce el contexto?", respuesta: "inferencial" },
        { nombre: "Inferencia de significado de palabras", teoria: "Deducir significado por contexto.", ejemplo: "Si dice 'El concierto fue estupendo', inferir que 'estupendo' es positivo.", ejercicio: "¿Qué nivel deduce significado por contexto?", respuesta: "inferencial" },
        { nombre: "Predicción de acciones", teoria: "Anticipar lo que ocurrirá después.", ejemplo: "Si un personaje se acerca a un acantilado, predecir que puede caer.", ejercicio: "¿Qué nivel predice acciones?", respuesta: "inferencial" },
        { nombre: "Inferencia del tema implícito", teoria: "Deducir el tema cuando no está declarado.", ejemplo: "Un texto sobre personas ayudando → tema implícito: solidaridad.", ejercicio: "¿Qué nivel deduce el tema oculto?", respuesta: "inferencial" },
        { nombre: "Inferencia de la tesis", teoria: "Deducir la opinión del autor cuando no la dice.", ejemplo: "Un texto que critica la contaminación → tesis: hay que cuidar el ambiente.", ejercicio: "¿Qué nivel deduce la postura del autor?", respuesta: "inferencial" },
        { nombre: "Inferencia de características psicológicas", teoria: "Deducir rasgos de personalidad.", ejemplo: "Si un personaje miente, inferir que es deshonesto.", ejercicio: "¿Qué nivel deduce rasgos de personalidad?", respuesta: "inferencial" },
        { nombre: "Inferencia de valores", teoria: "Deducir valores que defiende el texto.", ejemplo: "Si el texto promueve la paz, inferir que valora la no violencia.", ejercicio: "¿Qué nivel deduce valores?", respuesta: "inferencial" },
        { nombre: "Inferencia de relaciones espaciales", teoria: "Deducir ubicaciones a partir de descripciones.", ejemplo: "Si dice 'subió', inferir que está en un lugar elevado.", ejercicio: "¿Qué nivel deduce relaciones espaciales?", respuesta: "inferencial" },
        { nombre: "Inferencia de relaciones temporales", teoria: "Deducir el orden de eventos no explícitos.", ejemplo: "Si dice 'después del desayuno', inferir que antes durmió.", ejercicio: "¿Qué nivel deduce relaciones temporales?", respuesta: "inferencial" },
        { nombre: "Inferencia de implicaciones", teoria: "Deducir consecuencias lógicas.", ejemplo: "Si dice 'no estudió', inferir que puede reprobar.", ejercicio: "¿Qué nivel deduce implicaciones?", respuesta: "inferencial" },
