add(79,"Megane 1.6: consumo en carretera","Mecánica moto","Consumo aproximado 8 L/100 km (12 km/L). Tanque 60 L → autonomía 720 km.","Útil como vehículo nodriza para llevar combustible extra.","Autonomía Megane 1.6 en carretera","720 km");
add(80,"Yamaha SZR150: ajuste de suspensión trasera","Mecánica moto","5 niveles de precarga. Para equipaje, usar nivel 4 o 5.","Suspensión dura mejora estabilidad en curvas.","¿Nivel de precarga para equipaje?","4 o 5");
add(81,"Lubricación de cables (acelerador, embrague)","Mecánica moto","Usar aceite multigrado o spray de silicona. Evitar que se oxiden dentro de la funda.","Cable seco puede romperse.","¿Con qué lubricar cables?","aceite multigrado o silicona");
add(82,"Anteojos y careta antipolvo","Seguridad","En tramos destapados (vía Ocaña), usar gafas selladas.","Polvo puede causar accidentes.","¿Qué tipo de gafas usar en tierra?","selladas o antipolvo");
add(83,"Descanso cada 2 horas","Seguridad","Fatiga causa microsueños. Parar 15 minutos, estirar, hidratarse.","Moto pequeña requiere más paradas.","¿Cada cuánto tiempo descansar?","2 horas");
add(84,"Revisión de luces antes de salir","Seguridad","Verificar alta/baja, direccionales, stop. Llevar bombillos de repuesto.","Multa por luces rotas.","¿Qué bombillos llevar de repuesto?","H4 y de direccionales");
add(85,"Uso de GPS o mapa físico","Ruta y acampe","Descargar mapas Offline (Maps.me). Llevar mapa impreso como respaldo.","En zonas sin señal, el GPS satelital funciona.","¿Qué app funciona sin internet?","Maps.me u OSMand");
add(86,"Acampe en zona rural: normas","Ruta y acampe","Pedir permiso al dueño del terreno, no hacer ruido, no dejar basura.","Respetar la propiedad privada.","¿Qué regla básica de acampe?","no dejar basura");
add(87,"Fuego y cocina: seguridad","Ruta y acampe","Usar fogón portátil, no hacer fogatas directamente en el suelo.","En temporada seca, prohibido fogatas.","¿Qué usar en lugar de fogata?","cocinilla portátil");
add(88,"Gestión de residuos en campamento","Ruta y acampe","Llevar bolsas para basura, separar reciclables, no enterrar plásticos.","Dejar el lugar más limpio de lo encontrado.","¿Qué hacer con la basura?","llevársela");
add(89,"Kit de primeros auxilios para moto","Seguridad","Incluir vendas, gasas, alcohol, analgésico, curitas, solución salina.","En zonas remotas, improvisar con botiquín.","¿Qué desinfectante llevar?","alcohol o agua oxigenada");
add(90,"Comunicación entre motos (hand talk)","Seguridad","Usar manos libres o señales: mano izquierda abajo = peligro en el piso.","La SZR150 puede equipar intercomunicador.","¿Qué señal indica peligro en el piso?","mano izquierda abierta");
add(91,"Documentos obligatorios","Seguridad","SOAT, licencia, tarjeta de propiedad, cédula. Multa por no portarlos.","El SOAT se puede tener digital.","¿Se puede presentar SOAT digital?","sí");
add(92,"Control de velocidad","Seguridad","En carretera nacional límite 80 km/h para motos. En zona urbana 30-50 km/h.","Evitar multas y accidentes.","¿Velocidad máxima moto en carretera?","80 km/h");
add(93,"Seguro todo riesgo para moto","Seguridad","Cubre daños a terceros, robo, accidentes. Recomendado para viajes largos.","La Nova 124 tiene seguro económico.","¿Qué seguro cubre daños a la moto?","todo riesgo");
add(94,"Sufijo -dera (lugar)","Morfología","Forma sustantivos de lugar","parqueadero, mirador.","De 'campamento' a lugar","campamentero (campamentero no es común, usar 'campiña')");
add(95,"Prefijo multi-","Formación","muchos","multicilíndrico","Multi- + 'herramienta'","multiherramienta");
add(96,"Familia de palabras: moto","Morfemática","motocicleta, motoneta, motoviajero","Palabra de la familia de 'moto'","motoneta");
add(97,"Alternancia vocálica","Morfemática","contar → cuento","Alternancia en 'acelerar'?","ninguna");
add(98,"Futuro de subjuntivo en textos antiguos","Morfología","Si así fuere...","Futuro subjuntivo de 'ser'","fuere");
add(99,"Gerundio compuesto","Morfología","habiendo + participio","Habiendo rodado 200 km, paró.","Gerundio compuesto de 'viajar'","habiendo viajado");
add(100,"Epéntesis en lenguaje cotidiano","Morfemática","inserción de sonido","'pobrecito' (pobre + c + ito)","Epéntesis en 'motorcito'","-c-");

// Progreso
let userProgress = JSON.parse(localStorage.getItem('motoRutaProgress')) || {};
function updateGlobalProgress(){
    let completed = Object.values(userProgress).filter(v=>v===true).length;
    let percent = Math.round((completed/techniques.length)*100);
    let fill = document.getElementById('globalProgressFill');
    let percentSpan = document.getElementById('progressPercent');
    if(fill) fill.style.width = percent+'%';
    if(percentSpan) percentSpan.innerText = percent+'%';
}
function setStatus(id, ok){
    let span = document.getElementById(`status-${id}`);
    if(span) span.innerHTML = ok ? ' ✅' : '';
    userProgress[id] = ok;
    localStorage.setItem('motoRutaProgress', JSON.stringify(userProgress));
    updateGlobalProgress();
}
function checkAnswer(id, userAns, correctAns, inputEl, fbEl){
    let normUser = userAns.trim().toLowerCase().replace(/[¿¡]/g,'');
    let normCorr = correctAns.trim().toLowerCase().replace(/[¿¡]/g,'');
    let ok = normUser === normCorr;
    fbEl.innerHTML = ok ? '✓ ¡Correcto!' : `✗ Incorrecto. Respuesta: "${correctAns}"`;
    fbEl.className = `feedback ${ok ? 'correct' : 'incorrect'}`;
    inputEl.disabled = true;
    inputEl.style.backgroundColor = '#f0f0f0';
    setStatus(id, ok);
}
function resetCard(id, inputEl, fbEl){
    inputEl.disabled = false;
    inputEl.value = '';
    inputEl.style.backgroundColor = 'white';
    fbEl.innerHTML = '';
    fbEl.className = 'feedback';
    setStatus(id, false);
}
function speakText(text){
    if('speechSynthesis' in window){
        speechSynthesis.cancel();
        let utterance = new SpeechSynthesisUtterance(text);
        utterance.lang = 'es-ES';
        utterance.rate = 0.9;
        speechSynthesis.speak(utterance);
    } else alert("Voz no soportada.");
}
function renderCards(){
    let searchTerm = document.getElementById('searchInput').value.toLowerCase();
    let cat = document.getElementById('categorySelect').value;
    let filtered = techniques.filter(t => (cat==='all' || t.category===cat) && (t.name.toLowerCase().includes(searchTerm) || t.category.toLowerCase().includes(searchTerm) || t.teoria.toLowerCase().includes(searchTerm) || (t.grado && t.grado.toLowerCase().includes(searchTerm))));
    let container = document.getElementById('cardsContainer');
    if(filtered.length===0){ container.innerHTML='<div style="grid-column:1/-1;text-align:center;padding:3rem;">🔍 No hay técnicas con esos filtros.</div>'; return; }
    container.innerHTML = filtered.map(item => `
        <div class="card">
            <div class="card-header"><h3>#${item.id} · ${item.name} <span id="status-${item.id}" class="status-icon">${userProgress[item.id] ? '✅' : ''}</span></h3>
            <span class="category-tag">${item.category}</span>${item.grado ? `<span class="grade-tag">📘 ${item.grado}</span>` : ''}</div>
            <div class="card-body">
                <div class="teoria"><span>📘 ${item.teoria}</span><button class="btn-speak" data-teoria="${item.teoria.replace(/"/g,'&quot;')}">🔊 Leer</button></div>
                <div class="ejemplo"><span>💡 ${item.ejemplo}</span><button class="btn-speak-ejemplo" data-ejemplo="${item.ejemplo.replace(/"/g,'&quot;')}">🔊 Leer ejemplo</button></div>
                <div class="ejercicio-area"><div class="ejercicio-text">✏️ Ejercicio: ${item.ejercicio}</div>
                <div class="input-group"><input type="text" id="input-${item.id}" placeholder="Escribe tu respuesta..." ${userProgress[item.id] ? 'disabled' : ''}><button class="check-btn" data-id="${item.id}" ${userProgress[item.id] ? 'disabled' : ''}>Comprobar</button></div>
                <div id="feedback-${item.id}" class="feedback"></div>
                <button class="reset-card-btn" data-reset="${item.id}">⟳ Reiniciar ejercicio</button></div>
            </div>
        </div>`).join('');
    document.querySelectorAll('.btn-speak').forEach(btn=>btn.addEventListener('click',()=>speakText(btn.getAttribute('data-teoria'))));
    document.querySelectorAll('.btn-speak-ejemplo').forEach(btn=>btn.addEventListener('click',()=>speakText(btn.getAttribute('data-ejemplo'))));
    techniques.forEach(t=>{
        let btn = document.querySelector(`.check-btn[data-id="${t.id}"]`);
        let resetBtn = document.querySelector(`.reset-card-btn[data-reset="${t.id}"]`);
        let inputEl = document.getElementById(`input-${t.id}`);
        let fbEl = document.getElementById(`feedback-${t.id}`);
        if(btn && inputEl && fbEl) btn.addEventListener('click',()=>{ if(!inputEl.disabled) checkAnswer(t.id, inputEl.value, t.suggestedAnswer, inputEl, fbEl); btn.disabled=true; });
        if(resetBtn && inputEl && fbEl) resetBtn.addEventListener('click',()=>{ resetCard(t.id, inputEl, fbEl); let checkB = document.querySelector(`.check-btn[data-id="${t.id}"]`); if(checkB) checkB.disabled=false; });
    });
}
document.getElementById('totalCount').innerText = techniques.length;
document.getElementById('searchInput').addEventListener('input', renderCards);
document.getElementById('categorySelect').addEventListener('change', renderCards);
renderCards();
updateGlobalProgress();
</script>
</body>
</html>

