<body>
<div class="container">
    <div class="hero">
        <h1>🏍️ Ruta Bucaramanga → Costa Colombiana</h1>
        <p>100 técnicas para motoviajeros: Yamaha V80, SZR150, Suzuki Nova 124, Megane 1.6 · Acampar · Estándares MEN</p>
    </div>
    <div class="stats-progress">
        <span>📚 Inventario: <strong id="totalCount">100</strong> técnicas</span>
        <div class="progress-area">
            <span>🏆 Progreso:</span>
            <div class="progress-bar-container"><div class="progress-fill" id="globalProgressFill"></div></div>
            <span id="progressPercent">0%</span>
        </div>
        <span class="badge">🔊 Voz · ✍️ Ejercicios prácticos</span>
    </div>
    <div class="filter-bar">
        <input type="text" id="searchInput" placeholder="🔍 Buscar...">
        <select id="categorySelect">
            <option value="all">📌 Todas</option>
            <option value="Ruta y acampe">🏕️ Ruta BGA-Costa + acampar</option>
            <option value="Mecánica moto">🔧 Mecánica: V80, SZR150, Nova, Megane</option>
            <option value="Seguridad">🛡️ Seguridad en carretera</option>
            <option value="Estándares MEN">📘 Estándares lenguaje (MEN)</option>
            <option value="Morfología">🎭 Morfología flexiva/derivativa</option>
            <option value="Clases palabras">📂 Clases de palabras</option>
            <option value="Morfemática">🧬 Lexema, morfema, alomorfo</option>
            <option value="Formación palabras">🧩 Composición, acronimia, siglación</option>
            <option value="Lectura crítica">📖 Saber Pro / concurso docente</option>
        </select>
    </div>
    <div id="cardsContainer" class="cards-grid"></div>
    <div class="footer-note">✅ Ruta Bucaramanga - San Alberto - Aguachica - Ocaña - Valledupar - Santa Marta. Consejos de acampe, mecánica, lenguaje y morfología.</div>
</div>
<script>
const techniques = [];
function add(id, name, category, teoria, ejemplo, ejercicio, suggestedAnswer, grado="") {
    techniques.push({ id, name, category, teoria, ejemplo, ejercicio, suggestedAnswer, grado });
}
// ================= 1. RUTA BUCARAMANGA - COSTA Y ACAMPE =================
add(1,"Ruta Bucaramanga - San Alberto (primer tramo)","Ruta y acampe","Salida por la autopista vía Barrancabermeja. 160 km, clima cálido. Usa ropa ligera y mucha hidratación.","En San Alberto hay zona de camping cerca del río.","¿Cuántos km tiene el primer tramo hasta San Alberto?","160 km");
add(2,"San Alberto - Aguachica - Ocaña","Ruta y acampe","Vía nacional 45, luego desvío a Ocaña. 120 km. Subida pronunciada. La V80 puede sentir la altura.","Revisar frenos antes del descenso.","¿Qué moto puede tener dificultad en subida?","Yamaha V80");
add(3,"Ocaña - Valledupar","Ruta y acampe","Carretera 70, 180 km. Tramo con curvas y pocos poblados. Llevar combustible extra.","La Suzuki Nova 124 rinde bien en este tramo.","¿Cuántos km aproximados de Ocaña a Valledupar?","180 km");
add(4,"Valledupar - Santa Marta (final)","Ruta y acampe","Autopista 90, 160 km. Clima cálido y brisa fuerte. Cuidado con vientos laterales en moto pequeña.","La Megane 1.6 es estable como vehículo de apoyo.","¿Qué peligro hay en la autopista hacia Santa Marta?","vientos laterales");
add(5,"Camping Los Samanes (San Alberto)","Ruta y acampe","A orillas del río, con sombra y fogatas permitidas. Llevar mosquitero.","Tarifa aprox $15.000 por persona.","¿Qué elemento esencial para acampar cerca de río?","mosquitero");
add(6,"Camping El Mirador (Ocaña)","Ruta y acampe","Zona montañosa, vista panorámica. Temperatura fresca (18°C). Llevar bolsa de dormir térmica.","Se puede acampar en carpa o en cabañas rústicas.","¿Qué temperatura hay en Ocaña?","18°C");
add(7,"Acampe en la playa (Santa Marta)","Ruta y acampe","Playa Los Angeles, acampe permitido. Cuidado con la marea alta.","Llevar protector solar y abundante agua.","¿Qué riesgo hay al acampe en playa?","marea alta");
add(8,"Equipo de campamento básico","Ruta y acampe","Carpa (3 estaciones), sleeping bag, linterna, mechero, cocinilla, aislante térmico.","La SZR150 puede llevar alforjas laterales.","¿Cuál es el aislante térmico?","colchoneta o aislante");
add(9,"Alimentos no perecederos","Ruta y acampe","Atún, galletas, arroz instantáneo, frutos secos, chocolate energético.","En moto pequeña, priorizar peso ligero.","¿Qué alimento es buena fuente de energía?","chocolate o frutos secos");
add(10,"Purificación de agua","Ruta y acampe","Usar pastillas potabilizadoras o hervir durante 5 minutos.","En ríos de montaña, el agua puede tener bacterias.","¿Cuánto tiempo hervir agua para potabilizar?","5 minutos");
// ================= 2. MECÁNICA Y PREPARACIÓN DE VEHÍCULOS =================
add(11,"Yamaha V80: ajuste de carburador para altura","Mecánica moto","En subidas (Ocaña, 1500 msnm), enriquecer mezcla: girar tornillo de aire 1/4 vuelta.","Mezcla pobre causa calentamiento.","¿Qué se ajusta en carburador a mayor altura?","enriquecer mezcla");
add(12,"Suzuki Nova 124: tensión de cadena","Mecánica moto","Juego de 2-3 cm en punto medio. Lubricar cada 500 km con aceite SAE 90.","Cadena floja puede saltar y bloquear la rueda.","¿Cada cuánto lubricar cadena en ruta?","500 km");
add(13,"Yamaha SZR150: revisión de refrigeración","Mecánica moto","Motor refrigerado por aire, verificar aletas limpias y aceite 20W50 en climas cálidos.","En costa, no exceder RPM para evitar sobrecalentamiento.","¿Qué aceite usar en SZR150 para clima cálido?","20W50");
add(14,"Megane 1.6 como vehículo apoyo","Mecánica moto","Capacidad maletero 510 L, cargar repuestos (bujías, fusibles, kit de parche).","El Megane tiene protección bajo cárter de fábrica.","¿Capacidad maletero Megane 1.6?","510 litros");
add(15,"Preparación de alforjas para moto","Mecánica moto","Distribuir peso uniforme: objetos pesados abajo y cerca del centro.","V80 lleva máximo 15 kg de equipaje.","¿Peso máximo equipaje Yamaha V80?","15 kg");
add(16,"Kit de herramientas básico","Mecánica moto","Llaves 8,10,12,14,17; destornilladores; bomba de aire; parches; multímetro.","Para Nova 124 incluir extractor de bujía.","¿Qué herramienta saca la bujía?","extractor o llave de bujía");
add(17,"Neumáticos: presión adecuada","Mecánica moto","V80: 25 psi; Nova 124: 28 psi; SZR150: 29 psi; Megane 1.6: 32 psi.","En carretera con calor, la presión aumenta 2-3 psi.","¿Presión recomendada Suzuki Nova 124?","28 psi");
add(18,"Batería y sistema eléctrico","Mecánica moto","Revisar bornes limpios, voltaje mínimo 12.4V. V80 usa arranque por patada, ideal.","Cargar celular con power bank, no con la moto si es de baja potencia.","¿Qué moto tiene arranque por patada?","Yamaha V80");
add(19,"Frenos de tambor vs disco","Mecánica moto","V80 tiene tambor trasero; SZR150 y Nova disco delantero. Revisar pastillas cada 5000 km.","En mojado, frenar con suavidad.","¿Cada cuánto revisar pastillas de freno?","5000 km");
add(20,"Combustible: octanaje y autonomía","Mecánica moto","V80: 87 octanos (corriente), tanque 5L → autonomía ~120 km. Nova 124: 91 octanos (extra), 12L → ~250 km.","Llevar gasolina extra en botella certificada.","Autonomía Suzuki Nova 124?","~250 km");
// ================= 3. ESTÁNDARES MEN (LENGUAJE) =================
add(21,"Producción de crónicas de viaje (1°-3°)","Estándares MEN","Escribir relatos cortos sobre experiencias en moto.","'Salí de Bucaramanga con mi V80, el sol calentaba...'","Escribe una oración para iniciar una crónica de viaje","El motor rugió al salir de Bucaramanga","1°-3°");
add(22,"Comprensión de mapas y señales (4°-5°)","Estándares MEN","Interpretar información vial y kilómetros.","Señal 'Bucaramanga 160 km' indica distancia.","¿Qué indica una señal con 'Santa Marta 120 km'?","distancia a Santa Marta","4°-5°");
add(23,"Inferencia en relatos de carretera (6°-7°)","Estándares MEN","Deducir peligros o emociones implícitas.","'El viento soplaba fuerte, la moto se movía' infiere peligro.","Infiere: 'El conductor se puso chaqueta gruesa'","hace frío","6°-7°");
add(24,"Argumentación sobre seguridad vial (8°-9°)","Estándares MEN","Defender el uso de casco integral con argumentos.","El casco integral protege la cara en caídas.","¿Qué tipo de casco ofrece más protección?","integral","8°-9°");
add(25,"Lectura crítica de noticias (10°-11°)","Estándares MEN","Evaluar credibilidad de información sobre accidentes de tránsito.","Comparar dos versiones de un mismo accidente.","¿Qué se debe verificar en una noticia?","fuentes y evidencia","10°-11°");
// ================= 4. MORFOLOGÍA FLEXIVA =================
add(26,"Flexión de género (sustantivos)","Morfología","Los sustantivos varían en género con -o, -a.","moto (femenino), casco (masculino).","Femenino de 'conductor'","conductora");
add(27,"Flexión de número (plural)","Morfología","Se añade -s o -es.","carretera/carreteras, freno/frenos.","Plural de 'parachoques'","parachoques (invariable)");
add(28,"Pretérito perfecto simple","Morfología","Acción pasada puntual.","viajé, recorriste, aceleró.","Conjuga 'acelerar' en 1ª singular","aceleré");
add(29,"Modo subjuntivo presente","Morfología","Expresa deseo o posibilidad.","Espero que llegues bien.","Subjuntivo de 'frenar' para él","frene");
add(30,"Aspecto perfectivo/imperfectivo","Morfología","Perfectivo: acción terminada; imperfectivo: en desarrollo.","Rodé 200 km (perfectivo) / Rodaba 200 km (imperfectivo).","Aspecto de 'había recorrido'","perfectivo");
add(31,"Persona gramatical verbal","Morfología","Desinencias 1ª, 2ª, 3ª.","manejo, manejas, maneja.","Persona de 'recorrieron'","3ª plural");
add(32,"Futuro de indicativo","Morfología","Expresa acción futura.","viajaré, rodarás, manejará.","Futuro de 'poner' en 2ª singular","pondrás");
add(33,"Condicional simple","Morfología","Expresa hipótesis.","viajaría, frenarías.","Condicional de 'vivir' para él/ella","viviría");
add(34,"Imperativo","Morfología","Modo para mandatos.","¡Acelera!, ¡Frena!","Imperativo de 'venir' para vosotros","venid");
add(35,"Voz pasiva","Morfología","Ser + participio.","La ruta fue recorrida por el grupo.","Pasa a pasiva: 'El viento derribó la moto'","La moto fue derribada por el viento");
// ================= 5. DERIVACIÓN =================
add(36,"Prefijación (negación)","Morfología","Prefijos in-, des-, anti-","infrenable, desarmar.","Aplica prefijo 're-' a 'arrancar'","rearrancar");
add(37,"Sufijación -ción","Morfología","Sustantivos abstractos","aceleración, frenación.","Sustantivo de 'decelerar'","deceleración");
add(38,"Interfijación","Morfología","Inserción -c-, -it-","motoneta (moto + c + ita)","Interfijo en 'motorcito'","-c-");
add(39,"Parasíntesis","Morfología","Prefijo + sufijo simultáneos","enrielar (en- + riel + -ar)","Parasíntesis en 'aparcar'","a- + parque + -ar");
add(40,"Sufijos aumentativos","Morfología","-ón, -azo","motón, cascazo.","Aumentativo de 'moto'","motorra");
add(41,"Sufijo diminutivo -ito","Morfología","Expresa tamaño pequeño o afecto","moticas, frenitos.","Diminutivo de 'llanta'","llantita");
// ================= 6. CLASES DE PALABRAS =================
add(42,"Sustantivos concretos/abstractos","Clases palabras","Concretos: objetos; abstractos: conceptos.","carretera (concreto), aventura (abstracto).","Clasifica 'libertad'","abstracto");
add(43,"Adjetivos calificativos","Clases palabras","Expresan cualidades.","larga curva, camino empinado.","Adjetivo en 'moto ágil'","ágil");
add(44,"Verbos copulativos","Clases palabras","Ser, estar, parecer.","La ruta es peligrosa.","Copulativo en 'El motor parece fallar'","parece");
add(45,"Adverbios de modo","Clases palabras","Terminados en -mente o invariables","rápidamente, bien.","Adverbio de 'lento'","lentamente");
add(46,"Preposiciones","Clases palabras","Relacionan términos.","Voy a la costa.","Preposición de destino","a");
add(47,"Conjunciones coordinantes","Clases palabras","y, e, ni, o, u, pero, sino.","Aceleró y frenó.","Adversativa en 'Quiero ir, pero no puedo'","pero");
