<body>
<div class="container">
    <div class="hero">
        <h1>🏍️ Ruta Bucaramanga → Costa Colombiana</h1>
        <p>100 técnicas para motoviajeros: Yamaha V80, SZR150, Suzuki Nova 124, Megane 1.6 · Acampar · Estándares MEN</p>
    </div>
    <div class="stats-progress">
        <span>📚 Inventario: <strong id="totalCount">100</strong> técnicas</span>
        <div class="progress-area">
            <span>🏆 Progreso:</span>
            <div class="progress-bar-container"><div class="progress-fill" id="globalProgressFill"></div></div>
            <span id="progressPercent">0%</span>
        </div>
        <span class="badge">🔊 Voz · ✍️ Ejercicios prácticos</span>
    </div>
    <div class="filter-bar">
        <input type="text" id="searchInput" placeholder="🔍 Buscar...">
        <select id="categorySelect">
            <option value="all">📌 Todas</option>
            <option value="Ruta y acampe">🏕️ Ruta BGA-Costa + acampar</option>
            <option value="Mecánica moto">🔧 Mecánica: V80, SZR150, Nova, Megane</option>
            <option value="Seguridad">🛡️ Seguridad en carretera</option>
            <option value="Estándares MEN">📘 Estándares lenguaje (MEN)</option>
            <option value="Morfología">🎭 Morfología flexiva/derivativa</option>
            <option value="Clases palabras">📂 Clases de palabras</option>
            <option value="Morfemática">🧬 Lexema, morfema, alomorfo</option>
            <option value="Formación palabras">🧩 Composición, acronimia, siglación</option>
            <option value="Lectura crítica">📖 Saber Pro / concurso docente</option>
        </select>
    </div>
    <div id="cardsContainer" class="cards-grid"></div>
    <div class="footer-note">✅ Ruta Bucaramanga - San Alberto - Aguachica - Ocaña - Valledupar - Santa Marta. Consejos de acampe, mecánica, lenguaje y morfología.</div>
</div>
<script>
const techniques = [];
function add(id, name, category, teoria, ejemplo, ejercicio, suggestedAnswer, grado="") {
    techniques.push({ id, name, category, teoria, ejemplo, ejercicio, suggestedAnswer, grado });
}
// ================= 1. RUTA BUCARAMANGA - COSTA Y ACAMPE =================
add(1,"Ruta Bucaramanga - San Alberto (primer tramo)","Ruta y acampe","Salida por la autopista vía Barrancabermeja. 160 km, clima cálido. Usa ropa ligera y mucha hidratación.","En San Alberto hay zona de camping cerca del río.","¿Cuántos km tiene el primer tramo hasta San Alberto?","160 km");
add(2,"San Alberto - Aguachica - Ocaña","Ruta y acampe","Vía nacional 45, luego desvío a Ocaña. 120 km. Subida pronunciada. La V80 puede sentir la altura.","Revisar frenos antes del descenso.","¿Qué moto puede tener dificultad en subida?","Yamaha V80");
add(3,"Ocaña - Valledupar","Ruta y acampe","Carretera 70, 180 km. Tramo con curvas y pocos poblados. Llevar combustible extra.","La Suzuki Nova 124 rinde bien en este tramo.","¿Cuántos km aproximados de Ocaña a Valledupar?","180 km");
add(4,"Valledupar - Santa Marta (final)","Ruta y acampe","Autopista 90, 160 km. Clima cálido y brisa fuerte. Cuidado con vientos laterales en moto pequeña.","La Megane 1.6 es estable como vehículo de apoyo.","¿Qué peligro hay en la autopista hacia Santa Marta?","vientos laterales");
add(5,"Camping Los Samanes (San Alberto)","Ruta y acampe","A orillas del río, con sombra y fogatas permitidas. Llevar mosquitero.","Tarifa aprox $15.000 por persona.","¿Qué elemento esencial para acampar cerca de río?","mosquitero");
add(6,"Camping El Mirador (Ocaña)","Ruta y acampe","Zona montañosa, vista panorámica. Temperatura fresca (18°C). Llevar bolsa de dormir térmica.","Se puede acampar en carpa o en cabañas rústicas.","¿Qué temperatura hay en Ocaña?","18°C");
add(7,"Acampe en la playa (Santa Marta)","Ruta y acampe","Playa Los Angeles, acampe permitido. Cuidado con la marea alta.","Llevar protector solar y abundante agua.","¿Qué riesgo hay al acampe en playa?","marea alta");
add(8,"Equipo de campamento básico","Ruta y acampe","Carpa (3 estaciones), sleeping bag, linterna, mechero, cocinilla, aislante térmico.","La SZR150 puede llevar alforjas laterales.","¿Cuál es el aislante térmico?","colchoneta o aislante");
add(9,"Alimentos no perecederos","Ruta y acampe","Atún, galletas, arroz instantáneo, frutos secos, chocolate energético.","En moto pequeña, priorizar peso ligero.","¿Qué alimento es buena fuente de energía?","chocolate o frutos secos");
add(10,"Purificación de agua","Ruta y acampe","Usar pastillas potabilizadoras o hervir durante 5 minutos.","En ríos de montaña, el agua puede tener bacterias.","¿Cuánto tiempo hervir agua para potabilizar?","5 minutos");
// ================= 2. MECÁNICA Y PREPARACIÓN DE VEHÍCULOS =================
add(11,"Yamaha V80: ajuste de carburador para altura","Mecánica moto","En subidas (Ocaña, 1500 msnm), enriquecer mezcla: girar tornillo de aire 1/4 vuelta.","Mezcla pobre causa calentamiento.","¿Qué se ajusta en carburador a mayor altura?","enriquecer mezcla");
add(12,"Suzuki Nova 124: tensión de cadena","Mecánica moto","Juego de 2-3 cm en punto medio. Lubricar cada 500 km con aceite SAE 90.","Cadena floja puede saltar y bloquear la rueda.","¿Cada cuánto lubricar cadena en ruta?","500 km");
add(13,"Yamaha SZR150: revisión de refrigeración","Mecánica moto","Motor refrigerado por aire, verificar aletas limpias y aceite 20W50 en climas cálidos.","En costa, no exceder RPM para evitar sobrecalentamiento.","¿Qué aceite usar en SZR150 para clima cálido?","20W50");
add(14,"Megane 1.6 como vehículo apoyo","Mecánica moto","Capacidad maletero 510 L, cargar repuestos (bujías, fusibles, kit de parche).","El Megane tiene protección bajo cárter de fábrica.","¿Capacidad maletero Megane 1.6?","510 litros");
add(15,"Preparación de alforjas para moto","Mecánica moto","Distribuir peso uniforme: objetos pesados abajo y cerca del centro.","V80 lleva máximo 15 kg de equipaje.","¿Peso máximo equipaje Yamaha V80?","15 kg");
add(16,"Kit de herramientas básico","Mecánica moto","Llaves 8,10,12,14,17; destornilladores; bomba de aire; parches; multímetro.","Para Nova 124 incluir extractor de bujía.","¿Qué herramienta saca la bujía?","extractor o llave de bujía");
add(17,"Neumáticos: presión adecuada","Mecánica moto","V80: 25 psi; Nova 124: 28 psi; SZR150: 29 psi; Megane 1.6: 32 psi.","En carretera con calor, la presión aumenta 2-3 psi.","¿Presión recomendada Suzuki Nova 124?","28 psi");
add(18,"Batería y sistema eléctrico","Mecánica moto","Revisar bornes limpios, voltaje mínimo 12.4V. V80 usa arranque por patada, ideal.","Cargar celular con power bank, no con la moto si es de baja potencia.","¿Qué moto tiene arranque por patada?","Yamaha V80");
add(19,"Frenos de tambor vs disco","Mecánica moto","V80 tiene tambor trasero; SZR150 y Nova disco delantero. Revisar pastillas cada 5000 km.","En mojado, frenar con suavidad.","¿Cada cuánto revisar pastillas de freno?","5000 km");
add(20,"Combustible: octanaje y autonomía","Mecánica moto","V80: 87 octanos (corriente), tanque 5L → autonomía ~120 km. Nova 124: 91 octanos (extra), 12L → ~250 km.","Llevar gasolina extra en botella certificada.","Autonomía Suzuki Nova 124?","~250 km");
// ================= 3. ESTÁNDARES MEN (LENGUAJE) =================
add(21,"Producción de crónicas de viaje (1°-3°)","Estándares MEN","Escribir relatos cortos sobre experiencias en moto.","'Salí de Bucaramanga con mi V80, el sol calentaba...'","Escribe una oración para iniciar una crónica de viaje","El motor rugió al salir de Bucaramanga","1°-3°");
add(22,"Comprensión de mapas y señales (4°-5°)","Estándares MEN","Interpretar información vial y kilómetros.","Señal 'Bucaramanga 160 km' indica distancia.","¿Qué indica una señal con 'Santa Marta 120 km'?","distancia a Santa Marta","4°-5°");
add(23,"Inferencia en relatos de carretera (6°-7°)","Estándares MEN","Deducir peligros o emociones implícitas.","'El viento soplaba fuerte, la moto se movía' infiere peligro.","Infiere: 'El conductor se puso chaqueta gruesa'","hace frío","6°-7°");
add(24,"Argumentación sobre seguridad vial (8°-9°)","Estándares MEN","Defender el uso de casco integral con argumentos.","El casco integral protege la cara en caídas.","¿Qué tipo de casco ofrece más protección?","integral","8°-9°");
add(25,"Lectura crítica de noticias (10°-11°)","Estándares MEN","Evaluar credibilidad de información sobre accidentes de tránsito.","Comparar dos versiones de un mismo accidente.","¿Qué se debe verificar en una noticia?","fuentes y evidencia","10°-11°");
// ================= 4. MORFOLOGÍA FLEXIVA =================
add(26,"Flexión de género (sustantivos)","Morfología","Los sustantivos varían en género con -o, -a.","moto (femenino), casco (masculino).","Femenino de 'conductor'","conductora");
add(27,"Flexión de número (plural)","Morfología","Se añade -s o -es.","carretera/carreteras, freno/frenos.","Plural de 'parachoques'","parachoques (invariable)");
add(28,"Pretérito perfecto simple","Morfología","Acción pasada puntual.","viajé, recorriste, aceleró.","Conjuga 'acelerar' en 1ª singular","aceleré");
add(29,"Modo subjuntivo presente","Morfología","Expresa deseo o posibilidad.","Espero que llegues bien.","Subjuntivo de 'frenar' para él","frene");
add(30,"Aspecto perfectivo/imperfectivo","Morfología","Perfectivo: acción terminada; imperfectivo: en desarrollo.","Rodé 200 km (perfectivo) / Rodaba 200 km (imperfectivo).","Aspecto de 'había recorrido'","perfectivo");
add(31,"Persona gramatical verbal","Morfología","Desinencias 1ª, 2ª, 3ª.","manejo, manejas, maneja.","Persona de 'recorrieron'","3ª plural");
add(32,"Futuro de indicativo","Morfología","Expresa acción futura.","viajaré, rodarás, manejará.","Futuro de 'poner' en 2ª singular","pondrás");
add(33,"Condicional simple","Morfología","Expresa hipótesis.","viajaría, frenarías.","Condicional de 'vivir' para él/ella","viviría");
add(34,"Imperativo","Morfología","Modo para mandatos.","¡Acelera!, ¡Frena!","Imperativo de 'venir' para vosotros","venid");
add(35,"Voz pasiva","Morfología","Ser + participio.","La ruta fue recorrida por el grupo.","Pasa a pasiva: 'El viento derribó la moto'","La moto fue derribada por el viento");
// ================= 5. DERIVACIÓN =================
add(36,"Prefijación (negación)","Morfología","Prefijos in-, des-, anti-","infrenable, desarmar.","Aplica prefijo 're-' a 'arrancar'","rearrancar");
add(37,"Sufijación -ción","Morfología","Sustantivos abstractos","aceleración, frenación.","Sustantivo de 'decelerar'","deceleración");
add(38,"Interfijación","Morfología","Inserción -c-, -it-","motoneta (moto + c + ita)","Interfijo en 'motorcito'","-c-");
add(39,"Parasíntesis","Morfología","Prefijo + sufijo simultáneos","enrielar (en- + riel + -ar)","Parasíntesis en 'aparcar'","a- + parque + -ar");
add(40,"Sufijos aumentativos","Morfología","-ón, -azo","motón, cascazo.","Aumentativo de 'moto'","motorra");
add(41,"Sufijo diminutivo -ito","Morfología","Expresa tamaño pequeño o afecto","moticas, frenitos.","Diminutivo de 'llanta'","llantita");
// ================= 6. CLASES DE PALABRAS =================
add(42,"Sustantivos concretos/abstractos","Clases palabras","Concretos: objetos; abstractos: conceptos.","carretera (concreto), aventura (abstracto).","Clasifica 'libertad'","abstracto");
add(43,"Adjetivos calificativos","Clases palabras","Expresan cualidades.","larga curva, camino empinado.","Adjetivo en 'moto ágil'","ágil");
add(44,"Verbos copulativos","Clases palabras","Ser, estar, parecer.","La ruta es peligrosa.","Copulativo en 'El motor parece fallar'","parece");
add(45,"Adverbios de modo","Clases palabras","Terminados en -mente o invariables","rápidamente, bien.","Adverbio de 'lento'","lentamente");
add(46,"Preposiciones","Clases palabras","Relacionan términos.","Voy a la costa.","Preposición de destino","a");
add(47,"Conjunciones coordinantes","Clases palabras","y, e, ni, o, u, pero, sino.","Aceleró y frenó.","Adversativa en 'Quiero ir, pero no puedo'","pero");
add(48,"Conjunciones subordinantes","Clases palabras","que, porque, aunque.","Llegó tarde porque había trancón.","Conector causal","porque");
add(49,"Determinantes demostrativos","Clases palabras","este, ese, aquel.","Esa moto.","Determinante en 'Aquellos cascos'","aquellos");
add(50,"Pronombres átonos","Clases palabras","me, te, se, lo, la, le...","Se lo llevó.","Acusativo para 'el casco'","lo");
// ================= 7. FORMACIÓN DE PALABRAS =================
add(51,"Composición propia","Formación","Unión de dos lexemas","parabrisas (para+brisas)","Analiza 'portaequipaje'","verbo + sustantivo");
add(52,"Acronimia","Formación","Iniciales o sílabas","SOAT, RUNT.","Significado de 'SOAT'","Seguro Obligatorio de Accidentes de Tránsito");
add(53,"Siglación","Formación","Letras iniciales","DGT, INVÍAS.","Significado de 'INVÍAS'","Instituto Nacional de Vías");
add(54,"Composición culta","Formación","Raíces grecolatinas","motocicleta (moto + ciclo)","Forma palabra con 'velo-' y 'cidad'","velocidad");
// ================= 8. MORFEMÁTICA =================
add(55,"Lexema o raíz","Morfemática","Núcleo semántico","moto- en 'motoneta'","Lexema de 'motosierra'","moto-");
add(56,"Morfema flexivo de tiempo","Morfemática","Desinencia de tiempo","rodaba: -ba","Morfema de futuro en 'viajarás'","-ás");
add(57,"Alomorfo de plural","Morfemática","Variantes: -s, -es, cero","cascos, crisis","Alomorfo plural de 'bíceps'","cero");
add(58,"Alomorfo de género femenino","Morfemática","-a, -isa, -ina","conductora","Alomorfo en 'emperatriz'","-triz");
add(59,"Tema verbal","Morfemática","Raíz + vocal temática","corr-e-","Tema de 'partir'","part-");
add(60,"Interfijo","Morfemática","Elemento sin significado","humareda (-ar-)","Interfijo en 'ruedecita'","-ec-");
add(61,"Morfema cero","Morfemática","Categoría sin marca","singular en 'moto'","Marca de singular en 'cactus'","cero");
// ================= 9. LECTURA CRÍTICA Y CONCURSO DOCENTE =================
add(62,"Identificar tesis en artículo de seguridad vial","Lectura crítica","La tesis es la idea central que se defiende.","En 'Usar casco salva vidas', la tesis es que el casco es obligatorio.","Tesis de 'Viajar en moto es económico y emocionante'","viajar en moto es beneficioso");
add(63,"Falacia ad hominem","Lectura crítica","Atacar a la persona en lugar de argumentos.","'No le creas porque nunca ha viajado'","Falacia en 'No sabes de motos porque eres joven'","ad hominem");
add(64,"Falso dilema","Lectura crítica","Presentar solo dos opciones cuando hay más.","'O llevas casco o te mueres'","Falacia en 'O compras esta moto o no viajarás'","falso dilema");
add(65,"Inferencia causal","Lectura crítica","Deducir la causa de un evento.","'El motor se caló' → infiere que se acabó gasolina.","Causa inferida de 'El suelo estaba mojado'","llovió");
add(66,"Presuposición textual","Lectura crítica","Información implícita que se da por sentada.","'El motociclista frenó bruscamente' presupone que había peligro.","Presuposición de 'Apagó el motor'","el motor estaba encendido");
add(67,"Plan de redacción para crónica de viaje","Comunicación escrita","Orden: introducción (salida), desarrollo (anécdotas), conclusión (llegada).","Estructura de una crónica de moto.","Orden lógico de una crónica","inicio → nudo → desenlace");
add(68,"Cohesión referencial (anáfora)","Comunicación escrita","Uso de pronombres para evitar repetición.","La V80 es ágil. Ella sube bien montañas.","Pronombre que se refiere a 'V80'","Ella");
add(69,"Elipsis","Comunicación escrita","Omisión de elementos gramaticales sobreentendidos.","Juan maneja y Pedro también [maneja].","Elemento omitido en 'Ana frena y Luis acelera'","ninguno");
add(70,"Corrección de dequeísmo","Comunicación escrita","Uso incorrecto de 'de que'.","'Pienso de que es peligroso' (incorrecto) → 'Pienso que es peligroso'.","Corrige 'Me alegro de que vengas'","está bien");
add(71,"Uso del punto y coma","Comunicación escrita","Separa oraciones relacionadas sin usar punto.","'Llovía; sin embargo, salí.'","Signo que separa oraciones largas relacionadas","punto y coma");
add(72,"Tilde diacrítica","Comunicación escrita","Diferencia homófonas: té/te, él/el, sí/si.","'Sé prudente' (verbo saber) vs 'Se lo di' (pronombre).","Oración con 'sé' (verbo saber)","Sé cuidadoso");
add(73,"Uso de mayúsculas","Comunicación escrita","Después de punto y nombres propios.","'El río Magdalena. Colombia.'","¿Después de punto y coma se usa mayúscula?","no");
add(74,"Barbarismo","Comunicación escrita","Error en la escritura de una palabra.","'bacalado' por 'bacalao'","Barbarismo de 'setiembre'","septiembre");
add(75,"Paronimia","Comunicación escrita","Palabras de forma parecida pero significado diferente.","actitud / aptitud, absorber / adsorber.","Error común entre 'actitud' y 'aptitud'","actitud (disposición) / aptitud (capacidad)");
// ================= 10. COMPLEMENTOS FINALES (hasta 100) =================
add(76,"Ruta alterna por Barrancabermeja","Ruta y acampe","Desvío desde Bucaramanga a Barrancabermeja (110 km), luego a Aguachica por carretera 45.","Zona petrolera, extremar precaución por camiones.","¿Qué ciudad intermedia tiene industria petrolera?","Barrancabermeja");
add(77,"Camping en La Reserva (Valledupar)","Ruta y acampe","Zona de viento, usar estacas reforzadas. Hay servicios de ducha caliente.","Llevar anclajes extra.","¿Qué accesorio extra para carpa en Valledupar?","estacas reforzadas");
add(78,"Parque Natural Tayrona (cerca Santa Marta)","Ruta y acampe","Se puede acampar en zonas autorizadas. Llevar repelente y bloqueador solar.","No acampar en zonas prohibidas por peligro de derrumbes.","¿Qué elemento es esencial para Tayrona?","repelente");
add(79,"Megane 1.6: consumo en carretera","Mecánica moto","Consumo aproximado 8 L/100 km (12 km/L). Tanque 60 L → autonomía 720 km.","Útil como vehículo nodriza para llevar combustible extra.","Autonomía Megane 1.6 en carretera","720 km");
add(80,"Yamaha SZR150: ajuste de suspensión trasera","Mecánica moto","5 niveles de precarga. Para equipaje, usar nivel 4 o 5.","Suspensión dura mejora estabilidad en curvas.","¿Nivel de precarga para equipaje?","4 o 5");
add(81,"Lubricación de cables (acelerador, embrague)","Mecánica moto","Usar aceite multigrado o spray de silicona. Evitar que se oxiden dentro de la funda.","Cable seco puede romperse.","¿Con qué lubricar cables?","aceite multigrado o silicona");
add(82,"Anteojos y careta antipolvo","Seguridad","En tramos destapados (vía Ocaña), usar gafas selladas.","Polvo puede causar accidentes.","¿Qué tipo de gafas usar en tierra?","selladas o antipolvo");
add(83,"Descanso cada 2 horas","Seguridad","Fatiga causa microsueños. Parar 15 minutos, estirar, hidratarse.","Moto pequeña requiere más paradas.","¿Cada cuánto tiempo descansar?","2 horas");
add(84,"Revisión de luces antes de salir","Seguridad","Verificar alta/baja, direccionales, stop. Llevar bombillos de repuesto.","Multa por luces rotas.","¿Qué bombillos llevar de repuesto?","H4 y de direccionales");
add(85,"Uso de GPS o mapa físico","Ruta y acampe","Descargar mapas Offline (Maps.me). Llevar mapa impreso como respaldo.","En zonas sin señal, el GPS satelital funciona.","¿Qué app funciona sin internet?","Maps.me u OSMand");
add(86,"Acampe en zona rural: normas","Ruta y acampe","Pedir permiso al dueño del terreno, no hacer ruido, no dejar basura.","Respetar la propiedad privada.","¿Qué regla básica de acampe?","no dejar basura");
add(87,"Fuego y cocina: seguridad","Ruta y acampe","Usar fogón portátil, no hacer fogatas directamente en el suelo.","En temporada seca, prohibido fogatas.","¿Qué usar en lugar de fogata?","cocinilla portátil");
add(88,"Gestión de residuos en campamento","Ruta y acampe","Llevar bolsas para basura, separar reciclables, no enterrar plásticos.","Dejar el lugar más limpio de lo encontrado.","¿Qué hacer con la basura?","llevársela");
add(89,"Kit de primeros auxilios para moto","Seguridad","Incluir vendas, gasas, alcohol, analgésico, curitas, solución salina.","En zonas remotas, improvisar con botiquín.","¿Qué desinfectante llevar?","alcohol o agua oxigenada");
add(90,"Comunicación entre motos (hand talk)","Seguridad","Usar manos libres o señales: mano izquierda abajo = peligro en el piso.","La SZR150 puede equipar intercomunicador.","¿Qué señal indica peligro en el piso?","mano izquierda abierta");
add(91,"Documentos obligatorios","Seguridad","SOAT, licencia, tarjeta de propiedad, cédula. Multa por no portarlos.","El SOAT se puede tener digital.","¿Se puede presentar SOAT digital?","sí");
add(92,"Control de velocidad","Seguridad","En carretera nacional límite 80 km/h para motos. En zona urbana 30-50 km/h.","Evitar multas y accidentes.","¿Velocidad máxima moto en carretera?","80 km/h");
add(93,"Seguro todo riesgo para moto","Seguridad","Cubre daños a terceros, robo, accidentes. Recomendado para viajes largos.","La Nova 124 tiene seguro económico.","¿Qué seguro cubre daños a la moto?","todo riesgo");
add(94,"Sufijo -dera (lugar)","Morfología","Forma sustantivos de lugar","parqueadero, mirador.","De 'campamento' a lugar","campamentero (campamentero no es común, usar 'campiña')");
add(95,"Prefijo multi-","Formación","muchos","multicilíndrico","Multi- + 'herramienta'","multiherramienta");
add(96,"Familia de palabras: moto","Morfemática","motocicleta, motoneta, motoviajero","Palabra de la familia de 'moto'","motoneta");
add(97,"Alternancia vocálica","Morfemática","contar → cuento","Alternancia en 'acelerar'?","ninguna");
add(98,"Futuro de subjuntivo en textos antiguos","Morfología","Si así fuere...","Futuro subjuntivo de 'ser'","fuere");
add(99,"Gerundio compuesto","Morfología","habiendo + participio","Habiendo rodado 200 km, paró.","Gerundio compuesto de 'viajar'","habiendo viajado");
add(100,"Epéntesis en lenguaje cotidiano","Morfemática","inserción de sonido","'pobrecito' (pobre + c + ito)","Epéntesis en 'motorcito'","-c-");

// Progreso
let userProgress = JSON.parse(localStorage.getItem('motoRutaProgress')) || {};
function updateGlobalProgress(){
    let completed = Object.values(userProgress).filter(v=>v===true).length;
    let percent = Math.round((completed/techniques.length)*100);
    let fill = document.getElementById('globalProgressFill');
    let percentSpan = document.getElementById('progressPercent');
    if(fill) fill.style.width = percent+'%';
    if(percentSpan) percentSpan.innerText = percent+'%';
}
function setStatus(id, ok){
    let span = document.getElementById(`status-${id}`);
    if(span) span.innerHTML = ok ? ' ✅' : '';
    userProgress[id] = ok;
    localStorage.setItem('motoRutaProgress', JSON.stringify(userProgress));
    updateGlobalProgress();
}
function checkAnswer(id, userAns, correctAns, inputEl, fbEl){
    let normUser = userAns.trim().toLowerCase().replace(/[¿¡]/g,'');
    let normCorr = correctAns.trim().toLowerCase().replace(/[¿¡]/g,'');
    let ok = normUser === normCorr;
    fbEl.innerHTML = ok ? '✓ ¡Correcto!' : `✗ Incorrecto. Respuesta: "${correctAns}"`;
    fbEl.className = `feedback ${ok ? 'correct' : 'incorrect'}`;
    inputEl.disabled = true;
    inputEl.style.backgroundColor = '#f0f0f0';
    setStatus(id, ok);
}
function resetCard(id, inputEl, fbEl){
    inputEl.disabled = false;
    inputEl.value = '';
    inputEl.style.backgroundColor = 'white';
    fbEl.innerHTML = '';
    fbEl.className = 'feedback';
    setStatus(id, false);
}
function speakText(text){
    if('speechSynthesis' in window){
        speechSynthesis.cancel();
        let utterance = new SpeechSynthesisUtterance(text);
        utterance.lang = 'es-ES';
        utterance.rate = 0.9;
        speechSynthesis.speak(utterance);
    } else alert("Voz no soportada.");
}
function renderCards(){
    let searchTerm = document.getElementById('searchInput').value.toLowerCase();
    let cat = document.getElementById('categorySelect').value;
    let filtered = techniques.filter(t => (cat==='all' || t.category===cat) && (t.name.toLowerCase().includes(searchTerm) || t.category.toLowerCase().includes(searchTerm) || t.teoria.toLowerCase().includes(searchTerm) || (t.grado && t.grado.toLowerCase().includes(searchTerm))));
    let container = document.getElementById('cardsContainer');
    if(filtered.length===0){ container.innerHTML='<div style="grid-column:1/-1;text-align:center;padding:3rem;">🔍 No hay técnicas con esos filtros.</div>'; return; }
    container.innerHTML = filtered.map(item => `
        <div class="card">
            <div class="card-header"><h3>#${item.id} · ${item.name} <span id="status-${item.id}" class="status-icon">${userProgress[item.id] ? '✅' : ''}</span></h3>
            <span class="category-tag">${item.category}</span>${item.grado ? `<span class="grade-tag">📘 ${item.grado}</span>` : ''}</div>
            <div class="card-body">
                <div class="teoria"><span>📘 ${item.teoria}</span><button class="btn-speak" data-teoria="${item.teoria.replace(/"/g,'&quot;')}">🔊 Leer</button></div>
                <div class="ejemplo"><span>💡 ${item.ejemplo}</span><button class="btn-speak-ejemplo" data-ejemplo="${item.ejemplo.replace(/"/g,'&quot;')}">🔊 Leer ejemplo</button></div>
                <div class="ejercicio-area"><div class="ejercicio-text">✏️ Ejercicio: ${item.ejercicio}</div>
                <div class="input-group"><input type="text" id="input-${item.id}" placeholder="Escribe tu respuesta..." ${userProgress[item.id] ? 'disabled' : ''}><button class="check-btn" data-id="${item.id}" ${userProgress[item.id] ? 'disabled' : ''}>Comprobar</button></div>
                <div id="feedback-${item.id}" class="feedback"></div>
                <button class="reset-card-btn" data-reset="${item.id}">⟳ Reiniciar ejercicio</button></div>
            </div>
        </div>`).join('');
    document.querySelectorAll('.btn-speak').forEach(btn=>btn.addEventListener('click',()=>speakText(btn.getAttribute('data-teoria'))));
    document.querySelectorAll('.btn-speak-ejemplo').forEach(btn=>btn.addEventListener('click',()=>speakText(btn.getAttribute('data-ejemplo'))));
    techniques.forEach(t=>{
        let btn = document.querySelector(`.check-btn[data-id="${t.id}"]`);
        let resetBtn = document.querySelector(`.reset-card-btn[data-reset="${t.id}"]`);
        let inputEl = document.getElementById(`input-${t.id}`);
        let fbEl = document.getElementById(`feedback-${t.id}`);
        if(btn && inputEl && fbEl) btn.addEventListener('click',()=>{ if(!inputEl.disabled) checkAnswer(t.id, inputEl.value, t.suggestedAnswer, inputEl, fbEl); btn.disabled=true; });
        if(resetBtn && inputEl && fbEl) resetBtn.addEventListener('click',()=>{ resetCard(t.id, inputEl, fbEl); let checkB = document.querySelector(`.check-btn[data-id="${t.id}"]`); if(checkB) checkB.disabled=false; });
    });
}
document.getElementById('totalCount').innerText = techniques.length;
document.getElementById('searchInput').addEventListener('input', renderCards);
document.getElementById('categorySelect').addEventListener('change', renderCards);
renderCards();
updateGlobalProgress();
</script>
</body>
</html>

sections.exercise:
