// Progreso
let userProgress = JSON.parse(localStorage.getItem('motoRutaProgress')) || {};
function updateGlobalProgress(){
    let completed = Object.values(userProgress).filter(v=>v===true).length;
    let percent = Math.round((completed/techniques.length)*100);
    let fill = document.getElementById('globalProgressFill');
    let percentSpan = document.getElementById('progressPercent');
    if(fill) fill.style.width = percent+'%';
    if(percentSpan) percentSpan.innerText = percent+'%';
}
function setStatus(id, ok){
    let span = document.getElementById(`status-${id}`);
    if(span) span.innerHTML = ok ? ' ✅' : '';
    userProgress[id] = ok;
    localStorage.setItem('motoRutaProgress', JSON.stringify(userProgress));
    updateGlobalProgress();
}
function checkAnswer(id, userAns, correctAns, inputEl, fbEl){
    let normUser = userAns.trim().toLowerCase().replace(/[¿¡]/g,'');
    let normCorr = correctAns.trim().toLowerCase().replace(/[¿¡]/g,'');
    let ok = normUser === normCorr;
    fbEl.innerHTML = ok ? '✓ ¡Correcto!' : `✗ Incorrecto. Respuesta: "${correctAns}"`;
    fbEl.className = `feedback ${ok ? 'correct' : 'incorrect'}`;
    inputEl.disabled = true;
    inputEl.style.backgroundColor = '#f0f0f0';
    setStatus(id, ok);
}
function resetCard(id, inputEl, fbEl){
    inputEl.disabled = false;
    inputEl.value = '';
    inputEl.style.backgroundColor = 'white';
    fbEl.innerHTML = '';
    fbEl.className = 'feedback';
    setStatus(id, false);
}
function speakText(text){
    if('speechSynthesis' in window){
        speechSynthesis.cancel();
        let utterance = new SpeechSynthesisUtterance(text);
        utterance.lang = 'es-ES';
        utterance.rate = 0.9;
        speechSynthesis.speak(utterance);
    } else alert("Voz no soportada.");
}
function renderCards(){
    let searchTerm = document.getElementById('searchInput').value.toLowerCase();
    let cat = document.getElementById('categorySelect').value;
    let filtered = techniques.filter(t => (cat==='all' || t.category===cat) && (t.name.toLowerCase().includes(searchTerm) || t.category.toLowerCase().includes(searchTerm) || t.teoria.toLowerCase().includes(searchTerm) || (t.grado && t.grado.toLowerCase().includes(searchTerm))));
    let container = document.getElementById('cardsContainer');
    if(filtered.length===0){ container.innerHTML='<div style="grid-column:1/-1;text-align:center;padding:3rem;">🔍 No hay técnicas con esos filtros.</div>'; return; }
    container.innerHTML = filtered.map(item => `
        <div class="card">
            <div class="card-header"><h3>#${item.id} · ${item.name} <span id="status-${item.id}" class="status-icon">${userProgress[item.id] ? '✅' : ''}</span></h3>
            <span class="category-tag">${item.category}</span>${item.grado ? `<span class="grade-tag">📘 ${item.grado}</span>` : ''}</div>
            <div class="card-body">
                <div class="teoria"><span>📘 ${item.teoria}</span><button class="btn-speak" data-teoria="${item.teoria.replace(/"/g,'&quot;')}">🔊 Leer</button></div>
                <div class="ejemplo"><span>💡 ${item.ejemplo}</span><button class="btn-speak-ejemplo" data-ejemplo="${item.ejemplo.replace(/"/g,'&quot;')}">🔊 Leer ejemplo</button></div>
                <div class="ejercicio-area"><div class="ejercicio-text">✏️ Ejercicio: ${item.ejercicio}</div>
                <div class="input-group"><input type="text" id="input-${item.id}" placeholder="Escribe tu respuesta..." ${userProgress[item.id] ? 'disabled' : ''}><button class="check-btn" data-id="${item.id}" ${userProgress[item.id] ? 'disabled' : ''}>Comprobar</button></div>
                <div id="feedback-${item.id}" class="feedback"></div>
                <button class="reset-card-btn" data-reset="${item.id}">⟳ Reiniciar ejercicio</button></div>
            </div>
        </div>`).join('');
    document.querySelectorAll('.btn-speak').forEach(btn=>btn.addEventListener('click',()=>speakText(btn.getAttribute('data-teoria'))));
    document.querySelectorAll('.btn-speak-ejemplo').forEach(btn=>btn.addEventListener('click',()=>speakText(btn.getAttribute('data-ejemplo'))));
    techniques.forEach(t=>{
        let btn = document.querySelector(`.check-btn[data-id="${t.id}"]`);
        let resetBtn = document.querySelector(`.reset-card-btn[data-reset="${t.id}"]`);
        let inputEl = document.getElementById(`input-${t.id}`);
        let fbEl = document.getElementById(`feedback-${t.id}`);
        if(btn && inputEl && fbEl) btn.addEventListener('click',()=>{ if(!inputEl.disabled) checkAnswer(t.id, inputEl.value, t.suggestedAnswer, inputEl, fbEl); btn.disabled=true; });
        if(resetBtn && inputEl && fbEl) resetBtn.addEventListener('click',()=>{ resetCard(t.id, inputEl, fbEl); let checkB = document.querySelector(`.check-btn[data-id="${t.id}"]`); if(checkB) checkB.disabled=false; });
    });
}
document.getElementById('totalCount').innerText = techniques.length;
document.getElementById('searchInput').addEventListener('input', renderCards);
document.getElementById('categorySelect').addEventListener('change', renderCards);
renderCards();
updateGlobalProgress();
</script>
</body>
</html>

