<script>
    // --------------------------------------------------------------
    // 100 ENTRIES: ENGLISH MORPHOLOGY (flexive, derivational, word classes, formation processes, morphs)
    // --------------------------------------------------------------
    const techniques = [];

    function add(id, name, category, teoria, ejemplo, ejercicio, suggestedAnswer) {
        techniques.push({ id, name, category, teoria, ejemplo, ejercicio, suggestedAnswer });
    }

    // ========= 1. INFLECTIONAL MORPHOLOGY (gender, number, tense, mood, aspect, person) =========
    add(1, "Noun plural -s", "Inflection", "Regular plural formed by adding -s or -es to nouns.", "cat → cats, bus → buses", "Plural of 'child'", "children (irregular, not -s)");
    add(2, "Possessive case ('s)", "Inflection", "Indicates possession using apostrophe + s.", "Emma's book, the dog's collar", "Form possessive of 'the teachers' (plural)", "the teachers' (apostrophe only)");
    add(3, "Third person singular -s", "Inflection", "Present simple adds -s for he/she/it.", "She runs, he eats", "Conjugate 'go' for 3rd person singular", "goes");
    add(4, "Past tense -ed", "Inflection", "Regular past tense marker -ed.", "walk → walked, play → played", "Past form of 'study'", "studied");
    add(5, "Past participle -ed/en", "Inflection", "Used in perfect tenses and passive voice.", "I have finished (finished), eaten", "Past participle of 'write'", "written");
    add(6, "Present participle -ing", "Inflection", "Progressive aspect marker, also gerund.", "She is singing, running", "Add -ing to 'swim' (double consonant)", "swimming");
    add(7, "Comparative -er", "Inflection", "Suffix for comparative degree of adjectives.", "tall → taller, fast → faster", "Comparative of 'happy'", "happier");
    add(8, "Superlative -est", "Inflection", "Suffix for superlative degree.", "high → highest, big → biggest", "Superlative of 'good'", "best (irregular)");
    add(9, "Gender marking (feminine suffixes)", "Inflection", "Some nouns distinguish gender: -ess, -ine, etc.", "actor → actress, prince → princess", "Feminine of 'waiter'", "waitress");
    add(10, "Person (pronoun case)", "Inflection", "Pronouns inflect for subjective/objective/possessive.", "I/me/my, he/him/his", "Objective case of 'we'", "us");
    add(11, "Mood: subjunctive (were)", "Inflection", "Hypothetical or counterfactual uses 'were' for all persons.", "If I were rich...", "Subjunctive form of 'be' in 'I wish I ___ there'", "were");
    add(12, "Aspect: perfect have + -en", "Inflection", "Perfect aspect formed with have + past participle.", "She has visited, they had gone", "Perfect aspect of 'eat' for 3rd sg present", "has eaten");
    add(13, "Progressive aspect", "Inflection", "be + -ing for ongoing action.", "He was sleeping, they are playing", "Progressive form of 'run' (past, 3rd sg)", "was running");
    add(14, "Future with will", "Inflection", "Modal auxiliary indicating future time.", "She will arrive tomorrow", "Express future intention using 'shall' for 1st person", "I shall go (formal) / will go");
    add(15, "Passive voice (be + -en)", "Inflection", "Passive construction with auxiliary be + past participle.", "The cake was eaten", "Transform 'The cat chased the mouse' into passive", "The mouse was chased by the cat");

    // ========= 2. DERIVATIONAL MORPHOLOGY (prefixes, suffixes, infixation, parasynthesis) =========
    add(16, "Prefix un- (negation)", "Derivation", "Reversative or negative prefix.", "unhappy, undo, unlock", "Add un- to 'certain'", "uncertain");
    add(17, "Prefix re- (again)", "Derivation", "Repetition prefix.", "rewrite, replay, rebuild", "Form verb with re- from 'consider'", "reconsider");
    add(18, "Suffix -ness (abstract noun)", "Derivation", "Derives nouns from adjectives.", "happy → happiness, dark → darkness", "Derive abstract noun from 'kind'", "kindness");
    add(19, "Suffix -tion/-sion", "Derivation", "Forms nouns from verbs.", "inform → information, decide → decision", "Noun from 'explain'", "explanation");
    add(20, "Suffix -able (capability)", "Derivation", "Adjective suffix meaning 'able to be'.", "readable, washable, breakable", "Form adjective from 'predict'", "predictable");
    add(21, "Prefix mis- (wrongly)", "Derivation", "Indicates error or incorrectness.", "misunderstand, misplace", "Add mis- to 'calculate'", "miscalculate");
    add(22, "Suffix -er (agent noun)", "Derivation", "Forms nouns meaning 'one who does'.", "teacher, writer, driver", "Agent noun from 'bake'", "baker");
    add(23, "Suffix -ly (adverb formation)", "Derivation", "Derives adverbs from adjectives.", "quick → quickly, happy → happily", "Form adverb from 'sudden'", "suddenly");
    add(24, "Infixation (expletive infix)", "Derivation", "Insertion of emphatic words inside a word (colloquial).", "un-freaking-believable", "Insert 'bloody' in 'fantastic' as infix", "fan-bloody-tastic");
    add(25, "Parasynthesis (prefix+suffix)", "Derivation", "Simultaneous prefix and suffix addition to a base.", "enlighten (en- + light + -en)", "Identify parasynthesis in 'embolden'", "em- + bold + -en (both affixes needed)");
    add(26, "Prefix pre- (before)", "Derivation", "Temporal prefix meaning 'before'.", "preheat, prehistory, preview", "Add pre- to 'record'", "prerecord");
    add(27, "Suffix -less (without)", "Derivation", "Privative suffix forming adjectives.", "fearless, hopeless, cloudless", "Form adjective with -less from 'home'", "homeless");
    add(28, "Suffix -ful (full of)", "Derivation", "Adjective suffix indicating abundance.", "joyful, careful, hopeful", "Derive from 'beauty'", "beautiful");
    add(29, "Prefix over- (excessive)", "Derivation", "Means 'too much' or 'excess'.", "overcook, overheat, overreact", "Add over- to 'load'", "overload");
    add(30, "Suffix -ment (result of action)", "Derivation", "Forms nouns from verbs.", "enjoyment, development, government", "Noun from 'accomplish'", "accomplishment");

    // ========= 3. WORD FORMATION (compounding, acronymy, blending, clipping) =========
    add(31, "Compounding (noun+noun)", "Compounding", "Two free morphemes combined.", "toothbrush, bedroom, firefighter", "Combine 'rain' + 'coat'", "raincoat");
    add(32, "Compounding (adj+noun)", "Compounding", "Adjective + noun compound.", "blackboard, greenhouse, highway", "Form compound from 'blue' + 'berry'", "blueberry");
    add(33, "Blending (portmanteau)", "Compounding", "Merging parts of two words.", "brunch (breakfast+lunch), smog (smoke+fog)", "Blend of 'motor' and 'hotel'", "motel");
    add(34, "Clipping (shortening)", "Compounding", "Reduction of a longer word.", "ad (advertisement), phone (telephone)", "Clipped form of 'influenza'", "flu");
    add(35, "Acronym (initial letters as word)", "Compounding", "Pronounced as a single word.", "NASA, NATO, UNESCO", "Acronym for 'Self-Contained Underwater Breathing Apparatus'", "SCUBA");
    add(36, "Initialism (letter by letter)", "Compounding", "Syllabified or read as individual letters.", "FBI, CEO, HTML", "Initialism for 'World Health Organization'", "WHO");
    add(37, "Zero-derivation (conversion)", "Compounding", "Change word class without affix.", "email (n.) → to email (v.), bottle (n.) → to bottle", "Convert noun 'google' to verb", "to google");
    add(38, "Back-formation", "Compounding", "Removing affix from an existing word.", "edit (from editor), babysit (from babysitter)", "Back-form verb from 'television'", "televise");
    add(39, "Reduplication", "Compounding", "Repetition of syllable or word.", "bye-bye, night-night, zigzag", "Reduplicative word meaning chaotic disorder", "helter-skelter");
    add(40, "Eponym formation", "Compounding", "Words derived from proper names.", "sandwich (Earl of Sandwich), boycott (Charles Boycott)", "Eponym for a type of wine region from France", "Champagne");

    // ========= 4. WORD CLASSES (nouns, adjectives, verbs, adverbs, prepositions, conjunctions, determiners, pronouns) =========
    add(41, "Countable nouns", "Word classes", "Nouns that have plural form and can be counted.", "dog/dogs, apple/apples", "Is 'advice' countable or uncountable?", "uncountable");
    add(42, "Uncountable nouns", "Word classes", "Nouns without plural form, treated as singular.", "water, information, rice", "Use quantifier with 'furniture'", "a piece of furniture");
    add(43, "Gradable adjectives", "Word classes", "Adjectives that can vary in intensity.", "hot, hotter, hottest; beautiful, more beautiful", "Adverb intensifier for 'cold'", "very cold");
    add(44, "Dynamic verbs", "Word classes", "Action verbs that can be used in progressive.", "run, eat, write", "Is 'know' a dynamic verb?", "no, stative");
    add(45, "Stative verbs", "Word classes", "Describe state rather than action.", "believe, own, seem, love", "Why is 'hate' not used in progressive normally?", "stative meaning");
    add(46, "Adverbs of manner", "Word classes", "Describe how action is performed.", "happily, slowly, fast", "Form manner adverb from 'careful'", "carefully");
    add(47, "Prepositions of place", "Word classes", "Indicate location.", "in, on, at, under, between", "Preposition: 'The book is ___ the table' (on surface)", "on");
    add(48, "Coordinating conjunctions", "Word classes", "Connect equal elements: for, and, nor, but, or, yet, so.", "I like tea but not coffee", "Conjunction for addition", "and");
    add(49, "Subordinating conjunctions", "Word classes", "Introduce dependent clauses.", "because, although, if, when", "Subordinator for cause: 'He left ___ he was tired'", "because");
    add(50, "Determiners (articles)", "Word classes", "Definite/indefinite reference: a/an, the.", "an apple, the house", "Indefinite article before 'hour'", "an hour");
    add(51, "Possessive determiners", "Word classes", "my, your, his, her, its, our, their", "This is ___ (John) car -> correct determiner", "his");
    add(52, "Personal pronouns (subject)", "Word classes", "I, you, he, she, it, we, they", "Subject pronoun for Maria", "she");
    add(53, "Object pronouns", "Word classes", "me, you, him, her, it, us, them", "Replace 'the children' object: 'I see the children'", "them");
    add(54, "Reflexive pronouns", "Word classes", "-self / -selves forms.", "myself, yourself, himself, ourselves", "Reflexive for 'they': 'They did it by ___'", "themselves");
    add(55, "Interrogative pronouns", "Word classes", "who, whom, which, what", "Ask about person as subject", "who");

    // ========= 5. GRAMMATICAL ACCIDENTS (case, degree, voice, definiteness) =========
    add(56, "Nominative case", "Grammatical categories", "Subject of the verb.", "I, he, she, we, they", "Nominative form of 'them'", "they");
    add(57, "Accusative case", "Grammatical categories", "Direct/indirect object.", "me, him, her, us, them", "Accusative of 'I'", "me");
    add(58, "Genitive case", "Grammatical categories", "Possession with 's or of-phrase.", "John's car, the roof of the house", "Genitive phrase: 'the toys of the children' alternate", "the children's toys");
    add(59, "Positive degree", "Grammatical categories", "Base adjective form.", "tall, interesting, good", "Positive of 'best'", "good");
    add(60, "Comparative degree", "Grammatical categories", "Comparison between two.", "bigger, more intelligent", "Comparative of 'bad'", "worse");
    add(61, "Superlative degree", "Grammatical categories", "Extreme degree among three or more.", "biggest, most intelligent", "Superlative of 'far' (distance)", "farthest / furthest");
    add(62, "Active voice", "Grammatical categories", "Subject performs action.", "The dog bit the man", "Change to passive: 'The man was bitten'", "active already described");
    add(63, "Passive voice", "Grammatical categories", "Subject receives action.", "The song was sung by Lisa", "Transform 'They built a house' into passive", "A house was built by them");
    add(64, "Definiteness", "Grammatical categories", "Marked by 'the' vs 'a/an'.", "the car (specific), a car (non-specific)", "Definite article for 'universe'", "the universe");
    add(65, "Grammatical number (singular/plural)", "Grammatical categories", "Number agreement.", "mouse/mice, child/children", "Plural of 'phenomenon'", "phenomena");

    // ========= 6. MORPHEMICS: LEXEME, MORPHEME, ALLOMORPH, STEM, BASE, ROOT, INFIX, ETC. =========
    add(66, "Free morpheme", "Morphemics", "Can stand alone as word.", "dog, book, run, happy", "Identify free morpheme in 'unhappiness'", "happy");
    add(67, "Bound morpheme", "Morphemics", "Must attach to another morpheme.", "un-, -ness, pre-, -ed", "Bound morpheme in 'rewrite'", "re- and -write (write free?) re- bound");
    add(68, "Root (lexeme)", "Morphemics", "Core meaning, cannot be further analyzed.", "in 'unfaithful': 'faith' is root", "Root of 'nationalization'", "nation");
    add(69, "Stem", "Morphemics", "Base to which affixes attach.", "in 'national' stem is 'nation'", "Stem of 'prettier' before -er", "pretty");
    add(70, "Base", "Morphemics", "Any unit to which an affix is added.", "in 'unhappiness': base 'happy' (for -ness), base 'unhappy' (for -ness)", "Base for '-ed' in 'reprinted'", "reprint");
    add(71, "Allomorph (plural)", "Morphemics", "Different phonetic variants of same morpheme.", "-s / -z / -ɪz (cats, dogs, houses)", "Allomorph of plural in 'oxen'", "-en (irregular allomorph)");
    add(72, "Allomorph of past tense -ed", "Morphemics", "/t/, /d/, /ɪd/ allomorphs.", "walked /t/, played /d/, waited /ɪd/", "Which allomorph for 'landed'?", "/ɪd/");
    add(73, "Zero morpheme", "Morphemics", "Meaningful absence of an overt form.", "sheep (sg/pl identical), cut (past = cut)", "Zero plural of 'deer'", "deer (no overt marker)");
    add(74, "Suppletion (allomorph)", "Morphemics", "Complete replacement of root.", "go → went, good → better", "Suppletive past of 'be'", "was/were");
    add(75, "Cranberry morpheme", "Morphemics", "Unique bound morpheme only in one word.", "cran- (only in cranberry), huckle-", "Identify cranberry in 'boysenberry'", "boysen-");
    add(76, "Infix (expletive)", "Morphemics", "Inserted inside a base for emphasis.", "abso-bloody-lutely", "Insert 'freaking' in 'fantastic' as infix", "fan-freaking-tastic");
    add(77, "Derivational morpheme", "Morphemics", "Changes meaning or word class.", "-ness (adj→noun), un- (negation)", "Derivational affix in 'teacher'", "-er");
    add(78, "Inflectional morpheme", "Morphemics", "Adds grammatical info, no class change.", "plural -s, past -ed, -ing", "Inflectional suffix in 'walked'", "-ed");
    add(79, "Morphophonemic alternation", "Morphemics", "Sound changes at morpheme boundaries.", "leaf → leaves (f→v), knife → knives", "Why does 'wife' become 'wives'?", "voicing alternation before -s allomorph");
    add(80, "Word family (lexeme)", "Morphemics", "Set of related words sharing root.", "run, runner, running, ran", "Morphologically related to 'sing'", "singer, singing, sang");

    // extend to 100 with high-quality additional entries covering remaining areas
    for (let i = 81; i <= 100; i++) {
        if (i === 81) add(81, "Prefix ex- (former)", "Derivation", "Means out of, former.", "ex-president, ex-wife", "Add ex- to 'husband'", "ex-husband");
        else if (i === 82) add(82, "Suffix -hood (state)", "Derivation", "Forms abstract nouns for condition.", "childhood, adulthood, brotherhood", "Derive from 'neighbor'", "neighborhood");
        else if (i === 83) add(83, "Suffix -ship (status)", "Derivation", "Denotes condition or skill.", "friendship, membership", "From 'scholar' + -ship", "scholarship");
        else if (i === 84) add(84, "Prefix sub- (under)", "Derivation", "Below or subordinate.", "submarine, substandard", "Form word sub + 'way'", "subway");
        else if (i === 85) add(85, "Prefix super- (above)", "Derivation", "Means over, superior.", "supermarket, superstar", "Super + 'natural'", "supernatural");
        else if (i === 86) add(86, "Suffix -ive (tendency)", "Derivation", "Adjective suffix.", "active, creative, aggressive", "Adjective from 'explode'", "explosive");
        else if (i === 87) add(87, "Blending: smog + fog", "Compounding", "Lexical blend.", "spork (spoon+fork), brunch", "Blend of 'web' + 'log'", "blog");
        else if (i === 88) add(88, "Acronym: RADAR", "Compounding", "Radio Detection And Ranging", "LASER, SCUBA", "Acronym for 'Light Amplification by Stimulated Emission of Radiation'", "LASER");
        else if (i === 89) add(89, "Clipping: exam", "Compounding", "Shortening without change of meaning.", "gym (gymnasium), lab (laboratory)", "Clipped form of 'dormitory'", "dorm");
        else if (i === 90) add(90, "Appreciative suffix -ie (affection)", "Appreciative suffixes", "Diminutive/affectionate.", "doggie, birdie, sweetie", "Affectionate form of 'cat'", "kitty (cat → kitty, -y variant)");
        else if (i === 91) add(91, "Feminine suffix -ette", "Derivation", "Diminutive or feminine marker.", "usherette, suffragette", "Feminine of 'comedian' sometimes", "comedienne (not -ette but similar)");
        else if (i === 92) add(92, "Prefix anti- (opposite)", "Derivation", "Against or opposing.", "antibiotic, antifreeze", "Anti + 'social'", "antisocial");
        else if (i === 93) add(93, "Suffix -ize (verbal)", "Derivation", "Forms verbs meaning to make or become.", "modernize, standardize", "Verb from 'apology'", "apologize");
        else if (i === 94) add(94, "Suffix -al (relational)", "Derivation", "Adjective suffix.", "cultural, natural, emotional", "From 'universe' + -al", "universal");
        else if (i === 95) add(95, "Compound adjective (participle)", "Compounding", "Adj+participle compounds.", "good-looking, well-known, handmade", "Compound from 'quick' + 'thinking'", "quick-thinking");
        else if (i === 96) add(96, "Co-compounding", "Compounding", "Two coordinated elements.", "bittersweet, deaf-mute", "Form compound from 'writer' and 'director'", "writer-director");
        else if (i === 97) add(97, "Phrasal verb morphology", "Word classes", "Verb + particle (unit).", "give up, look after, run into", "Particle in 'figure out'", "out");
        else if (i === 98) add(98, "Negative prefix in- (with allomorphs)", "Derivation", "im-, il-, ir- before certain consonants.", "impossible, illegal, irrelevant", "Prefix for 'logical' negation", "illogical");
        else if (i === 99) add(99, "Suffix -ance (state)", "Derivation", "Forms nouns from verbs.", "acceptance, performance", "Derive from 'resist'", "resistance");
        else add(100, "Zero-derivation (verb→noun)", "Compounding", "Conversion without affix: verb to noun.", "a run, a guess, a swim", "Convert verb 'walk' into noun", "a walk (take a walk)");
    }

    // final sort by id
    techniques.sort((a,b) => a.id - b.id);
    document.getElementById('totalCount').innerText = techniques.length;

    const container = document.getElementById('cardsContainer');
    const searchInput = document.getElementById('searchInput');
    const categorySelect = document.getElementById('categorySelect');

    function renderCards() {
        const searchTerm = searchInput.value.toLowerCase();
        const selectedCat = categorySelect.value;
        const filtered = techniques.filter(t => {
            const matchSearch = t.name.toLowerCase().includes(searchTerm) ||
                                t.category.toLowerCase().includes(searchTerm) ||
                                t.teoria.toLowerCase().includes(searchTerm);
            const matchCat = selectedCat === 'all' || t.category === selectedCat;
            return matchSearch && matchCat;
        });

        if (filtered.length === 0) {
            container.innerHTML = `<div style="grid-column:1/-1; text-align:center;padding:3rem;">🔍 No morphological techniques match the filters.</div>`;
            return;
        }

        container.innerHTML = filtered.map(item => `
            <div class="card">
                <div class="card-header">
                    <h3>#${item.id} · ${item.name}</h3>
                    <span class="category-tag">${item.category}</span>
                </div>
                <div class="card-body">
                    <div class="teoria">📖 ${item.teoria}</div>
                    <div class="ejemplo">💡 Example: ${item.ejemplo}</div>
                    <div class="ejercicio">✏️ Exercise: ${item.ejercicio}</div>
                    <div class="answer-hint" data-id="${item.id}">🔎 Show suggested answer</div>
                    <div id="answer-${item.id}" class="hidden-answer">✅ ${item.suggestedAnswer}</div>
                </div>
            </div>
        `).join('');

        document.querySelectorAll('.answer-hint').forEach(btn => {
            btn.addEventListener('click', (e) => {
                const id = btn.getAttribute('data-id');
                const answerDiv = document.getElementById(`answer-${id}`);
                if(answerDiv.style.display === 'none' || answerDiv.style.display === '') {
                    answerDiv.style.display = 'block';
                    btn.textContent = '🙈 Hide answer';
                } else {
                    answerDiv.style.display = 'none';
                    btn.textContent = '🔎 Show suggested answer';
                }
            });
        });
    }

    searchInput.addEventListener('input', renderCards);
    categorySelect.addEventListener('change', renderCards);
    renderCards();
</script>
