        .exercise-section,
        .quiz-section {
            background: rgba(252, 246, 235, 0.15);
            border: 1px solid rgba(201, 168, 76, 0.05);
            border-radius: 14px;
            padding: 1.2rem 1.5rem;
            margin-top: 1rem;
            backdrop-filter: blur(4px);
            box-shadow: 0 2px 20px rgba(44, 24, 16, 0.02);
        }

        .exercise-section h3,
        .quiz-section h3 {
            font-family: var(--font-uncial);
            font-size: 1rem;
            color: var(--rubi);
            margin-bottom: 0.6rem;
            display: flex;
            align-items: center;
            gap: 0.5rem;
        }

        .exercise-section .exercise-prompt,
        .quiz-section .quiz-question {
            font-size: 0.9rem;
            color: var(--tinta-clara);
            line-height: 1.7;
            margin-bottom: 0.5rem;
        }

        .exercise-section .exercise-input {
            width: 100%;
            background: rgba(252, 246, 235, 0.15);
            border: 1px solid rgba(184, 149, 106, 0.06);
            border-radius: 10px;
            padding: 0.5rem 0.8rem;
            font-family: var(--font-serif);
            font-size: 0.85rem;
            color: var(--tinta);
            resize: vertical;
            min-height: 70px;
            transition: border-color 0.3s;
        }

        .exercise-section .exercise-input:focus {
            border-color: var(--oro);
            outline: none;
            box-shadow: 0 0 0 3px rgba(201, 168, 76, 0.03);
        }

        .exercise-section .exercise-actions,
        .quiz-section .quiz-actions {
            display: flex;
            gap: 0.5rem;
            margin-top: 0.5rem;
            flex-wrap: wrap;
        }

        .btn-exercise,
        .btn-quiz {
            font-family: var(--font-uncial);
            font-size: 0.6rem;
            padding: 0.2rem 1.2rem;
            border-radius: 40px;
            border: 1px solid var(--oro-light);
            background: rgba(255, 255, 255, 0.08);
            color: var(--tinta-clara);
            cursor: pointer;
            transition: all 0.3s;
            backdrop-filter: blur(2px);
        }

        .btn-exercise:hover,
        .btn-quiz:hover {
            background: rgba(201, 168, 76, 0.04);
            border-color: var(--oro);
            color: var(--rubi);
        }

        .btn-exercise.primary,
        .btn-quiz.primary {
            background: rgba(139, 26, 43, 0.04);
            border-color: var(--rubi-light);
            color: var(--rubi);
        }

        .btn-exercise.primary:hover,
        .btn-quiz.primary:hover {
            background: rgba(139, 26, 43, 0.06);
        }

        .exercise-feedback,
        .quiz-result {
