        /* ============================================================
           MODAL DE TÉCNICA (INTERACTIVO)
           ============================================================ */

        .modal-overlay {
            display: none;
            position: fixed;
            inset: 0;
            background: rgba(44, 24, 16, 0.5);
            backdrop-filter: blur(8px);
            z-index: 1000;
            justify-content: center;
            align-items: center;
            padding: 2rem;
        }

        .modal-overlay.open {
            display: flex;
        }

        .modal-content {
            background: var(--pergamino-light);
