            border-radius: 16px;
            max-width: 700px;
            width: 100%;
            max-height: 90vh;
            overflow-y: auto;
            padding: 2rem;
            border: 2px solid var(--oro);
            box-shadow: 0 8px 60px rgba(44, 24, 16, 0.3);
