        }

        .modal-content::-webkit-scrollbar {
            width: 5px;
        }
        .modal-content::-webkit-scrollbar-track {
            background: var(--pergamino);
            border-radius: 30px;
        }
        .modal-content::-webkit-scrollbar-thumb {
            background: var(--oro);
            border-radius: 30px;
        }

        .modal-close {
            position: absolute;
            top: 1rem;
            right: 1.2rem;
            font-size: 1.6rem;
            background: none;
            border: none;
            color: var(--tinta-gris);
            cursor: pointer;
            transition: all 0.3s;
            font-family: var(--font-serif);
            line-height: 1;
