            font-style: italic;
            opacity: 0.5;
            margin-top: 0.3rem;
        }

        .modal-content .modal-preview:empty::before {
            content: 'tu haiku aparecerá aquí...';
            color: var(--tinta-gris);
            opacity: 0.2;
            font-size: 0.7rem;
            font-style: italic;
        }

        /* ============================================================
           BOTÓN FLOTANTE DE STOP
           ============================================================ */

        .float-stop-btn {
            position: fixed;
            bottom: 1.5rem;
            right: 1.5rem;
