            font-family: var(--font-uncial);
            cursor: pointer;
            box-shadow: 0 4px 40px rgba(139, 26, 43, 0.12);
            transition: all 0.3s;
            display: none;
            align-items: center;
            justify-content: center;
            flex-direction: column;
            line-height: 1.2;
            text-transform: uppercase;
            letter-spacing: 0.04em;
        }

        .float-stop-btn:hover {
            transform: scale(1.05);
            box-shadow: 0 4px 60px rgba(139, 26, 43, 0.15);
        }

        .float-stop-btn.visible {
            display: flex;
        }

        .float-stop-btn .stop-icon {
            font-size: 1.1rem;
        }
        .float-stop-btn .stop-label {
            font-size: 0.3rem;
            opacity: 0.5;
        }

        /* ============================================================
           RESPONSIVE
           ============================================================ */

        @media (max-width: 700px) {
            .codex {
                padding: 1.2rem 0.8rem 0.8rem;
