            }
            .tech-card .tech-practice-area .practice-input-group .practice-preview {
                font-size: 0.7rem;
            }
            .category-accordion {
                max-height: 440px;
            }
            .style-pill {
                font-size: 0.35rem;
                padding: 0.03rem 0.3rem;
            }
            .style-pill .pill-preview {
                font-size: 0.5rem;
            }
            .float-stop-btn {
                width: 2.8rem;
                height: 2.8rem;
                bottom: 0.8rem;
                right: 0.8rem;
            }
            .float-stop-btn .stop-icon {
                font-size: 0.9rem;
            }
            .float-stop-btn .stop-label {
                font-size: 0.25rem;
            }
            .progress-summary .progress-text {
                font-size: 0.65rem;
            }
            .exercise-section,
            .quiz-section {
                padding: 0.8rem 0.8rem;
            }
            .exercise-section .exercise-prompt,
            .quiz-section .quiz-question {
                font-size: 0.8rem;
            }
            .quiz-section .quiz-options label {
                font-size: 0.7rem;
            }
            .modal-content {
                padding: 1.2rem;
                margin: 0.5rem;
            }
            .modal-content .modal-head .modal-title {
                font-size: 1.2rem;
            }
        }

        @media (max-width: 450px) {
            .category-accordion {
                max-height: 340px;
            }
            .app-header {
                flex-direction: column;
                align-items: stretch;
                gap: 0.3rem;
            }
            .app-header .header-actions {
                justify-content: flex-start;
            }
            .tab-bar {
                flex-direction: column;
                gap: 0.05rem;
                border-bottom: none;
            }
            .tab-btn {
                border-bottom: 2px solid transparent;
                border-radius: 0;
                text-align: left;
                padding: 0.15rem 0.4rem;
                font-size: 0.55rem;
            }
            .tab-btn.active {
                border-bottom-color: var(--oro);
                background: rgba(201, 168, 76, 0.02);
            }
            .tab-btn .badge-progress {
                float: right;
            }
            .tech-card .tech-practice-area {
                flex-direction: column;
            }
            .tech-card .tech-practice-area .practice-input-group {
                min-width: unset;
                width: 100%;
            }
            .tech-card .tech-practice-area .tech-actions {
                justify-content: flex-start;
                width: 100%;
            }
            .style-pills {
                justify-content: center;
            }
            .exercise-section .exercise-actions,
            .quiz-section .quiz-actions {
                justify-content: center;
            }
            .quiz-section .quiz-options label {
                font-size: 0.6rem;
            }
            .search-box {
                flex-direction: column;
                align-items: stretch;
            }
            .search-box input {
                min-width: unset;
            }
            .modal-content {
                padding: 0.8rem;
            }
        }

        ::-webkit-scrollbar {
            width: 6px;
        }
        ::-webkit-scrollbar-track {
            background: var(--pergamino);
            border-radius: 30px;
        }
        ::-webkit-scrollbar-thumb {
            background: var(--oro);
            border-radius: 30px;
        }
    </style>
</head>
<body>

    <!-- ============================================================
    CODEX HAIKUM
    ============================================================ -->
    <div class="codex" id="app">

        <!-- Encabezado -->
        <header class="app-header">
            <h1>
                🍃 HAIKUM
                <small>100 autores · 100 haikus · el arte de la brevedad</small>
            </h1>
            <div class="header-actions">
                <button class="btn-pergamino" id="resetAllBtn">⟳ limpiar</button>
            </div>
        </header>

        <!-- Pestañas -->
        <div class="tab-bar" role="tablist">
            <button class="tab-btn active" data-tab="tab-tecnicas" role="tab">
                ✦ autores
                <span class="badge-progress" id="progressBadge">0/100</span>
            </button>
            <button class="tab-btn" data-tab="tab-ejercicios" role="tab">
                ✦ ejercicios
            </button>
            <button class="tab-btn" data-tab="tab-quiz" role="tab">
                ✦ quiz
            </button>
