        <!-- ============================================================
        TAB 1 — AUTORES Y TÉCNICAS
        ============================================================ -->
        <div class="tab-pane active" id="tab-tecnicas" role="tabpanel">

            <div class="progress-summary">
                <span class="progress-text"><span id="sealDisplay">🟢</span> sello de cera</span>
                <div class="progress-bar-bg"><div class="progress-bar-fill" id="progressFill"></div></div>
