            <div class="category-accordion" id="accordionContainer">
                <!-- llenado por JS -->
            </div>

            <p style="text-align:center;font-size:0.65rem;color:var(--tinta-gris);opacity:0.25;margin-top:1rem;font-style:italic;border-top:1px solid rgba(184,149,106,0.06);padding-top:0.6rem;font-family:var(--font-uncial);letter-spacing:0.04em;">
                ✦ el haiku es el instante eterno ✦
