    <!-- ============================================================
    JAVASCRIPT
    ============================================================ -->
    <script>
        (function() {
            'use strict';

            // ============================================================
            //  1. DATOS: 100 AUTORES · 100 HAIKUS/TÉCNICAS POÉTICAS
            // ============================================================

            const AUTHORS = [{
                id: 'h1',
                icon: '🍃',
                name: 'Clásicos japoneses',
                techniques: [
                    { id: 1, author: 'Matsuo Bashō', noun: 'Rana', adj: 'Antigua', verb: 'Saltar', rhetoric: 'Haiku',
                        def: 'El haiku captura el instante eterno, donde una rana salta en un estanque antiguo, creando un eco de agua y silencio.',
                        example: 'Estanque antiguo / una rana salta / sonido del agua.' },
                    { id: 2, author: 'Yosa Buson', noun: 'Luna', adj: 'Plateada', verb: 'Brillar', rhetoric: 'Haiku',
                        def: 'La luna plateada brilla sobre la pintura de un paisaje, mientras el pincel del poeta traza el instante.',
                        example: 'Luna de invierno / sobre la pintura / el pincel se detiene.' },
                    { id: 3, author: 'Kobayashi Issa', noun: 'Caracol', adj: 'Pequeño', verb: 'Subir', rhetoric: 'Haiku',
                        def: 'Un caracol pequeño sube lentamente hacia el monte Fuji, pero lo hace sin prisa, con la eternidad del instante.',
                        example: 'Caracol / sube lentamente / al monte Fuji.' },
                    { id: 4, author: 'Masaoka Shiki', noun: 'Cigarra', adj: 'Roja', verb: 'Cantar', rhetoric: 'Haiku',
                        def: 'La cigarra roja canta al atardecer, su voz atraviesa el aire caluroso y se pierde en el ocaso.',
                        example: 'Atardecer / la cigarra roja / canta en el calor.' },
                    { id: 5, author: 'Takahama Kyoshi', noun: 'Nieve', adj: 'Blanca', verb: 'Caer', rhetoric: 'Haiku',
                        def: 'La nieve blanca cae sobre la montaña, cubriendo el paisaje de un silencio que solo el invierno puede ofrecer.',
                        example: 'Nieve blanca / sobre la montaña / silencio eterno.' },
                    { id: 6, author: 'Mizuhara Shūōshi', noun: 'Luna', adj: 'Nueva', verb: 'Asomar', rhetoric: 'Haiku',
                        def: 'La luna nueva asoma entre las ramas de los pinos, un instante de luz que se desvanece en la noche.',
                        example: 'Luna nueva / entre pinos / luz que se desvanece.' },
                    { id: 7, author: 'Yamaguchi Seishi', noun: 'Mar', adj: 'Profundo', verb: 'Bramar', rhetoric: 'Haiku',
                        def: 'El mar profundo brama en la distancia, su sonido es un eco de la inmensidad que abraza la costa.',
                        example: 'Mar profundo / brama en la distancia / eco inmenso.' },
                    { id: 8, author: 'Natsume Soseki', noun: 'Luna', adj: 'Llena', verb: 'Observar', rhetoric: 'Haiku',
                        def: 'Observar la luna llena es un acto de contemplación que conecta al poeta con la eternidad del cosmos.',
                        example: 'Luna llena / observar en silencio / la eternidad.' },
                    { id: 9, author: 'Shiki', noun: 'Crisantemo', adj: 'Amarillo', verb: 'Florecer', rhetoric: 'Haiku',
                        def: 'El crisantemo amarillo florece en el jardín, un destello de luz en la penumbra del otoño.',
                        example: 'Crisantemo / amarillo en el jardín / luz de otoño.' },
                    { id: 10, author: 'Bashō', noun: 'Nube', adj: 'Pasajera', verb: 'Desvanecer', rhetoric: 'Haiku',
                        def: 'La nube pasajera se desvanece en el horizonte, recordándonos la fugacidad de la vida y el instante.',
                        example: 'Nube pasajera / se desvanece / en el horizonte.' }
                ]
            }, {
                id: 'h2',
                icon: '🍃',
                name: 'Poetas japoneses modernos',
                techniques: [
                    { id: 11, author: 'Fukuda Chiyo-ni', noun: 'Hielo', adj: 'Frío', verb: 'Derretir', rhetoric: 'Haiku',
                        def: 'El hielo frío se derrite en la mañana, mientras el sol de invierno comienza a calentar la tierra.',
                        example: 'Hielo frío / se derrite al sol / mañana de invierno.' },
                    { id: 12, author: 'Kawahara Kōjirō', noun: 'Viento', adj: 'Sutil', verb: 'Susurrar', rhetoric: 'Haiku',
                        def: 'El viento sutil susurra entre los bambúes, un sonido que invita a la meditación y al silencio.',
                        example: 'Viento sutil / susurra entre bambúes / meditación.' },
                    { id: 13, author: 'Taneda Santōka', noun: 'Peregrino', adj: 'Solitario', verb: 'Andar', rhetoric: 'Haiku',
                        def: 'El peregrino solitario anda sin rumbo, su camino es el viaje de la vida, sin destino fijo.',
                        example: 'Peregrino / anda sin rumbo / vida en camino.' },
