                <span class="label"><i class="bi bi-arrow-right-circle"></i> Progreso</span>
                <span class="porcentaje" id="sidebar-porcentaje">0%</span>
            </div>
            <div class="progress"><div class="progress-bar" id="sidebar-barra" style="width:0%"></div></div>
            <div class="detalle" id="sidebar-detalle">0 / 100 técnicas</div>
        </div>
    </nav>

    <main class="main-stellar">
        <div id="section-dashboard" class="section-content">
