        tecnicas: [
            { titulo: "Sinonimia conceptual", teoria: "La sinonimia conceptual se da cuando dos palabras comparten el mismo significado conceptual, aunque pueden diferir en otros aspectos.", recurso: "Sinonimia conceptual", ejemplo: "'muerte' y 'fallecimiento' son sinónimos conceptuales.", ejercicio: "Escribe 5 pares de sinónimos conceptuales.", reto: "Investiga la diferencia entre 'sinónimo' y 'casi sinónimo'." },
            { titulo: "Sinonimia referencial", teoria: "La sinonimia referencial se da cuando dos palabras pueden referirse al mismo objeto en un contexto determinado.", recurso: "Sinonimia referencial", ejemplo: "'Coche' y 'automóvil' pueden referirse al mismo vehículo.", ejercicio: "Escribe 5 pares de sinónimos referenciales.", reto: "Investiga la sinonimia en diferentes registros." },
            { titulo: "Sinonimia contextual", teoria: "La sinonimia contextual se da cuando dos palabras son intercambiables en un contexto específico, pero no en todos.", recurso: "Sinonimia contextual", ejemplo: "'Llamar' y 'telefonear' son sinónimos en 'Le llamé ayer', pero no en 'Llamar a la puerta'.", ejercicio: "Escribe 5 pares de sinónimos contextuales.", reto: "Analiza la sinonimia en diferentes contextos." },
            { titulo: "Antonimia gradual", teoria: "La antonimia gradual se da entre palabras que representan extremos de una escala, con grados intermedios.", recurso: "Antonimia gradual", ejemplo: "'caliente' y 'frío' tienen grados intermedios: templado, tibio.", ejercicio: "Escribe 5 pares de antónimos graduales.", reto: "Investiga la escala de temperatura." },
            { titulo: "Antonimia complementaria", teoria: "La antonimia complementaria se da entre palabras que son mutuamente excluyentes, sin grados intermedios.", recurso: "Antonimia complementaria", ejemplo: "'vivo' y 'muerto' son complementarios; no hay grados intermedios.", ejercicio: "Escribe 5 pares de antónimos complementarios.", reto: "Investiga la lógica de la complementariedad." },
            { titulo: "Antonimia recíproca", teoria: "La antonimia recíproca se da entre palabras que implican una relación de mutua dependencia.", recurso: "Antonimia recíproca", ejemplo: "'comprar' y 'vender', 'dar' y 'recibir', 'padre' e 'hijo'.", ejercicio: "Escribe 5 pares de antónimos recíprocos.", reto: "Investiga la reciprocidad en el lenguaje." },
            { titulo: "Polisemia", teoria: "La polisemia es la multiplicidad de significados de una palabra, todos ellos relacionados etimológica o conceptualmente.", recurso: "Polisemia", ejemplo: "'Cabeza' significa 'parte del cuerpo', 'inteligencia', 'extremo de algo', 'persona' (ej. cabeza de familia).", ejercicio: "Escribe 5 palabras polisémicas.", reto: "Investiga la polisemia de 'pico'." },
            { titulo: "Homonimia", teoria: "La homonimia se da cuando dos palabras diferentes coinciden en su forma (escritura o pronunciación) pero tienen significados distintos y no relacionados etimológicamente.", recurso: "Homonimia", ejemplo: "'Vino' (bebida) y 'vino' (verbo venir).", ejercicio: "Escribe 5 pares de homónimos.", reto: "Investiga la homonimia en español." },
            { titulo: "Homofonía", teoria: "La homofonía es un tipo de homonimia en el que las palabras se pronuncian igual pero se escriben diferente y tienen significados distintos.", recurso: "Homofonía", ejemplo: "'caza' (acción de cazar) y 'casa' (vivienda) son homófonos en muchos dialectos.", ejercicio: "Escribe 5 pares de homófonos.", reto: "Investiga la homofonía en tu dialecto." },
            { titulo: "Homografía", teoria: "La homografía es un tipo de homonimia en el que las palabras se escriben igual pero se pronuncian diferente y tienen significados distintos.", recurro: "Homografía", ejemplo: "'Llamo' (verbo llamar) y 'llamo' (sustantivo) no son homógrafos en español porque se escriben y pronuncian igual, pero sí en otros idiomas.", ejercicio: "Investiga la homografía en español.", reto: "Escribe 3 pares de homógrafos." },
            { titulo: "Hiperonimia", teoria: "La hiperonimia es la relación entre un término general (hiperónimo) y un término más específico (hipónimo). El hiperónimo incluye al hipónimo.", recurso: "Hiperonimia", ejemplo: "'Animal' es hiperónimo de 'perro', 'gato', 'caballo'.", ejercicio: "Escribe 5 hiperónimos con sus hipónimos.", reto: "Investiga la jerarquía de términos en un campo semántico." },
            { titulo: "Hiponimia", teoria: "La hiponimia es la relación inversa a la hiperonimia: un término específico (hipónimo) está incluido en un término más general (hiperónimo).", recurso: "Hiponimia", ejemplo: "'Perro' es hipónimo de 'animal'.", ejercicio: "Escribe 5 hipónimos con su hiperónimo.", reto: "Investiga la hiponimia en un campo semántico." },
            { titulo: "Cohiponimia", teoria: "La cohiponimia es la relación entre términos que comparten el mismo hiperónimo. Son términos del mismo nivel jerárquico.", recurso: "Cohiponimia", ejemplo: "'Perro', 'gato' y 'caballo' son cohipónimos de 'animal'.", ejercicio: "Escribe 3 cohipónimos para 3 hiperónimos.", reto: "Investiga la cohiponimia en un campo semántico." },
            { titulo: "Holonimia", teoria: "La holonimia es la relación entre un todo (holónimo) y sus partes (merónimos).", recurso: "Holonimia", ejemplo: "'Casa' es holónimo de 'techo', 'pared', 'puerta', 'ventana'.", ejercicio: "Escribe 5 holónimos con sus merónimos.", reto: "Investiga la holonimia en un objeto complejo." },
            { titulo: "Meronimia", teoria: "La meronimia es la relación entre una parte (merónimo) y el todo (holónimo).", recurso: "Meronimia", ejemplo: "'Techo' es merónimo de 'casa'.", ejercicio: "Escribe 5 merónimos con su holónimo.", reto: "Investiga la meronimia en un objeto cotidiano." },
            { titulo: "Sinonimia y variación dialectal", teoria: "La sinonimia varía según el dialecto: una palabra puede ser sinónimo en un dialecto pero no en otro.", recurso: "Sinonimia dialectal", ejemplo: "'Coche' (España) y 'carro' (América Latina) son sinónimos dialectales.", ejercicio: "Escribe 5 pares de sinónimos dialectales.", reto: "Investiga las variantes dialectales del español." },
            { titulo: "Antonimia y variación contextual", teoria: "La antonimia puede variar según el contexto: una palabra puede tener diferentes antónimos en diferentes contextos.", recurro: "Antonimia contextual", ejemplo: "'Alto' es antónimo de 'bajo' en altura, pero de 'grave' en sonido.", ejercicio: "Escribe 5 pares de antónimos contextuales.", reto: "Investiga la antonimia en diferentes contextos." },
            { titulo: "Polisemia y homonimia: diferencias", teoria: "La polisemia tiene significados relacionados; la homonimia tiene significados no relacionados. La diferencia puede ser difícil de determinar.", recurso: "Polisemia vs Homonimia", ejemplo: "'Banco' (entidad financiera) y 'banco' (asiento) son polisemia; 'vino' (bebida) y 'vino' (verbo) son homonimia.", ejercicio: "Clasifica 5 palabras como polisémicas u homónimas.", reto: "Investiga la diferencia entre polisemia y homonimia." },
            { titulo: "Elipsis semántica", teoria: "La elipsis semántica es la omisión de un elemento cuyo significado se sobreentiende por el contexto.", recurso: "Elipsis semántica", ejemplo: "'Juan tiene dos y Pedro tres' (se sobreentiende 'hijos').", ejercicio: "Escribe 5 oraciones con elipsis semántica.", reto: "Analiza la elipsis en un texto." },
            { titulo: "Repetición semántica", teoria: "La repetición semántica es la reiteración de un mismo significado con diferentes palabras, a menudo para enfatizar.", recurso: "Repetición semántica", ejemplo: "'Lo vi con mis propios ojos' (redundancia).", ejercicio: "Escribe 5 oraciones con repetición semántica.", reto: "Elimina la repetición semántica en un texto." }
        ]
    },
