    contexto: {
        nombre: "Contexto", color: "purpura", icono: "bi-robot",
        especialidad: "Pragmática, deixis, implicatura, presuposición, actos de habla",
        tecnicas: [
            { titulo: "Pragmática", teoria: "La pragmática estudia el uso del lenguaje en contexto, los significados que no son literales y la intención comunicativa del hablante.", recurso: "Pragmática", ejemplo: "'¿Puedes cerrar la ventana?' no es una pregunta sobre habilidad, sino una petición.", ejercicio: "Analiza el uso pragmático de 3 expresiones.", reto: "Investiga la pragmática en la comunicación cotidiana." },
            { titulo: "Deíxis", teoria: "La deixis es la referencia a elementos del contexto: persona (yo, tú), espacio (aquí, allí), tiempo (ahora, entonces).", recurso: "Deíxis", ejemplo: "'Yo' se refiere al hablante; 'aquí' se refiere al lugar del hablante.", ejercicio: "Identifica la deixis en 5 oraciones.", reto: "Investiga la deixis en diferentes culturas." },
            { titulo: "Deíxis personal", teoria: "La deixis personal se refiere a los participantes en el acto de habla: yo (hablante), tú (oyente), él (tercero).", recurso: "Deíxis personal", ejemplo: "'Yo' es el hablante; 'tú' es el oyente.", ejercicio: "Escribe 5 oraciones con deixis personal.", reto: "Investiga la deixis personal en diferentes lenguas." },
            { titulo: "Deíxis espacial", teoria: "La deixis espacial se refiere a la ubicación de los objetos respecto al hablante: aquí, allí, acá, allá, cerca, lejos.", recurso: "Deíxis espacial", ejemplo: "'Aquí' indica proximidad al hablante.", ejercicio: "Escribe 5 oraciones con deixis espacial.", reto: "Investiga la deixis espacial en diferentes culturas." },
            { titulo: "Deíxis temporal", teoria: "La deixis temporal se refiere al momento del acto de habla: ahora, entonces, hoy, ayer, mañana.", recurso: "Deíxis temporal", ejemplo: "'Ahora' indica el momento presente del hablante.", ejercicio: "Escribe 5 oraciones con deixis temporal.", reto: "Investiga la deixis temporal en diferentes lenguas." },
            { titulo: "Deíxis social", teoria: "La deixis social se refiere a la relación jerárquica entre los participantes: tú/usted, vos, etc.", recurso: "Deíxis social", ejemplo: "'Usted' indica formalidad y distancia; 'tú' indica confianza y cercanía.", ejercicio: "Escribe 5 oraciones con deixis social.", reto: "Investiga la deixis social en el español." },
            { titulo: "Implicatura", teoria: "La implicatura es lo que el hablante sugiere o implica sin decir explícitamente, y que el oyente infiere gracias al contexto.", recurso: "Implicatura", ejemplo: "'Tengo un examen mañana' puede implicar 'no puedo salir esta noche'.", ejercicio: "Escribe 5 oraciones con implicatura.", reto: "Investiga las implicaturas en la conversación." },
            { titulo: "Presuposición", teoria: "La presuposición es la información que se da por supuesta en un enunciado, sin afirmarse explícitamente.", recurso: "Presuposición", ejemplo: "'El rey de Francia es calvo' presupone que existe un rey de Francia.", ejercicio: "Identifica las presuposiciones en 5 oraciones.", reto: "Investiga las presuposiciones en la publicidad." },
            { titulo: "Actos de habla", teoria: "Los actos de habla son las acciones que realizamos al hablar: afirmar, preguntar, prometer, ordenar, etc.", recurso: "Actos de habla", ejemplo: "'Te prometo que vendré' es un acto de habla promisorio.", ejercicio: "Clasifica 5 oraciones según su acto de habla.", reto: "Investiga la teoría de los actos de habla." },
            { titulo: "Acto locutivo", teoria: "El acto locutivo es el acto de decir algo, el enunciado en sí mismo, con su significado literal.", recurso: "Acto locutivo", ejemplo: "'La puerta está abierta' es un acto locutivo.", ejercicio: "Escribe 5 actos locutivos.", reto: "Investiga la diferencia entre actos locutivos e ilocutivos." },
            { titulo: "Acto ilocutivo", teoria: "El acto ilocutivo es la intención del hablante al decir algo: afirmar, preguntar, prometer, ordenar, etc.", recurso: "Acto ilocutivo", ejemplo: "'La puerta está abierta' puede ser una afirmación o una sugerencia.", ejercicio: "Identifica el acto ilocutivo en 5 oraciones.", reto: "Investiga los actos ilocutivos." },
            { titulo: "Acto perlocutivo", teoria: "El acto perlocutivo es el efecto que el enunciado produce en el oyente: convencer, persuadir, asustar, etc.", recurso: "Acto perlocutivo", ejemplo: "'La puerta está abierta' puede hacer que el oyente la cierre.", ejercicio: "Analiza el efecto perlocutivo en 5 oraciones.", reto: "Investiga los actos perlocutivos." },
            { titulo: "Máximas conversacionales (Grice)", teoria: "Las máximas conversacionales son principios que guían la conversación: cantidad, calidad, relación, manera.", recurso: "Máximas conversacionales", ejemplo: "Máxima de cantidad: di todo lo necesario, pero no más.", ejercicio: "Analiza el cumplimiento de las máximas en un diálogo.", reto: "Investiga las máximas de Grice." },
            { titulo: "Máxima de cantidad", teoria: "La máxima de cantidad exige que el hablante proporcione la cantidad de información necesaria, ni más ni menos.", recurso: "Máxima de cantidad", ejemplo: "Si preguntan '¿Qué hora es?', no se debe responder con la historia del reloj.", ejercicio: "Escribe un diálogo que cumpla con la máxima de cantidad.", reto: "Investiga la máxima de cantidad." },
            { titulo: "Máxima de calidad", teoria: "La máxima de calidad exige que el hablante diga la verdad, que no afirme lo que cree falso o no tiene pruebas.", recurso: "Máxima de calidad", ejemplo: "No se debe afirmar algo sin pruebas.", ejercicio: "Escribe un diálogo que cumpla con la máxima de calidad.", reto: "Investiga la máxima de calidad." },
            { titulo: "Máxima de relación", teoria: "La máxima de relación exige que el hablante sea relevante, que sus aportaciones estén relacionadas con el tema.", recurso: "Máxima de relación", ejemplo: "En una conversación sobre el tiempo, no se debe hablar de política.", ejercicio: "Escribe un diálogo que cumpla con la máxima de relación.", reto: "Investiga la máxima de relación." },
            { titulo: "Máxima de manera", teoria: "La máxima de manera exige que el hablante sea claro, ordenado, breve y evite la ambigüedad.", recurso: "Máxima de manera", ejemplo: "Se debe evitar la ambigüedad y la oscuridad.", ejercicio: "Escribe un diálogo que cumpla con la máxima de manera.", reto: "Investiga la máxima de manera." },
            { titulo: "Inferencia pragmática", teoria: "La inferencia pragmática es el proceso por el cual el oyente deduce el significado implícito a partir del contexto.", recurso: "Inferencia pragmática", ejemplo: "'Hace frío aquí' puede inferir 'cierra la ventana'.", ejercicio: "Identifica las inferencias en 5 diálogos.", reto: "Investiga la inferencia pragmática." },
            { titulo: "Contexto situacional", teoria: "El contexto situacional incluye el lugar, el momento, los participantes y la relación entre ellos, que influyen en el significado.", recurso: "Contexto situacional", ejemplo: "Un '¡Qué calor!' en la calle en verano es diferente a decirlo en una sauna.", ejercicio: "Analiza el contexto situacional de 5 enunciados.", reto: "Investiga el contexto situacional en la comunicación." },
            { titulo: "Contexto cultural", teoria: "El contexto cultural incluye las creencias, valores, normas y costumbres que influyen en la interpretación del significado.", recurso: "Contexto cultural", ejemplo: "El concepto de 'honor' tiene diferentes significados según la cultura.", ejercicio: "Analiza el contexto cultural de 5 expresiones.", reto: "Investiga el contexto cultural en la comunicación intercultural." },
            { titulo: "Contexto lingüístico", teoria: "El contexto lingüístico es el entorno textual inmediato que rodea a una palabra o expresión.", recurso: "Contexto lingüístico", ejemplo: "'El banco' puede referirse a una entidad financiera o a un asiento, según el contexto lingüístico.", ejercicio: "Analiza el contexto lingüístico de 5 palabras.", reto: "Investiga el contexto lingüístico en la desambiguación." }
        ]
    },
