    contexto: {
        nombre: "Contexto", color: "purpura", icono: "bi-robot",
        especialidad: "Pragmática, deixis, implicatura, presuposición, actos de habla",
        tecnicas: [
            { titulo: "Pragmática", teoria: "La pragmática estudia el uso del lenguaje en contexto, los significados que no son literales y la intención comunicativa del hablante.", recurso: "Pragmática", ejemplo: "'¿Puedes cerrar la ventana?' no es una pregunta sobre habilidad, sino una petición.", ejercicio: "Analiza el uso pragmático de 3 expresiones.", reto: "Investiga la pragmática en la comunicación cotidiana." },
            { titulo: "Deíxis", teoria: "La deixis es la referencia a elementos del contexto: persona (yo, tú), espacio (aquí, allí), tiempo (ahora, entonces).", recurso: "Deíxis", ejemplo: "'Yo' se refiere al hablante; 'aquí' se refiere al lugar del hablante.", ejercicio: "Identifica la deixis en 5 oraciones.", reto: "Investiga la deixis en diferentes culturas." },
            { titulo: "Deíxis personal", teoria: "La deixis personal se refiere a los participantes en el acto de habla: yo (hablante), tú (oyente), él (tercero).", recurso: "Deíxis personal", ejemplo: "'Yo' es el hablante; 'tú' es el oyente.", ejercicio: "Escribe 5 oraciones con deixis personal.", reto: "Investiga la deixis personal en diferentes lenguas." },
            { titulo: "Deíxis espacial", teoria: "La deixis espacial se refiere a la ubicación de los objetos respecto al hablante: aquí, allí, acá, allá, cerca, lejos.", recurso: "Deíxis espacial", ejemplo: "'Aquí' indica proximidad al hablante.", ejercicio: "Escribe 5 oraciones con deixis espacial.", reto: "Investiga la deixis espacial en diferentes culturas." },
            { titulo: "Deíxis temporal", teoria: "La deixis temporal se refiere al momento del acto de habla: ahora, entonces, hoy, ayer, mañana.", recurso: "Deíxis temporal", ejemplo: "'Ahora' indica el momento presente del hablante.", ejercicio: "Escribe 5 oraciones con deixis temporal.", reto: "Investiga la deixis temporal en diferentes lenguas." },
            { titulo: "Deíxis social", teoria: "La deixis social se refiere a la relación jerárquica entre los participantes: tú/usted, vos, etc.", recurso: "Deíxis social", ejemplo: "'Usted' indica formalidad y distancia; 'tú' indica confianza y cercanía.", ejercicio: "Escribe 5 oraciones con deixis social.", reto: "Investiga la deixis social en el español." },
            { titulo: "Implicatura", teoria: "La implicatura es lo que el hablante sugiere o implica sin decir explícitamente, y que el oyente infiere gracias al contexto.", recurso: "Implicatura", ejemplo: "'Tengo un examen mañana' puede implicar 'no puedo salir esta noche'.", ejercicio: "Escribe 5 oraciones con implicatura.", reto: "Investiga las implicaturas en la conversación." },
            { titulo: "Presuposición", teoria: "La presuposición es la información que se da por supuesta en un enunciado, sin afirmarse explícitamente.", recurso: "Presuposición", ejemplo: "'El rey de Francia es calvo' presupone que existe un rey de Francia.", ejercicio: "Identifica las presuposiciones en 5 oraciones.", reto: "Investiga las presuposiciones en la publicidad." },
            { titulo: "Actos de habla", teoria: "Los actos de habla son las acciones que realizamos al hablar: afirmar, preguntar, prometer, ordenar, etc.", recurso: "Actos de habla", ejemplo: "'Te prometo que vendré' es un acto de habla promisorio.", ejercicio: "Clasifica 5 oraciones según su acto de habla.", reto: "Investiga la teoría de los actos de habla." },
            { titulo: "Acto locutivo", teoria: "El acto locutivo es el acto de decir algo, el enunciado en sí mismo, con su significado literal.", recurso: "Acto locutivo", ejemplo: "'La puerta está abierta' es un acto locutivo.", ejercicio: "Escribe 5 actos locutivos.", reto: "Investiga la diferencia entre actos locutivos e ilocutivos." },
            { titulo: "Acto ilocutivo", teoria: "El acto ilocutivo es la intención del hablante al decir algo: afirmar, preguntar, prometer, ordenar, etc.", recurso: "Acto ilocutivo", ejemplo: "'La puerta está abierta' puede ser una afirmación o una sugerencia.", ejercicio: "Identifica el acto ilocutivo en 5 oraciones.", reto: "Investiga los actos ilocutivos." },
            { titulo: "Acto perlocutivo", teoria: "El acto perlocutivo es el efecto que el enunciado produce en el oyente: convencer, persuadir, asustar, etc.", recurso: "Acto perlocutivo", ejemplo: "'La puerta está abierta' puede hacer que el oyente la cierre.", ejercicio: "Analiza el efecto perlocutivo en 5 oraciones.", reto: "Investiga los actos perlocutivos." },
            { titulo: "Máximas conversacionales (Grice)", teoria: "Las máximas conversacionales son principios que guían la conversación: cantidad, calidad, relación, manera.", recurso: "Máximas conversacionales", ejemplo: "Máxima de cantidad: di todo lo necesario, pero no más.", ejercicio: "Analiza el cumplimiento de las máximas en un diálogo.", reto: "Investiga las máximas de Grice." },
            { titulo: "Máxima de cantidad", teoria: "La máxima de cantidad exige que el hablante proporcione la cantidad de información necesaria, ni más ni menos.", recurso: "Máxima de cantidad", ejemplo: "Si preguntan '¿Qué hora es?', no se debe responder con la historia del reloj.", ejercicio: "Escribe un diálogo que cumpla con la máxima de cantidad.", reto: "Investiga la máxima de cantidad." },
            { titulo: "Máxima de calidad", teoria: "La máxima de calidad exige que el hablante diga la verdad, que no afirme lo que cree falso o no tiene pruebas.", recurso: "Máxima de calidad", ejemplo: "No se debe afirmar algo sin pruebas.", ejercicio: "Escribe un diálogo que cumpla con la máxima de calidad.", reto: "Investiga la máxima de calidad." },
            { titulo: "Máxima de relación", teoria: "La máxima de relación exige que el hablante sea relevante, que sus aportaciones estén relacionadas con el tema.", recurso: "Máxima de relación", ejemplo: "En una conversación sobre el tiempo, no se debe hablar de política.", ejercicio: "Escribe un diálogo que cumpla con la máxima de relación.", reto: "Investiga la máxima de relación." },
            { titulo: "Máxima de manera", teoria: "La máxima de manera exige que el hablante sea claro, ordenado, breve y evite la ambigüedad.", recurso: "Máxima de manera", ejemplo: "Se debe evitar la ambigüedad y la oscuridad.", ejercicio: "Escribe un diálogo que cumpla con la máxima de manera.", reto: "Investiga la máxima de manera." },
            { titulo: "Inferencia pragmática", teoria: "La inferencia pragmática es el proceso por el cual el oyente deduce el significado implícito a partir del contexto.", recurso: "Inferencia pragmática", ejemplo: "'Hace frío aquí' puede inferir 'cierra la ventana'.", ejercicio: "Identifica las inferencias en 5 diálogos.", reto: "Investiga la inferencia pragmática." },
            { titulo: "Contexto situacional", teoria: "El contexto situacional incluye el lugar, el momento, los participantes y la relación entre ellos, que influyen en el significado.", recurso: "Contexto situacional", ejemplo: "Un '¡Qué calor!' en la calle en verano es diferente a decirlo en una sauna.", ejercicio: "Analiza el contexto situacional de 5 enunciados.", reto: "Investiga el contexto situacional en la comunicación." },
            { titulo: "Contexto cultural", teoria: "El contexto cultural incluye las creencias, valores, normas y costumbres que influyen en la interpretación del significado.", recurso: "Contexto cultural", ejemplo: "El concepto de 'honor' tiene diferentes significados según la cultura.", ejercicio: "Analiza el contexto cultural de 5 expresiones.", reto: "Investiga el contexto cultural en la comunicación intercultural." },
            { titulo: "Contexto lingüístico", teoria: "El contexto lingüístico es el entorno textual inmediato que rodea a una palabra o expresión.", recurso: "Contexto lingüístico", ejemplo: "'El banco' puede referirse a una entidad financiera o a un asiento, según el contexto lingüístico.", ejercicio: "Analiza el contexto lingüístico de 5 palabras.", reto: "Investiga el contexto lingüístico en la desambiguación." }
        ]
    },
    estilo: {
        nombre: "Estilo", color: "rojo", icono: "bi-robot",
        especialidad: "Retórica, figuras semánticas, ironía, hipérbole, eufemismo",
        tecnicas: [
            { titulo: "Retórica", teoria: "La retórica es el arte de usar el lenguaje para persuadir, conmover o agradar. Incluye el estudio de las figuras retóricas.", recurso: "Retórica", ejemplo: "El discurso político usa la retórica para persuadir.", ejercicio: "Analiza el uso de la retórica en un discurso.", reto: "Investiga la retórica en la publicidad." },
            { titulo: "Ironía", teoria: "La ironía es decir lo contrario de lo que se quiere expresar, con un tono burlesco o sarcástico, para dar a entender lo opuesto.", recurso: "Ironía", ejemplo: "'Claro, confía en él, seguro que no te falla' (significa lo contrario).", ejercicio: "Escribe 3 oraciones con ironía.", reto: "Investiga la ironía en la literatura." },
            { titulo: "Sarcasmo", teoria: "El sarcasmo es una ironía más agresiva, con intención de herir o burlarse de alguien.", recurso: "Sarcasmo", ejemplo: "'Muy inteligente eres' (cuando alguien hace una tontería).", ejercicio: "Escribe 3 oraciones con sarcasmo.", reto: "Investiga el sarcasmo en el lenguaje coloquial." },
            { titulo: "Hipérbole", teoria: "La hipérbole es una exageración intencionada para enfatizar una idea y darle mayor expresividad.", recurso: "Hipérbole", ejemplo: "'Tengo un hambre que me comería un mundo'.", ejercicio: "Escribe 3 hipérboles.", reto: "Investiga la hipérbole en la poesía." },
            { titulo: "Eufemismo", teoria: "El eufemismo es la sustitución de una palabra o expresión considerada tabú o desagradable por otra más suave o neutra.", recurso: "Eufemismo", ejemplo: "'Fallecer' en lugar de 'morir'.", ejercicio: "Escribe 3 eufemismos.", reto: "Investiga los eufemismos en el lenguaje político." },
            { titulo: "Disfemismo", teoria: "El disfemismo es la sustitución de una palabra neutra por otra más despectiva o vulgar, con intención de ofender o degradar.", recurso: "Disfemismo", ejemplo: "'Cascarla' en lugar de 'morir'.", ejercicio: "Escribe 3 disfemismos.", reto: "Investiga los disfemismos en el lenguaje coloquial." },
            { titulo: "Metáfora literaria", teoria: "La metáfora es una figura retórica que identifica un término real con uno imaginario, creando una imagen sugerente.", recurso: "Metáfora literaria", ejemplo: "'Tus ojos son dos estrellas'.", ejercicio: "Escribe 3 metáforas literarias.", reto: "Investiga la metáfora en la poesía." },
            { titulo: "Símil", teoria: "El símil es una comparación explícita que usa 'como' o 'cual' para establecer una relación de semejanza.", recurso: "Símil", ejemplo: "'Corre como un guepardo'.", ejercicio: "Escribe 3 símiles.", reto: "Investiga el símil en la literatura." },
            { titulo: "Personificación", teoria: "La personificación (o prosopopeya) atribuye cualidades humanas a objetos inanimados o animales.", recurso: "Personificación", ejemplo: "'El viento susurraba secretos'.", ejercicio: "Escribe 3 personificaciones.", reto: "Investiga la personificación en la poesía." },
            { titulo: "Antítesis", teoria: "La antítesis contrapone dos ideas opuestas en una misma expresión, creando un efecto de contraste.", recurso: "Antítesis", ejemplo: "'El amor y el odio', 'La luz y la oscuridad'.", ejercicio: "Escribe 3 antítesis.", reto: "Investiga la antítesis en la literatura." },
            { titulo: "Oxímoron", teoria: "El oxímoron es una antítesis que une dos términos contradictorios en una misma expresión.", recurso: "Oxímoron", ejemplo: "'Un silencio atronador', 'Una luz oscura'.", ejercicio: "Escribe 3 oxímorones.", reto: "Investiga el oxímoron en la poesía." },
            { titulo: "Paradoja", teoria: "La paradoja es una afirmación que parece contradictoria pero encierra una verdad profunda.", recurso: "Paradoja", ejemplo: "'Solo sé que no sé nada' (Sócrates).", ejercicio: "Escribe 3 paradojas.", reto: "Investiga la paradoja en la filosofía." },
            { titulo: "Anáfora retórica", teoria: "La anáfora es la repetición de una palabra o grupo de palabras al inicio de varias oraciones o versos.", recurso: "Anáfora retórica", ejemplo: "'Lucha por tus sueños. Lucha por tu gente. Lucha por ti'.", ejercicio: "Escribe 3 anáforas.", reto: "Investiga la anáfora en la oratoria." },
            { titulo: "Epífora", teoria: "La epífora es la repetición de una palabra o grupo de palabras al final de varias oraciones o versos.", recurso: "Epífora", ejemplo: "'Los sueños se construyen, los sueños se siembran, los sueños se cosechan'.", ejercicio: "Escribe 3 epíforas.", reto: "Investiga la epífora en la literatura." },
            { titulo: "Paralelismo", teoria: "El paralelismo es la repetición de la misma estructura sintáctica en varias oraciones o versos.", recurso: "Paralelismo", ejemplo: "'Vine, vi, vencí'.", ejercicio: "Escribe 3 paralelismos.", reto: "Investiga el paralelismo en la poesía." },
            { titulo: "Interrogación retórica", teoria: "La interrogación retórica es una pregunta que no espera respuesta, sino que provoca reflexión o enfatiza una idea.", recurso: "Interrogación retórica", ejemplo: "'¿Acaso no merecemos un futuro mejor?'", ejercicio: "Escribe 3 interrogaciones retóricas.", reto: "Investiga la interrogación retórica en la oratoria." },
            { titulo: "Exclamación retórica", teoria: "La exclamación retórica expresa una emoción intensa (alegría, sorpresa, indignación) sin esperar respuesta.", recurso: "Exclamación retórica", ejemplo: "'¡Qué bonito es el amor!'", ejercicio: "Escribe 3 exclamaciones retóricas.", reto: "Investiga la exclamación retórica en la literatura." },
            { titulo: "Apóstrofe", teoria: "El apóstrofe es una figura retórica que consiste en dirigir la palabra a una persona ausente, a un objeto inanimado o a una idea abstracta.", recurso: "Apóstrofe", ejemplo: "'¡Oh, muerte, ven a buscarme!'", ejercicio: "Escribe 3 apóstrofes.", reto: "Investiga el apóstrofe en la poesía." },
            { titulo: "Prosopopeya", teoria: "La prosopopeya (o personificación) atribuye cualidades humanas a objetos inanimados o animales. Es similar a la personificación.", recurso: "Prosopopeya", ejemplo: "'La luna me sonreía'.", ejercicio: "Escribe 3 prosopopeyas.", reto: "Investiga la prosopopeya en la literatura." },
            { titulo: "Aliteración", teoria: "La aliteración es la repetición de sonidos consonánticos para crear un efecto musical o expresivo.", recurso: "Aliteración", ejemplo: "'El susurro del silencio'.", ejercicio: "Escribe 3 aliteraciones.", reto: "Investiga la aliteración en la poesía." }
        ]
    }
};

// ============================================================
// GENERAR LISTA COMPLETA DE TÉCNICAS
// ============================================================
let TECNICAS = [];
let idCounter = 0;
for (const [key, amazona] of Object.entries(AMAZONAS_DATA)) {
    const tecnicas = amazona.tecnicas.map((t, idx) => ({
        id: ++idCounter,
        amazonaKey: key,
        amazonaNombre: amazona.nombre,
        color: amazona.color,
        ...t,
        numero: idx + 1
    }));
    TECNICAS.push(...tecnicas);
}

// ============================================================
// LÓGICA DE LA APP
// ============================================================

document.querySelectorAll('.sidebar-stellar .nav-link').forEach(link => {
    link.addEventListener('click', function(e) {
        e.preventDefault();
        const section = this.dataset.section;
        document.querySelectorAll('.sidebar-stellar .nav-link').forEach(l => l.classList.remove('active'));
        this.classList.add('active');
        document.querySelectorAll('.section-content').forEach(el => el.style.display = 'none');
        const target = document.getElementById('section-' + section);
        if (target) target.style.display = 'block';
        if (['significado','relaciones','cambio','contexto','estilo'].includes(section)) {
            renderAmazona(section);
        }
        if (section === 'dashboard') actualizarDashboard();
        if (section === 'seguimiento') renderSeguimiento();
    });
});

function leerTexto(texto, boton) {
    if (!window.speechSynthesis) { alert('Tu navegador no soporta síntesis de voz.'); return; }
    if (window.speechSynthesis.speaking) {
        window.speechSynthesis.cancel();
        if (boton) { boton.innerHTML = '<i class="bi bi-play-circle"></i> Escuchar'; boton.classList.remove('escuchando'); }
        return;
    }
    const utterance = new SpeechSynthesisUtterance(texto);
    utterance.lang = 'es-ES';
    utterance.rate = 0.9;
    utterance.pitch = 1;
    if (boton) {
        boton.innerHTML = '<i class="bi bi-stop-circle"></i> Detener';
        boton.classList.add('escuchando');
        utterance.onend = function() { boton.innerHTML = '<i class="bi bi-play-circle"></i> Escuchar'; boton.classList.remove('escuchando'); };
        utterance.onerror = function() { boton.innerHTML = '<i class="bi bi-play-circle"></i> Escuchar'; boton.classList.remove('escuchando'); };
    }
    window.speechSynthesis.speak(utterance);
}

function renderAmazona(amazonaKey) {
    const container = document.getElementById('section-' + amazonaKey);
    if (!container) return;
    const data = AMAZONAS_DATA[amazonaKey];
    const colorHex = data.color === 'dorado' ? 'var(--neon-dorado)' :
                     data.color === 'azul' ? 'var(--neon-azul)' :
                     data.color === 'verde' ? 'var(--neon-verde)' :
                     data.color === 'purpura' ? 'var(--neon-purpura)' : 'var(--neon-rojo)';

    let html = `
        <div class="personaje-destacado" style="border-left:4px solid ${colorHex};">
            <div class="avatar">🤖</div>
            <div class="info">
                <h4 style="color:${colorHex};">${data.nombre} · ${data.especialidad}</h4>
                <p style="color:var(--texto-muted);">${data.tecnicas.length} técnicas interactivas. Haz clic para desplegar contenido.</p>
            </div>
        </div>
        <div id="tecnicas-${amazonaKey}">
    `;

    const tecnicas = TECNICAS.filter(t => t.amazonaKey === amazonaKey);
    const seguimiento = getSeguimiento();

    tecnicas.forEach((t) => {
        const completada = seguimiento[t.id] || false;
        const teoriaCompleta = `Técnica ${t.numero}: ${t.titulo}. ${t.teoria}`;
        const flashPregunta = t.titulo;
        const flashRespuesta = t.teoria;
        html += `
            <div class="tecnica-card" style="border-left-color: ${colorHex};">
                <div class="cabecera" onclick="toggleTecnicaCard(${t.id})">
                    <span class="num">#${t.id}</span>
                    <span class="titulo">${t.numero}. ${t.titulo}</span>
                    <span class="badge-personaje" style="background:${completada ? 'rgba(0,255,0,0.15)' : 'rgba(255,255,255,0.05)'}; color:${completada ? 'var(--neon-verde)' : '#fff'};">${completada ? '✅ Completada' : '⬜ Pendiente'}</span>
                </div>
                <div class="contenido" id="contenido-${t.id}">
                    <div class="teoria">
                        <strong>📖 Teoría:</strong> ${t.teoria}
                        <button class="btn-audio ms-2" onclick="event.stopPropagation(); leerTexto('${teoriaCompleta.replace(/'/g, "\\'")}', this);">
                            <i class="bi bi-play-circle"></i> Escuchar
                        </button>
                    </div>
                    <div class="recurso-clave">
                        <span>${t.recurso}</span>
                    </div>
                    <div class="ejemplo">
                        <strong>💡 Ejemplo del autor:</strong> ${t.ejemplo}
                    </div>
                    <div class="ejercicio">
                        <strong>✍️ Ejercicio:</strong> ${t.ejercicio}
                        <textarea placeholder="Escribe tu respuesta aquí..." rows="2"></textarea>
                        <button class="btn-neon-lleno mt-1" onclick="marcarEjercicio(${t.id})"><i class="bi bi-check-circle"></i> Marcar como completado</button>
                    </div>
                    <div class="reto"><i class="bi bi-trophy"></i> <strong>🏆 Reto:</strong> ${t.reto}</div>
                    <div class="flashcard-area" onclick="event.stopPropagation(); toggleFlashcard(${t.id})" id="flash-${t.id}">
                        <div class="flash-front" id="flash-front-${t.id}">${flashPregunta}</div>
                        <div class="flash-back" id="flash-back-${t.id}" style="display:none;">${flashRespuesta}</div>
                        <div class="flash-indicador">👆 Haz clic para ver la respuesta</div>
                    </div>
                </div>
            </div>
        `;
    });

    html += `</div>`;
    container.innerHTML = html;
}

function toggleTecnicaCard(id) {
    const content = document.getElementById('contenido-' + id);
    if (content) {
        content.style.display = content.style.display === 'block' ? 'none' : 'block';
    }
}

function toggleFlashcard(id) {
    const front = document.getElementById('flash-front-' + id);
    const back = document.getElementById('flash-back-' + id);
    const indicador = document.querySelector(`#flash-${id} .flash-indicador`);
    if (!front || !back) return;
    if (front.style.display !== 'none') {
        front.style.display = 'none';
        back.style.display = 'block';
        if (indicador) indicador.textContent = '👆 Haz clic para volver';
    } else {
        front.style.display = 'block';
        back.style.display = 'none';
        if (indicador) indicador.textContent = '👆 Haz clic para ver la respuesta';
    }
}

function marcarEjercicio(id) {
    const seguimiento = getSeguimiento();
    seguimiento[id] = true;
    setSeguimiento(seguimiento);
    const card = document.querySelector(`.tecnica-card .cabecera[onclick*="${id}"]`)?.closest('.tecnica-card');
    if (card) {
        const badge = card.querySelector('.badge-personaje');
        if (badge) {
            badge.textContent = '✅ Completada';
            badge.style.background = 'rgba(0,255,0,0.15)';
            badge.style.color = 'var(--neon-verde)';
        }
        const btn = card.querySelector('.ejercicio button');
        if (btn) {
            btn.textContent = '✅ ¡Completado!';
            btn.disabled = true;
            btn.style.opacity = '0.6';
        }
    }
    actualizarProgreso();
    actualizarDashboard();
}

// ============================================================
// SEGUIMIENTO
// ============================================================
const SEGUIMIENTO_KEY = 'flota_semantica_seguimiento_v2';

function getSeguimiento() {
    const raw = localStorage.getItem(SEGUIMIENTO_KEY);
    if (raw) {
        try { return JSON.parse(raw); } catch(e) {}
    }
    return {};
}

function setSeguimiento(data) {
    localStorage.setItem(SEGUIMIENTO_KEY, JSON.stringify(data));
}

function renderSeguimiento() {
    const seguimiento = getSeguimiento();
    const tbody = document.getElementById('tabla-seguimiento-body');
    if (!tbody) return;
    let html = '';
    TECNICAS.forEach(t => {
        const checked = seguimiento[t.id] ? 'checked' : '';
        const colorHex = t.color === 'dorado' ? 'var(--neon-dorado)' :
                         t.color === 'azul' ? 'var(--neon-azul)' :
                         t.color === 'verde' ? 'var(--neon-verde)' :
                         t.color === 'purpura' ? 'var(--neon-purpura)' : 'var(--neon-rojo)';
        html += `
            <tr>
                <td>${t.id}</td>
                <td>${t.titulo}</td>
                <td><span style="background:${colorHex}; color:#0a0e17; padding:0.05rem 0.5rem; border-radius:30px; font-size:0.6rem; font-weight:600;">${t.amazonaNombre}</span></td>
                <td class="text-center"><input class="form-check-input" type="checkbox" ${checked} onchange="toggleTecnicaCheck(${t.id})"></td>
            </tr>
        `;
    });
    tbody.innerHTML = html;
    actualizarProgreso();
}

function toggleTecnicaCheck(id) {
    const seguimiento = getSeguimiento();
    seguimiento[id] = !seguimiento[id];
    setSeguimiento(seguimiento);
    actualizarProgreso();
    actualizarDashboard();
    const card = document.querySelector(`.tecnica-card .cabecera[onclick*="${id}"]`)?.closest('.tecnica-card');
    if (card) {
        const badge = card.querySelector('.badge-personaje');
        if (badge) {
            const completada = seguimiento[id];
            badge.textContent = completada ? '✅ Completada' : '⬜ Pendiente';
            badge.style.background = completada ? 'rgba(0,255,0,0.15)' : 'rgba(255,255,255,0.05)';
            badge.style.color = completada ? 'var(--neon-verde)' : '#fff';
        }
    }
}

function actualizarProgreso() {
    const seguimiento = getSeguimiento();
    const total = TECNICAS.length;
    let completadas = 0;
    TECNICAS.forEach(t => {
        if (seguimiento[t.id]) completadas++;
    });
    const pct = total > 0 ? Math.round((completadas / total) * 100) : 0;
    document.getElementById('sidebar-porcentaje').textContent = pct + '%';
    document.getElementById('sidebar-barra').style.width = pct + '%';
    document.getElementById('sidebar-detalle').textContent = `${completadas} / ${total} técnicas`;
}

function actualizarDashboard() {
    const seguimiento = getSeguimiento();
    const total = TECNICAS.length;
    let completadas = 0;
    TECNICAS.forEach(t => {
        if (seguimiento[t.id]) completadas++;
    });
    const pct = total > 0 ? Math.round((completadas / total) * 100) : 0;
    document.getElementById('dashboard-completadas').textContent = completadas;
    document.getElementById('dashboard-porcentaje').textContent = pct + '%';
}

// ============================================================
// INICIALIZACIÓN
// ============================================================
document.addEventListener('DOMContentLoaded', function() {
    document.querySelectorAll('.section-content').forEach((el, idx) => {
        el.style.display = idx === 0 ? 'block' : 'none';
    });
    renderSeguimiento();
    actualizarDashboard();
});
</script>
</body>
</html>

