            { titulo: "Especialización", teoria: "La especialización es un cambio semántico en el que una palabra pasa de un significado general a uno más específico.", recurso: "Especialización", ejemplo: "'Carne' antes significaba 'alimento' en general, ahora se refiere a la carne animal.", ejercicio: "Escribe 3 ejemplos de especialización.", reto: "Investiga la especialización de 'carnicero'." },
            { titulo: "Generalización", teoria: "La generalización es un cambio semántico en el que una palabra pasa de un significado específico a uno más general.", recurso: "Generalización", ejemplo: "'Compañero' antes significaba 'el que comparte el pan', ahora se refiere a cualquier persona con la que se comparte algo.", ejercicio: "Escribe 3 ejemplos de generalización.", reto: "Investiga la generalización de 'cosa'." },
            { titulo: "Metáfora", teoria: "La metáfora es un cambio semántico por el que una palabra adquiere un nuevo significado por analogía o comparación con el original.", recurso: "Metáfora", ejemplo: "'Pata' (de animal) → 'pata de la mesa' (por analogía de forma y función).", ejercicio: "Escribe 3 metáforas lexicalizadas.", reto: "Investiga la metáfora en el lenguaje cotidiano." },
            { titulo: "Metonimia", teoria: "La metonimia es un cambio semántico por el que una palabra adquiere un nuevo significado por contigüidad o asociación con el original.", recurso: "Metonimia", ejemplo: "'Corona' (objeto) → 'la Corona' (la monarquía).", ejercicio: "Escribe 3 metonimias lexicalizadas.", reto: "Investiga la metonimia en el lenguaje político." },
            { titulo: "Sinécdoque", teoria: "La sinécdoque es un tipo de metonimia en la que se usa la parte por el todo o el todo por la parte.", recurso: "Sinécdoque", ejemplo: "'Techo' (parte) por 'casa' (todo): 'Compartimos el mismo techo'.", ejercicio: "Escribe 3 sinécdoques.", reto: "Investiga la sinécdoque en la literatura." },
            { titulo: "Etimología", teoria: "La etimología es el estudio del origen y evolución de las palabras. Conocer la etimología ayuda a entender el significado actual.", recurso: "Etimología", ejemplo: "'Trabajo' viene del latín 'tripalium', un instrumento de tortura.", ejercicio: "Investiga la etimología de 5 palabras.", reto: "Escribe un texto sobre la etimología de una palabra." },
            { titulo: "Préstamo léxico", teoria: "El préstamo léxico es la incorporación de palabras de otras lenguas al español. Pueden ser anglicismos, galicismos, italianismos, etc.", recurso: "Préstamo léxico", ejemplo: "'Software' (inglés), 'champú' (francés), 'piano' (italiano).", ejercicio: "Escribe 5 préstamos léxicos.", reto: "Investiga los préstamos del español." },
            { titulo: "Calco semántico", teoria: "El calco semántico es la adopción de un significado de una palabra extranjera para una palabra ya existente en español.", recurso: "Calco semántico", ejemplo: "'Realizar' antes significaba 'hacer real', ahora también significa 'llevar a cabo' por influencia del inglés 'realize'.", ejercicio: "Escribe 3 calcos semánticos.", reto: "Investiga los calcos semánticos del español." },
            { titulo: "Neologismo", teoria: "El neologismo es una palabra nueva creada para nombrar un concepto nuevo o para renovar el léxico.", recurso: "Neologismo", ejemplo: "'Ciberespacio', 'selfi', 'teletrabajo'.", ejercicio: "Escribe 5 neologismos.", reto: "Investiga los neologismos en el español actual." },
            { titulo: "Arcaísmo", teoria: "El arcaísmo es una palabra o expresión que ha caído en desuso, pero que se mantiene en algunos contextos literarios o regionales.", recurso: "Arcaísmo", ejemplo: "'Ansí' (así), 'facer' (hacer), 'guisa' (manera).", ejercicio: "Escribe 5 arcaísmos.", reto: "Investiga los arcaísmos en la literatura." },
