            { titulo: "Cultismo", teoria: "Los cultismos son palabras que han sido tomadas directamente del latín o del griego, sin sufrir la evolución fonética del español.", recurso: "Cultismo", ejemplo: "'Cándido' (del latín 'candidus'), 'débil' (del latín 'debile').", ejercicio: "Escribe 5 cultismos.", reto: "Investiga los cultismos en el español." },
            { titulo: "Doblete etimológico", teoria: "Los dobletes son pares de palabras que provienen de la misma raíz latina pero han evolucionado de forma diferente: una patrimonial y una culta.", recurso: "Doblete etimológico", ejemplo: "'Cátedra' (cultismo) y 'cadera' (patrimonial) vienen de 'cathedra'.", ejercicio: "Escribe 3 dobletes etimológicos.", reto: "Investiga los dobletes en el español." },
            { titulo: "Cambio de significado por contexto", teoria: "El contexto de uso puede cambiar el significado de una palabra, creando nuevos usos y acepciones.", recurso: "Cambio por contexto", ejemplo: "'Navegar' ha pasado del ámbito marítimo al de internet.", ejercicio: "Escribe 3 ejemplos de cambio por contexto.", reto: "Investiga el cambio de 'ratón'." },
            { titulo: "Cambio de significado por tecnología", teoria: "La tecnología crea nuevos significados para palabras antiguas (ej. 'memoria', 'mouse', 'nube').", recurso: "Cambio por tecnología", ejemplo: "'Nube' antes significaba 'masa de vapor de agua'; ahora también significa 'almacenamiento en internet'.", ejercicio: "Escribe 3 ejemplos de cambio por tecnología.", reto: "Investiga el cambio de 'red'." },
