            { titulo: "Pragmática", teoria: "La pragmática estudia el uso del lenguaje en contexto, los significados que no son literales y la intención comunicativa del hablante.", recurso: "Pragmática", ejemplo: "'¿Puedes cerrar la ventana?' no es una pregunta sobre habilidad, sino una petición.", ejercicio: "Analiza el uso pragmático de 3 expresiones.", reto: "Investiga la pragmática en la comunicación cotidiana." },
            { titulo: "Deíxis", teoria: "La deixis es la referencia a elementos del contexto: persona (yo, tú), espacio (aquí, allí), tiempo (ahora, entonces).", recurso: "Deíxis", ejemplo: "'Yo' se refiere al hablante; 'aquí' se refiere al lugar del hablante.", ejercicio: "Identifica la deixis en 5 oraciones.", reto: "Investiga la deixis en diferentes culturas." },
            { titulo: "Deíxis personal", teoria: "La deixis personal se refiere a los participantes en el acto de habla: yo (hablante), tú (oyente), él (tercero).", recurso: "Deíxis personal", ejemplo: "'Yo' es el hablante; 'tú' es el oyente.", ejercicio: "Escribe 5 oraciones con deixis personal.", reto: "Investiga la deixis personal en diferentes lenguas." },
