            { titulo: "Implicatura", teoria: "La implicatura es lo que el hablante sugiere o implica sin decir explícitamente, y que el oyente infiere gracias al contexto.", recurso: "Implicatura", ejemplo: "'Tengo un examen mañana' puede implicar 'no puedo salir esta noche'.", ejercicio: "Escribe 5 oraciones con implicatura.", reto: "Investiga las implicaturas en la conversación." },
            { titulo: "Presuposición", teoria: "La presuposición es la información que se da por supuesta en un enunciado, sin afirmarse explícitamente.", recurso: "Presuposición", ejemplo: "'El rey de Francia es calvo' presupone que existe un rey de Francia.", ejercicio: "Identifica las presuposiciones en 5 oraciones.", reto: "Investiga las presuposiciones en la publicidad." },
            { titulo: "Actos de habla", teoria: "Los actos de habla son las acciones que realizamos al hablar: afirmar, preguntar, prometer, ordenar, etc.", recurso: "Actos de habla", ejemplo: "'Te prometo que vendré' es un acto de habla promisorio.", ejercicio: "Clasifica 5 oraciones según su acto de habla.", reto: "Investiga la teoría de los actos de habla." },
            { titulo: "Acto locutivo", teoria: "El acto locutivo es el acto de decir algo, el enunciado en sí mismo, con su significado literal.", recurso: "Acto locutivo", ejemplo: "'La puerta está abierta' es un acto locutivo.", ejercicio: "Escribe 5 actos locutivos.", reto: "Investiga la diferencia entre actos locutivos e ilocutivos." },
