<script>
    (function() {
        const familiasData = [
            {
                nombre: "A. Pronombres personales, posesivos y demostrativos",
                tecnicas: [
                    {nombre:"Pronombres personales de sujeto (yo, tú, él...)", desc:"Reemplazan al sujeto. En español se suelen omitir.", ej:"'(Yo) estudio español. (Tú) eres mi amigo. (Él) vive en Bogotá.'"},
                    {nombre:"Pronombres de objeto directo (me, te, lo, la...)", desc:"Reemplazan al objeto directo de la oración.", ej:"'Lo vi ayer. La compré hoy. Te llamo mañana.'"},
                    {nombre:"Pronombres de objeto indirecto (me, te, le, nos...)", desc:"Reemplazan al objeto indirecto.", ej:"'Le di el libro. Me regalaron flores. Nos contaron la historia.'"},
                    {nombre:"Pronombres posesivos (mío, tuyo, suyo...)", desc:"Indican posesión y reemplazan al sustantivo.", ej:"'Este libro es mío. Esa casa es tuya. El carro es suyo.'"},
                    {nombre:"Pronombres demostrativos (este, ese, aquel)", desc:"Señalan objetos según la distancia.", ej:"'Este es mi cuaderno. Ese es tu lápiz. Aquel es el salón.'"},
                    {nombre:"Pronombres reflexivos (me, te, se, nos, os, se)", desc:"Indican que la acción recae sobre el mismo sujeto.", ej:"'Me lavo las manos. Él se peina. Nos levantamos temprano.'"},
                    {nombre:"Pronombres indefinidos (alguien, nadie, algo, nada)", desc:"Se refieren a personas o cosas de manera imprecisa.", ej:"'Alguien llamó. Nadie respondió. ¿Quieres algo? No quiero nada.'"},
                    {nombre:"Pronombres interrogativos (¿quién?, ¿qué?, ¿cuál?)", desc:"Sirven para preguntar. Siempre llevan tilde.", ej:"'¿Quién es? ¿Qué quieres? ¿Cuál prefieres?'"},
                    {nombre:"Pronombres relativos (que, quien, cual, cuyo)", desc:"Relacionan una oración subordinada con el antecedente.", ej:"'El libro que leo es interesante. La chica con quien hablé es amable.'"},
                    {nombre:"Diferencia entre pronombre y adjetivo", desc:"El pronombre reemplaza al sustantivo. El adjetivo lo acompaña.", ej:"'Este (pronombre) es mío. Este libro (adjetivo) es mío.'"}
                ]
            },
            {
                nombre: "B. Adverbios y locuciones adverbiales",
                tecnicas: [
                    {nombre:"Adverbios de lugar (aquí, ahí, allí, cerca, lejos)", desc:"Indican dónde ocurre la acción.", ej:"'Ven aquí. La escuela está cerca. Mi casa está lejos.'"},
                    {nombre:"Adverbios de tiempo (ahora, hoy, ayer, mañana, siempre, nunca)", desc:"Indican cuándo ocurre la acción.", ej:"'Ahora estudio. Ayer jugué fútbol. Siempre llego temprano.'"},
                    {nombre:"Adverbios de modo (bien, mal, así, rápido, lentamente)", desc:"Indican cómo ocurre la acción.", ej:"'Habla bien. Corre rápido. Camina lentamente.'"},
                    {nombre:"Adverbios de cantidad (mucho, poco, bastante, demasiado)", desc:"Indican cuánto o en qué medida.", ej:"'Estudia mucho. Come poco. Hace bastante calor.'"},
                    {nombre:"Adverbios de afirmación (sí, también, ciertamente)", desc:"Confirman o afirman algo.", ej:"'Sí, quiero ir. También me gusta. Ciertamente, es verdad.'"},
                    {nombre:"Adverbios de negación (no, nunca, jamás, tampoco)", desc:"Niegan algo.", ej:"'No quiero. Nunca miento. Jamás lo haré. Tampoco voy.'"},
                    {nombre:"Adverbios de duda (quizá, tal vez, acaso, probablemente)", desc:"Expresan incertidumbre.", ej:"'Quizá llueva. Tal vez vaya. Probablemente llegue tarde.'"},
                    {nombre:"Locuciones adverbiales (a ciegas, de repente, sin embargo)", desc:"Grupos de palabras que funcionan como adverbios.", ej:"'Lo hizo a ciegas. De repente, todo cambió. Sin embargo, no se rindió.'"},
                    {nombre:"Adverbios terminados en -mente", desc:"Se forman añadiendo -mente al adjetivo femenino.", ej:"'Rápidamente, fácilmente, lentamente, felizmente.'"},
                    {nombre:"Diferencia entre adverbio y adjetivo", desc:"El adverbio modifica al verbo. El adjetivo modifica al sustantivo.", ej:"'Corre rápido (adverbio). Un coche rápido (adjetivo).'"}
                ]
            },
            {
                nombre: "C. Preposiciones y conjunciones",
                tecnicas: [
                    {nombre:"Preposiciones de lugar (a, en, sobre, bajo, entre)", desc:"Indican ubicación espacial.", ej:"'Voy a la escuela. Está en la mesa. El libro está sobre el escritorio.'"},
                    {nombre:"Preposiciones de tiempo (a, de, desde, hasta, durante)", desc:"Indican ubicación temporal.", ej:"'Llego a las tres. Estudio desde las dos hasta las cinco.'"},
                    {nombre:"Preposiciones de compañía (con) y de modo (sin)", desc:"'Con' indica compañía. 'Sin' indica carencia.", ej:"'Voy con mi amigo. Café sin azúcar.'"},
                    {nombre:"Preposiciones de causa (por) y finalidad (para)", desc:"'Por' indica causa. 'Para' indica finalidad.", ej:"'Gracias por tu ayuda. Estudio para aprender.'"},
                    {nombre:"Contracciones: al (a + el) y del (de + el)", desc:"Son las únicas contracciones del español.", ej:"'Voy al cine. Vengo del colegio.'"},
                    {nombre:"Conjunciones copulativas (y, e, ni)", desc:"Unen palabras u oraciones.", ej:"'Juan y María. Padre e hijo. Ni come ni deja comer.'"},
                    {nombre:"Conjunciones disyuntivas (o, u)", desc:"Presentan alternativas.", ej:"'¿Café o té? Uno u otro.'"},
                    {nombre:"Conjunciones adversativas (pero, sino, sin embargo)", desc:"Expresan oposición.", ej:"'Quiero ir, pero no puedo. No es azul, sino verde.'"},
                    {nombre:"Conjunciones causales (porque, pues, puesto que)", desc:"Expresan causa o razón.", ej:"'No fui porque estaba enfermo. Puesto que insistes, iré.'"},
                    {nombre:"Conjunciones temporales y condicionales (cuando, si, aunque)", desc:"Expresan tiempo, condición o concesión.", ej:"'Cuando llegue, te llamo. Si llueve, no salgo. Aunque llueva, iré.'"}
                ]
            },
            {
                nombre: "D. Conjugación verbal avanzada",
                tecnicas: [
                    {nombre:"Modo indicativo: tiempos simples (presente, pretérito, futuro)", desc:"Expresan hechos reales y objetivos.", ej:"'Estudio (presente), estudié (pretérito), estudiaré (futuro).'"},
                    {nombre:"Modo indicativo: pretérito imperfecto (-aba, -ía)", desc:"Acción pasada no terminada o habitual.", ej:"'Cuando era niño, jugaba en el parque. Siempre leía antes de dormir.'"},
                    {nombre:"Modo indicativo: pretérito perfecto compuesto (he cantado)", desc:"Acción pasada relacionada con el presente.", ej:"'He estudiado mucho esta semana. Hemos viajado a Cartagena.'"},
                    {nombre:"Modo indicativo: pretérito pluscuamperfecto (había cantado)", desc:"Acción pasada anterior a otra acción pasada.", ej:"'Cuando llegué, ya había salido. Había estudiado antes del examen.'"},
                    {nombre:"Modo subjuntivo: presente (cante, coma, viva)", desc:"Expresa duda, deseo, posibilidad.", ej:"'Ojalá llueva. Quiero que vengas. Dudo que venga.'"},
                    {nombre:"Modo subjuntivo: pretérito imperfecto (-ara, -iera)", desc:"Expresa duda o deseo en pasado.", ej:"'Si estudiara más, aprobaría. Ojalá lloviera.'"},
                    {nombre:"Modo imperativo (canta, come, vive)", desc:"Expresa orden, mandato o ruego.", ej:"'Ven aquí. Come la sopa. Haced la tarea.'"},
                    {nombre:"Verbos irregulares comunes (tener, venir, decir, hacer, poner)", desc:"Cambian la raíz o las desinencias.", ej:"'Tengo, vengo, digo, hago, pongo (presente). Tuve, vine, dije, hice, puse (pretérito).'"},
                    {nombre:"Perífrasis verbales (ir a + infinitivo, estar + gerundio)", desc:"Combinaciones de verbos que funcionan como uno solo.", ej:"'Voy a estudiar. Estoy comiendo. Tengo que salir.'"},
                    {nombre:"Voz pasiva (ser + participio)", desc:"El sujeto recibe la acción en lugar de realizarla.", ej:"'El libro fue escrito por García Márquez. La carta fue enviada ayer.'"}
                ]
            },
            {
                nombre: "E. Oraciones compuestas: coordinación",
                tecnicas: [
                    {nombre:"Oración simple vs. oración compuesta", desc:"Simple (un verbo). Compuesta (dos o más verbos).", ej:"'Simple: Juan estudia. Compuesta: Juan estudia y María lee.'"},
                    {nombre:"Oraciones coordinadas copulativas (y, e, ni)", desc:"Unen oraciones sumando información.", ej:"'Juan estudia y María lee. Ni come ni deja comer.'"},
                    {nombre:"Oraciones coordinadas disyuntivas (o, u)", desc:"Presentan alternativas entre oraciones.", ej:"'¿Estudias o trabajas? Llámame u escríbeme.'"},
                    {nombre:"Oraciones coordinadas adversativas (pero, sino, mas)", desc:"Expresan oposición entre oraciones.", ej:"'Estudié mucho, pero no aprobé. No es alto, sino bajo.'"},
                    {nombre:"Oraciones coordinadas explicativas (es decir, o sea)", desc:"Una oración explica a la otra.", ej:"'Es políglota, es decir, habla varios idiomas.'"},
                    {nombre:"Oraciones coordinadas distributivas (bien... bien, ya... ya)", desc:"Presentan acciones alternativas.", ej:"'Bien ríe, bien llora. Ya estudia, ya descansa.'"},
                    {nombre:"Yuxtaposición (oraciones unidas sin nexo)", desc:"Oraciones separadas por comas, punto y coma o dos puntos.", ej:"'Llegó, vio, venció. Unos cantaban; otros bailaban.'"},
                    {nombre:"Coma en oraciones coordinadas", desc:"Se usa coma antes de 'pero', 'aunque', 'sin embargo'.", ej:"'Estudié mucho, pero no aprobé. Fui a la fiesta, aunque no quería.'"},
                    {nombre:"Punto y coma en oraciones coordinadas", desc:"Separa oraciones relacionadas sin usar conjunciones.", ej:"'Unos estudiaban; otros jugaban; todos aprendían.'"},
                    {nombre:"Dos puntos en oraciones coordinadas", desc:"Introducen una explicación o consecuencia.", ej:"'Llueve: nos quedaremos en casa. Lo supe: había terminado.'"}
                ]
            },
            {
                nombre: "F. Oraciones compuestas: subordinación",
                tecnicas: [
                    {nombre:"Oración subordinada sustantiva (que, si)", desc:"Funciona como sujeto, objeto directo, etc.", ej:"'Quiero que vengas. Dijo que vendría. No sé si lloverá.'"},
                    {nombre:"Oración subordinada adjetiva o de relativo (que, quien, cual)", desc:"Modifica a un sustantivo.", ej:"'El libro que leo es bueno. La chica con quien hablé es mi prima.'"},
                    {nombre:"Oración subordinada adverbial de tiempo (cuando, mientras)", desc:"Indica cuándo ocurre la acción.", ej:"'Cuando llegue, te aviso. Mientras estudias, yo cocino.'"},
                    {nombre:"Oración subordinada adverbial de lugar (donde)", desc:"Indica dónde ocurre la acción.", ej:"'Lo encontrarás donde lo dejaste. Vivo donde nací.'"},
                    {nombre:"Oración subordinada adverbial de modo (como)", desc:"Indica cómo ocurre la acción.", ej:"'Hazlo como te dije. Baila como su madre.'"},
                    {nombre:"Oración subordinada adverbial de causa (porque, ya que)", desc:"Indica por qué ocurre la acción.", ej:"'No fui porque estaba enfermo. Ya que insistes, iré.'"},
                    {nombre:"Oración subordinada adverbial de consecuencia (tanto que, tan que)", desc:"Indica la consecuencia de la acción.", ej:"'Gritó tanto que se quedó afónico. Es tan alto que no cabe.'"},
                    {nombre:"Oración subordinada adverbial de condición (si)", desc:"Indica una condición para que ocurra la acción.", ej:"'Si estudias, aprobarás. Si llueve, no saldré.'"},
                    {nombre:"Oración subordinada adverbial de finalidad (para que)", desc:"Indica la finalidad de la acción.", ej:"'Estudio para que mis padres se sientan orgullosos.'"},
                    {nombre:"Oración subordinada adverbial concesiva (aunque)", desc:"Indica una objeción que no impide la acción.", ej:"'Aunque llueva, saldré. Aunque estaba cansado, siguió.'"}
                ]
            },
            {
                nombre: "G. Ortografía: homófonos y parónimos",
                tecnicas: [
                    {nombre:"Por qué (pregunta) / porque (respuesta) / porqué (sustantivo) / por que (preposición + relativo)", desc:"Cuatro formas diferentes.", ej:"'¿Por qué vienes? Porque te quiero. El porqué. La razón por que vine.'"},
                    {nombre:"Con qué (pregunta) / conque (consecuencia) / con que (preposición + relativo)", desc:"Tres formas diferentes.", ej:"'¿Con qué lo harás? Conque te vas... El arma con que luchó.'"},
                    {nombre:"Sino (adversativo) / si no (condicional)", desc:"'Sino' corrige. 'Si no' es condición negativa.", ej:"'No es azul, sino verde. Si no vienes, me enfado.'"},
                    {nombre:"También (adición) / tan bien (cantidad + modo)", desc:"'También' suma. 'Tan bien' compara.", ej:"'También quiero ir. Cocinas tan bien como tu madre.'"},
                    {nombre:"Tampoco (negación) / tan poco (cantidad)", desc:"'Tampoco' niega. 'Tan poco' indica cantidad.", ej:"'Tampoco quiero ir. Come tan poco que preocupa.'"},
                    {nombre:"Asimismo (también) / así mismo (de ese modo) / a sí mismo (reflexivo)", desc:"Tres formas diferentes.", ej:"'Asimismo, lo haré. Lo haré así mismo. Se habló a sí mismo.'"},
                    {nombre:"Hecho (hacer) / echo (echar)", desc:"'Hecho' con h. 'Echo' sin h.", ej:"'He hecho la tarea. Echo agua al vaso.'"},
                    {nombre:"Hasta (preposición) / asta (cuerno, palo)", desc:"'Hasta' con h. 'Asta' sin h.", ej:"'Hasta mañana. El asta de la bandera.'"},
                    {nombre:"Habría (haber) / abría (abrir)", desc:"'Habría' con h. 'Abría' sin h.", ej:"'Habría que estudiarlo. Él abría la puerta.'"},
                    {nombre:"Cocer (hervir) / coser (aguja)", desc:"'Cocer' con c. 'Coser' con s.", ej:"'Cocer verduras. Coser un vestido.'"}
                ]
            },
            {
                nombre: "H. Prefijos, sufijos y formación de palabras",
                tecnicas: [
                    {nombre:"Prefijos de negación (in-, des-, a-, anti-)", desc:"Niegan el significado de la palabra base.", ej:"'Inútil, deshacer, amorfo, antivirus.'"},
                    {nombre:"Prefijos de lugar (sub-, sobre-, inter-, trans-)", desc:"Indican posición o movimiento.", ej:"'Submarino, sobrevolar, internacional, transatlántico.'"},
                    {nombre:"Prefijos de tiempo (pre-, post-, ante-)", desc:"Indican temporalidad.", ej:"'Prehistoria, posmoderno, anteayer.'"},
                    {nombre:"Prefijos de cantidad (mono-, bi-, tri-, multi-)", desc:"Indican número o cantidad.", ej:"'Monolingüe, bilingüe, trilingüe, multicolor.'"},
                    {nombre:"Sufijos de profesión (-dor, -ista, -ero, -nte)", desc:"Forman sustantivos de oficio.", ej:"'Trabajador, periodista, cartero, estudiante.'"},
                    {nombre:"Sufijos de cualidad (-dad, -eza, -ura, -ía)", desc:"Forman sustantivos abstractos.", ej:"'Bondad, tristeza, hermosura, alegría.'"},
                    {nombre:"Sufijos de acción (-ción, -sión, -miento)", desc:"Forman sustantivos a partir de verbos.", ej:"'Educación, decisión, conocimiento.'"},
                    {nombre:"Sufijos aumentativos (-ón, -azo, -ote)", desc:"Expresan tamaño grande.", ej:"'Golazo, caserón, grandote.'"},
                    {nombre:"Sufijos diminutivos (-ito, -illo, -ico)", desc:"Expresan tamaño pequeño o afecto.", ej:"'Casita, panecillo, cafecico (Colombia).'"},
                    {nombre:"Sufijos despectivos (-ucho, -ajo, -ejo)", desc:"Expresan desprecio o ironía.", ej:"'Papelucho, casucha, librejo.'"}
                ]
            },
            {
                nombre: "I. Sinónimos, antónimos y campos semánticos",
                tecnicas: [
                    {nombre:"Sinónimos totales (significado idéntico)", desc:"Palabras que significan exactamente lo mismo.", ej:"'Comenzar / empezar. Acabar / terminar. Andar / caminar.'"},
                    {nombre:"Sinónimos parciales (significado similar)", desc:"Palabras que solo coinciden en algunos contextos.", ej:"'Mirar / observar. Decir / afirmar. Contento / feliz.'"},
                    {nombre:"Antónimos graduales (con grados intermedios)", desc:"Entre los opuestos hay términos medios.", ej:"'Frío / templado / caliente. Alto / mediano / bajo.'"},
                    {nombre:"Antónimos complementarios (se excluyen mutuamente)", desc:"No hay término medio.", ej:"'Vivo / muerto. Verdadero / falso. Presente / ausente.'"},
                    {nombre:"Antónimos recíprocos (misma relación desde otro ángulo)", desc:"Implican la misma relación.", ej:"'Comprar / vender. Dar / recibir. Enseñar / aprender.'"},
                    {nombre:"Campo semántico (palabras de un mismo tema)", desc:"Conjunto de palabras relacionadas por su significado.", ej:"'Fútbol: balón, gol, árbitro, portería, penalti.'"},
                    {nombre:"Familia léxica (palabras con la misma raíz)", desc:"Comparten la misma raíz o lexema.", ej:"'Pan: panadero, panadería, panecillo, panificar.'"},
                    {nombre:"Hiperónimos e hipónimos (general y específico)", desc:"Hiperónimo (general). Hipónimo (específico).", ej:"'Flor (hiperónimo). Rosa, clavel, margarita (hipónimos).'"},
                    {nombre:"Polisemia (una palabra, varios significados)", desc:"Una misma palabra con varios significados relacionados.", ej:"'Cabeza: parte del cuerpo, líder, parte superior de algo.'"},
                    {nombre:"Homonimia (palabras iguales con significados diferentes)", desc:"Coinciden en forma pero no en significado.", ej:"'Banco: asiento, entidad financiera. Vino: bebida, verbo venir.'"}
                ]
            },
            {
                nombre: "J. Producción textual: narración y descripción",
                tecnicas: [
                    {nombre:"El texto narrativo (estructura: inicio, nudo, desenlace)", desc:"Cuenta hechos reales o imaginarios.", ej:"'Inicio: Había una vez... Nudo: De repente... Desenlace: Finalmente...'"},
                    {nombre:"Elementos de la narración (narrador, personajes, tiempo, espacio)", desc:"Componentes básicos de todo texto narrativo.", ej:"'Narrador: quien cuenta. Personajes: quienes actúan. Tiempo: cuándo. Espacio: dónde.'"},
                    {nombre:"Tipos de narrador (primera persona, tercera persona)", desc:"Protagonista (yo), testigo (él/ella), omnisciente (todo lo sabe).", ej:"'Yo caminaba (1ª). Él caminaba (3ª). El narrador lo sabía todo (omnisciente).'"},
                    {nombre:"El texto descriptivo (rasgos, características)", desc:"Describe personas, lugares, objetos o sentimientos.", ej:"'Era una casa grande, de madera oscura, con ventanas pequeñas.'"},
                    {nombre:"Tipos de descripción (prosopografía, etopeya, topografía)", desc:"Prosopografía (física). Etopeya (carácter). Topografía (lugar).", ej:"'Era alto y delgado (prosopografía). Era generoso (etopeya). Un valle verde (topografía).'"},
                    {nombre:"Conectores de orden narrativo (primero, luego, después, finalmente)", desc:"Organizan la secuencia de los hechos.", ej:"'Primero, desperté. Luego, desayuné. Después, fui al colegio. Finalmente, volví a casa.'"},
                    {nombre:"Conectores de contraste (pero, sin embargo, en cambio)", desc:"Introducen oposición entre ideas.", ej:"'Estudié mucho, pero no aprobé. Sin embargo, no me rindo.'"},
                    {nombre:"Conectores de causa-efecto (porque, por lo tanto, en consecuencia)", desc:"Relacionan causa y efecto.", ej:"'No estudié, por lo tanto, perdí el examen. En consecuencia, debo recuperar.'"},
                    {nombre:"La descripción subjetiva vs. objetiva", desc:"Subjetiva (opinión). Objetiva (datos comprobables).", ej:"'Subjetiva: Es un paisaje hermoso. Objetiva: El paisaje tiene montañas y un río.'"},
                    {nombre:"Coherencia y cohesión textual", desc:"Coherencia (sentido global). Cohesión (conexión entre oraciones).", ej:"'Usar conectores, sinónimos y pronombres para que el texto fluya bien.'"}
                ]
            }
        ];

        const todasLasTecnicas = [];
        familiasData.forEach(fam => {
            fam.tecnicas.forEach(t => {
                todasLasTecnicas.push({...t, familia: fam.nombre});
            });
        });

        // Fecha
        document.getElementById('fechaHoy').textContent = new Date().toLocaleDateString('es-CO',{year:'numeric',month:'long',day:'numeric'});

        // Acordeón
        const acordeonDiv = document.getElementById('acordeonFamilias');
        const sinResultados = document.getElementById('sinResultados');
        const buscadorInput = document.getElementById('buscarTecnica');

        function renderizarAcordeon(familiasFiltradas = null) {
            acordeonDiv.innerHTML = '';
            const familiasARenderizar = familiasFiltradas || familiasData;
            let algunaCoincidencia = false;
            familiasARenderizar.forEach((fam, idx) => {
                const colDiv = document.createElement('div');
                colDiv.className = 'col-lg-6 mb-3';
                const card = document.createElement('div');
                card.className = 'card card-familia';
                const header = document.createElement('div');
                header.className = 'card-header d-flex justify-content-between align-items-center';
                header.setAttribute('data-bs-toggle', 'collapse');
                header.setAttribute('data-bs-target', `#familia${idx}`);
                header.setAttribute('aria-expanded', 'false');
                header.style.cursor = 'pointer';
                header.innerHTML = `<span>${fam.nombre}</span><span class="badge badge-tecnicas">${fam.tecnicas.length} técnicas</span>`;
                const collapse = document.createElement('div');
                collapse.className = 'collapse';
                collapse.id = `familia${idx}`;
                const body = document.createElement('div');
                body.className = 'card-body';
                fam.tecnicas.forEach(t => {
                    const item = document.createElement('div');
                    item.className = 'tecnica-item';
                    const anotacion = document.createElement('div');
                    anotacion.className = 'tecnica-anotacion';
                    anotacion.textContent = '✎ ' + t.nombre.substring(0, 18);
                    item.appendChild(anotacion);
                    const nombre = document.createElement('div');
                    nombre.className = 'tecnica-nombre';
                    nombre.textContent = t.nombre;
                    item.appendChild(nombre);
                    const desc = document.createElement('div');
                    desc.className = 'tecnica-desc';
                    desc.textContent = t.desc;
                    item.appendChild(desc);
                    const ejemplo = document.createElement('div');
                    ejemplo.className = 'tecnica-ejemplo';
                    ejemplo.innerHTML = `<span style="text-decoration:underline; text-decoration-color:var(--colombia-azul); text-decoration-thickness:2px;">${t.ej}</span>`;
                    item.appendChild(ejemplo);
                    body.appendChild(item);
                });
                collapse.appendChild(body);
                card.appendChild(header);
                card.appendChild(collapse);
                colDiv.appendChild(card);
                acordeonDiv.appendChild(colDiv);
                algunaCoincidencia = true;
            });
            sinResultados.style.display = algunaCoincidencia ? 'none' : 'block';
        }

        buscadorInput.addEventListener('input', () => {
            const termino = buscadorInput.value.toLowerCase().trim();
            if (!termino) { renderizarAcordeon(); return; }
            const filtradas = familiasData.map(fam => {
                const tecFiltradas = fam.tecnicas.filter(t =>
                    t.nombre.toLowerCase().includes(termino) ||
                    t.desc.toLowerCase().includes(termino) ||
                    t.ej.toLowerCase().includes(termino) ||
                    fam.nombre.toLowerCase().includes(termino)
                );
                return {...fam, tecnicas: tecFiltradas};
            }).filter(fam => fam.tecnicas.length > 0);
            renderizarAcordeon(filtradas);
        });
        renderizarAcordeon();

        // Quiz
        let preguntaActual = null, respondido = false;
        let aciertos = 0, totalPreguntas = 0, racha = 0, rachaMax = 0;
        const contadorAciertos = document.getElementById('contadorAciertos');
        const contadorRacha = document.getElementById('contadorRacha');
        const contadorTotal = document.getElementById('contadorTotal');
        const preguntaTexto = document.getElementById('preguntaTexto');
        const opcionesDiv = document.getElementById('opcionesFragmentos');
        const feedbackDiv = document.getElementById('feedbackQuiz');
        const btnSiguiente = document.getElementById('btnSiguiente');

        function cargarProgreso() {
            if (localStorage.getItem('progresoGrado7')) {
                const p = JSON.parse(localStorage.getItem('progresoGrado7'));
                aciertos = p.aciertos||0; totalPreguntas = p.total||0; racha = p.racha||0; rachaMax = p.rachaMax||0;
            }
            actualizarMarcadores();
        }
        function guardarProgreso() {
            localStorage.setItem('progresoGrado7', JSON.stringify({aciertos,total:totalPreguntas,racha,rachaMax}));
        }
        function actualizarMarcadores() {
            contadorAciertos.textContent = aciertos;
            contadorRacha.textContent = racha;
            contadorTotal.textContent = totalPreguntas;
        }
        function generarPregunta() {
            const correcta = todasLasTecnicas[Math.floor(Math.random()*todasLasTecnicas.length)];
            const distractores = todasLasTecnicas.filter(t => t.nombre !== correcta.nombre).sort(()=>Math.random()-0.5).slice(0,3);
            return { correcta, opciones: [correcta,...distractores].sort(()=>Math.random()-0.5) };
        }
        function mostrarPregunta() {
            respondido = false;
            const { correcta, opciones } = generarPregunta();
            preguntaActual = { correcta, opciones };
            preguntaTexto.innerHTML = `¿Cuál de estos fragmentos ilustra la técnica <em class="text-danger">${correcta.nombre}</em>?`;
            opcionesDiv.innerHTML = '';
            opciones.forEach(op => {
                const div = document.createElement('div');
                div.className = 'col-md-6';
                const opt = document.createElement('div');
                opt.className = 'quiz-option';
                opt.textContent = op.ej;
                opt.addEventListener('click', () => seleccionarFragmento(op, opt));
                div.appendChild(opt);
                opcionesDiv.appendChild(div);
            });
            feedbackDiv.innerHTML = '';
            btnSiguiente.style.display = 'none';
        }
        function seleccionarFragmento(opcion, elementoDiv) {
            if (respondido) return;
            respondido = true;
            const correcta = preguntaActual.correcta;
            const esCorrecta = opcion.nombre === correcta.nombre;
            totalPreguntas++;
            if (esCorrecta) {
                aciertos++; racha++;
                if (racha > rachaMax) rachaMax = racha;
                elementoDiv.classList.add('correcta');
                feedbackDiv.innerHTML = `<div class="alert alert-success mt-3">✓ Correcto: <strong>${correcta.nombre}</strong> — ${correcta.desc}</div>`;
            } else {
                racha = 0;
                elementoDiv.classList.add('incorrecta');
                const divs = document.querySelectorAll('.quiz-option');
                divs.forEach(d => { if (d.textContent === correcta.ej) d.classList.add('correcta'); });
                feedbackDiv.innerHTML = `<div class="alert alert-danger mt-3">✗ Incorrecto. La respuesta era <strong>${correcta.nombre}</strong>: ${correcta.desc}</div>`;
            }
            guardarProgreso();
            actualizarMarcadores();
            btnSiguiente.style.display = 'inline-block';
        }
        btnSiguiente.addEventListener('click', mostrarPregunta);
        document.querySelector('[data-bs-target="#practicarTab"]').addEventListener('click', () => {
            if (!preguntaActual) mostrarPregunta();
        });
        cargarProgreso();
        mostrarPregunta();
    })();
</script>
</body>
</html>

