<div class="container mt-3">
  <div class="row">
    <div class="col-12 d-flex flex-wrap align-items-center gap-2 filtro-bloque p-2">
      <span class="fw-bold me-2" style="color:var(--teal-dark);"><i class="bi bi-tags"></i> Bloques:</span>
      <button class="btn btn-outline-secondary active" data-bloque="todos">Todos</button>
      <button class="btn btn-outline-secondary" data-bloque="I">I</button>
      <button class="btn btn-outline-secondary" data-bloque="II">II</button>
      <button class="btn btn-outline-secondary" data-bloque="III">III</button>
      <button class="btn btn-outline-secondary" data-bloque="IV">IV</button>
      <button class="btn btn-outline-secondary" data-bloque="V">V</button>
      <button class="btn btn-outline-secondary" data-bloque="VI">VI</button>
      <button class="btn btn-outline-secondary" data-bloque="VII">VII</button>
      <button class="btn btn-outline-secondary" data-bloque="VIII">VIII</button>
      <button class="btn btn-outline-secondary" data-bloque="IX">IX</button>
      <button class="btn btn-outline-secondary" data-bloque="X">X</button>
      <span class="ms-2 text-muted small" id="resultCount">100 técnicas</span>
    </div>
  </div>
</div>

<!-- Grid -->
<div class="container mt-3 pb-5">
  <div id="gridTecnicas" class="row g-3"></div>
</div>

<!-- Modal de práctica (detalle) -->
<div class="modal fade" id="modalPractica" tabindex="-1">
  <div class="modal-dialog modal-dialog-centered">
    <div class="modal-content" style="background-color:var(--yellow-bg); border-left:8px solid var(--teal);">
      <div class="modal-header" style="border-bottom:2px solid var(--teal-light);">
        <h5 class="modal-title" style="color:var(--teal-dark);"><i class="bi bi-puzzle me-2"></i>Practica</h5>
        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
      </div>
      <div class="modal-body" id="modalPracticaBody"></div>
      <div class="modal-footer">
        <button class="btn btn-teal" id="btnRevelarPractica"><i class="bi bi-eye"></i> Revelar</button>
        <button class="btn btn-outline-secondary" data-bs-dismiss="modal">Cerrar</button>
      </div>
    </div>
  </div>
</div>

<!-- Scripts -->
<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0-alpha3/dist/js/bootstrap.bundle.min.js"></script>
<script>
  (function() {
    'use strict';

    // ----------------------------------------------------------------
    // 1. DATOS: 100 técnicas en 10 bloques
    // ----------------------------------------------------------------
    const TECNICAS = [];

    // BLOQUE I: Elementos básicos del párrafo descriptivo
    const bloqueI = [
      { nombre: 'Impresión dominante', definicion: 'Sensación global o atmósfera que el autor quiere transmitir al lector.', ejemplo: 'La habitación olía a viejo y a misterio, una penumbra que envolvía cada rincón.' },
      { nombre: 'Foco descriptivo', definicion: 'Punto de atención principal hacia el cual se orienta la mirada del observador.', ejemplo: 'Su mirada se fijó en la ventana empañada, centro de toda la escena.' },
      { nombre: 'Distancia del observador', definicion: 'Proximidad o lejanía del narrador respecto al objeto descrito.', ejemplo: 'Desde la colina, el pueblo parecía un juguete; al acercarse, cada piedra cobraba vida.' },
      { nombre: 'Ángulo de visión', definicion: 'Perspectiva desde la que se observa: frontal, cenital, picado, contrapicado.', ejemplo: 'Visto desde arriba, el laberinto de calles trazaba un mapa celeste.' },
      { nombre: 'Selección de detalles', definicion: 'Elección de los rasgos más significativos para crear una imagen precisa.', ejemplo: 'No mencionó la mesa ni las sillas, solo el polvo que bailaba en el rayo de sol.' },
      { nombre: 'Orden de percepción', definicion: 'Secuencia en que se presentan los estímulos: visual, auditivo, táctil, olfativo, gustativo.', ejemplo: 'Primero el aroma a café, luego el rumor de la taza, después el calor en las manos.' },
      { nombre: 'Ritmo descriptivo', definicion: 'Velocidad y cadencia en la presentación de los detalles (pausado, rápido, acumulativo).', ejemplo: 'Una tras otra, las hojas caían: lenta, pausada, interminablemente.' },
      { nombre: 'Color y luz', definicion: 'Uso de tonalidades, intensidades y claroscuros para dar atmósfera.', ejemplo: 'El atardecer tiñó de naranja y violeta los tejados, mientras las sombras se alargaban.' },
      { nombre: 'Textura y materialidad', definicion: 'Descripción de la superficie, consistencia y cualidades táctiles.', ejemplo: 'La piedra era rugosa y fría, como si guardara la humedad de los siglos.' },
      { nombre: 'Dimensión y escala', definicion: 'Indicación del tamaño, proporción y relación con el entorno.', ejemplo: 'La catedral empequeñecía a las personas, sus torres se perdían entre las nubes.' }
    ];
    bloqueI.forEach((t, i) => TECNICAS.push({ id: i+1, bloque: 'I', ...t }));

    // BLOQUE II: Tipos según el objeto
    const bloqueII = [
      { nombre: 'Prosopografía', definicion: 'Descripción física de una persona (rasgos, vestimenta, gestos).', ejemplo: 'Era alto, de hombros anchos, y su barba gris contrastaba con sus ojos azules.' },
      { nombre: 'Etopeya', definicion: 'Descripción del carácter, costumbres y cualidades morales de una persona.', ejemplo: 'Era un hombre de palabra, generoso hasta la ruina, pero de mal genio.' },
      { nombre: 'Retrato', definicion: 'Combinación de prosopografía y etopeya: imagen completa de una persona.', ejemplo: 'Flaco, desgarbado, con una risa fácil que ocultaba una tristeza profunda.' },
      { nombre: 'Topografía', definicion: 'Descripción detallada de un lugar o paisaje.', ejemplo: 'El valle se extendía verde y salpicado de casas blancas, con un río serpenteante.' },
      { nombre: 'Zoografía', definicion: 'Descripción de animales: aspecto, comportamiento, hábitat.', ejemplo: 'El gato, de pelaje atigrado, se movía con sigilo, sus ojos brillaban en la oscuridad.' },
      { nombre: 'Cronografía', definicion: 'Descripción de una época o período histórico, con sus costumbres y ambiente.', ejemplo: 'Los años veinte bullían de jazz y optimismo, las faldas subían y el humo de los cigarros llenaba los cafés.' },
      { nombre: 'Cerografía', definicion: 'Descripción de objetos inanimados, herramientas o utensilios.', ejemplo: 'La vieja máquina de escribir, con sus teclas redondas y el carro metálico, parecía un artefacto de otro siglo.' },
      { nombre: 'Hidrografía', definicion: 'Descripción de masas de agua, ríos, mares y sus movimientos.', ejemplo: 'El mar estaba encrespado, sus olas rompían contra los acantilados con furia.' },
      { nombre: 'Ficografía', definicion: 'Descripción de seres imaginarios o fantásticos.', ejemplo: 'El dragón tenía escamas de obsidiana y su aliento desprendía un calor abrasador.' },
      { nombre: 'Pintura de costumbres', definicion: 'Descripción de escenas típicas, tradiciones y modos de vida.', ejemplo: 'La verbena popular llenaba la plaza de farolillos y el olor a churros.' }
    ];
    bloqueII.forEach((t, i) => TECNICAS.push({ id: 10+i+1, bloque: 'II', ...t }));

    // BLOQUE III: Órdenes de organización espacial
    const bloqueIII = [
      { nombre: 'Orden arriba-abajo', definicion: 'De lo más alto a lo más bajo (cielo-tierra, techo-suelo).', ejemplo: 'Las nubes, luego la cima del monte, el bosque y al final el río.' },
      { nombre: 'Orden por planos', definicion: 'Primer plano, segundo plano, fondo (jerarquía de profundidad).', ejemplo: 'En primer plano la mesa, al fondo la chimenea, y entre ambas una alfombra desgastada.' },
      { nombre: 'Panorámico', definicion: 'Visión de conjunto, barrido horizontal de izquierda a derecha.', ejemplo: 'El ojo recorría el horizonte: montañas, viñedos, el caserío y la iglesia.' },
      { nombre: 'Orden de cercanía a lejanía', definicion: 'Desde lo más próximo a lo más distante.', ejemplo: 'Junto al camino, una valla; más allá, un campo de trigo; al fondo, la sierra.' },
      { nombre: 'Orden de lejanía a cercanía', definicion: 'Desde el horizonte hacia el observador.', ejemplo: 'La cordillera se acercaba, primero azul, luego verde, hasta tocar mis pies.' },
      { nombre: 'Orden circular', definicion: 'Movimiento alrededor del objeto, como un giro de 360°.', ejemplo: 'La plaza giraba a su alrededor: la fuente, el kiosco, los bancos y las farolas.' },
      { nombre: 'Orden centrífugo', definicion: 'Desde el centro hacia los bordes o periferia.', ejemplo: 'Desde el corazón de la ciudad, las calles se extendían como radios de una rueda.' },
      { nombre: 'Orden centrípeto', definicion: 'Desde los bordes hacia el centro o núcleo.', ejemplo: 'Los arrabales, las fábricas, el mercado, hasta llegar a la plaza mayor.' },
      { nombre: 'Orden de izquierda a derecha', definicion: 'Secuencia horizontal según la lectura occidental.', ejemplo: 'A la izquierda la panadería, al centro el quiosco, a la derecha la farmacia.' },
      { nombre: 'Orden de derecha a izquierda', definicion: 'Recorrido inverso, usado con intención estilística.', ejemplo: 'La biblioteca a la derecha, luego el archivo, y por último el despacho.' }
    ];
    bloqueIII.forEach((t, i) => TECNICAS.push({ id: 20+i+1, bloque: 'III', ...t }));

    // BLOQUE IV: Construcción del párrafo
    const bloqueIV = [
      { nombre: 'Oración temática', definicion: 'Frase que introduce y sintetiza la idea principal del párrafo.', ejemplo: 'La casa de la abuela era un mundo de aromas y recuerdos.' },
      { nombre: 'Verbos de percepción', definicion: 'Uso de verbos como ver, oír, sentir, oler, gustar para anclar la descripción.', ejemplo: 'Oía el crujir de las tablas y sentía el olor a madera y a humo.' },
      { nombre: 'Adjetivación precisa', definicion: 'Selección de adjetivos específicos que matizan y enriquecen.', ejemplo: 'El cielo, de un azul profundo y limpio, se reflejaba en las aguas cristalinas.' },
      { nombre: 'Cierre conclusivo', definicion: 'Frase final que redondea o resume la impresión dominante.', ejemplo: 'Y todo aquello quedó grabado en su memoria como un sueño vivo.' },
      { nombre: 'Variedad de conectores', definicion: 'Uso de nexos espaciales (junto a, frente a, al fondo) para cohesionar.', ejemplo: 'Junto al río, el molino; detrás, la arboleda; al frente, el camino de sirga.' },
      { nombre: 'Uso de la anáfora', definicion: 'Repetición de una palabra al inicio de varias oraciones para dar énfasis.', ejemplo: 'Era el viento, era el polvo, era el murmullo de las hojas.' },
      { nombre: 'Construcción en bloques', definicion: 'División del párrafo en segmentos temáticos (ej. exterior e interior).', ejemplo: 'Fuera, el jardín florecía; dentro, las cortinas guardaban la penumbra.' },
      { nombre: 'Dosificación de información', definicion: 'Presentar detalles de manera gradual, sin saturar.', ejemplo: 'Primero, el color de la puerta; luego, el pomo de bronce; después, el chirrido al abrir.' },
      { nombre: 'Contraste interno', definicion: 'Incluir opuestos dentro del párrafo para crear tensión.', ejemplo: 'La alegría de los niños contrastaba con la severidad del viejo edificio.' },
      { nombre: 'Cierre abierto', definicion: 'Terminar con una sugerencia o pregunta que invite a la reflexión.', ejemplo: '¿Y si aquel silencio ocultaba más de lo que mostraba?' }
    ];
    bloqueIV.forEach((t, i) => TECNICAS.push({ id: 30+i+1, bloque: 'IV', ...t }));

    // BLOQUE V: Figuras de comparación e imagen
    const bloqueV = [
      { nombre: 'Símil o comparación', definicion: 'Relación explícita con "como" o "cual".', ejemplo: 'Sus cabellos brillaban como el oro bajo la luz de la tarde.' },
      { nombre: 'Metáfora', definicion: 'Identificación de un término real con otro imaginario.', ejemplo: 'Sus ojos eran dos luceros en la noche.' },
      { nombre: 'Alegoría', definicion: 'Metáfora continuada que representa una idea abstracta con imágenes concretas.', ejemplo: 'La vida es un río que fluye hacia el mar.' },
      { nombre: 'Sinécdoque', definicion: 'Designar el todo por la parte o viceversa.', ejemplo: 'Por el amor de Cristo, se arrodilló.' },
      { nombre: 'Metonimia', definicion: 'Sustitución de un término por otro con relación de contigüidad causal.', ejemplo: 'Leer a Cervantes (por sus obras).' },
      { nombre: 'Hipérbole', definicion: 'Exageración deliberada para enfatizar.', ejemplo: 'Te he esperado un siglo.' },
      { nombre: 'Personificación', definicion: 'Atribuir cualidades humanas a objetos o animales.', ejemplo: 'El viento susurraba secretos entre los árboles.' },
      { nombre: 'Sinestesia', definicion: 'Mezcla de sensaciones de diferentes sentidos.', ejemplo: 'El sabor de la música llenaba la habitación.' },
      { nombre: 'Epíteto', definicion: 'Adjetivo que resalta una cualidad inherente al sustantivo.', ejemplo: 'La blanca nieve cubría la pradera.' },
      { nombre: 'Imagen', definicion: 'Representación mental viva creada mediante lenguaje figurado.', ejemplo: 'El mar era un espejo roto en mil pedazos.' }
    ];
    bloqueV.forEach((t, i) => TECNICAS.push({ id: 40+i+1, bloque: 'V', ...t }));

    // BLOQUE VI: Figuras de repetición
    const bloqueVI = [
      { nombre: 'Anáfora', definicion: 'Repetición de una palabra o grupo al inicio de varios versos u oraciones.', ejemplo: 'Temprano, temprano, temprano, me despierto.' },
      { nombre: 'Epífora', definicion: 'Repetición de una palabra o grupo al final de varios versos u oraciones.', ejemplo: '...y todo es sueño, todo es sueño, todo es sueño.' },
      { nombre: 'Políptoton', definicion: 'Repetición de una misma raíz con diferentes flexiones.', ejemplo: 'Cantando, cantaré, canta conmigo.' },
      { nombre: 'Derivación', definicion: 'Repetición de palabras de la misma familia léxica.', ejemplo: 'El amor que ama, amado y amante.' },
      { nombre: 'Concatenación', definicion: 'Encadenamiento de palabras en la que la última de una oración es la primera de la siguiente.', ejemplo: 'La noche trae el sueño, el sueño trae el olvido.' },
      { nombre: 'Gradación', definicion: 'Serie de elementos en orden creciente o decreciente de intensidad.', ejemplo: 'Suspiro, lloro, grito, maldigo.' },
      { nombre: 'Paralelismo', definicion: 'Repetición de estructuras sintácticas similares.', ejemplo: 'Ni el mar, ni el viento, ni el fuego pudieron detenerlo.' },
      { nombre: 'Quiasmo', definicion: 'Disposición cruzada de elementos paralelos (ABBA).', ejemplo: 'Cuando quiero reír, lloro; cuando quiero llorar, río.' },
      { nombre: 'Retruécano', definicion: 'Inversión de los términos de una frase para crear un nuevo sentido.', ejemplo: 'No es lo mismo, "si yo te quiero, tú me quieres" que "si tú me quieres, yo te quiero".' },
      { nombre: 'Antanaclasis', definicion: 'Repetición de una palabra con diferente sentido.', ejemplo: 'La luz que no se apaga, la luz que ilumina la luz.' }
    ];
    bloqueVI.forEach((t, i) => TECNICAS.push({ id: 50+i+1, bloque: 'VI', ...t }));

    // BLOQUE VII: Figuras de contraste y pensamiento
    const bloqueVII = [
      { nombre: 'Antítesis', definicion: 'Contraste de ideas opuestas en una misma estructura.', ejemplo: 'Eres todo para mí, pero nada para ti.' },
      { nombre: 'Oxímoron', definicion: 'Unión de dos conceptos contradictorios en una misma expresión.', ejemplo: 'Silencio atronador, oscuridad cegadora.' },
      { nombre: 'Paradoja', definicion: 'Idea que parece contradictoria pero encierra una verdad profunda.', ejemplo: 'Solo sé que no sé nada.' },
      { nombre: 'Ironía', definicion: 'Expresión que dice lo contrario de lo que se piensa, con intención burlesca.', ejemplo: '¡Qué bonito día para quedarse en casa!' },
      { nombre: 'Sarcasmo', definicion: 'Ironía más agresiva y mordaz.', ejemplo: 'Genial, otro informe que nadie va a leer.' },
      { nombre: 'Interrogación retórica', definicion: 'Pregunta que no espera respuesta, sino que enfatiza una idea.', ejemplo: '¿Quién no ha soñado con volar?' },
      { nombre: 'Exclamación', definicion: 'Expresión enfática de emoción o sorpresa.', ejemplo: '¡Qué maravillosa es la vida!' },
      { nombre: 'Apóstrofe', definicion: 'Invocación directa a alguien o algo ausente.', ejemplo: 'Oh, muerte, ven a llevarme.' },
      { nombre: 'Asíndeton', definicion: 'Omisión de conjunciones para dar velocidad.', ejemplo: 'Vine, vi, vencí.' },
      { nombre: 'Polisíndeton', definicion: 'Repetición de conjunciones para dar lentitud o énfasis.', ejemplo: 'Y el sol, y la luna, y las estrellas, y el mar.' }
    ];
    bloqueVII.forEach((t, i) => TECNICAS.push({ id: 60+i+1, bloque: 'VII', ...t }));

    // BLOQUE VIII: Figuras de omisión y orden
    const bloqueVIII = [
      { nombre: 'Elipsis', definicion: 'Supresión de un elemento que se sobrentiende.', ejemplo: 'Cada uno a su casa, y la fiesta a la plaza.' },
      { nombre: 'Zeugma', definicion: 'Elipsis de un verbo que rige varias oraciones.', ejemplo: 'El niño corre, la niña (corre) también.' },
      { nombre: 'Hipérbaton', definicion: 'Alteración del orden lógico de la oración.', ejemplo: 'De la montaña bajó el pastor.' },
      { nombre: 'Anacoluto', definicion: 'Ruptura sintáctica por cambio de construcción.', ejemplo: 'Ese libro, yo lo leí.' },
      { nombre: 'Perífrasis', definicion: 'Expresión de una idea con más palabras de las necesarias.', ejemplo: 'La ciudad de la luz (París).' },
      { nombre: 'Énfasis', definicion: 'Uso de recursos para destacar una idea.', ejemplo: '¡Mira, mira, mira lo que has hecho!' },
      { nombre: 'Hipotiposis', definicion: 'Descripción tan viva que parece representar la realidad.', ejemplo: 'El caballo galopaba con tal furia que el polvo se levantaba como una nube.' },
      { nombre: 'Prosopopeya', definicion: 'Atribuir cualidades humanas a seres inanimados (similar a personificación).', ejemplo: 'La tierra llora la ausencia de la lluvia.' },
      { nombre: 'Etopeia', definicion: 'Descripción de costumbres y carácter (ya en bloque II, pero aquí la incluimos como figura).', ejemplo: 'Siempre reía a carcajadas, pero en su interior lloraba.' },
      { nombre: 'Diálogo', definicion: 'Inserción de discurso directo dentro de la descripción.', ejemplo: '—¿Qué hora es? —preguntó, mientras el reloj marcaba las doce.' }
    ];
    bloqueVIII.forEach((t, i) => TECNICAS.push({ id: 70+i+1, bloque: 'VIII', ...t }));

    // BLOQUE IX: Figuras de sonido y juego verbal
    const bloqueIX = [
      { nombre: 'Aliteración', definicion: 'Repetición de sonidos consonánticos.', ejemplo: 'El susurro de las serpientes sisea.' },
      { nombre: 'Onomatopeya', definicion: 'Palabra que imita el sonido de la realidad.', ejemplo: 'El tic‑tac del reloj, el crac de la rama.' },
      { nombre: 'Paranomasia', definicion: 'Empleo de palabras de sonido parecido pero significado diferente.', ejemplo: 'Tanto trabajo y tan poco provecho.' },
      { nombre: 'Calambur', definicion: 'Agrupación de sílabas para crear un doble sentido.', ejemplo: 'A caballo regalado no le mires el diente / No le mires el diente a caballo regalado.' },
      { nombre: 'Anagrama', definicion: 'Transposición de letras para formar otra palabra.', ejemplo: 'Roma / Amor.' },
      { nombre: 'Palíndromo', definicion: 'Frase que se lee igual al derecho y al revés.', ejemplo: 'Anita lava la tina.' },
      { nombre: 'Acróstico', definicion: 'Composición poética cuyas letras iniciales forman un mensaje.', ejemplo: 'Siempre, Amor, Vida...' },
      { nombre: 'Estribillo', definicion: 'Verso o frase que se repite en una composición.', ejemplo: 'Y la la la, y la la la, etc.' },
      { nombre: 'Rima', definicion: 'Semejanza de sonidos entre finales de versos.', ejemplo: 'El sol brillaba / y el campo cantaba.' },
      { nombre: 'Ritmo', definicion: 'Regularidad de acentos y pausas que da musicalidad.', ejemplo: 'El tambor marcaba el paso de los soldados.' }
    ];
    bloqueIX.forEach((t, i) => TECNICAS.push({ id: 80+i+1, bloque: 'IX', ...t }));

    // BLOQUE X: Técnicas bilingües (español-inglés)
    const bloqueX = [
      { nombre: 'Impresión dominante / Dominant impression', definicion: 'Sensación global que guía la descripción.', ejemplo: 'The room smelled of old mystery.' },
      { nombre: 'Foco / Focus', definicion: 'Punto central de atención.', ejemplo: 'Her gaze fixed on the foggy window.' },
      { nombre: 'Distancia / Distance', definicion: 'Proximidad del observador.', ejemplo: 'From the hill, the village looked like a toy.' },
      { nombre: 'Prosopografía / Prosopography', definicion: 'Descripción física de una persona.', ejemplo: 'He was tall, broad-shouldered, with a gray beard.' },
      { nombre: 'Etopeya / Ethopoeia', definicion: 'Descripción del carácter.', ejemplo: 'He was a man of his word, generous but short-tempered.' },
      { nombre: 'Metáfora / Metaphor', definicion: 'Identificación de dos términos.', ejemplo: 'Her eyes were two stars.' },
      { nombre: 'Símil / Simile', definicion: 'Comparación con "como".', ejemplo: 'Her hair shone like gold.' },
      { nombre: 'Hipérbole / Hyperbole', definicion: 'Exageración para enfatizar.', ejemplo: 'I have waited a century.' },
      { nombre: 'Anáfora / Anaphora', definicion: 'Repetición al inicio.', ejemplo: 'Early, early, early I wake up.' },
      { nombre: 'Antítesis / Antithesis', definicion: 'Contraste de ideas.', ejemplo: 'You are everything to me, but nothing to you.' }
    ];
    bloqueX.forEach((t, i) => TECNICAS.push({ id: 90+i+1, bloque: 'X', ...t }));

    // ----------------------------------------------------------------
    // 2. ESTADO Y ALMACENAMIENTO
    // ----------------------------------------------------------------
    const STORAGE_KEY = 'cuadernoDescriptivoFiguras_tecnicas';
    let progreso = {}; // { id: true }
    let modoActual = 'explorar';
    let bloqueFiltro = 'todos';
    let voiceEnabled = false;
    let speechSynth = window.speechSynthesis;
    let utterance = null;

    function cargarProgreso() {
      try {
        const data = localStorage.getItem(STORAGE_KEY);
        if (data) progreso = JSON.parse(data);
        else progreso = {};
      } catch (e) { progreso = {}; }
    }

    function guardarProgreso() {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(progreso));
      actualizarContador();
    }

    function toggleAprendida(id) {
      if (progreso[id]) delete progreso[id];
      else progreso[id] = true;
      guardarProgreso();
      renderizar();
    }

    function actualizarContador() {
      const total = TECNICAS.length;
      const aprendidas = Object.keys(progreso).filter(k => progreso[k]).length;
      document.getElementById('contadorAprendidas').textContent = `${aprendidas}/${total}`;
    }

    // ----------------------------------------------------------------
    // 3. RENDERIZADO
    // ----------------------------------------------------------------
    function getTecnicasFiltradas() {
      let lista = TECNICAS;
      if (bloqueFiltro !== 'todos') lista = lista.filter(t => t.bloque === bloqueFiltro);
      return lista;
    }

    function leerTexto(texto) {
      if (!voiceEnabled) return;
      if (speechSynth.speaking) speechSynth.cancel();
      utterance = new SpeechSynthesisUtterance(texto);
      utterance.lang = 'es-ES';
      utterance.rate = 0.9;
      utterance.pitch = 1;
      speechSynth.speak(utterance);
    }

    function renderizar() {
      const grid = document.getElementById('gridTecnicas');
      const lista = getTecnicasFiltradas();
      document.getElementById('resultCount').textContent = `${lista.length} técnicas`;

      if (modoActual === 'explorar') {
        grid.innerHTML = lista.map(t => {
          const aprendida = progreso[t.id] || false;
          return `
            <div class="col-12 col-md-6 col-lg-4">
              <div class="card card-descriptivo p-3">
                <div class="d-flex justify-content-between align-items-start">
                  <span class="badge-bloque">${t.bloque}</span>
                  <span class="badge bg-${aprendida ? 'success' : 'secondary'} rounded-pill">${aprendida ? '✓ Aprendida' : 'Pendiente'}</span>
                </div>
                <h6 class="card-title mt-2">${t.nombre}</h6>
                <p class="card-text definicion small">${t.definicion}</p>
                <p class="card-text ejemplo-cursiva small"><i class="bi bi-quote"></i> ${t.ejemplo}</p>
                <div class="d-flex justify-content-between align-items-center mt-2">
                  <button class="btn btn-outline-teal btn-sm btn-voice" data-id="${t.id}" title="Escuchar">
                    <i class="bi bi-volume-up"></i>
                  </button>
                  <button class="btn btn-sm ${aprendida ? 'btn-outline-warning' : 'btn-teal'} btn-firmar" data-id="${t.id}">
                    ${aprendida ? '<i class="bi bi-check2-circle"></i> Firmar' : '<i class="bi bi-pen"></i> Firmar'}
                  </button>
                </div>
              </div>
            </div>
          `;
        }).join('');
      } else if (modoActual === 'practicar') {
        grid.innerHTML = lista.map(t => {
          const aprendida = progreso[t.id] || false;
          return `
            <div class="col-12 col-md-6 col-lg-4">
              <div class="card card-descriptivo p-3" data-practica-id="${t.id}" style="cursor:pointer;">
                <div class="d-flex justify-content-between align-items-start">
                  <span class="badge-bloque">${t.bloque}</span>
                  <span class="badge bg-${aprendida ? 'success' : 'secondary'} rounded-pill">${aprendida ? '✓' : '?'}</span>
                </div>
                <h6 class="card-title mt-2">${t.nombre}</h6>
                <p class="card-text definicion small" style="filter:blur(4px);user-select:none;">${t.definicion}</p>
                <p class="card-text ejemplo-cursiva small" style="filter:blur(4px);user-select:none;"><i class="bi bi-quote"></i> ${t.ejemplo}</p>
                <div class="d-flex justify-content-between mt-2">
                  <button class="btn btn-outline-teal btn-sm btn-revelar-practica" data-id="${t.id}">
                    <i class="bi bi-eye"></i> Revelar
                  </button>
                  <button class="btn btn-sm ${aprendida ? 'btn-outline-warning' : 'btn-teal'} btn-firmar" data-id="${t.id}">
                    ${aprendida ? '<i class="bi bi-check2-circle"></i>' : '<i class="bi bi-pen"></i>'}
                  </button>
                </div>
              </div>
            </div>
          `;
        }).join('');
      } else if (modoActual === 'progreso') {
        const aprendidas = TECNICAS.filter(t => progreso[t.id]);
        const pendientes = TECNICAS.filter(t => !progreso[t.id]);
        const pct = Math.round((aprendidas.length / TECNICAS.length) * 100);
        grid.innerHTML = `
          <div class="col-12">
            <div class="card p-4" style="background-color:var(--yellow-card); border-left:6px solid var(--teal);">
              <h5><i class="bi bi-bar-chart-fill me-2" style="color:var(--teal);"></i>Tu progreso</h5>
              <div class="progreso-bar mt-2"><div class="progress-fill" style="width:${pct}%;"></div></div>
              <p class="mt-2"><strong>${aprendidas.length}</strong> de ${TECNICAS.length} técnicas aprendidas (${pct}%)</p>
              <div class="row mt-3">
                <div class="col-md-6">
                  <h6 class="text-success"><i class="bi bi-check-circle"></i> Aprendidas</h6>
                  ${aprendidas.length ? aprendidas.map(t => `<span class="badge bg-success me-1 mb-1">${t.nombre}</span>`).join('') : '<p class="text-muted small">Aún no has firmado ninguna.</p>'}
                </div>
                <div class="col-md-6">
                  <h6 class="text-secondary"><i class="bi bi-hourglass-split"></i> Pendientes</h6>
                  ${pendientes.length ? pendientes.map(t => `<span class="badge bg-secondary me-1 mb-1">${t.nombre}</span>`).join('') : '<p class="text-muted small">¡Todo aprendido!</p>'}
                </div>
              </div>
              <div class="firma-cursiva mt-3 text-end">— Tu cuaderno descriptivo + figuras</div>
            </div>
          </div>
        `;
      }

      // Reasignar eventos
      document.querySelectorAll('.btn-firmar').forEach(btn => {
        btn.addEventListener('click', function(e) {
          e.stopPropagation();
          const id = parseInt(this.dataset.id);
          toggleAprendida(id);
        });
      });

      document.querySelectorAll('.btn-voice').forEach(btn => {
        btn.addEventListener('click', function(e) {
          e.stopPropagation();
          const id = parseInt(this.dataset.id);
          const tec = TECNICAS.find(t => t.id === id);
          if (tec) leerTexto(`${tec.nombre}: ${tec.definicion}. Ejemplo: ${tec.ejemplo}`);
        });
      });

      if (modoActual === 'practicar') {
        document.querySelectorAll('.btn-revelar-practica').forEach(btn => {
          btn.addEventListener('click', function(e) {
            e.stopPropagation();
            const id = parseInt(this.dataset.id);
            const card = this.closest('.card-descriptivo');
            if (card) {
              card.classList.add('revelado');
              this.textContent = '✓ Visible';
              this.disabled = true;
            }
          });
        });
        document.querySelectorAll('.card-descriptivo[data-practica-id]').forEach(card => {
          card.addEventListener('click', function() {
            const id = parseInt(this.dataset.practicaId);
            const tec = TECNICAS.find(t => t.id === id);
            if (tec) {
              const modal = new bootstrap.Modal(document.getElementById('modalPractica'));
              document.getElementById('modalPracticaBody').innerHTML = `
                <h5>${tec.nombre}</h5>
                <p><span class="badge-bloque">${tec.bloque}</span></p>
                <p><strong>Definición:</strong> ${tec.definicion}</p>
                <p class="ejemplo-cursiva"><strong>Ejemplo:</strong> "${tec.ejemplo}"</p>
                <button class="btn btn-sm btn-outline-teal btn-voice-modal" data-id="${tec.id}"><i class="bi bi-volume-up"></i> Escuchar</button>
              `;
              modal.show();
              document.querySelector('.btn-voice-modal')?.addEventListener('click', function() {
                const id2 = parseInt(this.dataset.id);
                const t2 = TECNICAS.find(t => t.id === id2);
                if (t2) leerTexto(`${t2.nombre}: ${t2.definicion}. Ejemplo: ${t2.ejemplo}`);
              });
            }
          });
        });
      }

      actualizarContador();
    }

    // ----------------------------------------------------------------
    // 4. NAVEGACIÓN Y FILTROS
    // ----------------------------------------------------------------
    function setModo(modo) {
      modoActual = modo;
      document.querySelectorAll('.navbar-custom .nav-link').forEach(el => el.classList.remove('active'));
      document.querySelector(`.navbar-custom .nav-link[data-modo="${modo}"]`)?.classList.add('active');
      renderizar();
    }

    function setBloque(bloque) {
      bloqueFiltro = bloque;
      document.querySelectorAll('.filtro-bloque .btn').forEach(el => el.classList.remove('active'));
      document.querySelector(`.filtro-bloque .btn[data-bloque="${bloque}"]`)?.classList.add('active');
      renderizar();
    }

    function toggleVoice() {
      voiceEnabled = !voiceEnabled;
      if (voiceEnabled) {
        document.getElementById('voiceStatus').classList.remove('d-none');
        document.getElementById('btnVoiceToggle').classList.add('btn-teal');
        document.getElementById('btnVoiceToggle').classList.remove('btn-outline-teal');
      } else {
        document.getElementById('voiceStatus').classList.add('d-none');
        document.getElementById('btnVoiceToggle').classList.remove('btn-teal');
        document.getElementById('btnVoiceToggle').classList.add('btn-outline-teal');
        if (speechSynth.speaking) speechSynth.cancel();
      }
    }

    // ----------------------------------------------------------------
    // 5. INICIALIZACIÓN
    // ----------------------------------------------------------------
    function init() {
      cargarProgreso();

      document.querySelectorAll('.navbar-custom .nav-link').forEach(el => {
        el.addEventListener('click', function(e) {
          e.preventDefault();
          const modo = this.dataset.modo;
          setModo(modo);
        });
      });

      document.querySelectorAll('.filtro-bloque .btn').forEach(el => {
        el.addEventListener('click', function() {
          const bloque = this.dataset.bloque;
          setBloque(bloque);
        });
      });

      document.getElementById('btnVoiceToggle').addEventListener('click', toggleVoice);

      // Botón revelar en modal
      document.getElementById('btnRevelarPractica').addEventListener('click', function() {
        const body = document.getElementById('modalPracticaBody');
        // Si hay alguna tarjeta en modal, no aplica porque el modal muestra texto fijo, pero no hay blur.
        // Simplemente leemos en voz alta
        const texto = body.innerText;
        leerTexto(texto);
      });

      setModo('explorar');
      setBloque('todos');
    }

    document.addEventListener('DOMContentLoaded', init);
  })();
</script>
</body>
</html>

