                            <div class="row">
                                <div class="col-md-6"><strong>📊 Estructura:</strong> ${analisis?.palabras || 0} palabras | ${analisis?.oraciones || 0} oraciones<br>Longitud media: ${analisis?.promedio || 0} palabras</div>
                                <div class="col-md-6"><strong>🎯 Patrón oracional:</strong> ${tech.analisisOracional}<br>Palabras >7 letras: ${analisis?.largas || 0}</div>
                            </div>
                            <hr>
                            <div><strong>📖 Recursos retóricos detectados:</strong> ${analisis?.recursos?.join(", ") || "Ninguno evidente"}</div>
                            <div><strong>⚡ Efecto argumentativo:</strong> ${analisis?.efecto}</div>
                            <div><strong>💡 Consejo de estilo:</strong> ${analisis?.consejo}</div>
                            <hr>
                            <div class="bg-light p-2 rounded"><strong>📝 Ejemplo de la técnica:</strong><br>${tech.ejemplo}</div>
                            <button class="btn btn-teal mt-3 w-100" id="useExampleBtn">Usar este ejemplo en el taller</button>
                        </div>
                    </div>
                </div>
            </div>
        `;
        if (document.querySelector("#syntaxModal")) document.querySelector("#syntaxModal").remove();
        document.body.insertAdjacentHTML("beforeend", html);
        let modal = new bootstrap.Modal(document.getElementById("syntaxModal"));
        modal.show();
        document.getElementById("useExampleBtn").onclick = () => {
            document.getElementById("writingArea").value = tech.ejemplo;
            modal.hide();
        };
    }

    // ============================== EVALUACIÓN DEL TALLER ==============================
    function evaluarEscritura() {
        let texto = document.getElementById("writingArea").value;
        if (!texto.trim()) { alert("Escribe algo antes de evaluar"); return; }
        let analisis = analisisProfundo(texto);
        if (!analisis) return;
        let puntTecnica = Math.min(100, analisis.puntuacionTecnica);
        let puntSintaxis = analisis.puntSintaxis;
        let puntEstilo = analisis.puntEstilo;
        let promedio = (puntTecnica + puntSintaxis + puntEstilo) / 3;

        let detalles = `
            <div class="alert alert-light mt-2">
                <strong>📌 Puntuación técnica (tesis, argumentación):</strong> ${puntTecnica}/100<br>
                <strong>✍️ Sintaxis (fluidez, estructura):</strong> ${puntSintaxis}/100<br>
                <strong>🎨 Estilo (recursos, voz):</strong> ${puntEstilo}/100<br>
                <div class="progress mt-1 mb-2" style="height: 6px;"><div class="progress-bar bg-crimson" style="width: ${promedio}%"></div></div>
