<footer class="text-center py-3 mt-5">
    <p><i class="fas fa-microscope"></i> Análisis sintáctico con patrones oracionales · Puntuación técnica, sintaxis y estilo · Datos guardados localmente</p>
</footer>

<script>
    // ============================== GENERACIÓN DE 100 TÉCNICAS ==============================
    const categoriasMap = {
        tesis: { nombre: "Tesis y argumentación", rango: [1,10], color: "#8b2c2c" },
        estructura: { nombre: "Estructura y organización", rango: [11,20] },
        voz: { nombre: "Voz y persona", rango: [21,25] },
        apertura: { nombre: "Apertura y cierre", rango: [26,30] },
        estilo: { nombre: "Estilo y lenguaje", rango: [31,40] },
        critico: { nombre: "Pensamiento crítico", rango: [41,50] },
        evidencia: { nombre: "Evidencia y fuentes", rango: [51,60] },
        retorica: { nombre: "Retórica", rango: [61,70] },
        personal: { nombre: "Ensayo personal (Montaigne)", rango: [71,75] },
        academico: { nombre: "Ensayo académico", rango: [76,80] },
        intertextualidad: { nombre: "Intertextualidad", rango: [81,85] },
        avanzadas: { nombre: "Síntesis + Avanzadas", rango: [86,100] }
    };

    function generarTecnicas() {
        let tecnicas = [];
        let id = 0;
        for (let [key, cat] of Object.entries(categoriasMap)) {
            let [inicio, fin] = cat.rango;
            for (let num = inicio; num <= fin; num++) {
                let titulo = "";
                let descripcion = "";
                let ejemplo = "";
                if (key === "tesis") {
                    titulo = `Tesis afirmativa con reservas · técnica ${num}`;
                    descripcion = `Formula una tesis clara pero matizada, admitiendo excepciones. Ejemplo: "Aunque la tecnología acelera el conocimiento, también fragmenta la atención, lo que sugiere un uso pedagógico regulado."`;
                    ejemplo = "La educación debe equilibrar innovación digital y pensamiento lento, pues no toda rapidez es profundidad.";
                } else if (key === "estructura") {
                    titulo = `Estructura de tres actos · técnica ${num}`;
                    descripcion = `Introducción (tesis), cuerpo (argumentos en espiral), conclusión (apertura). Ideal para ensayos breves.`;
                    ejemplo = "Primero planteo la contradicción; luego desarrollo sus matices; finalmente sugiero una síntesis provisional.";
                } else if (key === "voz") {
                    titulo = `Voz ensayística personal · técnica ${num}`;
                    descripcion = `Usa la primera persona del singular como recurso de honestidad intelectual, sin caer en el exceso confesional.`;
                    ejemplo = "He notado que las pausas en la escritura me permiten articular mejor la duda.";
                } else if (key === "apertura") {
                    titulo = `Apertura in media res · técnica ${num}`;
                    descripcion = `Comienza con una anécdota, pregunta o imagen que capte la atención y conduzca a la tesis.`;
                    ejemplo = "Cuando leí a Montaigne por primera vez, entendí que el ensayo era un género de la vulnerabilidad.";
                } else if (key === "estilo") {
                    titulo = `Claridad sintáctica · técnica ${num}`;
                    descripcion = `Prefiere oraciones de extensión media (15-25 palabras). Alterna subordinación y coordinación.`;
                    ejemplo = "La claridad no es simpleza, sino precisión. Un ensayo luminoso respira entre pausas.";
                } else if (key === "critico") {
                    titulo = `Detección de falacias · técnica ${num}`;
                    descripcion = `Identifica falsas dicotomías, generalizaciones apresuradas o argumentos ad hominem.`;
                    ejemplo = "Decir que 'quien critica la IA no entiende de tecnología' es una falacia de autoridad.";
                } else if (key === "evidencia") {
                    titulo = `Citas integradas · técnica ${num}`;
                    descripcion = `Parafrasea y cita con fluidez, mostrando diálogo con las fuentes.`;
                    ejemplo = "Como sostiene Nussbaum (2011), 'las emociones son juicios de valor' que moldean nuestra ética.";
                } else if (key === "retorica") {
                    titulo = `Figuras retóricas moderadas · técnica ${num}`;
                    descripcion = `Usa anáforas, metáforas conceptuales o epíforas para enfatizar ideas clave.`;
                    ejemplo = "La memoria es un palimpsesto: se borra, se reescribe, nunca queda en blanco.";
                } else if (key === "personal") {
                    titulo = `Ensayo personal (estilo Montaigne) · técnica ${num}`;
                    descripcion = `Explora una experiencia íntima hasta convertirla en reflexión universal.`;
                    ejemplo = "Aquella tarde en la biblioteca, entre libros olvidados, comprendí que leer es conversar con ausentes.";
                } else if (key === "academico") {
                    titulo = `Estructura IMRyD adaptada · técnica ${num}`;
                    descripcion = `Introducción, método reflexivo, resultados interpretativos y discusión.`;
                    ejemplo = "Tras analizar doce ensayos contemporáneos, observo una tendencia hacia la hibridación genérica.";
                } else if (key === "intertextualidad") {
                    titulo = `Diálogo con autores · técnica ${num}`;
                    descripcion = `Integra voces de otros pensadores para construir una polifonía argumentativa.`;
                    ejemplo = "Borges temía al espejo; yo temo a las respuestas sin preguntas previas.";
                } else {
                    titulo = `Síntesis creativa · técnica ${num}`;
                    descripcion = `Conecta disciplinas aparentemente ajenas para generar una perspectiva novedosa.`;
                    ejemplo = "La biología y la literatura coinciden en la metáfora del rizoma: todo se conecta sin centro fijo.";
                }
                tecnicas.push({
                    id: id++, numero: num, categoriaKey: key, categoriaNombre: cat.nombre,
                    titulo: titulo, descripcion: descripcion, ejemplo: ejemplo,
                    analisisOracional: "Oración compuesta por subordinación + coordinación. Patrón: tesis, evidencia, consecuencia."
                });
            }
        }
        return tecnicas;
    }

    let allTechniques = generarTecnicas();
    let currentFilterCat = "all";
    let currentSearch = "";
    let selectedTech = allTechniques[0];

    // ============================== LOCALSTORAGE ==============================
    let library = JSON.parse(localStorage.getItem("ensayoteca_library")) || [];

    function saveLibrary() {
        localStorage.setItem("ensayoteca_library", JSON.stringify(library));
        renderLibrary();
    }

    function renderLibrary() {
        const container = document.getElementById("libraryContainer");
        if (!library.length) { container.innerHTML = '<p class="text-muted small">Aún no hay textos guardados. Escribe y guarda tu práctica.</p>'; return; }
        container.innerHTML = library.map((item, idx) => `
            <div class="library-item">
                <div class="d-flex justify-content-between align-items-start">
                    <div><strong>${item.techTitle.substring(0, 50)}</strong><br>
                    <span class="small">Técnica: ${item.score_tecnica}/100 | Sintaxis: ${item.score_sintaxis}/100 | Estilo: ${item.score_estilo}/100</span><br>
                    <span class="small text-muted">${item.text.substring(0, 80)}...</span></div>
                    <button class="btn btn-sm btn-outline-danger" data-idx="${idx}"><i class="fas fa-trash"></i></button>
                </div>
            </div>
        `).join('');
        document.querySelectorAll("[data-idx]").forEach(btn => {
            btn.onclick = () => { library.splice(parseInt(btn.dataset.idx), 1); saveLibrary(); };
        });
    }

    // ============================== ANÁLISIS SINTÁCTICO AVANZADO ==============================
    function analisisProfundo(texto) {
        if (!texto.trim()) return null;
        let palabras = texto.match(/\b\w+\b/g) || [];
        let oraciones = texto.split(/[.!?]+/).filter(s => s.trim().length > 2);
        let promedio = (palabras.length / (oraciones.length || 1)).toFixed(1);
        let largas = palabras.filter(p => p.length > 7).length;
        let puntuacionTecnica = Math.min(100, Math.max(50, 80 - Math.abs(20 - promedio) * 2 + (largas < palabras.length*0.2 ? 10 : 0)));

        let recursos = [];
        if (texto.match(/\b(como|así|puesto que|por lo tanto|sin embargo|no obstante)\b/i)) recursos.push("Conectores lógicos");
        if (texto.match(/\b(metáfora|símil|analogía)\b/i)) recursos.push("Figura retórica");
        if (texto.match(/"[^"]+"/)) recursos.push("Discurso directo/cita");
        if (texto.match(/\b(yo|me|mi|nosotros)\b/i)) recursos.push("Voz personal");

        let efecto = promedio > 25 ? "Oraciones extensas: ritmo pausado, ideal para matizar." : promedio < 12 ? "Frases cortas: efecto contundente, agiliza la lectura." : "Ritmo equilibrado, facilita la argumentación.";
        let consejo = "Varía la longitud oracional y revisa el uso de conectores.";
        if (largas > palabras.length * 0.25) consejo = "Reducir palabras técnicas o muy largas mejora la claridad.";

        let puntSintaxis = Math.min(100, 70 + (oraciones.length > 1 ? 15 : 0) - (largas > palabras.length*0.3 ? 10 : 0));
        let puntEstilo = Math.min(100, 65 + (recursos.length * 8) + (texto.length > 100 ? 10 : 0));
        return { palabras: palabras.length, oraciones: oraciones.length, promedio, largas, puntuacionTecnica: Math.round(puntuacionTecnica), puntSintaxis: Math.round(puntSintaxis), puntEstilo: Math.round(puntEstilo), recursos, efecto, consejo };
    }

    // ============================== RENDER TÉCNICAS ==============================
    function renderTechniques() {
        let filtered = allTechniques.filter(t => {
            let matchCat = currentFilterCat === "all" || t.categoriaKey === currentFilterCat;
            let matchSearch = currentSearch === "" || t.titulo.toLowerCase().includes(currentSearch) || t.descripcion.toLowerCase().includes(currentSearch);
            return matchCat && matchSearch;
        });
        const container = document.getElementById("techniquesList");
        container.innerHTML = filtered.map(tech => `
            <div class="tech-item p-3 mb-2" style="background: #fefaf2; border-radius: 20px; cursor: pointer; border-left: 4px solid #b8865b;" data-id="${tech.id}">
                <div class="d-flex justify-content-between">
                    <span><strong class="serif">${tech.numero}. ${tech.titulo}</strong> <span class="badge-cat ms-2">${tech.categoriaNombre}</span></span>
                    <i class="fas fa-chevron-right text-crimson"></i>
                </div>
                <p class="small text-muted mt-1">${tech.descripcion.substring(0, 100)}...</p>
            </div>
        `).join('');
        document.querySelectorAll(".tech-item").forEach(el => {
            el.onclick = () => {
                let id = parseInt(el.dataset.id);
                selectedTech = allTechniques.find(t => t.id === id);
                mostrarModalAnalisis(selectedTech);
            };
        });
    }

    function mostrarModalAnalisis(tech) {
        let analisis = analisisProfundo(tech.ejemplo);
        let html = `
            <div class="modal fade" id="syntaxModal" tabindex="-1">
                <div class="modal-dialog modal-lg">
                    <div class="modal-content syntax-modal-content">
                        <div class="modal-header border-0">
                            <h5 class="modal-title serif"><i class="fas fa-microchip"></i> Análisis sintáctico · ${tech.titulo}</h5>
                            <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
                        </div>
                        <div class="modal-body">
                            <div class="row">
                                <div class="col-md-6"><strong>📊 Estructura:</strong> ${analisis?.palabras || 0} palabras | ${analisis?.oraciones || 0} oraciones<br>Longitud media: ${analisis?.promedio || 0} palabras</div>
                                <div class="col-md-6"><strong>🎯 Patrón oracional:</strong> ${tech.analisisOracional}<br>Palabras >7 letras: ${analisis?.largas || 0}</div>
                            </div>
                            <hr>
                            <div><strong>📖 Recursos retóricos detectados:</strong> ${analisis?.recursos?.join(", ") || "Ninguno evidente"}</div>
                            <div><strong>⚡ Efecto argumentativo:</strong> ${analisis?.efecto}</div>
                            <div><strong>💡 Consejo de estilo:</strong> ${analisis?.consejo}</div>
                            <hr>
                            <div class="bg-light p-2 rounded"><strong>📝 Ejemplo de la técnica:</strong><br>${tech.ejemplo}</div>
                            <button class="btn btn-teal mt-3 w-100" id="useExampleBtn">Usar este ejemplo en el taller</button>
                        </div>
                    </div>
                </div>
            </div>
        `;
        if (document.querySelector("#syntaxModal")) document.querySelector("#syntaxModal").remove();
        document.body.insertAdjacentHTML("beforeend", html);
        let modal = new bootstrap.Modal(document.getElementById("syntaxModal"));
        modal.show();
        document.getElementById("useExampleBtn").onclick = () => {
            document.getElementById("writingArea").value = tech.ejemplo;
            modal.hide();
        };
    }

    // ============================== EVALUACIÓN DEL TALLER ==============================
    function evaluarEscritura() {
        let texto = document.getElementById("writingArea").value;
        if (!texto.trim()) { alert("Escribe algo antes de evaluar"); return; }
        let analisis = analisisProfundo(texto);
        if (!analisis) return;
        let puntTecnica = Math.min(100, analisis.puntuacionTecnica);
        let puntSintaxis = analisis.puntSintaxis;
        let puntEstilo = analisis.puntEstilo;
        let promedio = (puntTecnica + puntSintaxis + puntEstilo) / 3;

        let detalles = `
            <div class="alert alert-light mt-2">
                <strong>📌 Puntuación técnica (tesis, argumentación):</strong> ${puntTecnica}/100<br>
                <strong>✍️ Sintaxis (fluidez, estructura):</strong> ${puntSintaxis}/100<br>
                <strong>🎨 Estilo (recursos, voz):</strong> ${puntEstilo}/100<br>
                <div class="progress mt-1 mb-2" style="height: 6px;"><div class="progress-bar bg-crimson" style="width: ${promedio}%"></div></div>
                <strong>🔍 Análisis detallado:</strong> ${analisis.palabras} palabras, ${analisis.oraciones} oraciones. ${analisis.efecto}<br>
                <strong>💬 Reescritura sugerida:</strong> "${texto.length > 80 ? texto.substring(0, 80) + "..." : texto} — Considera variar la longitud oracional y reforzar la tesis."
            </div>
        `;
        document.getElementById("evaluationResult").innerHTML = detalles;

        // Guardar temporalmente puntuaciones para guardar en biblioteca
        window.lastScores = { tecnica: puntTecnica, sintaxis: puntSintaxis, estilo: puntEstilo, text: texto, techTitle: selectedTech.titulo };
    }

    function guardarEnBiblioteca() {
        if (!window.lastScores || !document.getElementById("writingArea").value.trim()) {
            alert("Primero escribe y evalúa tu texto en el taller.");
            return;
        }
        library.push({
            techTitle: selectedTech.titulo,
            text: window.lastScores.text,
            score_tecnica: window.lastScores.tecnica,
            score_sintaxis: window.lastScores.sintaxis,
            score_estilo: window.lastScores.estilo,
            fecha: new Date().toISOString()
        });
        saveLibrary();
        alert("Guardado en tu biblioteca personal.");
    }

    // ============================== FILTROS Y BÚSQUEDA ==============================
    document.getElementById("globalSearch").addEventListener("input", (e) => { currentSearch = e.target.value.toLowerCase(); renderTechniques(); });
    document.getElementById("categoryFilter").addEventListener("change", (e) => { currentFilterCat = e.target.value; renderTechniques(); });
    document.getElementById("evaluateBtn").onclick = evaluarEscritura;
    document.getElementById("saveToLibraryBtn").onclick = guardarEnBiblioteca;
    document.getElementById("clearLibraryBtn").onclick = () => { if(confirm("Vaciar toda la biblioteca?")) { library = []; saveLibrary(); } };

    renderTechniques();
    renderLibrary();
    selectedTech = allTechniques[0];
    // Cargar bootstrap modal dinámico
    let bootstrapScript = document.createElement("script");
    bootstrapScript.src = "https://cdn.jsdelivr.net/npm/bootstrap@5.3.0-alpha1/dist/js/bootstrap.bundle.min.js";
    document.body.appendChild(bootstrapScript);
</script>
</body>
</html>

