<script>
  (function() {
    'use strict';

    // ----------------------------------------------------------------
    // 1. DATOS: 100 técnicas de gramática castellana para extranjeros
    // ----------------------------------------------------------------
    const TECNICAS = [];

    const caligrafias = ['caveat', 'tangerine', 'cookie', 'greatvibes', 'garabato'];
    const nombresCaligrafia = { caveat: 'Caveat', tangerine: 'Tangerine', cookie: 'Cookie', greatvibes: 'Great Vibes', garabato: 'Garabato' };
    const clasesCaligrafia = { caveat: 'fuente-caveat', tangerine: 'fuente-tangerine', cookie: 'fuente-cookie', greatvibes: 'fuente-greatvibes', garabato: 'fuente-garabato' };

    // BLOQUE I: Artículos y determinantes
    const bloqueI = [
      { nombre: 'Artículo definido (el, la, los, las)', definicion: 'Se usa para hablar de algo conocido o mencionado anteriormente.', ejemplo: 'Esp: "El libro está en la mesa." / Eng: "The book is on the table."', caligrafia: 'caveat' },
      { nombre: 'Artículo indefinido (un, una, unos, unas)', definicion: 'Se usa para hablar de algo no específico o mencionado por primera vez.', ejemplo: 'Esp: "Tengo un coche rojo." / Eng: "I have a red car."', caligrafia: 'cookie' },
      { nombre: 'Artículo neutro (lo)', definicion: 'Se usa con adjetivos para formar sustantivos abstractos.', ejemplo: 'Esp: "Lo importante es estudiar." / Eng: "The important thing is to study."', caligrafia: 'tangerine' },
      { nombre: 'Omisión del artículo', definicion: 'En español se omite el artículo en ciertos contextos (profesiones, nacionalidades).', ejemplo: 'Esp: "Soy profesor." / Eng: "I am a teacher." (en inglés se usa) / "Soy español." / "I am Spanish."', caligrafia: 'garabato' },
      { nombre: 'Contracción del artículo (al, del)', definicion: 'Artículo + preposición se contraen en "al" (a+el) y "del" (de+el).', ejemplo: 'Esp: "Voy al parque." / "Vengo del cine." / Eng: "I go to the park." / "I come from the cinema."', caligrafia: 'greatvibes' },
      { nombre: 'Demostrativos (este, ese, aquel)', definicion: 'Indican distancia respecto al hablante y al oyente.', ejemplo: 'Esp: "Este libro (cerca), ese libro (distancia media), aquel libro (lejos)." / Eng: "This book, that book, that book over there."', caligrafia: 'caveat' },
      { nombre: 'Posesivos (mi, tu, su, nuestro, vuestro)', definicion: 'Indican pertenencia o posesión.', ejemplo: 'Esp: "Mi casa es grande. Tu coche es rojo." / Eng: "My house is big. Your car is red."', caligrafia: 'cookie' },
      { nombre: 'Posesivos pospuestos (mío, tuyo, suyo)', definicion: 'Van después del sustantivo y concuerdan en género y número.', ejemplo: 'Esp: "Un amigo mío." / "La casa suya." / Eng: "A friend of mine." / "His/her house."', caligrafia: 'tangerine' },
      { nombre: 'Cuantificadores (mucho, poco, bastante, demasiado)', definicion: 'Indican cantidad.', ejemplo: 'Esp: "Hay mucha gente. Tengo poco tiempo." / Eng: "There are many people. I have little time."', caligrafia: 'garabato' },
      { nombre: 'Numerales (cardinales y ordinales)', definicion: 'Indican cantidad u orden.', ejemplo: 'Esp: "Tres libros. El primer capítulo." / Eng: "Three books. The first chapter."', caligrafia: 'greatvibes' }
    ];
    bloqueI.forEach((t, i) => TECNICAS.push({ id: i+1, bloque: 'I', ...t }));

    // BLOQUE II: Pronombres
    const bloqueII = [
      { nombre: 'Pronombres personales de sujeto (yo, tú, él, ella, etc.)', definicion: 'Indican quién realiza la acción.', ejemplo: 'Esp: "Yo estudio español. Tú hablas inglés." / Eng: "I study Spanish. You speak English."', caligrafia: 'caveat' },
      { nombre: 'Pronombres de objeto directo (me, te, lo/la, nos, os, los/las)', definicion: 'Reemplazan el objeto directo.', ejemplo: 'Esp: "Veo a Juan. Lo veo." / Eng: "I see Juan. I see him."', caligrafia: 'cookie' },
      { nombre: 'Pronombres de objeto indirecto (me, te, le, nos, os, les)', definicion: 'Reemplazan el objeto indirecto.', ejemplo: 'Esp: "Doy un regalo a María. Le doy un regalo." / Eng: "I give a gift to María. I give her a gift."', caligrafia: 'tangerine' },
      { nombre: 'Pronombres reflexivos (me, te, se, nos, os, se)', definicion: 'Indican que la acción recae sobre el sujeto.', ejemplo: 'Esp: "Me lavo las manos. Se peina el pelo." / Eng: "I wash my hands. She combs her hair."', caligrafia: 'garabato' },
      { nombre: 'Pronombres posesivos (el mío, la tuya, los suyos, etc.)', definicion: 'Reemplazan un sustantivo con posesión.', ejemplo: 'Esp: "Este libro es mío. La casa es suya." / Eng: "This book is mine. The house is hers."', caligrafia: 'greatvibes' },
      { nombre: 'Pronombres demostrativos (éste, ése, aquél)', definicion: 'Reemplazan un sustantivo indicando distancia.', ejemplo: 'Esp: "Éste es mi libro. Ése es el tuyo." / Eng: "This one is my book. That one is yours."', caligrafia: 'caveat' },
      { nombre: 'Pronombres relativos (que, quien, el cual, cuyo)', definicion: 'Introducen oraciones subordinadas.', ejemplo: 'Esp: "El hombre que habla. La mujer a quien vi." / Eng: "The man who speaks. The woman whom I saw."', caligrafia: 'tangerine' },
      { nombre: 'Pronombres interrogativos (qué, quién, cuál, cuánto)', definicion: 'Se usan para hacer preguntas.', ejemplo: 'Esp: "¿Qué quieres? ¿Quién es ella?" / Eng: "What do you want? Who is she?"', caligrafia: 'cookie' },
      { nombre: 'Pronombres exclamativos (qué, cuánto)', definicion: 'Se usan para exclamaciones.', ejemplo: 'Esp: "¡Qué bonito! ¡Cuánto tiempo!" / Eng: "How beautiful! So much time!"', caligrafia: 'garabato' },
      { nombre: 'Pronombres indefinidos (alguien, nadie, algo, nada, todo)', definicion: 'Indican cantidad o existencia de manera imprecisa.', ejemplo: 'Esp: "Alguien llamó. No hay nadie." / Eng: "Someone called. There is no one."', caligrafia: 'greatvibes' }
    ];
    bloqueII.forEach((t, i) => TECNICAS.push({ id: 10+i+1, bloque: 'II', ...t }));

    // BLOQUE III: Verbos y conjugación
    const bloqueIII = [
      { nombre: 'Verbos regulares (AR, ER, IR)', definicion: 'Siguen un patrón de conjugación fijo.', ejemplo: 'Esp: "Hablar: hablo, hablas, habla..." / Eng: "To speak: I speak, you speak, he speaks..."', caligrafia: 'caveat' },
      { nombre: 'Verbos irregulares (ser, estar, ir, tener, hacer)', definicion: 'No siguen el patrón regular de conjugación.', ejemplo: 'Esp: "Ser: soy, eres, es..." / Eng: "To be: I am, you are, he is..."', caligrafia: 'tangerine' },
      { nombre: 'Verbos reflexivos (levantarse, ducharse, vestirse)', definicion: 'El sujeto realiza y recibe la acción.', ejemplo: 'Esp: "Me levanto a las 7. Me ducho." / Eng: "I get up at 7. I shower."', caligrafia: 'cookie' },
      { nombre: 'Verbos de cambio (ponerse, hacerse, volverse, convertirse)', definicion: 'Indican cambios de estado.', ejemplo: 'Esp: "Se puso nervioso. Se hizo rico." / Eng: "He got nervous. He became rich."', caligrafia: 'garabato' },
      { nombre: 'Verbos de percepción (ver, oír, sentir, notar)', definicion: 'Indican percepción sensorial.', ejemplo: 'Esp: "Veo una casa. Oigo música." / Eng: "I see a house. I hear music."', caligrafia: 'greatvibes' },
      { nombre: 'Verbos de pensamiento (pensar, creer, opinar)', definicion: 'Indican procesos mentales.', ejemplo: 'Esp: "Pienso que es importante. Creo en ti." / Eng: "I think it\'s important. I believe in you."', caligrafia: 'caveat' },
      { nombre: 'Verbos de voluntad (querer, desear, preferir)', definicion: 'Indican deseos o preferencias.', ejemplo: 'Esp: "Quiero viajar. Prefiero el café." / Eng: "I want to travel. I prefer coffee."', caligrafia: 'cookie' },
      { nombre: 'Verbos de influencia (pedir, prohibir, recomendar)', definicion: 'Indican influencia sobre otros.', ejemplo: 'Esp: "Pido ayuda. Recomiendo este libro." / Eng: "I ask for help. I recommend this book."', caligrafia: 'tangerine' },
      { nombre: 'Verbos impersonales (haber, hacer, llover, nevar)', definicion: 'No tienen sujeto explícito.', ejemplo: 'Esp: "Hay mucha gente. Hace calor." / Eng: "There are many people. It\'s hot."', caligrafia: 'garabato' },
      { nombre: 'Perífrasis verbales (estar + gerundio, ir a + infinitivo, tener que + infinitivo)', definicion: 'Estructuras verbales compuestas con matices aspectuales.', ejemplo: 'Esp: "Estoy estudiando. Voy a viajar. Tengo que estudiar." / Eng: "I am studying. I am going to travel. I have to study."', caligrafia: 'greatvibes' }
    ];
    bloqueIII.forEach((t, i) => TECNICAS.push({ id: 20+i+1, bloque: 'III', ...t }));

    // BLOQUE IV: Tiempos verbales
    const bloqueIV = [
      { nombre: 'Presente de indicativo', definicion: 'Expresa acciones habituales o hechos actuales.', ejemplo: 'Esp: "Vivo en Madrid. Trabajo todos los días." / Eng: "I live in Madrid. I work every day."', caligrafia: 'caveat' },
      { nombre: 'Pretérito perfecto (he hablado, he comido)', definicion: 'Expresa acciones pasadas con relevancia en el presente.', ejemplo: 'Esp: "He visitado París. He comido paella." / Eng: "I have visited Paris. I have eaten paella."', caligrafia: 'cookie' },
      { nombre: 'Pretérito indefinido (hablé, comí, viví)', definicion: 'Expresa acciones pasadas y terminadas.', ejemplo: 'Esp: "Ayer hablé con Juan. Comí en ese restaurante." / Eng: "Yesterday I spoke with Juan. I ate at that restaurant."', caligrafia: 'tangerine' },
      { nombre: 'Pretérito imperfecto (hablaba, comía, vivía)', definicion: 'Expresa acciones pasadas habituales o en desarrollo.', ejemplo: 'Esp: "Cuando era niño, jugaba en el parque." / Eng: "When I was a child, I played in the park."', caligrafia: 'garabato' },
      { nombre: 'Pretérito pluscuamperfecto (había hablado)', definicion: 'Expresa acciones pasadas anteriores a otra acción pasada.', ejemplo: 'Esp: "Cuando llegué, ya habían salido." / Eng: "When I arrived, they had already left."', caligrafia: 'greatvibes' },
      { nombre: 'Futuro simple (hablaré, comeré, viviré)', definicion: 'Expresa acciones futuras o predicciones.', ejemplo: 'Esp: "Mañana hablaré con él. Viviremos en París." / Eng: "Tomorrow I will talk to him. We will live in Paris."', caligrafia: 'caveat' },
      { nombre: 'Futuro compuesto (habré hablado)', definicion: 'Expresa acciones futuras que se completarán antes de otra acción futura.', ejemplo: 'Esp: "Cuando llegues, ya habré terminado." / Eng: "When you arrive, I will have already finished."', caligrafia: 'tangerine' },
      { nombre: 'Condicional simple (hablaría, comería, viviría)', definicion: 'Expresa hipótesis o acciones dependientes de una condición.', ejemplo: 'Esp: "Si pudiera, viajaría por el mundo." / Eng: "If I could, I would travel the world."', caligrafia: 'cookie' },
      { nombre: 'Condicional compuesto (habría hablado)', definicion: 'Expresa hipótesis sobre acciones pasadas.', ejemplo: 'Esp: "No habría hecho eso." / Eng: "I wouldn\'t have done that."', caligrafia: 'greatvibes' },
      { nombre: 'Imperativo (habla, come, vive)', definicion: 'Expresa órdenes, consejos o peticiones.', ejemplo: 'Esp: "Habla más alto. Come verduras." / Eng: "Speak louder. Eat vegetables."', caligrafia: 'garabato' }
    ];
    bloqueIV.forEach((t, i) => TECNICAS.push({ id: 30+i+1, bloque: 'IV', ...t }));

    // BLOQUE V: Preposiciones
    const bloqueV = [
      { nombre: 'Preposición "a" (movimiento, tiempo)', definicion: 'Indica dirección, tiempo o complemento indirecto.', ejemplo: 'Esp: "Voy a Madrid. Llegamos a las 5." / Eng: "I go to Madrid. We arrive at 5."', caligrafia: 'caveat' },
      { nombre: 'Preposición "de" (origen, posesión, materia)', definicion: 'Indica origen, pertenencia o material.', ejemplo: 'Esp: "Soy de España. La casa de Juan." / Eng: "I am from Spain. Juan\'s house."', caligrafia: 'cookie' },
      { nombre: 'Preposición "en" (lugar, tiempo, modo)', definicion: 'Indica lugar, tiempo o medio.', ejemplo: 'Esp: "Vivo en Madrid. En verano." / Eng: "I live in Madrid. In summer."', caligrafia: 'tangerine' },
      { nombre: 'Preposición "por" (causa, modo, lugar)', definicion: 'Indica causa, medio, o lugar aproximado.', ejemplo: 'Esp: "Gracias por todo. Viajé por Europa." / Eng: "Thanks for everything. I traveled through Europe."', caligrafia: 'greatvibes' },
      { nombre: 'Preposición "para" (finalidad, destino, plazo)', definicion: 'Indica propósito, destino o plazo.', ejemplo: 'Esp: "Estudio para aprender. El regalo es para ti." / Eng: "I study to learn. The gift is for you."', caligrafia: 'garabato' },
      { nombre: 'Preposición "con" (compañía, instrumento)', definicion: 'Indica compañía o instrumento.', ejemplo: 'Esp: "Voy con mi amigo. Corto con tijeras." / Eng: "I go with my friend. I cut with scissors."', caligrafia: 'caveat' },
      { nombre: 'Preposición "sin" (ausencia, carencia)', definicion: 'Indica falta o ausencia.', ejemplo: 'Esp: "Voy sin prisa. Sin dinero no puedo." / Eng: "I go without hurry. Without money I can\'t."', caligrafia: 'cookie' },
      { nombre: 'Preposición "sobre" (encima de, acerca de)', definicion: 'Indica posición superior o tema.', ejemplo: 'Esp: "El libro está sobre la mesa. Hablaron sobre política." / Eng: "The book is on the table. They talked about politics."', caligrafia: 'tangerine' },
      { nombre: 'Preposición "entre" (en medio de)', definicion: 'Indica posición intermedia.', ejemplo: 'Esp: "Estoy entre dos opciones." / Eng: "I am between two options."', caligrafia: 'greatvibes' },
      { nombre: 'Locuciones preposicionales (debajo de, encima de, delante de, detrás de)', definicion: 'Grupos de palabras que funcionan como preposición.', ejemplo: 'Esp: "El gato está debajo de la mesa. La casa está detrás del árbol." / Eng: "The cat is under the table. The house is behind the tree."', caligrafia: 'garabato' }
    ];
    bloqueV.forEach((t, i) => TECNICAS.push({ id: 40+i+1, bloque: 'V', ...t }));

    // BLOQUE VI: Conjunciones
    const bloqueVI = [
      { nombre: 'Conjunciones coordinantes (y, o, pero, sino)', definicion: 'Unen elementos de igual jerarquía.', ejemplo: 'Esp: "Vivo en Madrid y trabajo en Barcelona. Quiero café o té." / Eng: "I live in Madrid and work in Barcelona. I want coffee or tea."', caligrafia: 'caveat' },
      { nombre: 'Conjunciones subordinantes causales (porque, ya que, puesto que)', definicion: 'Indican causa o razón.', ejemplo: 'Esp: "No fui porque estaba enfermo. Ya que llegas tarde, empezamos." / Eng: "I didn\'t go because I was sick. Since you arrive late, we start."', caligrafia: 'cookie' },
      { nombre: 'Conjunciones subordinantes concesivas (aunque, a pesar de que, pese a que)', definicion: 'Indican obstáculo o dificultad.', ejemplo: 'Esp: "Aunque llueve, salgo. A pesar de que está lejos, voy." / Eng: "Although it rains, I go out. Despite being far, I go."', caligrafia: 'tangerine' },
      { nombre: 'Conjunciones subordinantes condicionales (si, siempre que, con tal de que)', definicion: 'Indican condición.', ejemplo: 'Esp: "Si estudias, apruebas. Siempre que vengas, te ayudo." / Eng: "If you study, you pass. As long as you come, I help you."', caligrafia: 'greatvibes' },
      { nombre: 'Conjunciones subordinantes finales (para que, a fin de que)', definicion: 'Indican propósito.', ejemplo: 'Esp: "Estudio para que me den el título." / Eng: "I study so that they give me the degree."', caligrafia: 'garabato' },
      { nombre: 'Conjunciones subordinantes consecutivas (así que, por tanto, luego)', definicion: 'Indican consecuencia.', ejemplo: 'Esp: "Llegué tarde, así que me fui." / Eng: "I arrived late, so I left."', caligrafia: 'caveat' },
      { nombre: 'Conjunciones subordinantes comparativas (como, igual que, más... que)', definicion: 'Indican comparación.', ejemplo: 'Esp: "Estudia como su hermano. Es más alto que yo." / Eng: "He studies like his brother. He is taller than me."', caligrafia: 'cookie' },
      { nombre: 'Conjunciones subordinantes temporales (cuando, mientras, antes de que, después de que)', definicion: 'Indican tiempo.', ejemplo: 'Esp: "Cuando llegues, avísame. Mientras estudio, escucho música." / Eng: "When you arrive, tell me. While I study, I listen to music."', caligrafia: 'tangerine' },
      { nombre: 'Conjunciones subordinantes modales (como, según, conforme)', definicion: 'Indican modo.', ejemplo: 'Esp: "Hazlo como quieras. Según dice el profesor." / Eng: "Do it as you want. According to the teacher."', caligrafia: 'greatvibes' },
      { nombre: 'Conjunciones subordinantes dubitativas (quizás, tal vez, probablemente)', definicion: 'Indican duda.', ejemplo: 'Esp: "Quizás venga mañana. Tal vez estudie más tarde." / Eng: "Maybe I will come tomorrow. Perhaps I will study later."', caligrafia: 'garabato' }
    ];
    bloqueVI.forEach((t, i) => TECNICAS.push({ id: 50+i+1, bloque: 'VI', ...t }));

    // BLOQUE VII: Adverbios
    const bloqueVII = [
      { nombre: 'Adverbios de lugar (aquí, allí, cerca, lejos, dentro, fuera)', definicion: 'Indican ubicación o dirección.', ejemplo: 'Esp: "Vivo aquí. El parque está cerca." / Eng: "I live here. The park is near."', caligrafia: 'caveat' },
      { nombre: 'Adverbios de tiempo (ahora, después, antes, siempre, nunca, ya)', definicion: 'Indican momento, frecuencia o duración.', ejemplo: 'Esp: "Ahora estudio. Siempre llego temprano." / Eng: "Now I study. I always arrive early."', caligrafia: 'cookie' },
      { nombre: 'Adverbios de modo (bien, mal, así, despacio, rápido)', definicion: 'Indican manera o modo.', ejemplo: 'Esp: "Habla bien. Camina despacio." / Eng: "He speaks well. He walks slowly."', caligrafia: 'tangerine' },
      { nombre: 'Adverbios de cantidad (mucho, poco, bastante, demasiado, casi)', definicion: 'Indican intensidad o grado.', ejemplo: 'Esp: "Estudia mucho. Hay bastante comida." / Eng: "He studies a lot. There is enough food."', caligrafia: 'greatvibes' },
      { nombre: 'Adverbios de afirmación (sí, también, realmente, efectivamente)', definicion: 'Expresan acuerdo o confirmación.', ejemplo: 'Esp: "Sí, quiero ir. También me gusta." / Eng: "Yes, I want to go. I also like it."', caligrafia: 'garabato' },
      { nombre: 'Adverbios de negación (no, nunca, jamás, tampoco)', definicion: 'Expresan negación o rechazo.', ejemplo: 'Esp: "No quiero. Nunca he estado." / Eng: "I don\'t want to. I have never been."', caligrafia: 'caveat' },
      { nombre: 'Adverbios de duda (quizás, tal vez, acaso)', definicion: 'Expresan incertidumbre.', ejemplo: 'Esp: "Quizás venga. Tal vez no." / Eng: "Maybe I will come. Perhaps not."', caligrafia: 'cookie' },
      { nombre: 'Adverbios relativos (donde, cuando, como)', definicion: 'Introducen oraciones subordinadas.', ejemplo: 'Esp: "La casa donde vivo. El día cuando llegaste." / Eng: "The house where I live. The day when you arrived."', caligrafia: 'tangerine' },
      { nombre: 'Adverbios interrogativos (dónde, cuándo, cómo, cuánto)', definicion: 'Se usan para preguntar.', ejemplo: 'Esp: "¿Dónde vives? ¿Cuándo llegas?" / Eng: "Where do you live? When do you arrive?"', caligrafia: 'greatvibes' },
      { nombre: 'Locuciones adverbiales (a veces, de repente, por supuesto)', definicion: 'Grupos de palabras que funcionan como adverbio.', ejemplo: 'Esp: "A veces voy al cine. De repente empezó a llover." / Eng: "Sometimes I go to the cinema. Suddenly it started to rain."', caligrafia: 'garabato' }
    ];
    bloqueVII.forEach((t, i) => TECNICAS.push({ id: 60+i+1, bloque: 'VII', ...t }));

    // BLOQUE VIII: Estructuras comparativas y superlativas
    const bloqueVIII = [
      { nombre: 'Comparativo de superioridad (más... que)', definicion: 'Indica que algo es mayor en comparación con otro.', ejemplo: 'Esp: "Juan es más alto que Pedro." / Eng: "Juan is taller than Pedro."', caligrafia: 'caveat' },
      { nombre: 'Comparativo de inferioridad (menos... que)', definicion: 'Indica que algo es menor en comparación con otro.', ejemplo: 'Esp: "Este libro es menos interesante que el otro." / Eng: "This book is less interesting than the other."', caligrafia: 'cookie' },
      { nombre: 'Comparativo de igualdad (tan... como)', definicion: 'Indica que algo es igual en comparación con otro.', ejemplo: 'Esp: "Ella es tan inteligente como su hermano." / Eng: "She is as intelligent as her brother."', caligrafia: 'tangerine' },
      { nombre: 'Comparativos irregulares (mejor/peor, mayor/menor)', definicion: 'Comparativos de bueno, malo, grande, pequeño.', ejemplo: 'Esp: "Este vino es mejor que aquel. La ciudad es mayor que el pueblo." / Eng: "This wine is better than that one. The city is bigger than the town."', caligrafia: 'greatvibes' },
      { nombre: 'Superlativo absoluto (muy + adjetivo, -ísimo)', definicion: 'Expresa el grado máximo de una cualidad.', ejemplo: 'Esp: "Muy alto. Altísimo. Felicísimo." / Eng: "Very tall. Extremely tall. Very happy."', caligrafia: 'garabato' },
      { nombre: 'Superlativo relativo (el/la más... de)', definicion: 'Expresa el grado máximo en un grupo.', ejemplo: 'Esp: "Ella es la más inteligente de la clase." / Eng: "She is the most intelligent in the class."', caligrafia: 'caveat' },
      { nombre: 'Superlativos irregulares (óptimo, pésimo, máximo, mínimo)', definicion: 'Superlativos de bueno, malo, grande, pequeño.', ejemplo: 'Esp: "El óptimo resultado. El pésimo servicio." / Eng: "The optimal result. The worst service."', caligrafia: 'cookie' },
      { nombre: 'Falsos comparativos (mayor que, menor que, superior a, inferior a)', definicion: 'Expresiones comparativas formales.', ejemplo: 'Esp: "La temperatura es superior a 30°C. El coste es inferior al esperado." / Eng: "The temperature is above 30°C. The cost is below expected."', caligrafia: 'tangerine' },
      { nombre: 'Comparación con verbos (hacer + sustantivo)', definicion: 'Comparaciones con verbos de acción.', ejemplo: 'Esp: "Juan corre más rápido que Pedro." / Eng: "Juan runs faster than Pedro."', caligrafia: 'greatvibes' },
      { nombre: 'Comparación con adverbios (más/menos + adverbio + que)', definicion: 'Comparaciones con adverbios.', ejemplo: 'Esp: "Ella habla más rápido que yo." / Eng: "She speaks faster than me."', caligrafia: 'garabato' }
    ];
    bloqueVIII.forEach((t, i) => TECNICAS.push({ id: 70+i+1, bloque: 'VIII', ...t }));

    // BLOQUE IX: Oraciones subordinadas
    const bloqueIX = [
      { nombre: 'Oración subordinada sustantiva (que + verbo)', definicion: 'Funciona como sustantivo (sujeto, objeto).', ejemplo: 'Esp: "Creo que es importante. Es evidente que estudia." / Eng: "I think it\'s important. It\'s obvious that he studies."', caligrafia: 'caveat' },
      { nombre: 'Oración subordinada adjetiva (que/quien + verbo)', definicion: 'Modifica a un sustantivo.', ejemplo: 'Esp: "El libro que leí es interesante. La persona a quien vi." / Eng: "The book that I read is interesting. The person whom I saw."', caligrafia: 'cookie' },
      { nombre: 'Oración subordinada adverbial de tiempo (cuando, mientras, antes de que)', definicion: 'Expresa circunstancias de tiempo.', ejemplo: 'Esp: "Cuando llegues, avísame." / Eng: "When you arrive, let me know."', caligrafia: 'tangerine' },
      { nombre: 'Oración subordinada adverbial de lugar (donde, adonde)', definicion: 'Expresa circunstancias de lugar.', ejemplo: 'Esp: "Vivo donde nací." / Eng: "I live where I was born."', caligrafia: 'greatvibes' },
      { nombre: 'Oración subordinada adverbial de modo (como, según, conforme)', definicion: 'Expresa circunstancias de modo.', ejemplo: 'Esp: "Hazlo como quieras." / Eng: "Do it as you want."', caligrafia: 'garabato' },
      { nombre: 'Oración subordinada adverbial causal (porque, ya que, puesto que)', definicion: 'Expresa causa.', ejemplo: 'Esp: "No fui porque estaba cansado." / Eng: "I didn\'t go because I was tired."', caligrafia: 'caveat' },
      { nombre: 'Oración subordinada adverbial condicional (si, con tal de que)', definicion: 'Expresa condición.', ejemplo: 'Esp: "Si estudias, apruebas." / Eng: "If you study, you pass."', caligrafia: 'cookie' },
      { nombre: 'Oración subordinada adverbial concesiva (aunque, a pesar de que)', definicion: 'Expresa concesión.', ejemplo: 'Esp: "Aunque llueve, salgo." / Eng: "Although it rains, I go out."', caligrafia: 'tangerine' },
      { nombre: 'Oración subordinada adverbial final (para que, a fin de que)', definicion: 'Expresa finalidad.', ejemplo: 'Esp: "Estudio para que me den el título." / Eng: "I study so that they give me the degree."', caligrafia: 'greatvibes' },
      { nombre: 'Oración subordinada adverbial consecutiva (así que, por tanto, luego)', definicion: 'Expresa consecuencia.', ejemplo: 'Esp: "Llegué tarde, así que me fui." / Eng: "I arrived late, so I left."', caligrafia: 'garabato' }
    ];
    bloqueIX.forEach((t, i) => TECNICAS.push({ id: 80+i+1, bloque: 'IX', ...t }));

    // BLOQUE X: Estilo y registro
    const bloqueX = [
      { nombre: 'Registro formal en español', definicion: 'Uso de "usted", "ustedes", lenguaje cuidado.', ejemplo: 'Esp: "¿Cómo está usted? Le agradezco su atención." / Eng: "How are you? I appreciate your attention."', caligrafia: 'greatvibes' },
      { nombre: 'Registro informal (tú, vosotros)', definicion: 'Lenguaje coloquial, cercano.', ejemplo: 'Esp: "¿Cómo estás? ¿Qué tal?" / Eng: "How are you? What\'s up?"', caligrafia: 'cookie' },
      { nombre: 'Tuteo vs. voseo', definicion: 'Uso de "tú" o "vos" según región.', ejemplo: 'Esp: "Tú eres (Argentina: Vos sos)." / Eng: "You are (Argentina: You are)."', caligrafia: 'garabato' },
      { nombre: 'Diferencias español/inglés en fórmulas de cortesía', definicion: 'Expresiones de cortesía distintas.', ejemplo: 'Esp: "Por favor, gracias, de nada." / Eng: "Please, thank you, you\'re welcome."', caligrafia: 'caveat' },
      { nombre: 'Expresiones coloquiales (¡vaya!, ¡anda!, ¡ole!)', definicion: 'Interjecciones y expresiones de sorpresa.', ejemplo: 'Esp: "¡Vaya! ¿Qué haces aquí? ¡Ole!" / Eng: "Wow! What are you doing here? Bravo!"', caligrafia: 'cookie' },
      { nombre: 'Refranes y dichos populares', definicion: 'Expresiones idiomáticas y sabiduría popular.', ejemplo: 'Esp: "Más vale tarde que nunca. A quien madruga, Dios le ayuda." / Eng: "Better late than never. The early bird catches the worm."', caligrafia: 'tangerine' },
      { nombre: 'Uso de "sí" y "no" en respuestas', definicion: 'Respuestas afirmativas y negativas.', ejemplo: 'Esp: "¿Quieres café? Sí, gracias. No, gracias." / Eng: "Do you want coffee? Yes, thank you. No, thank you."', caligrafia: 'garabato' },
      { nombre: 'Falsos amigos en español-inglés', definicion: 'Palabras que se parecen pero tienen significado diferente.', ejemplo: 'Esp: "Embarazada" (pregnant) no "embarrassed". "Éxito" (success) no "exit".', caligrafia: 'greatvibes' },
      { nombre: 'Uso de diminutivos y aumentativos (-ito, -ón)', definicion: 'Expresan tamaño o afecto.', ejemplo: 'Esp: "Casita (little house), grandote (big)." / Eng: "Little house, big."', caligrafia: 'caveat' },
      { nombre: 'Expresiones de tiempo (hace, desde, desde hace)', definicion: 'Indican duración o punto de partida.', ejemplo: 'Esp: "Hace dos años que estudio. Desde 2020. Desde hace tres meses." / Eng: "I have been studying for two years. Since 2020. For three months."', caligrafia: 'cookie' }
    ];
    bloqueX.forEach((t, i) => TECNICAS.push({ id: 90+i+1, bloque: 'X', ...t }));

    // ----------------------------------------------------------------
    // 2. ESTADO Y ALMACENAMIENTO
    // ----------------------------------------------------------------
    const STORAGE_KEY = 'cuadernoCaligraficoGramatica100';
    const CUADERNO_KEY = 'cuadernoCaligrafico_entradas';
    const CALIGRAFIA_KEY = 'cuadernoCaligrafico_frases';
    const ESTADISTICAS_KEY = 'cuadernoCaligrafico_estadisticas';
    let progreso = {};
    let modoActual = 'explorar';
    let bloqueFiltro = 'todos';
    let voiceEnabled = false;
    let speechSynth = window.speechSynthesis;
    let utterance = null;
    let flashIndex = 0;
    let flashList = [];
    let entradasCuaderno = [];
    let frasesCaligrafia = [];
    let estadisticas = { racha: 0, aciertos: 0, intentos: 0 };
    let niveles = {};
    let caligrafiaActual = 'caveat';

    function cargarProgreso() {
      try {
        const data = localStorage.getItem(STORAGE_KEY);
        if (data) progreso = JSON.parse(data);
        else progreso = {};
      } catch (e) { progreso = {}; }
      try {
        const data = localStorage.getItem(CUADERNO_KEY);
        if (data) entradasCuaderno = JSON.parse(data);
        else entradasCuaderno = [];
      } catch (e) { entradasCuaderno = []; }
      try {
        const data = localStorage.getItem(CALIGRAFIA_KEY);
        if (data) frasesCaligrafia = JSON.parse(data);
        else frasesCaligrafia = [];
      } catch (e) { frasesCaligrafia = []; }
      try {
        const data = localStorage.getItem(ESTADISTICAS_KEY);
        if (data) estadisticas = JSON.parse(data);
        else estadisticas = { racha: 0, aciertos: 0, intentos: 0 };
      } catch (e) { estadisticas = { racha: 0, aciertos: 0, intentos: 0 }; }
      try {
        const data = localStorage.getItem(STORAGE_KEY + '_niveles');
        if (data) niveles = JSON.parse(data);
        else niveles = {};
      } catch (e) { niveles = {}; }
    }

    function guardarProgreso() {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(progreso));
      localStorage.setItem(CUADERNO_KEY, JSON.stringify(entradasCuaderno));
      localStorage.setItem(CALIGRAFIA_KEY, JSON.stringify(frasesCaligrafia));
      localStorage.setItem(ESTADISTICAS_KEY, JSON.stringify(estadisticas));
      localStorage.setItem(STORAGE_KEY + '_niveles', JSON.stringify(niveles));
      actualizarContador();
    }

    function toggleAprendida(id) {
      if (progreso[id]) {
        delete progreso[id];
        estadisticas.racha = 0;
      } else {
        progreso[id] = true;
        estadisticas.racha++;
        estadisticas.aciertos++;
        niveles[id] = (niveles[id] || 0) + 1;
      }
      estadisticas.intentos++;
      guardarProgreso();
      renderizar();
      if (modoActual === 'flashcards') mostrarFlashcard(flashIndex);
    }

    function actualizarContador() {
      const total = TECNICAS.length;
      const aprendidas = Object.keys(progreso).filter(k => progreso[k]).length;
      document.getElementById('contadorAprendidas').textContent = `${aprendidas}/${total}`;
      if (modoActual === 'progreso') actualizarEstadisticas();
    }

    function getTecnicasFiltradas() {
      let lista = TECNICAS;
      if (bloqueFiltro !== 'todos') lista = lista.filter(t => t.bloque === bloqueFiltro);
      return lista;
    }

    function leerTexto(texto) {
      if (!voiceEnabled) return;
      if (speechSynth.speaking) speechSynth.cancel();
      utterance = new SpeechSynthesisUtterance(texto);
      utterance.lang = 'es-ES';
      utterance.rate = 0.9;
      utterance.pitch = 1;
      speechSynth.speak(utterance);
    }

    function getClaseCaligrafia(caligrafia) {
      return clasesCaligrafia[caligrafia] || 'fuente-caveat';
    }

    function getNombreCaligrafia(caligrafia) {
      return nombresCaligrafia[caligrafia] || 'Caveat';
    }

    // ----------------------------------------------------------------
    // 3. FLASHCARDS
    // ----------------------------------------------------------------
    function mostrarFlashcard(index) {
      const lista = getTecnicasFiltradas();
      if (lista.length === 0) {
        document.getElementById('flashcardContainer').style.display = 'none';
        return;
      }
      flashList = lista;
      if (index >= lista.length) index = 0;
      if (index < 0) index = lista.length - 1;
      flashIndex = index;

      const t = lista[index];
      const aprendida = progreso[t.id] || false;

      document.getElementById('flashBloque').textContent = t.bloque;
      document.getElementById('flashNombre').textContent = t.nombre;
      document.getElementById('flashBloqueBack').textContent = t.bloque;
      document.getElementById('flashNombreBack').textContent = t.nombre;
      document.getElementById('flashDefinicion').textContent = t.definicion;
      document.getElementById('flashEjemplo').textContent = t.ejemplo;

      document.getElementById('flashContador').textContent = `${index+1} / ${lista.length}`;

      const flashcard = document.getElementById('flashcard');
      flashcard.classList.remove('revelada');
      document.getElementById('flashVoltear').innerHTML = '<i class="bi bi-arrow-repeat"></i> Voltear';

      const firmarBtn = document.getElementById('flashFirmar');
      if (aprendida) {
        firmarBtn.innerHTML = '<i class="bi bi-check2-circle"></i> Firmada';
        firmarBtn.className = 'btn btn-success';
      } else {
        firmarBtn.innerHTML = '<i class="bi bi-pen"></i> Firmar';
        firmarBtn.className = 'btn btn-outline-warning';
      }
      actualizarContador();
    }

    function flashVoltear() {
      const flashcard = document.getElementById('flashcard');
      flashcard.classList.toggle('revelada');
      const btn = document.getElementById('flashVoltear');
      btn.innerHTML = flashcard.classList.contains('revelada') ? '<i class="bi bi-arrow-repeat"></i> Ocultar' : '<i class="bi bi-arrow-repeat"></i> Voltear';
    }

    function flashNext() { mostrarFlashcard(flashIndex + 1); document.getElementById('flashcard').classList.remove('revelada'); document.getElementById('flashVoltear').innerHTML = '<i class="bi bi-arrow-repeat"></i> Voltear'; }
    function flashPrev() { mostrarFlashcard(flashIndex - 1); document.getElementById('flashcard').classList.remove('revelada'); document.getElementById('flashVoltear').innerHTML = '<i class="bi bi-arrow-repeat"></i> Voltear'; }
    function flashFirmar() {
      const lista = getTecnicasFiltradas();
      if (lista.length === 0) return;
      toggleAprendida(lista[flashIndex].id);
      mostrarFlashcard(flashIndex);
    }
    function flashVoice() {
      const lista = getTecnicasFiltradas();
      if (lista.length === 0) return;
      const t = lista[flashIndex];
      leerTexto(`${t.nombre}: ${t.definicion}. Ejemplo: ${t.ejemplo}`);
    }

    // ----------------------------------------------------------------
    // 4. BITÁCORA (guardado automático)
    // ----------------------------------------------------------------
    function renderizarCuaderno() {
      const container = document.getElementById('miCuadernoLista');
      if (entradasCuaderno.length === 0) {
        container.innerHTML = '<p class="text-muted">Aún no has guardado ninguna entrada en tu bitácora. Escribe en el modo Practicar para empezar.</p>';
        return;
      }
      const html = entradasCuaderno.slice().reverse().map((entry, idx) => {
        const realIndex = entradasCuaderno.length - 1 - idx;
        const claseCalig = getClaseCaligrafia(entry.caligrafia || 'caveat');
        return `
          <div class="cuaderno-entry">
            <div class="d-flex justify-content-between">
              <strong>${entry.nombreTecnica}</strong>
              <span class="fecha">${entry.fecha}</span>
            </div>
            <div><span class="text-muted">Tu respuesta:</span> <span class="respuesta">${entry.respuestaUsuario || '(vacío)'}</span></div>
            <div><span class="text-muted">Caligrafía:</span> <span class="${claseCalig}">${getNombreCaligrafia(entry.caligrafia || 'caveat')}</span></div>
            <div><span class="text-muted">Firma:</span> <span class="firma">${entry.firma || '(sin firma)'}</span></div>
            <button class="btn btn-outline-danger btn-sm mt-1" data-borrar="${realIndex}"><i class="bi bi-x-circle"></i> Borrar</button>
          </div>
        `;
      }).join('');
      container.innerHTML = html;
      container.querySelectorAll('[data-borrar]').forEach(btn => {
        btn.addEventListener('click', function() {
          const idx = parseInt(this.dataset.borrar);
          entradasCuaderno.splice(idx, 1);
          guardarProgreso();
          renderizarCuaderno();
        });
      });
    }

    function guardarEntradaCuaderno(tecnicaId, respuesta, firma, caligrafia) {
      const tec = TECNICAS.find(t => t.id === tecnicaId);
      if (!tec) return;
      const fecha = new Date().toLocaleString();
      entradasCuaderno.push({
        tecnicaId: tecnicaId,
        nombreTecnica: tec.nombre,
        respuestaUsuario: respuesta.trim(),
        firma: firma.trim() || '(sin firma)',
        caligrafia: caligrafia || tec.caligrafia || 'caveat',
        fecha: fecha
      });
      guardarProgreso();
      renderizarCuaderno();
    }

    // ----------------------------------------------------------------
    // 5. CALIGRAFÍA
    // ----------------------------------------------------------------
    function renderizarCaligrafia() {
      document.querySelectorAll('.btn-caligrafia').forEach(btn => {
        btn.classList.toggle('active', btn.dataset.caligrafia === caligrafiaActual);
      });
      document.getElementById('caligrafiaNombre').textContent = getNombreCaligrafia(caligrafiaActual);
      document.getElementById('caligrafiaPreview').style.fontFamily = getClaseCaligrafia(caligrafiaActual);
      document.getElementById('inputCaligrafia').style.fontFamily = getClaseCaligrafia(caligrafiaActual);

      const container = document.getElementById('frasesCaligrafia');
      const frasesFiltradas = frasesCaligrafia.filter(f => f.caligrafia === caligrafiaActual);
      if (frasesFiltradas.length === 0) {
        container.innerHTML = '<p class="text-muted small">No hay frases guardadas en esta caligrafía.</p>';
      } else {
        container.innerHTML = frasesFiltradas.map((f, i) => `
          <div class="d-flex justify-content-between align-items-center small p-1 border-bottom">
            <span style="font-family:${getClaseCaligrafia(f.caligrafia)};font-size:1.1rem;">${f.texto}</span>
            <button class="btn btn-outline-danger btn-sm" data-borrar-frase="${i}"><i class="bi bi-x"></i></button>
          </div>
        `).join('');
        container.querySelectorAll('[data-borrar-frase]').forEach(btn => {
          btn.addEventListener('click', function() {
            const idx = parseInt(this.dataset.borrar-frase);
            frasesCaligrafia.splice(idx, 1);
            guardarProgreso();
            renderizarCaligrafia();
          });
        });
      }

      const asociacionContainer = document.getElementById('asociacionCaligrafia');
      const asociaciones = [
        { caligrafia: 'caveat', descripcion: 'Oraciones simples, registro coloquial' },
        { caligrafia: 'tangerine', descripcion: 'Subordinación, registro literario' },
        { caligrafia: 'cookie', descripcion: 'Registro coloquial, conectores' },
        { caligrafia: 'greatvibes', descripcion: 'Formal, voz pasiva' },
        { caligrafia: 'garabato', descripcion: 'Exploración, falsos amigos' }
      ];
      asociacionContainer.innerHTML = asociaciones.map(a => `
        <div class="col-6 col-md-4">
          <div class="stat-card text-center p-2 ${a.caligrafia === caligrafiaActual ? 'border border-indigo' : ''}" style="font-family:${getClaseCaligrafia(a.caligrafia)};">
            <strong>${getNombreCaligrafia(a.caligrafia)}</strong>
            <div class="small">${a.descripcion}</div>
          </div>
        </div>
      `).join('');
    }

    function guardarFraseCaligrafia() {
      const input = document.getElementById('inputCaligrafia');
      const texto = input.value.trim();
      if (!texto) {
        alert('Escribe una frase primero.');
        return;
      }
      frasesCaligrafia.push({ caligrafia: caligrafiaActual, texto: texto });
      guardarProgreso();
      input.value = '';
      renderizarCaligrafia();
    }

    // ----------------------------------------------------------------
    // 6. ESTADÍSTICAS
    // ----------------------------------------------------------------
    function actualizarEstadisticas() {
      const total = TECNICAS.length;
      const aprendidas = Object.keys(progreso).filter(k => progreso[k]).length;
      const pct = Math.round((aprendidas / total) * 100);
      document.getElementById('statAprendidas').textContent = aprendidas;
      document.getElementById('statRacha').textContent = estadisticas.racha || 0;
      document.getElementById('statDominio').textContent = pct + '%';
      document.getElementById('statEntradas').textContent = entradasCuaderno.length;

      const bloques = ['I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX', 'X'];
      let html = '<h6 class="mt-3">Dominio por bloque</h6><div class="row g-2">';
      bloques.forEach(b => {
        const tecBloque = TECNICAS.filter(t => t.bloque === b);
        const aprendidasBloque = tecBloque.filter(t => progreso[t.id]).length;
        const pctBloque = tecBloque.length > 0 ? Math.round((aprendidasBloque / tecBloque.length) * 100) : 0;
        html += `
          <div class="col-6 col-md-3">
            <div class="stat-card text-center p-2">
              <div class="fw-bold">Bloque ${b}</div>
              <div class="progress" style="height:6px;margin:4px 0;">
                <div class="progress-fill" style="width:${pctBloque}%;"></div>
              </div>
              <small>${aprendidasBloque}/${tecBloque.length} (${pctBloque}%)</small>
            </div>
          </div>
        `;
      });
      html += '</div>';
      document.getElementById('estadisticasDetalladas').innerHTML = html;
    }

    // ----------------------------------------------------------------
    // 7. EXAMEN
    // ----------------------------------------------------------------
    function generarExamen() {
      const cantidad = parseInt(document.getElementById('examenCantidad').value);
      const dificultad = document.getElementById('examenDificultad').value;
      let pool = TECNICAS;
      if (dificultad === 'facil') pool = TECNICAS.filter(t => !progreso[t.id]);
      else if (dificultad === 'dificil') pool = TECNICAS.filter(t => progreso[t.id]);
      if (pool.length === 0) {
        document.getElementById('examenPreguntas').innerHTML = '<div class="alert alert-warning">No hay técnicas en el rango seleccionado.</div>';
        return;
      }
      const shuffled = pool.sort(() => Math.random() - 0.5);
      const seleccionadas = shuffled.slice(0, Math.min(cantidad, shuffled.length));
      let html = '';
      seleccionadas.forEach((t, idx) => {
        const opciones = pool.filter(o => o.id !== t.id).sort(() => Math.random() - 0.5).slice(0, 3);
        const todasOpciones = [t, ...opciones].sort(() => Math.random() - 0.5);
        html += `
          <div class="cuaderno-entry mb-2" data-examen="${idx}">
            <p><strong>${idx+1}.</strong> <span class="definicion-examen">${t.definicion}</span></p>
            <div class="opciones-examen">
              ${todasOpciones.map((o, oi) => `
                <div class="form-check">
                  <input class="form-check-input opcion-examen" type="radio" name="examen_${idx}" value="${o.id}" id="examen_${idx}_${oi}">
                  <label class="form-check-label" for="examen_${idx}_${oi}">${o.nombre}</label>
                </div>
              `).join('')}
            </div>
            <div class="feedback-examen mt-1"></div>
          </div>
        `;
      });
      document.getElementById('examenPreguntas').innerHTML = html;
      document.getElementById('examenResultados').innerHTML = '';
      document.getElementById('btnGenerarExamen').dataset.respuestas = JSON.stringify(seleccionadas.map(t => t.id));
    }

    function corregirExamen() {
      const respuestasCorrectas = JSON.parse(document.getElementById('btnGenerarExamen').dataset.respuestas || '[]');
      let aciertos = 0;
      document.querySelectorAll('[data-examen]').forEach((div, idx) => {
        const selected = div.querySelector('input[type="radio"]:checked');
        const feedback = div.querySelector('.feedback-examen');
        const correcta = respuestasCorrectas[idx];
        if (selected) {
          const valor = parseInt(selected.value);
          if (valor === correcta) {
            aciertos++;
            feedback.innerHTML = '<span class="text-success">✓ Correcto</span>';
          } else {
            const nombreCorrecto = TECNICAS.find(t => t.id === correcta)?.nombre || 'desconocida';
            feedback.innerHTML = `<span class="text-danger">✗ Incorrecto. La respuesta correcta es: ${nombreCorrecto}</span>`;
          }
        } else {
          const nombreCorrecto = TECNICAS.find(t => t.id === correcta)?.nombre || 'desconocida';
          feedback.innerHTML = `<span class="text-warning">⚠ No respondiste. La respuesta correcta es: ${nombreCorrecto}</span>`;
        }
      });
      document.getElementById('examenResultados').innerHTML = `
        <div class="alert alert-info">
          <strong>Resultado:</strong> ${aciertos} de ${respuestasCorrectas.length} correctas 
          (${Math.round((aciertos/respuestasCorrectas.length)*100)}%)
        </div>
        <button class="btn btn-indigo" onclick="window.location.reload()"><i class="bi bi-arrow-repeat"></i> Nuevo examen</button>
      `;
    }

    // ----------------------------------------------------------------
    // 8. EXPORTACIÓN
    // ----------------------------------------------------------------
    function exportarCSV() {
      let csv = 'Técnica,Definición,Ejemplo,Bloque,Caligrafía,Estado,Fecha\n';
      TECNICAS.forEach(t => {
        const estado = progreso[t.id] ? 'Aprendida' : 'Pendiente';
        const fecha = entradasCuaderno.find(e => e.tecnicaId === t.id)?.fecha || '';
        csv += `"${t.nombre}","${t.definicion}","${t.ejemplo}",${t.bloque},${t.caligrafia},${estado},"${fecha}"\n`;
      });
      const blob = new Blob([csv], { type: 'text/csv' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'cuaderno_caligrafico.csv';
      a.click();
      URL.revokeObjectURL(url);
    }

    function exportarJSON() {
      const data = {
        tecnicas: TECNICAS,
        progreso: progreso,
        entradas: entradasCuaderno,
        frasesCaligrafia: frasesCaligrafia,
        estadisticas: estadisticas,
        fecha: new Date().toISOString()
      };
      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'cuaderno_caligrafico.json';
      a.click();
      URL.revokeObjectURL(url);
    }

    // ----------------------------------------------------------------
    // 9. RENDER PRINCIPAL
    // ----------------------------------------------------------------
    function renderizar() {
      const grid = document.getElementById('gridTecnicas');
      const flashContainer = document.getElementById('flashcardContainer');
      const caligrafiaContainer = document.getElementById('caligrafiaContainer');
      const miCuadernoContainer = document.getElementById('miCuadernoContainer');
      const progresoContainer = document.getElementById('progresoContainer');
      const examenContainer = document.getElementById('examenContainer');
      const lista = getTecnicasFiltradas();
      document.getElementById('resultCount').textContent = `${lista.length} técnicas`;

      grid.style.display = 'none';
      flashContainer.style.display = 'none';
      caligrafiaContainer.style.display = 'none';
      miCuadernoContainer.style.display = 'none';
      progresoContainer.style.display = 'none';
      examenContainer.style.display = 'none';

      if (modoActual === 'flashcards') {
        flashContainer.style.display = 'block';
        if (lista.length > 0) mostrarFlashcard(0);
        else flashContainer.innerHTML = `<div class="alert alert-warning">No hay técnicas en este bloque.</div>`;
        return;
      }

      if (modoActual === 'caligrafia') {
        caligrafiaContainer.style.display = 'block';
        renderizarCaligrafia();
        return;
      }

      if (modoActual === 'cuaderno') {
        miCuadernoContainer.style.display = 'block';
        renderizarCuaderno();
        return;
      }

      if (modoActual === 'progreso') {
        progresoContainer.style.display = 'block';
        actualizarEstadisticas();
        return;
      }

      if (modoActual === 'examen') {
        examenContainer.style.display = 'block';
        if (!document.getElementById('examenPreguntas').innerHTML) {
          generarExamen();
        }
        return;
      }

      grid.style.display = 'flex';
      const caligrafiaClass = getClaseCaligrafia(caligrafiaActual);

      if (modoActual === 'explorar') {
        grid.innerHTML = lista.map(t => {
          const aprendida = progreso[t.id] || false;
          const claseCalig = getClaseCaligrafia(t.caligrafia || 'caveat');
          return `
            <div class="col-12 col-md-6 col-lg-4">
              <div class="card-cuaderno">
                <div class="d-flex justify-content-between align-items-start">
                  <span class="badge-bloque">${t.bloque}</span>
                  <span class="badge bg-${aprendida ? 'success' : 'secondary'} rounded-pill">${aprendida ? '✓ Aprendida' : 'Pendiente'}</span>
                </div>
                <h6 class="card-title mt-2">${t.nombre}</h6>
                <p class="definicion small">${t.definicion}</p>
                <p class="ejemplo-cursiva small ${claseCalig}"><i class="bi bi-quote"></i> ${t.ejemplo}</p>
                <div class="d-flex justify-content-between align-items-center mt-2">
                  <span class="badge bg-info text-dark" style="font-size:0.65rem;">${getNombreCaligrafia(t.caligrafia || 'caveat')}</span>
                  <div>
                    <button class="btn btn-outline-indigo btn-sm btn-voice" data-id="${t.id}" title="Escuchar"><i class="bi bi-volume-up"></i></button>
                    <button class="btn btn-sm ${aprendida ? 'btn-outline-warning' : 'btn-indigo'} btn-firmar" data-id="${t.id}">${aprendida ? '<i class="bi bi-check2-circle"></i>' : '<i class="bi bi-pen"></i>'}</button>
                  </div>
                </div>
              </div>
            </div>
          `;
        }).join('');
      } else if (modoActual === 'practicar') {
        grid.innerHTML = lista.map(t => {
          const aprendida = progreso[t.id] || false;
          const claseCalig = getClaseCaligrafia(t.caligrafia || 'caveat');
          return `
            <div class="col-12 col-md-6 col-lg-4">
              <div class="card-cuaderno" data-practica-id="${t.id}">
                <div class="d-flex justify-content-between align-items-start">
                  <span class="badge-bloque">${t.bloque}</span>
                  <span class="badge bg-${aprendida ? 'success' : 'secondary'} rounded-pill">${aprendida ? '✓' : '?'}</span>
                </div>
                <h6 class="card-title mt-2">${t.nombre}</h6>
                <p class="definicion small" style="filter:blur(4px);user-select:none;">${t.definicion}</p>
                <p class="ejemplo-cursiva small ${claseCalig}" style="filter:blur(4px);user-select:none;"><i class="bi bi-quote"></i> ${t.ejemplo}</p>
                <div class="d-flex justify-content-between mt-2">
                  <span class="badge bg-info text-dark" style="font-size:0.65rem;">${getNombreCaligrafia(t.caligrafia || 'caveat')}</span>
                  <div>
                    <button class="btn btn-outline-indigo btn-sm btn-revelar-practica" data-id="${t.id}"><i class="bi bi-eye"></i></button>
                    <button class="btn btn-sm btn-outline-info btn-practicar-detalle" data-id="${t.id}"><i class="bi bi-pencil"></i></button>
                    <button class="btn btn-sm ${aprendida ? 'btn-outline-warning' : 'btn-indigo'} btn-firmar" data-id="${t.id}">${aprendida ? '<i class="bi bi-check2-circle"></i>' : '<i class="bi bi-pen"></i>'}</button>
                  </div>
                </div>
              </div>
            </div>
          `;
        }).join('');
      }

      asignarEventos();
      actualizarContador();
    }

    // ----------------------------------------------------------------
    // 10. ASIGNACIÓN DE EVENTOS
    // ----------------------------------------------------------------
    function asignarEventos() {
      document.querySelectorAll('.btn-firmar').forEach(btn => {
        btn.removeEventListener('click', handleFirmar);
        btn.addEventListener('click', handleFirmar);
      });

      document.querySelectorAll('.btn-voice').forEach(btn => {
        btn.removeEventListener('click', handleVoice);
        btn.addEventListener('click', handleVoice);
      });

      document.querySelectorAll('.btn-revelar-practica').forEach(btn => {
        btn.removeEventListener('click', handleRevelarPractica);
        btn.addEventListener('click', handleRevelarPractica);
      });

      document.querySelectorAll('.btn-practicar-detalle').forEach(btn => {
        btn.removeEventListener('click', handlePracticarDetalle);
        btn.addEventListener('click', handlePracticarDetalle);
      });

      document.querySelectorAll('.card-cuaderno[data-practica-id]').forEach(card => {
        card.removeEventListener('click', handleCardClick);
        card.addEventListener('click', handleCardClick);
      });
    }

    function handleFirmar(e) {
      e.stopPropagation();
      const id = parseInt(this.dataset.id);
      toggleAprendida(id);
    }

    function handleVoice(e) {
      e.stopPropagation();
      const id = parseInt(this.dataset.id);
      const tec = TECNICAS.find(t => t.id === id);
      if (tec) leerTexto(`${tec.nombre}: ${tec.definicion}. Ejemplo: ${tec.ejemplo}`);
    }

    function handleRevelarPractica(e) {
      e.stopPropagation();
      const card = this.closest('.card-cuaderno');
      if (card) {
        card.classList.toggle('revelado');
        this.innerHTML = card.classList.contains('revelado') ? '<i class="bi bi-eye-slash"></i>' : '<i class="bi bi-eye"></i>';
      }
    }

    function handlePracticarDetalle(e) {
      e.stopPropagation();
      const id = parseInt(this.dataset.id);
      const tec = TECNICAS.find(t => t.id === id);
      if (!tec) return;
      const modal = new bootstrap.Modal(document.getElementById('modalPractica'));
      document.getElementById('modalDefinicion').textContent = tec.definicion;
      document.getElementById('modalEjemplo').textContent = tec.ejemplo;
      document.getElementById('modalCaligrafia').textContent = getNombreCaligrafia(tec.caligrafia || 'caveat');
      document.getElementById('modalCaligrafia').style.fontFamily = getClaseCaligrafia(tec.caligrafia || 'caveat');
      document.getElementById('inputRespuesta').value = '';
      document.getElementById('inputRespuesta').style.fontFamily = getClaseCaligrafia(tec.caligrafia || 'caveat');
      document.getElementById('inputFirma').value = '';
      document.getElementById('modalFeedback').innerHTML = '';
      document.getElementById('btnGuardarCuaderno').dataset.id = tec.id;
      document.getElementById('btnGuardarCuaderno').dataset.caligrafia = tec.caligrafia || 'caveat';
      document.getElementById('btnVoiceModal').dataset.id = tec.id;
      modal.show();
    }

    function handleCardClick(e) {
      if (e.target.closest('button')) return;
      this.classList.toggle('revelado');
      const btn = this.querySelector('.btn-revelar-practica');
      if (btn) btn.innerHTML = this.classList.contains('revelado') ? '<i class="bi bi-eye-slash"></i>' : '<i class="bi bi-eye"></i>';
    }

    // ----------------------------------------------------------------
    // 11. NAVEGACIÓN
    // ----------------------------------------------------------------
    function setModo(modo) {
      modoActual = modo;
      document.querySelectorAll('.navbar-custom .nav-link').forEach(el => el.classList.remove('active'));
      const activeLink = document.querySelector(`.navbar-custom .nav-link[data-modo="${modo}"]`);
      if (activeLink) activeLink.classList.add('active');
      renderizar();
    }

    function setBloque(bloque) {
      bloqueFiltro = bloque;
      document.querySelectorAll('.filtro-bloque .btn').forEach(el => el.classList.remove('active'));
      const activeBtn = document.querySelector(`.filtro-bloque .btn[data-bloque="${bloque}"]`);
      if (activeBtn) activeBtn.classList.add('active');
      renderizar();
    }

    function toggleVoice() {
      voiceEnabled = !voiceEnabled;
      const status = document.getElementById('voiceStatus');
      const btn = document.getElementById('btnVoiceToggle');
      if (voiceEnabled) {
        status.classList.remove('d-none');
        btn.classList.add('btn-indigo');
        btn.classList.remove('btn-outline-indigo');
      } else {
        status.classList.add('d-none');
        btn.classList.remove('btn-indigo');
        btn.classList.add('btn-outline-indigo');
        if (speechSynth.speaking) speechSynth.cancel();
      }
    }

    function toggleTheme() {
      const current = document.documentElement.getAttribute('data-theme');
      if (current === 'dark') {
        document.documentElement.removeAttribute('data-theme');
        document.getElementById('themeToggle').innerHTML = '<i class="bi bi-moon-fill"></i>';
      } else {
        document.documentElement.setAttribute('data-theme', 'dark');
        document.getElementById('themeToggle').innerHTML = '<i class="bi bi-sun-fill"></i>';
      }
    }

    // ----------------------------------------------------------------
    // 12. INICIALIZACIÓN
    // ----------------------------------------------------------------
    function init() {
      cargarProgreso();

      document.querySelectorAll('.navbar-custom .nav-link').forEach(el => {
        el.addEventListener('click', function(e) {
          e.preventDefault();
          setModo(this.dataset.modo);
        });
      });

      document.querySelectorAll('.filtro-bloque .btn').forEach(el => {
        el.addEventListener('click', function() {
          setBloque(this.dataset.bloque);
        });
      });

      document.getElementById('btnVoiceToggle').addEventListener('click', toggleVoice);
      document.getElementById('themeToggle').addEventListener('click', toggleTheme);

      // Flashcard eventos
      document.getElementById('flashVoltear').addEventListener('click', flashVoltear);
      document.getElementById('flashNext').addEventListener('click', flashNext);
      document.getElementById('flashPrev').addEventListener('click', flashPrev);
      document.getElementById('flashFirmar').addEventListener('click', flashFirmar);
      document.getElementById('flashVoice').addEventListener('click', flashVoice);
      document.getElementById('flashcard').addEventListener('click', function(e) {
        if (e.target.closest('button')) return;
        flashVoltear();
      });

      // Caligrafía eventos
      document.querySelectorAll('.btn-caligrafia').forEach(btn => {
        btn.addEventListener('click', function() {
          caligrafiaActual = this.dataset.caligrafia;
          renderizarCaligrafia();
        });
      });
      document.getElementById('btnGuardarCaligrafia').addEventListener('click', guardarFraseCaligrafia);
      document.getElementById('inputCaligrafia').addEventListener('keypress', function(e) {
        if (e.key === 'Enter') guardarFraseCaligrafia();
      });

      // Modal: Guardar entrada
      document.getElementById('btnGuardarCuaderno').addEventListener('click', function() {
        const id = parseInt(this.dataset.id);
        const caligrafia = this.dataset.caligrafia || 'caveat';
        const respuesta = document.getElementById('inputRespuesta').value;
        const firma = document.getElementById('inputFirma').value;
        if (!respuesta.trim()) {
          document.getElementById('modalFeedback').innerHTML = '<div class="alert alert-warning">Escribe la técnica antes de guardar.</div>';
          return;
        }
        guardarEntradaCuaderno(id, respuesta, firma, caligrafia);
        document.getElementById('modalFeedback').innerHTML = '<div class="alert alert-success">¡Guardado en tu bitácora!</div>';
        if (!progreso[id]) {
          toggleAprendida(id);
        }
        setTimeout(() => {
          const modal = bootstrap.Modal.getInstance(document.getElementById('modalPractica'));
          if (modal) modal.hide();
        }, 1200);
      });

      document.getElementById('btnVoiceModal').addEventListener('click', function() {
        const id = parseInt(this.dataset.id);
        const tec = TECNICAS.find(t => t.id === id);
        if (tec) leerTexto(`${tec.nombre}: ${tec.definicion}. Ejemplo: ${tec.ejemplo}`);
      });

      document.getElementById('borrarTodoCuaderno').addEventListener('click', function() {
        if (confirm('¿Borrar todas las entradas de tu bitácora?')) {
          entradasCuaderno = [];
          guardarProgreso();
          renderizarCuaderno();
        }
      });

      // Examen
      document.getElementById('btnGenerarExamen').addEventListener('click', function() {
        generarExamen();
        if (!document.getElementById('btnCorregirExamen')) {
          const btnCorregir = document.createElement('button');
          btnCorregir.id = 'btnCorregirExamen';
          btnCorregir.className = 'btn btn-indigo mt-2';
          btnCorregir.innerHTML = '<i class="bi bi-check2-circle"></i> Corregir examen';
          btnCorregir.addEventListener('click', corregirExamen);
          document.getElementById('examenResultados').parentNode.insertBefore(btnCorregir, document.getElementById('examenResultados'));
        }
      });

      document.getElementById('btnExportarCSV').addEventListener('click', exportarCSV);
      document.getElementById('btnExportarJSON').addEventListener('click', exportarJSON);

      document.getElementById('btnResetearProgreso').addEventListener('click', function() {
        if (confirm('¿Resetear todo el progreso?')) {
          progreso = {};
          entradasCuaderno = [];
          frasesCaligrafia = [];
          estadisticas = { racha: 0, aciertos: 0, intentos: 0 };
          niveles = {};
          guardarProgreso();
          renderizar();
        }
      });

      setModo('explorar');
      setBloque('todos');
    }

    document.addEventListener('DOMContentLoaded', init);
  })();
</script>
</body>
</html>

