.card-cuaderno { cursor: pointer; }
    .modo-practica .card-cuaderno .definicion,
    .modo-practica .card-cuaderno .ejemplo {
      filter: blur(4px);
      user-select: none;
      transition: filter 0.5s ease, background 0.3s;
    }
    .modo-practica .card-cuaderno.revelado .definicion,
    .modo-practica .card-cuaderno.revelado .ejemplo {
      filter: blur(0);
      user-select: auto;
    }
    .cuaderno {
      background: var(--card-bg);
      border-radius: 16px;
      box-shadow: var(--shadow);
      position: relative;
      padding: 2rem 2rem 2rem 3.5rem;
      margin-bottom: 2rem;
      border: 1px solid #ddd;
      transition: background 0.3s, box-shadow 0.3s;
    }
    .cuaderno::before {
      content: '';
      position: absolute;
      left: 20px;
      top: 20px;
      bottom: 20px;
      width: 4px;
      background-color: var(--margin-red);
      border-radius: 2px;
    }
    .cuaderno::after {
      content: '';
      position: absolute;
      left: -8px;
      top: 30px;
      bottom: 30px;
      width: 16px;
      background: repeating-linear-gradient(to bottom, #aaa 0px, #aaa 6px, transparent 6px, transparent 18px);
      border-radius: 8px;
      opacity: 0.4;
    }
    .cuaderno .lineas {
      background: repeating-linear-gradient(transparent, transparent 28px, var(--line-blue) 28px, var(--line-blue) 29px);
      background-size: 100% 29px;
      padding-bottom: 10px;
    }
    .manuscrito {
      font-family: 'Caveat', cursive;
      font-size: 1.5rem;
      border: none;
      border-bottom: 2px dashed var(--indigo-light);
      background: transparent;
      width: 100%;
      outline: none;
      padding: 0.2rem 0.4rem;
      color: var(--indigo-dark);
      transition: border-color 0.3s;
    }
    .manuscrito:focus { border-bottom: 2px solid var(--indigo); }
    .firma-input {
      font-family: 'Great Vibes', cursive;
      font-size: 1.8rem;
      border: none;
      border-bottom: 2px solid var(--margin-red);
      background: transparent;
      width: 100%;
      outline: none;
      padding: 0.2rem 0.4rem;
      color: #2c3e50;
    }
    .firma-input:focus { border-bottom: 2px solid #c0392b; }
    .cuaderno-entry {
      background: var(--card-bg);
      border-left: 4px solid var(--indigo);
      padding: 0.75rem 1rem;
      margin-bottom: 0.75rem;
      border-radius: 8px;
      box-shadow: 0 2px 8px rgba(0,0,0,0.04);
      transition: background 0.3s;
    }
    .cuaderno-entry .fecha { font-size: 0.75rem; color: #888; }
    .cuaderno-entry .firma { font-family: 'Great Vibes', cursive; font-size: 1.4rem; color: #2c3e50; }
    .cuaderno-entry .respuesta { font-family: 'Caveat', cursive; font-size: 1.2rem; }

    .flashcard-wrapper { perspective: 1000px; }
    .flashcard {
      background: var(--card-bg);
      border: 3px solid var(--indigo);
      border-radius: 16px;
      padding: 2rem;
      min-height: 320px;
      box-shadow: var(--shadow);
      transition: transform 0.6s cubic-bezier(0.4, 0, 0.2, 1), background 0.3s;
      transform-style: preserve-3d;
      display: flex;
      flex-direction: column;
      justify-content: center;
      cursor: pointer;
      position: relative;
    }
    .flashcard .card-front, .flashcard .card-back {
      position: absolute;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      padding: 2rem;
      display: flex;
      flex-direction: column;
      justify-content: center;
      backface-visibility: hidden;
      border-radius: 16px;
      background: var(--card-bg);
      transition: background 0.3s;
