<script>
  (function() {
    'use strict';

    // ----------------------------------------------------------------
    // 1. DATOS: 100 técnicas de gramática castellana para extranjeros
    // ----------------------------------------------------------------
    const TECNICAS = [];

    const caligrafias = ['caveat', 'tangerine', 'cookie', 'greatvibes', 'garabato'];
    const nombresCaligrafia = { caveat: 'Caveat', tangerine: 'Tangerine', cookie: 'Cookie', greatvibes: 'Great Vibes', garabato: 'Garabato' };
    const clasesCaligrafia = { caveat: 'fuente-caveat', tangerine: 'fuente-tangerine', cookie: 'fuente-cookie', greatvibes: 'fuente-greatvibes', garabato: 'fuente-garabato' };

    // BLOQUE I: Artículos y determinantes
    const bloqueI = [
      { nombre: 'Artículo definido (el, la, los, las)', definicion: 'Se usa para hablar de algo conocido o mencionado anteriormente.', ejemplo: 'Esp: "El libro está en la mesa." / Eng: "The book is on the table."', caligrafia: 'caveat' },
      { nombre: 'Artículo indefinido (un, una, unos, unas)', definicion: 'Se usa para hablar de algo no específico o mencionado por primera vez.', ejemplo: 'Esp: "Tengo un coche rojo." / Eng: "I have a red car."', caligrafia: 'cookie' },
      { nombre: 'Artículo neutro (lo)', definicion: 'Se usa con adjetivos para formar sustantivos abstractos.', ejemplo: 'Esp: "Lo importante es estudiar." / Eng: "The important thing is to study."', caligrafia: 'tangerine' },
      { nombre: 'Omisión del artículo', definicion: 'En español se omite el artículo en ciertos contextos (profesiones, nacionalidades).', ejemplo: 'Esp: "Soy profesor." / Eng: "I am a teacher." (en inglés se usa) / "Soy español." / "I am Spanish."', caligrafia: 'garabato' },
      { nombre: 'Contracción del artículo (al, del)', definicion: 'Artículo + preposición se contraen en "al" (a+el) y "del" (de+el).', ejemplo: 'Esp: "Voy al parque." / "Vengo del cine." / Eng: "I go to the park." / "I come from the cinema."', caligrafia: 'greatvibes' },
      { nombre: 'Demostrativos (este, ese, aquel)', definicion: 'Indican distancia respecto al hablante y al oyente.', ejemplo: 'Esp: "Este libro (cerca), ese libro (distancia media), aquel libro (lejos)." / Eng: "This book, that book, that book over there."', caligrafia: 'caveat' },
      { nombre: 'Posesivos (mi, tu, su, nuestro, vuestro)', definicion: 'Indican pertenencia o posesión.', ejemplo: 'Esp: "Mi casa es grande. Tu coche es rojo." / Eng: "My house is big. Your car is red."', caligrafia: 'cookie' },
      { nombre: 'Posesivos pospuestos (mío, tuyo, suyo)', definicion: 'Van después del sustantivo y concuerdan en género y número.', ejemplo: 'Esp: "Un amigo mío." / "La casa suya." / Eng: "A friend of mine." / "His/her house."', caligrafia: 'tangerine' },
      { nombre: 'Cuantificadores (mucho, poco, bastante, demasiado)', definicion: 'Indican cantidad.', ejemplo: 'Esp: "Hay mucha gente. Tengo poco tiempo." / Eng: "There are many people. I have little time."', caligrafia: 'garabato' },
      { nombre: 'Numerales (cardinales y ordinales)', definicion: 'Indican cantidad u orden.', ejemplo: 'Esp: "Tres libros. El primer capítulo." / Eng: "Three books. The first chapter."', caligrafia: 'greatvibes' }
    ];
    bloqueI.forEach((t, i) => TECNICAS.push({ id: i+1, bloque: 'I', ...t }));

    // BLOQUE II: Pronombres
    const bloqueII = [
      { nombre: 'Pronombres personales de sujeto (yo, tú, él, ella, etc.)', definicion: 'Indican quién realiza la acción.', ejemplo: 'Esp: "Yo estudio español. Tú hablas inglés." / Eng: "I study Spanish. You speak English."', caligrafia: 'caveat' },
      { nombre: 'Pronombres de objeto directo (me, te, lo/la, nos, os, los/las)', definicion: 'Reemplazan el objeto directo.', ejemplo: 'Esp: "Veo a Juan. Lo veo." / Eng: "I see Juan. I see him."', caligrafia: 'cookie' },
      { nombre: 'Pronombres de objeto indirecto (me, te, le, nos, os, les)', definicion: 'Reemplazan el objeto indirecto.', ejemplo: 'Esp: "Doy un regalo a María. Le doy un regalo." / Eng: "I give a gift to María. I give her a gift."', caligrafia: 'tangerine' },
      { nombre: 'Pronombres reflexivos (me, te, se, nos, os, se)', definicion: 'Indican que la acción recae sobre el sujeto.', ejemplo: 'Esp: "Me lavo las manos. Se peina el pelo." / Eng: "I wash my hands. She combs her hair."', caligrafia: 'garabato' },
      { nombre: 'Pronombres posesivos (el mío, la tuya, los suyos, etc.)', definicion: 'Reemplazan un sustantivo con posesión.', ejemplo: 'Esp: "Este libro es mío. La casa es suya." / Eng: "This book is mine. The house is hers."', caligrafia: 'greatvibes' },
      { nombre: 'Pronombres demostrativos (éste, ése, aquél)', definicion: 'Reemplazan un sustantivo indicando distancia.', ejemplo: 'Esp: "Éste es mi libro. Ése es el tuyo." / Eng: "This one is my book. That one is yours."', caligrafia: 'caveat' },
      { nombre: 'Pronombres relativos (que, quien, el cual, cuyo)', definicion: 'Introducen oraciones subordinadas.', ejemplo: 'Esp: "El hombre que habla. La mujer a quien vi." / Eng: "The man who speaks. The woman whom I saw."', caligrafia: 'tangerine' },
      { nombre: 'Pronombres interrogativos (qué, quién, cuál, cuánto)', definicion: 'Se usan para hacer preguntas.', ejemplo: 'Esp: "¿Qué quieres? ¿Quién es ella?" / Eng: "What do you want? Who is she?"', caligrafia: 'cookie' },
      { nombre: 'Pronombres exclamativos (qué, cuánto)', definicion: 'Se usan para exclamaciones.', ejemplo: 'Esp: "¡Qué bonito! ¡Cuánto tiempo!" / Eng: "How beautiful! So much time!"', caligrafia: 'garabato' },
      { nombre: 'Pronombres indefinidos (alguien, nadie, algo, nada, todo)', definicion: 'Indican cantidad o existencia de manera imprecisa.', ejemplo: 'Esp: "Alguien llamó. No hay nadie." / Eng: "Someone called. There is no one."', caligrafia: 'greatvibes' }
    ];
    bloqueII.forEach((t, i) => TECNICAS.push({ id: 10+i+1, bloque: 'II', ...t }));

    // BLOQUE III: Verbos y conjugación
    const bloqueIII = [
      { nombre: 'Verbos regulares (AR, ER, IR)', definicion: 'Siguen un patrón de conjugación fijo.', ejemplo: 'Esp: "Hablar: hablo, hablas, habla..." / Eng: "To speak: I speak, you speak, he speaks..."', caligrafia: 'caveat' },
      { nombre: 'Verbos irregulares (ser, estar, ir, tener, hacer)', definicion: 'No siguen el patrón regular de conjugación.', ejemplo: 'Esp: "Ser: soy, eres, es..." / Eng: "To be: I am, you are, he is..."', caligrafia: 'tangerine' },
      { nombre: 'Verbos reflexivos (levantarse, ducharse, vestirse)', definicion: 'El sujeto realiza y recibe la acción.', ejemplo: 'Esp: "Me levanto a las 7. Me ducho." / Eng: "I get up at 7. I shower."', caligrafia: 'cookie' },
