    let niveles = {};
    let caligrafiaActual = 'caveat';

    function cargarProgreso() {
      try {
        const data = localStorage.getItem(STORAGE_KEY);
        if (data) progreso = JSON.parse(data);
        else progreso = {};
      } catch (e) { progreso = {}; }
      try {
        const data = localStorage.getItem(CUADERNO_KEY);
        if (data) entradasCuaderno = JSON.parse(data);
        else entradasCuaderno = [];
      } catch (e) { entradasCuaderno = []; }
      try {
        const data = localStorage.getItem(CALIGRAFIA_KEY);
        if (data) frasesCaligrafia = JSON.parse(data);
        else frasesCaligrafia = [];
      } catch (e) { frasesCaligrafia = []; }
      try {
        const data = localStorage.getItem(ESTADISTICAS_KEY);
        if (data) estadisticas = JSON.parse(data);
        else estadisticas = { racha: 0, aciertos: 0, intentos: 0 };
      } catch (e) { estadisticas = { racha: 0, aciertos: 0, intentos: 0 }; }
      try {
        const data = localStorage.getItem(STORAGE_KEY + '_niveles');
        if (data) niveles = JSON.parse(data);
        else niveles = {};
      } catch (e) { niveles = {}; }
    }

    function guardarProgreso() {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(progreso));
      localStorage.setItem(CUADERNO_KEY, JSON.stringify(entradasCuaderno));
      localStorage.setItem(CALIGRAFIA_KEY, JSON.stringify(frasesCaligrafia));
      localStorage.setItem(ESTADISTICAS_KEY, JSON.stringify(estadisticas));
      localStorage.setItem(STORAGE_KEY + '_niveles', JSON.stringify(niveles));
      actualizarContador();
    }

    function toggleAprendida(id) {
      if (progreso[id]) {
        delete progreso[id];
        estadisticas.racha = 0;
      } else {
        progreso[id] = true;
        estadisticas.racha++;
        estadisticas.aciertos++;
        niveles[id] = (niveles[id] || 0) + 1;
      }
      estadisticas.intentos++;
      guardarProgreso();
      renderizar();
      if (modoActual === 'flashcards') mostrarFlashcard(flashIndex);
    }

    function actualizarContador() {
      const total = TECNICAS.length;
      const aprendidas = Object.keys(progreso).filter(k => progreso[k]).length;
      document.getElementById('contadorAprendidas').textContent = `${aprendidas}/${total}`;
      if (modoActual === 'progreso') actualizarEstadisticas();
    }

    function getTecnicasFiltradas() {
      let lista = TECNICAS;
      if (bloqueFiltro !== 'todos') lista = lista.filter(t => t.bloque === bloqueFiltro);
      return lista;
    }

    function leerTexto(texto) {
      if (!voiceEnabled) return;
      if (speechSynth.speaking) speechSynth.cancel();
      utterance = new SpeechSynthesisUtterance(texto);
      utterance.lang = 'es-ES';
      utterance.rate = 0.9;
      utterance.pitch = 1;
      speechSynth.speak(utterance);
    }

    function getClaseCaligrafia(caligrafia) {
      return clasesCaligrafia[caligrafia] || 'fuente-caveat';
    }

    function getNombreCaligrafia(caligrafia) {
      return nombresCaligrafia[caligrafia] || 'Caveat';
    }

    // ----------------------------------------------------------------
    // 3. FLASHCARDS
    // ----------------------------------------------------------------
    function mostrarFlashcard(index) {
      const lista = getTecnicasFiltradas();
      if (lista.length === 0) {
        document.getElementById('flashcardContainer').style.display = 'none';
        return;
      }
      flashList = lista;
      if (index >= lista.length) index = 0;
      if (index < 0) index = lista.length - 1;
      flashIndex = index;

      const t = lista[index];
      const aprendida = progreso[t.id] || false;

      document.getElementById('flashBloque').textContent = t.bloque;
      document.getElementById('flashNombre').textContent = t.nombre;
      document.getElementById('flashBloqueBack').textContent = t.bloque;
      document.getElementById('flashNombreBack').textContent = t.nombre;
      document.getElementById('flashDefinicion').textContent = t.definicion;
      document.getElementById('flashEjemplo').textContent = t.ejemplo;

      document.getElementById('flashContador').textContent = `${index+1} / ${lista.length}`;

      const flashcard = document.getElementById('flashcard');
      flashcard.classList.remove('revelada');
      document.getElementById('flashVoltear').innerHTML = '<i class="bi bi-arrow-repeat"></i> Voltear';

      const firmarBtn = document.getElementById('flashFirmar');
      if (aprendida) {
        firmarBtn.innerHTML = '<i class="bi bi-check2-circle"></i> Firmada';
        firmarBtn.className = 'btn btn-success';
      } else {
        firmarBtn.innerHTML = '<i class="bi bi-pen"></i> Firmar';
        firmarBtn.className = 'btn btn-outline-warning';
      }
      actualizarContador();
    }

    function flashVoltear() {
      const flashcard = document.getElementById('flashcard');
      flashcard.classList.toggle('revelada');
      const btn = document.getElementById('flashVoltear');
      btn.innerHTML = flashcard.classList.contains('revelada') ? '<i class="bi bi-arrow-repeat"></i> Ocultar' : '<i class="bi bi-arrow-repeat"></i> Voltear';
    }

    function flashNext() { mostrarFlashcard(flashIndex + 1); document.getElementById('flashcard').classList.remove('revelada'); document.getElementById('flashVoltear').innerHTML = '<i class="bi bi-arrow-repeat"></i> Voltear'; }
    function flashPrev() { mostrarFlashcard(flashIndex - 1); document.getElementById('flashcard').classList.remove('revelada'); document.getElementById('flashVoltear').innerHTML = '<i class="bi bi-arrow-repeat"></i> Voltear'; }
    function flashFirmar() {
      const lista = getTecnicasFiltradas();
      if (lista.length === 0) return;
      toggleAprendida(lista[flashIndex].id);
      mostrarFlashcard(flashIndex);
    }
    function flashVoice() {
      const lista = getTecnicasFiltradas();
      if (lista.length === 0) return;
      const t = lista[flashIndex];
      leerTexto(`${t.nombre}: ${t.definicion}. Ejemplo: ${t.ejemplo}`);
    }

    // ----------------------------------------------------------------
    // 4. BITÁCORA (guardado automático)
    // ----------------------------------------------------------------
    function renderizarCuaderno() {
      const container = document.getElementById('miCuadernoLista');
      if (entradasCuaderno.length === 0) {
        container.innerHTML = '<p class="text-muted">Aún no has guardado ninguna entrada en tu bitácora. Escribe en el modo Practicar para empezar.</p>';
        return;
      }
      const html = entradasCuaderno.slice().reverse().map((entry, idx) => {
        const realIndex = entradasCuaderno.length - 1 - idx;
        const claseCalig = getClaseCaligrafia(entry.caligrafia || 'caveat');
        return `
          <div class="cuaderno-entry">
            <div class="d-flex justify-content-between">
              <strong>${entry.nombreTecnica}</strong>
              <span class="fecha">${entry.fecha}</span>
            </div>
            <div><span class="text-muted">Tu respuesta:</span> <span class="respuesta">${entry.respuestaUsuario || '(vacío)'}</span></div>
            <div><span class="text-muted">Caligrafía:</span> <span class="${claseCalig}">${getNombreCaligrafia(entry.caligrafia || 'caveat')}</span></div>
            <div><span class="text-muted">Firma:</span> <span class="firma">${entry.firma || '(sin firma)'}</span></div>
            <button class="btn btn-outline-danger btn-sm mt-1" data-borrar="${realIndex}"><i class="bi bi-x-circle"></i> Borrar</button>
          </div>
        `;
      }).join('');
      container.innerHTML = html;
      container.querySelectorAll('[data-borrar]').forEach(btn => {
        btn.addEventListener('click', function() {
          const idx = parseInt(this.dataset.borrar);
          entradasCuaderno.splice(idx, 1);
          guardarProgreso();
          renderizarCuaderno();
        });
      });
    }

    function guardarEntradaCuaderno(tecnicaId, respuesta, firma, caligrafia) {
      const tec = TECNICAS.find(t => t.id === tecnicaId);
      if (!tec) return;
      const fecha = new Date().toLocaleString();
      entradasCuaderno.push({
        tecnicaId: tecnicaId,
        nombreTecnica: tec.nombre,
        respuestaUsuario: respuesta.trim(),
        firma: firma.trim() || '(sin firma)',
        caligrafia: caligrafia || tec.caligrafia || 'caveat',
        fecha: fecha
      });
      guardarProgreso();
      renderizarCuaderno();
    }

    // ----------------------------------------------------------------
    // 5. CALIGRAFÍA
    // ----------------------------------------------------------------
    function renderizarCaligrafia() {
      document.querySelectorAll('.btn-caligrafia').forEach(btn => {
        btn.classList.toggle('active', btn.dataset.caligrafia === caligrafiaActual);
      });
      document.getElementById('caligrafiaNombre').textContent = getNombreCaligrafia(caligrafiaActual);
      document.getElementById('caligrafiaPreview').style.fontFamily = getClaseCaligrafia(caligrafiaActual);
      document.getElementById('inputCaligrafia').style.fontFamily = getClaseCaligrafia(caligrafiaActual);

      const container = document.getElementById('frasesCaligrafia');
      const frasesFiltradas = frasesCaligrafia.filter(f => f.caligrafia === caligrafiaActual);
      if (frasesFiltradas.length === 0) {
        container.innerHTML = '<p class="text-muted small">No hay frases guardadas en esta caligrafía.</p>';
      } else {
        container.innerHTML = frasesFiltradas.map((f, i) => `
          <div class="d-flex justify-content-between align-items-center small p-1 border-bottom">
            <span style="font-family:${getClaseCaligrafia(f.caligrafia)};font-size:1.1rem;">${f.texto}</span>
            <button class="btn btn-outline-danger btn-sm" data-borrar-frase="${i}"><i class="bi bi-x"></i></button>
          </div>
        `).join('');
        container.querySelectorAll('[data-borrar-frase]').forEach(btn => {
          btn.addEventListener('click', function() {
            const idx = parseInt(this.dataset.borrar-frase);
            frasesCaligrafia.splice(idx, 1);
            guardarProgreso();
            renderizarCaligrafia();
          });
        });
      }

      const asociacionContainer = document.getElementById('asociacionCaligrafia');
      const asociaciones = [
        { caligrafia: 'caveat', descripcion: 'Oraciones simples, registro coloquial' },
        { caligrafia: 'tangerine', descripcion: 'Subordinación, registro literario' },
        { caligrafia: 'cookie', descripcion: 'Registro coloquial, conectores' },
        { caligrafia: 'greatvibes', descripcion: 'Formal, voz pasiva' },
        { caligrafia: 'garabato', descripcion: 'Exploración, falsos amigos' }
      ];
      asociacionContainer.innerHTML = asociaciones.map(a => `
        <div class="col-6 col-md-4">
          <div class="stat-card text-center p-2 ${a.caligrafia === caligrafiaActual ? 'border border-indigo' : ''}" style="font-family:${getClaseCaligrafia(a.caligrafia)};">
            <strong>${getNombreCaligrafia(a.caligrafia)}</strong>
            <div class="small">${a.descripcion}</div>
          </div>
        </div>
      `).join('');
    }

    function guardarFraseCaligrafia() {
      const input = document.getElementById('inputCaligrafia');
      const texto = input.value.trim();
      if (!texto) {
        alert('Escribe una frase primero.');
        return;
      }
      frasesCaligrafia.push({ caligrafia: caligrafiaActual, texto: texto });
      guardarProgreso();
      input.value = '';
      renderizarCaligrafia();
    }

    // ----------------------------------------------------------------
    // 6. ESTADÍSTICAS
    // ----------------------------------------------------------------
    function actualizarEstadisticas() {
      const total = TECNICAS.length;
      const aprendidas = Object.keys(progreso).filter(k => progreso[k]).length;
      const pct = Math.round((aprendidas / total) * 100);
      document.getElementById('statAprendidas').textContent = aprendidas;
      document.getElementById('statRacha').textContent = estadisticas.racha || 0;
      document.getElementById('statDominio').textContent = pct + '%';
      document.getElementById('statEntradas').textContent = entradasCuaderno.length;

      const bloques = ['I', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX', 'X'];
      let html = '<h6 class="mt-3">Dominio por bloque</h6><div class="row g-2">';
      bloques.forEach(b => {
        const tecBloque = TECNICAS.filter(t => t.bloque === b);
        const aprendidasBloque = tecBloque.filter(t => progreso[t.id]).length;
        const pctBloque = tecBloque.length > 0 ? Math.round((aprendidasBloque / tecBloque.length) * 100) : 0;
        html += `
          <div class="col-6 col-md-3">
            <div class="stat-card text-center p-2">
              <div class="fw-bold">Bloque ${b}</div>
              <div class="progress" style="height:6px;margin:4px 0;">
                <div class="progress-fill" style="width:${pctBloque}%;"></div>
              </div>
              <small>${aprendidasBloque}/${tecBloque.length} (${pctBloque}%)</small>
            </div>
          </div>
        `;
      });
      html += '</div>';
      document.getElementById('estadisticasDetalladas').innerHTML = html;
    }

    // ----------------------------------------------------------------
    // 7. EXAMEN
    // ----------------------------------------------------------------
    function generarExamen() {
      const cantidad = parseInt(document.getElementById('examenCantidad').value);
      const dificultad = document.getElementById('examenDificultad').value;
      let pool = TECNICAS;
      if (dificultad === 'facil') pool = TECNICAS.filter(t => !progreso[t.id]);
      else if (dificultad === 'dificil') pool = TECNICAS.filter(t => progreso[t.id]);
      if (pool.length === 0) {
        document.getElementById('examenPreguntas').innerHTML = '<div class="alert alert-warning">No hay técnicas en el rango seleccionado.</div>';
        return;
      }
      const shuffled = pool.sort(() => Math.random() - 0.5);
      const seleccionadas = shuffled.slice(0, Math.min(cantidad, shuffled.length));
      let html = '';
      seleccionadas.forEach((t, idx) => {
        const opciones = pool.filter(o => o.id !== t.id).sort(() => Math.random() - 0.5).slice(0, 3);
        const todasOpciones = [t, ...opciones].sort(() => Math.random() - 0.5);
        html += `
          <div class="cuaderno-entry mb-2" data-examen="${idx}">
            <p><strong>${idx+1}.</strong> <span class="definicion-examen">${t.definicion}</span></p>
            <div class="opciones-examen">
              ${todasOpciones.map((o, oi) => `
                <div class="form-check">
                  <input class="form-check-input opcion-examen" type="radio" name="examen_${idx}" value="${o.id}" id="examen_${idx}_${oi}">
                  <label class="form-check-label" for="examen_${idx}_${oi}">${o.nombre}</label>
                </div>
              `).join('')}
            </div>
            <div class="feedback-examen mt-1"></div>
          </div>
        `;
      });
      document.getElementById('examenPreguntas').innerHTML = html;
      document.getElementById('examenResultados').innerHTML = '';
      document.getElementById('btnGenerarExamen').dataset.respuestas = JSON.stringify(seleccionadas.map(t => t.id));
    }

    function corregirExamen() {
      const respuestasCorrectas = JSON.parse(document.getElementById('btnGenerarExamen').dataset.respuestas || '[]');
      let aciertos = 0;
      document.querySelectorAll('[data-examen]').forEach((div, idx) => {
        const selected = div.querySelector('input[type="radio"]:checked');
        const feedback = div.querySelector('.feedback-examen');
        const correcta = respuestasCorrectas[idx];
        if (selected) {
          const valor = parseInt(selected.value);
          if (valor === correcta) {
            aciertos++;
            feedback.innerHTML = '<span class="text-success">✓ Correcto</span>';
          } else {
            const nombreCorrecto = TECNICAS.find(t => t.id === correcta)?.nombre || 'desconocida';
            feedback.innerHTML = `<span class="text-danger">✗ Incorrecto. La respuesta correcta es: ${nombreCorrecto}</span>`;
          }
        } else {
          const nombreCorrecto = TECNICAS.find(t => t.id === correcta)?.nombre || 'desconocida';
          feedback.innerHTML = `<span class="text-warning">⚠ No respondiste. La respuesta correcta es: ${nombreCorrecto}</span>`;
        }
      });
      document.getElementById('examenResultados').innerHTML = `
        <div class="alert alert-info">
          <strong>Resultado:</strong> ${aciertos} de ${respuestasCorrectas.length} correctas 
          (${Math.round((aciertos/respuestasCorrectas.length)*100)}%)
        </div>
        <button class="btn btn-indigo" onclick="window.location.reload()"><i class="bi bi-arrow-repeat"></i> Nuevo examen</button>
      `;
    }

    // ----------------------------------------------------------------
    // 8. EXPORTACIÓN
    // ----------------------------------------------------------------
    function exportarCSV() {
      let csv = 'Técnica,Definición,Ejemplo,Bloque,Caligrafía,Estado,Fecha\n';
      TECNICAS.forEach(t => {
        const estado = progreso[t.id] ? 'Aprendida' : 'Pendiente';
        const fecha = entradasCuaderno.find(e => e.tecnicaId === t.id)?.fecha || '';
        csv += `"${t.nombre}","${t.definicion}","${t.ejemplo}",${t.bloque},${t.caligrafia},${estado},"${fecha}"\n`;
      });
      const blob = new Blob([csv], { type: 'text/csv' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'cuaderno_caligrafico.csv';
      a.click();
      URL.revokeObjectURL(url);
    }

    function exportarJSON() {
      const data = {
        tecnicas: TECNICAS,
        progreso: progreso,
        entradas: entradasCuaderno,
        frasesCaligrafia: frasesCaligrafia,
        estadisticas: estadisticas,
        fecha: new Date().toISOString()
      };
      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = 'cuaderno_caligrafico.json';
      a.click();
      URL.revokeObjectURL(url);
    }

    // ----------------------------------------------------------------
    // 9. RENDER PRINCIPAL
    // ----------------------------------------------------------------
    function renderizar() {
      const grid = document.getElementById('gridTecnicas');
      const flashContainer = document.getElementById('flashcardContainer');
      const caligrafiaContainer = document.getElementById('caligrafiaContainer');
      const miCuadernoContainer = document.getElementById('miCuadernoContainer');
      const progresoContainer = document.getElementById('progresoContainer');
      const examenContainer = document.getElementById('examenContainer');
      const lista = getTecnicasFiltradas();
      document.getElementById('resultCount').textContent = `${lista.length} técnicas`;

      grid.style.display = 'none';
      flashContainer.style.display = 'none';
      caligrafiaContainer.style.display = 'none';
      miCuadernoContainer.style.display = 'none';
      progresoContainer.style.display = 'none';
      examenContainer.style.display = 'none';

      if (modoActual === 'flashcards') {
        flashContainer.style.display = 'block';
        if (lista.length > 0) mostrarFlashcard(0);
        else flashContainer.innerHTML = `<div class="alert alert-warning">No hay técnicas en este bloque.</div>`;
        return;
      }

      if (modoActual === 'caligrafia') {
        caligrafiaContainer.style.display = 'block';
        renderizarCaligrafia();
        return;
      }

      if (modoActual === 'cuaderno') {
        miCuadernoContainer.style.display = 'block';
        renderizarCuaderno();
        return;
      }

      if (modoActual === 'progreso') {
        progresoContainer.style.display = 'block';
        actualizarEstadisticas();
        return;
      }

      if (modoActual === 'examen') {
        examenContainer.style.display = 'block';
        if (!document.getElementById('examenPreguntas').innerHTML) {
          generarExamen();
        }
        return;
      }

      grid.style.display = 'flex';
      const caligrafiaClass = getClaseCaligrafia(caligrafiaActual);

      if (modoActual === 'explorar') {
        grid.innerHTML = lista.map(t => {
          const aprendida = progreso[t.id] || false;
          const claseCalig = getClaseCaligrafia(t.caligrafia || 'caveat');
          return `
            <div class="col-12 col-md-6 col-lg-4">
              <div class="card-cuaderno">
                <div class="d-flex justify-content-between align-items-start">
                  <span class="badge-bloque">${t.bloque}</span>
                  <span class="badge bg-${aprendida ? 'success' : 'secondary'} rounded-pill">${aprendida ? '✓ Aprendida' : 'Pendiente'}</span>
                </div>
                <h6 class="card-title mt-2">${t.nombre}</h6>
                <p class="definicion small">${t.definicion}</p>
                <p class="ejemplo-cursiva small ${claseCalig}"><i class="bi bi-quote"></i> ${t.ejemplo}</p>
                <div class="d-flex justify-content-between align-items-center mt-2">
                  <span class="badge bg-info text-dark" style="font-size:0.65rem;">${getNombreCaligrafia(t.caligrafia || 'caveat')}</span>
                  <div>
                    <button class="btn btn-outline-indigo btn-sm btn-voice" data-id="${t.id}" title="Escuchar"><i class="bi bi-volume-up"></i></button>
                    <button class="btn btn-sm ${aprendida ? 'btn-outline-warning' : 'btn-indigo'} btn-firmar" data-id="${t.id}">${aprendida ? '<i class="bi bi-check2-circle"></i>' : '<i class="bi bi-pen"></i>'}</button>
                  </div>
                </div>
              </div>
            </div>
          `;
        }).join('');
      } else if (modoActual === 'practicar') {
        grid.innerHTML = lista.map(t => {
          const aprendida = progreso[t.id] || false;
          const claseCalig = getClaseCaligrafia(t.caligrafia || 'caveat');
          return `
            <div class="col-12 col-md-6 col-lg-4">
              <div class="card-cuaderno" data-practica-id="${t.id}">
                <div class="d-flex justify-content-between align-items-start">
                  <span class="badge-bloque">${t.bloque}</span>
                  <span class="badge bg-${aprendida ? 'success' : 'secondary'} rounded-pill">${aprendida ? '✓' : '?'}</span>
                </div>
                <h6 class="card-title mt-2">${t.nombre}</h6>
                <p class="definicion small" style="filter:blur(4px);user-select:none;">${t.definicion}</p>
                <p class="ejemplo-cursiva small ${claseCalig}" style="filter:blur(4px);user-select:none;"><i class="bi bi-quote"></i> ${t.ejemplo}</p>
                <div class="d-flex justify-content-between mt-2">
                  <span class="badge bg-info text-dark" style="font-size:0.65rem;">${getNombreCaligrafia(t.caligrafia || 'caveat')}</span>
                  <div>
                    <button class="btn btn-outline-indigo btn-sm btn-revelar-practica" data-id="${t.id}"><i class="bi bi-eye"></i></button>
                    <button class="btn btn-sm btn-outline-info btn-practicar-detalle" data-id="${t.id}"><i class="bi bi-pencil"></i></button>
                    <button class="btn btn-sm ${aprendida ? 'btn-outline-warning' : 'btn-indigo'} btn-firmar" data-id="${t.id}">${aprendida ? '<i class="bi bi-check2-circle"></i>' : '<i class="bi bi-pen"></i>'}</button>
                  </div>
                </div>
              </div>
            </div>
          `;
        }).join('');
      }

      asignarEventos();
      actualizarContador();
    }

    // ----------------------------------------------------------------
    // 10. ASIGNACIÓN DE EVENTOS
    // ----------------------------------------------------------------
    function asignarEventos() {
      document.querySelectorAll('.btn-firmar').forEach(btn => {
        btn.removeEventListener('click', handleFirmar);
        btn.addEventListener('click', handleFirmar);
      });

      document.querySelectorAll('.btn-voice').forEach(btn => {
        btn.removeEventListener('click', handleVoice);
        btn.addEventListener('click', handleVoice);
      });

      document.querySelectorAll('.btn-revelar-practica').forEach(btn => {
        btn.removeEventListener('click', handleRevelarPractica);
        btn.addEventListener('click', handleRevelarPractica);
      });

      document.querySelectorAll('.btn-practicar-detalle').forEach(btn => {
        btn.removeEventListener('click', handlePracticarDetalle);
        btn.addEventListener('click', handlePracticarDetalle);
      });

      document.querySelectorAll('.card-cuaderno[data-practica-id]').forEach(card => {
        card.removeEventListener('click', handleCardClick);
        card.addEventListener('click', handleCardClick);
      });
    }

    function handleFirmar(e) {
      e.stopPropagation();
      const id = parseInt(this.dataset.id);
      toggleAprendida(id);
    }

    function handleVoice(e) {
      e.stopPropagation();
      const id = parseInt(this.dataset.id);
      const tec = TECNICAS.find(t => t.id === id);
      if (tec) leerTexto(`${tec.nombre}: ${tec.definicion}. Ejemplo: ${tec.ejemplo}`);
    }

    function handleRevelarPractica(e) {
      e.stopPropagation();
      const card = this.closest('.card-cuaderno');
      if (card) {
        card.classList.toggle('revelado');
        this.innerHTML = card.classList.contains('revelado') ? '<i class="bi bi-eye-slash"></i>' : '<i class="bi bi-eye"></i>';
      }
    }

    function handlePracticarDetalle(e) {
      e.stopPropagation();
      const id = parseInt(this.dataset.id);
      const tec = TECNICAS.find(t => t.id === id);
      if (!tec) return;
      const modal = new bootstrap.Modal(document.getElementById('modalPractica'));
      document.getElementById('modalDefinicion').textContent = tec.definicion;
      document.getElementById('modalEjemplo').textContent = tec.ejemplo;
      document.getElementById('modalCaligrafia').textContent = getNombreCaligrafia(tec.caligrafia || 'caveat');
      document.getElementById('modalCaligrafia').style.fontFamily = getClaseCaligrafia(tec.caligrafia || 'caveat');
      document.getElementById('inputRespuesta').value = '';
      document.getElementById('inputRespuesta').style.fontFamily = getClaseCaligrafia(tec.caligrafia || 'caveat');
      document.getElementById('inputFirma').value = '';
      document.getElementById('modalFeedback').innerHTML = '';
      document.getElementById('btnGuardarCuaderno').dataset.id = tec.id;
      document.getElementById('btnGuardarCuaderno').dataset.caligrafia = tec.caligrafia || 'caveat';
      document.getElementById('btnVoiceModal').dataset.id = tec.id;
      modal.show();
    }

    function handleCardClick(e) {
      if (e.target.closest('button')) return;
      this.classList.toggle('revelado');
      const btn = this.querySelector('.btn-revelar-practica');
      if (btn) btn.innerHTML = this.classList.contains('revelado') ? '<i class="bi bi-eye-slash"></i>' : '<i class="bi bi-eye"></i>';
    }

    // ----------------------------------------------------------------
    // 11. NAVEGACIÓN
    // ----------------------------------------------------------------
    function setModo(modo) {
      modoActual = modo;
      document.querySelectorAll('.navbar-custom .nav-link').forEach(el => el.classList.remove('active'));
      const activeLink = document.querySelector(`.navbar-custom .nav-link[data-modo="${modo}"]`);
      if (activeLink) activeLink.classList.add('active');
      renderizar();
    }

    function setBloque(bloque) {
      bloqueFiltro = bloque;
      document.querySelectorAll('.filtro-bloque .btn').forEach(el => el.classList.remove('active'));
      const activeBtn = document.querySelector(`.filtro-bloque .btn[data-bloque="${bloque}"]`);
      if (activeBtn) activeBtn.classList.add('active');
      renderizar();
    }

    function toggleVoice() {
      voiceEnabled = !voiceEnabled;
      const status = document.getElementById('voiceStatus');
      const btn = document.getElementById('btnVoiceToggle');
      if (voiceEnabled) {
        status.classList.remove('d-none');
        btn.classList.add('btn-indigo');
        btn.classList.remove('btn-outline-indigo');
      } else {
        status.classList.add('d-none');
        btn.classList.remove('btn-indigo');
        btn.classList.add('btn-outline-indigo');
        if (speechSynth.speaking) speechSynth.cancel();
      }
    }

    function toggleTheme() {
      const current = document.documentElement.getAttribute('data-theme');
      if (current === 'dark') {
        document.documentElement.removeAttribute('data-theme');
        document.getElementById('themeToggle').innerHTML = '<i class="bi bi-moon-fill"></i>';
      } else {
        document.documentElement.setAttribute('data-theme', 'dark');
        document.getElementById('themeToggle').innerHTML = '<i class="bi bi-sun-fill"></i>';
      }
    }

    // ----------------------------------------------------------------
    // 12. INICIALIZACIÓN
    // ----------------------------------------------------------------
    function init() {
      cargarProgreso();

      document.querySelectorAll('.navbar-custom .nav-link').forEach(el => {
        el.addEventListener('click', function(e) {
          e.preventDefault();
          setModo(this.dataset.modo);
        });
      });

      document.querySelectorAll('.filtro-bloque .btn').forEach(el => {
        el.addEventListener('click', function() {
          setBloque(this.dataset.bloque);
        });
      });

      document.getElementById('btnVoiceToggle').addEventListener('click', toggleVoice);
      document.getElementById('themeToggle').addEventListener('click', toggleTheme);

      // Flashcard eventos
      document.getElementById('flashVoltear').addEventListener('click', flashVoltear);
      document.getElementById('flashNext').addEventListener('click', flashNext);
      document.getElementById('flashPrev').addEventListener('click', flashPrev);
      document.getElementById('flashFirmar').addEventListener('click', flashFirmar);
      document.getElementById('flashVoice').addEventListener('click', flashVoice);
      document.getElementById('flashcard').addEventListener('click', function(e) {
        if (e.target.closest('button')) return;
        flashVoltear();
      });

      // Caligrafía eventos
      document.querySelectorAll('.btn-caligrafia').forEach(btn => {
        btn.addEventListener('click', function() {
          caligrafiaActual = this.dataset.caligrafia;
          renderizarCaligrafia();
        });
      });
      document.getElementById('btnGuardarCaligrafia').addEventListener('click', guardarFraseCaligrafia);
      document.getElementById('inputCaligrafia').addEventListener('keypress', function(e) {
        if (e.key === 'Enter') guardarFraseCaligrafia();
      });

      // Modal: Guardar entrada
      document.getElementById('btnGuardarCuaderno').addEventListener('click', function() {
        const id = parseInt(this.dataset.id);
        const caligrafia = this.dataset.caligrafia || 'caveat';
        const respuesta = document.getElementById('inputRespuesta').value;
        const firma = document.getElementById('inputFirma').value;
        if (!respuesta.trim()) {
          document.getElementById('modalFeedback').innerHTML = '<div class="alert alert-warning">Escribe la técnica antes de guardar.</div>';
          return;
        }
        guardarEntradaCuaderno(id, respuesta, firma, caligrafia);
        document.getElementById('modalFeedback').innerHTML = '<div class="alert alert-success">¡Guardado en tu bitácora!</div>';
        if (!progreso[id]) {
          toggleAprendida(id);
        }
        setTimeout(() => {
          const modal = bootstrap.Modal.getInstance(document.getElementById('modalPractica'));
          if (modal) modal.hide();
        }, 1200);
      });

      document.getElementById('btnVoiceModal').addEventListener('click', function() {
        const id = parseInt(this.dataset.id);
        const tec = TECNICAS.find(t => t.id === id);
        if (tec) leerTexto(`${tec.nombre}: ${tec.definicion}. Ejemplo: ${tec.ejemplo}`);
      });

      document.getElementById('borrarTodoCuaderno').addEventListener('click', function() {
        if (confirm('¿Borrar todas las entradas de tu bitácora?')) {
          entradasCuaderno = [];
          guardarProgreso();
          renderizarCuaderno();
        }
      });

      // Examen
      document.getElementById('btnGenerarExamen').addEventListener('click', function() {
        generarExamen();
        if (!document.getElementById('btnCorregirExamen')) {
          const btnCorregir = document.createElement('button');
          btnCorregir.id = 'btnCorregirExamen';
          btnCorregir.className = 'btn btn-indigo mt-2';
          btnCorregir.innerHTML = '<i class="bi bi-check2-circle"></i> Corregir examen';
          btnCorregir.addEventListener('click', corregirExamen);
          document.getElementById('examenResultados').parentNode.insertBefore(btnCorregir, document.getElementById('examenResultados'));
        }
      });

      document.getElementById('btnExportarCSV').addEventListener('click', exportarCSV);
      document.getElementById('btnExportarJSON').addEventListener('click', exportarJSON);

      document.getElementById('btnResetearProgreso').addEventListener('click', function() {
        if (confirm('¿Resetear todo el progreso?')) {
          progreso = {};
          entradasCuaderno = [];
          frasesCaligrafia = [];
          estadisticas = { racha: 0, aciertos: 0, intentos: 0 };
          niveles = {};
          guardarProgreso();
          renderizar();
        }
      });

      setModo('explorar');
      setBloque('todos');
    }

    document.addEventListener('DOMContentLoaded', init);
  })();
</script>
</body>
</html>

