    function handleTerminal() {
        const val = termInput.value.trim();
        if (!val) {
            termOutput.textContent = '⏺ escribe una frase con figura retórica...';
            termOutput.classList.remove('populated');
            return;
        }
        let found = false, msg = `🔍 "${val}" → `;
        for (const block of BLOCKS) {
            for (const item of block.items) {
                const rootClean = item.root.replace(/[()]/g, '').trim();
                if (val.toLowerCase().includes(rootClean.toLowerCase()) ||
                    item.example.toLowerCase().includes(val.toLowerCase().replace(/[()]/g, ''))) {
                    msg += `relacionado con "${item.root}" (${item.meaning}). `;
                    found = true;
                    break;
                }
            }
            if (found) break;
        }
        if (!found) msg += 'no se reconoció una figura retórica concreta, pero tu creatividad cuenta. 🎭';
        termOutput.textContent = msg;
        termOutput.classList.add('populated');
        termInput.value = '';
    }

