function mostrarToast(msg){
  const t = document.getElementById('saveToast');
  t.querySelector('.toast-body').textContent = msg;
  new bootstrap.Toast(t, {delay:1400}).show();
}
async function cargarTodo(){
  try{ const r = await window.storage.get('futurista:estado'); if(r && r.value) estadoTecnicas = JSON.parse(r.value); }catch(e){}
  try{ const g = await window.storage.get('futurista:galeria'); if(g && g.value) galeria = JSON.parse(g.value); }catch(e){}
  renderTecnicas(); actualizarProgreso(); renderGaleria();
