   ====================================================================== */
function idTecnica(catIdx, tIdx){ return catIdx+"-"+tIdx; }
function renderTecnicas(filtro=""){
  const cont = document.getElementById('accordionCategorias');
  cont.innerHTML = "";
  categorias.forEach((cat, ci)=>{
    const items = cat.tecnicas.map((t,ti)=>({t,ti})).filter(o => filtro==="" || o.t[0].toLowerCase().includes(filtro.toLowerCase()));
    if(items.length===0) return;
    const accId = "cat"+ci;
    const item = document.createElement('div');
    item.className = "accordion-item";
    item.innerHTML = `
      <h2 class="accordion-header">
        <button class="accordion-button ${ci===0?'':'collapsed'}" type="button" data-bs-toggle="collapse" data-bs-target="#${accId}">
          <span class="mono me-2">${String(ci+1).padStart(2,'0')}/10</span> ${cat.nombre}
        </button>
      </h2>
      <div id="${accId}" class="accordion-collapse collapse ${ci===0?'show':''}" data-bs-parent="#accordionCategorias">
        <div class="accordion-body" id="body-${accId}"></div>
      </div>`;
    cont.appendChild(item);
    const body = item.querySelector(`#body-${accId}`);
    items.forEach(({t,ti})=>{
      const id = idTecnica(ci,ti);
      const [nombre,def,ejemplo,ejercicio] = t;
      const numGlobal = categorias.slice(0,ci).reduce((a,c)=>a+c.tecnicas.length,0) + ti + 1;
      const done = !!estadoTecnicas.practicadas[id];
      const texto = estadoTecnicas.textos[id] || "";
      const card = document.createElement('div');
      card.className = "tech-card" + (done ? " done":"");
      card.innerHTML = `
        <div class="d-flex justify-content-between align-items-start flex-wrap gap-2">
          <div>
            <span class="tech-num">${String(numGlobal).padStart(3,'0')}</span> <strong>${nombre}</strong>
            <div class="small mt-1">${def}</div>
            <div class="small fst-italic mt-1 accent-c">Ejemplo: ${ejemplo}</div>
          </div>
          <div class="form-check">
            <input class="form-check-input chk-done" type="checkbox" id="chk-${id}" ${done?'checked':''}>
            <label class="form-check-label small" for="chk-${id}">practicada</label>
          </div>
        </div>
        <div class="small mt-2 mb-1" style="color:var(--velocity);"><strong>Ejercicio:</strong> ${ejercicio}</div>
        <textarea class="form-control mt-1" rows="3" placeholder="Escribe aquí tu práctica…">${texto}</textarea>
        <button class="btn btn-sm btn-fx-o mt-2 btn-save">Guardar folio</button>
      `;
      body.appendChild(card);
      card.querySelector('.chk-done').addEventListener('change', async (e)=>{
        estadoTecnicas.practicadas[id] = e.target.checked;
        card.classList.toggle('done', e.target.checked);
        await guardarEstadoTecnicas(); actualizarProgreso();
      });
      card.querySelector('.btn-save').addEventListener('click', async ()=>{
        estadoTecnicas.textos[id] = card.querySelector('textarea').value;
        await guardarEstadoTecnicas();
        mostrarToast('Guardado.');
      });
    });
  });
}
function actualizarProgreso(){
  const total = categorias.reduce((a,c)=>a+c.tecnicas.length,0);
  const hechas = Object.values(estadoTecnicas.practicadas).filter(Boolean).length;
  document.getElementById('sealCount').textContent = hechas+"/"+total;
  document.getElementById('progressBar').style.width = (hechas/total*100)+"%";
}
