/* ======================================================================
   LIENZOS DE TRAZADO
   ====================================================================== */
function crearLienzo(canvas, colorInput, widthInput){
  function resize(){
    const rect = canvas.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;
    canvas.width = Math.max(1, rect.width * dpr);
    canvas.height = Math.max(1, rect.height * dpr);
    const ctx = canvas.getContext('2d');
    ctx.scale(dpr, dpr);
    ctx.lineCap = 'round'; ctx.lineJoin = 'round';
    canvas._ctx = ctx;
  }
  resize();
  canvas._undoStack = [];
  let drawing = false, lastX=0, lastY=0;
  function pos(e){ const r = canvas.getBoundingClientRect(); return { x: e.clientX - r.left, y: e.clientY - r.top }; }
  function pushUndo(){
    try{ const snap = canvas.toDataURL('image/png'); canvas._undoStack.push(snap); if(canvas._undoStack.length > 12) canvas._undoStack.shift(); }catch(e){}
  }
  canvas.addEventListener('pointerdown', (e)=>{
    canvas.setPointerCapture(e.pointerId);
    pushUndo(); drawing = true;
    const p = pos(e); lastX = p.x; lastY = p.y;
    const ctx = canvas._ctx;
    ctx.strokeStyle = colorInput.value;
    ctx.lineWidth = parseFloat(widthInput.value);
    ctx.beginPath(); ctx.moveTo(lastX, lastY);
  });
  canvas.addEventListener('pointermove', (e)=>{
    if(!drawing) return;
    const p = pos(e); const ctx = canvas._ctx;
    ctx.lineTo(p.x, p.y); ctx.stroke();
    lastX = p.x; lastY = p.y;
  });
  function endStroke(){ drawing = false; }
  canvas.addEventListener('pointerup', endStroke);
  canvas.addEventListener('pointerleave', endStroke);
  canvas.addEventListener('pointercancel', endStroke);
  canvas._resize = resize;
  canvas._clear = ()=>{ const ctx=canvas._ctx; ctx.clearRect(0,0,canvas.width,canvas.height); };
  canvas._undo = ()=>{
    if(canvas._undoStack.length===0){ canvas._clear(); return; }
    const data = canvas._undoStack.pop();
    const img = new Image();
    img.onload = ()=>{
      const ctx = canvas._ctx;
      ctx.save(); ctx.setTransform(1,0,0,1,0,0);
      ctx.clearRect(0,0,canvas.width,canvas.height);
      ctx.drawImage(img,0,0,canvas.width,canvas.height);
      ctx.restore();
    };
    img.src = data;
  };
  return canvas;
}

