        function cargarProgreso() { if (localStorage.getItem('progresoMateGrado9')) { const p = JSON.parse(localStorage.getItem('progresoMateGrado9')); aciertos = p.aciertos||0; totalPreguntas = p.total||0; racha = p.racha||0; rachaMax = p.rachaMax||0; } actualizarMarcadores(); }
        function guardarProgreso() { localStorage.setItem('progresoMateGrado9', JSON.stringify({aciertos,total:totalPreguntas,racha,rachaMax})); }
